/* 数据来源: chinese-poetry 开源项目(公有领域) | 1500 首 */
window.SHICI_TANG=[{"id":"T00001","t":"在狱咏蝉","a":"骆宾王","c":["西陆蝉声唱，南冠客思侵。","那堪玄鬓影，来对白头吟。","露重飞难进，风多响易沈。","无人信高洁，谁为表予心。"]},{"id":"T00002","t":"登幽州台歌","a":"陈子昂","c":["前不见古人，后不见来者。","念天地之悠悠，独怆然而涕下。"]},{"id":"T00003","t":"经邹鲁祭孔子而叹之","a":"明皇帝","c":["夫子何为者？栖栖一代中。","地犹鄹氏邑，宅即鲁王宫。","叹凤嗟身否，伤麟怨道穷。","今看两楹奠，当与梦时同。"]},{"id":"T00004","t":"鼓吹曲辞 将进酒","a":"李白","c":["君不见黄河之水天上来，奔流到海不复回。","君不见高堂明镜悲白发，朝如青丝暮成雪。","人生得意须尽欢，莫使金尊空对月。","天生我材必有用，千金散尽还复来。","烹羊宰牛且为乐，会须一饮三百杯。","岑夫子，丹丘生，将进酒，杯莫停。","与君歌一曲，请君为我侧耳听。","钟鼓馔玉不足贵，但愿长醉不复醒。","古来圣贤皆寂寞，惟有饮者留其名。","陈王昔时宴平乐，斗酒十千恣欢谑。","主人何为言少钱，径须酤取对君酌。","五花马，千金裘，呼儿将出换美酒，与尔同销万古愁。"]},{"id":"T00005","t":"横吹曲辞 出塞 一","a":"王昌龄","c":["秦时明月汉时关，万里长征人未还。","但使龙城飞将在，不教胡马度阴山。"]},{"id":"T00006","t":"横吹曲辞 出塞","a":"王之涣","c":["黄砂直上白云间，一片孤城万仞山。","羌笛何须怨杨柳，春风不度玉门关。"]},{"id":"T00007","t":"横吹曲辞 关山月","a":"李白","c":["明月出天山，苍茫云海间。","长风几万里，吹度玉门关。","汉下白登道，胡窥青海湾。","由来征战地，不见有人还。","戍客望边色，思归多苦颜。","高楼当此夜，叹息未应闲。"]},{"id":"T00008","t":"新嫁娘词三首 三","a":"王建","c":["三日入厨下，洗手作羹汤。","未谙姑食性，先遣小姑尝。"]},{"id":"T00009","t":"故行宫","a":"王建","c":["寥落古行宫，宫花寂寞红。","白头宫女在，闲坐说玄宗。"]},{"id":"T00010","t":"锦瑟","a":"李商隐","c":["锦瑟无端五十弦，一弦一柱思华年。","庄生晓梦迷蝴蝶，望帝春心托杜鹃。","沧海月明珠有泪，蓝田日暖玉生烟。","此情可待成追忆，只是当时已惘然。"]},{"id":"T00011","t":"蝉","a":"李商隐","c":["本以高难饱，徒劳恨费声。","五更疎欲断，一树碧无情。","薄宦梗犹泛，故园芜已平。","烦君最相警，我亦举家清。"]},{"id":"T00012","t":"乐游原","a":"李商隐","c":["向晚意不适，驱车登古原。","夕阳无限好，只是近黄昏。"]},{"id":"T00013","t":"夜雨寄北","a":"李商隐","c":["君问归期未有期，巴山夜雨涨秋池。","何当共剪西窗烛，却话巴山夜雨时。"]},{"id":"T00014","t":"韩碑","a":"李商隐","c":["元和天子神武姿，彼何人哉轩与羲。","誓将上雪列圣耻，坐法宫中朝四夷。","淮西有贼五十载，封狼生䝙䝙生罴。","不据山河据平地，长戈利矛日可麾。","帝得圣相相曰度，贼斫不死神扶持。","腰悬相印作都统，阴风惨澹天王旗。","愬武古通作牙爪，仪曹外郎载笔随。","行军司马智且勇，十四万众犹虎貔。","入蔡缚贼献太庙，功无与让恩不訾。","帝曰汝度功第一，汝从事愈宜为辞。","愈拜稽首蹈且舞，金石刻画臣能为。","古者世称大手笔，此事不系于职司。","当仁自古有不让，言讫屡颔天子颐。","公退斋戒坐小阁，濡染大笔何淋漓。","点窜尧典舜典字，涂改清庙生民诗。","文成破体书在纸，清晨再拜铺丹墀。","表曰臣愈昧死上，咏神圣功书之碑。","碑高三丈字如斗，负以灵鼇蟠以螭。","句奇语重喻者少，谗之天子言其私。","长绳百尺拽碑倒，麤砂大石相磨治。","公之斯文若元气，先时已入人肝脾。","汤盘孔鼎有述作，今无其器存其辞。","呜呼圣皇及圣相，相与烜赫流淳熙。","公之斯文不示后，曷与三五相攀追。","愿书万本诵万过，口角流沫右手胝。","传之七十有二代，以为封禅玉检明堂基。"]},{"id":"T00015","t":"风雨","a":"李商隐","c":["凄凉宝剑篇，羁泊欲穷年。","黄叶仍风雨，青楼自管弦。","新知遭薄俗，旧好隔良缘。","心断新丰酒，销愁斗几千。"]},{"id":"T00016","t":"寄令狐郎中","a":"李商隐","c":["嵩云秦树久离居，双鲤迢迢一纸书。","休问梁园旧宾客，茂陵秋雨病相如。"]},{"id":"T00017","t":"隋宫","a":"李商隐","c":["紫泉宫殿锁烟霞，欲取芜城作帝家。","玉玺不缘归日角，锦帆应是到天涯。","于今腐草无萤火，终古垂杨有暮鸦。","地下若逢陈后主，岂宜重问后庭花。"]},{"id":"T00018","t":"筹笔驿","a":"李商隐","c":["猿鸟犹疑畏简书，风云常为护储胥。","徒令上将挥神笔，终见降王走传车。","管乐有才终不忝，关张无命欲何如。","他年锦里经祠庙，梁父吟成恨有余。"]},{"id":"T00019","t":"无题二首 一","a":"李商隐","c":["昨夜星辰昨夜风，画楼西畔桂堂东。","身无彩凤双飞翼，心有灵犀一点通。","隔座送钩春酒暖，分曹射复蜡灯红。","嗟余听鼓应官去，走马兰台类断蓬。"]},{"id":"T00020","t":"无题四首 一","a":"李商隐","c":["来是空言去绝踪，月斜楼上五更钟。","梦为远别啼难唤，书被催成墨未浓。","蜡照半笼金翡翠，麝熏微度绣芙蓉。","刘郎已恨蓬山远，更隔蓬山一万重。"]},{"id":"T00021","t":"无题四首 二","a":"李商隐","c":["飒飒东风细雨来，芙蓉塘外有轻雷。","金蟾啮鏁烧香入，玉虎牵丝汲井回。","贾氏窥帘韩掾少，宓妃留枕魏王才。","春心莫共花争发，一寸相思一寸灰。"]},{"id":"T00022","t":"落花","a":"李商隐","c":["高阁客竟去，小园花乱飞。","参差连曲陌，迢遰送斜晖。","肠断未忍扫，眼穿仍欲归。","芳心向春尽，所得是沾衣。"]},{"id":"T00023","t":"为有","a":"李商隐","c":["为有云屏无限娇，凤城寒尽怕春宵。","无端嫁得金龟壻，辜负香衾事早朝。"]},{"id":"T00024","t":"无题","a":"李商隐","c":["相见时难别亦难，东风无力百花残。","春蚕到死丝方尽，蜡炬成灰泪始干。","晓镜但愁云鬓改，夜吟应觉月光寒。","蓬山此去无多路，青鸟殷勤为探看。"]},{"id":"T00025","t":"瑶池","a":"李商隐","c":["瑶池阿母绮窗开，黄竹歌声动地哀。","八骏日行三万里，穆王何事不重来。"]},{"id":"T00026","t":"春雨","a":"李商隐","c":["怅卧新春白袷衣，白门寥落意多违。","红楼隔雨相望冷，珠箔飘灯独自归。","远路应悲春晼晚，残宵犹得梦依稀。","玉珰缄札何由达，万里云罗一雁飞。"]},{"id":"T00027","t":"常娥","a":"李商隐","c":["云母屏风烛影深，长河渐落晓星沈。","常娥应悔偷灵药，碧海青天夜夜心。"]},{"id":"T00028","t":"无题二首 二","a":"李商隐","c":["重帷深下莫愁堂，卧后清宵细细长。","神女生涯原是梦，小姑居处本无郎。","风波不信菱枝弱，月露谁教桂叶香。","直道相思了无益，未妨惆怅是清狂。"]},{"id":"T00029","t":"贾生","a":"李商隐","c":["宣室求贤访逐臣，贾生才调更无伦。","可怜夜半虚前席，不问苍生问鬼神。"]},{"id":"T00030","t":"凉思","a":"李商隐","c":["客去波平槛，蝉休露满枝。","永怀当此节，倚立自移时。","北斗兼春远，南陵寓使迟。","天涯占梦数，疑误有新知。"]},{"id":"T00031","t":"北青萝","a":"李商隐","c":["残阳西入崦，茅屋访孤僧。","落叶人何在，寒云路几层。","独敲初夜磬，闲倚一枝藤。","世界微尘里，吾宁爱与憎。"]},{"id":"T00032","t":"赤壁","a":"李商隐","c":["折戟沈沙铁未销，自将磨洗认前朝。","东风不与周郎便，铜雀春深锁二乔。"]},{"id":"T00033","t":"章台夜思","a":"韦庄","c":["清瑟怨遥夜，遶弦风雨哀。","孤灯闻楚角，残月下章台。","芳草已云暮，故人殊未来。","乡书不可寄，秋雁又南回。"]},{"id":"T00034","t":"金陵图","a":"韦庄","c":["谁谓伤心画不成，画人心逐世人情。","君看六幅南朝事，老木寒云满故城。"]},{"id":"T00035","t":"台城","a":"韦庄","c":["江雨霏霏江草齐，六朝如梦鸟空啼。","无情最是台城柳，依旧烟笼十里堤。"]},{"id":"T00036","t":"宫词","a":"薛逢","c":["十二楼中尽晓妆，望仙楼上望君王。","锁衔金兽连环冷，水滴铜龙昼漏长。","云髻罢梳还对镜，罗衣欲换更添香。","遥窥正殿帘开处，袍袴宫人扫御床。"]},{"id":"T00037","t":"楚江怀古三首 一","a":"马戴","c":["露气寒光集，微阳下楚丘。","猨啼洞庭树，人在木兰舟。","广泽生明月，苍山夹乱流。","云中君不降，竟夕自悲秋。"]},{"id":"T00038","t":"灞上秋居","a":"马戴","c":["灞原风雨定，晚见鴈行频。","落叶他乡树，寒灯独夜人。","空园白露滴，孤壁野僧隣。","寄卧郊扉久，何门致此身。"]},{"id":"T00039","t":"马嵬坡","a":"郑畋","c":["[玄]宗回马杨妃死，云雨虽亡日月新。","终是圣明天子事，景阳宫井又何人。"]},{"id":"T00040","t":"没蕃故人","a":"张籍","c":["前年伐月支，城上没全师。","蕃汉断消息，死生长别离。","无人收废帐，归马识残旗。","欲祭疑君在，天涯哭此时。"]},{"id":"T00041","t":"春怨","a":"金昌绪","c":["打起黄莺儿，莫教枝上啼。","啼时惊妾梦，不得到辽西。"]},{"id":"T00042","t":"遣悲怀三首 一","a":"元稹","c":["谢公最小偏怜女，嫁与黔娄百事乖。","顾我无衣搜画箧，泥他沽酒拔金钗。","野蔬充膳甘长藿，落叶添薪仰古槐。","今日俸钱过十万，与君营奠复营斋。"]},{"id":"T00043","t":"遣悲怀三首 二","a":"元稹","c":["昔日戏言身后意，今朝皆到眼前来。","衣裳已施行看尽，针线犹存未忍开。","尚想旧情怜婢仆，也曾因梦送钱财。","诚知此恨人人有，贫贱夫妻百事哀。"]},{"id":"T00044","t":"遣悲怀三首 三","a":"元稹","c":["闲坐悲君亦自悲，百年都是几多时。","邓攸无子寻知命，潘岳悼亡犹费词。","同穴窅冥何所望，他生缘会更难期。","唯将终夜长开眼，报荅平生未展眉。"]},{"id":"T00045","t":"行宫","a":"元稹","c":["寥落古行宫，宫花寂寞红。","白头宫女在，闲坐说玄宗。"]},{"id":"T00046","t":"哥舒歌","a":"西鄙人","c":["北斗七星高，哥舒夜带刀。","至今窥牧马，不敢过临洮。"]},{"id":"T00047","t":"杂诗 十三","a":"无名氏","c":["近寒食雨草萋萋，著麦苗风柳映堤。","早是有家归未得，杜鹃休向耳边啼。"]},{"id":"T00048","t":"杂诗三首 三","a":"沈佺期","c":["闻道黄龙戍，频年不解兵。","可怜闺里月，长在汉家营。","少妇今春意，良人昨夜情。","谁能将旗鼓，一为取龙城。"]},{"id":"T00049","t":"古意呈补阙乔知之","a":"沈佺期","c":["卢家少妇郁金堂，海燕双栖玳瑁梁。","九月寒砧催木叶，十年征戍忆辽阳。","白狼河北音书断，丹凤城南秋夜长。","谁谓含愁独不见，更教明月照流黄。"]},{"id":"T00050","t":"次北固山下","a":"王湾","c":["客路青山外，行舟绿水前。","潮平两岸阔，风正一帆悬。","海日生残夜，江春入旧年。","乡书何处达，归雁洛阳边。"]},{"id":"T00051","t":"桃花谿","a":"张旭","c":["隐隐飞桥隔野烟，石矶西畔问渔船。","桃花尽日随流水，洞在清谿何处边。"]},{"id":"T00052","t":"送别","a":"王维","c":["下马饮君酒，问君何所之。","君言不得意，归卧南山陲。","但去莫复问，白云无尽时。"]},{"id":"T00053","t":"送綦毋潜落第还乡","a":"王维","c":["圣代无隐者，英灵尽来归。","遂令东山客，不得顾采薇。","既至君门远，孰云吾道非。","江淮度寒食，京洛缝春衣。","置酒临长道，同心与我违。","行当浮桂櫂，未几拂荆扉。","远树带行客，孤村当落晖。","吾谋适不用，勿谓知音稀。"]},{"id":"T00054","t":"青谿","a":"王维","c":["言入黄花川，每逐青谿水。","随山将万转，趣途无百里。","声喧乱石中，色静深松里。","漾漾泛菱荇，澄澄映葭苇。","我心素已闲，清川澹如此。","请留盘石上，垂钓将已矣。"]},{"id":"T00055","t":"渭川田家","a":"王维","c":["斜阳照墟落，穷巷牛羊归。","野老念牧童，倚杖候荆扉。","雉雊麦苗秀，蚕眠桑叶稀。","田夫荷锄至，相见语依依。","即此羡闲逸，怅然吟式微。"]},{"id":"T00056","t":"西施咏","a":"王维","c":["艳色天下重，西施宁久微。","朝仍越溪女，暮作吴宫妃。","贱日岂殊众，贵来方悟稀。","邀人傅香粉，不自著罗衣。","君宠益娇态，君怜无是非。","当时浣纱伴，莫得同车归。","持谢邻家子，效颦安可希。"]},{"id":"T00057","t":"老将行","a":"王维","c":["少年十五二十时，步行夺得胡马射。","射杀中山白额虎，肯数邺下黄须儿。","一身转战三千里，一劒曾当百万师。","汉兵奋迅如霹雳，虏骑崩腾畏蒺藜。","衞青不败由天幸，李广无功缘数奇。","自从弃置便衰朽，世事磋跎成白首。","昔时飞箭无全目，今日垂杨生左肘。","路傍时卖故侯瓜，门前学种先生柳。","苍茫古木连穷巷，寥落寒山对虚牖。","誓令疏勒出飞泉，不似颍川空使酒。","贺兰山下阵如云，羽檄交驰日夕闻。","节使三河募年少，诏书五道出将军。","试拂铁衣如雪色，聊持宝劒动星文。","愿得燕弓射天将，耻令越甲鸣吴军。","莫嫌旧日云中守，犹堪一战取功勋。"]},{"id":"T00058","t":"桃源行","a":"王维","c":["渔舟逐水爱山春，两岸桃花夹去津。","坐看红树不知远，行尽青溪不见人。","山口潜行始隈隩，山开旷望旋平陆。","遥看一处攒云树，近入千家散花竹。","樵客初传汉姓名，居人未改秦衣服。","居人共住武陵源，还从物外起田园。","月明松下房栊静，日出云中鸡犬喧。","惊闻俗客争来集，竞引还家问都邑。","平明闾巷埽花开，薄暮渔樵乘水入。","初因避地去人间，及至成仙遂不还。","峡里谁知有人事，世中遥望空云山。","不疑灵境难闻见，尘心未尽思乡县。","出洞无论隔山水，辞家终拟长游衍。","自谓经过旧不迷，安知峰壑今来变。","当时只记入山深，青溪几曲到云林。","春来遍是桃花水，不辨仙源何处寻。"]},{"id":"T00059","t":"洛阳女儿行","a":"王维","c":["洛阳女儿对门居，才可容颜十五余。","良人玉勒乘骢马，侍女金盘鲙鲤鱼。","画阁朱楼尽相望，红桃绿柳垂簷向。","罗帏送上七香车，宝扇迎归九华帐。","狂夫富贵在青春，意气骄奢剧季伦。","自怜碧玉亲教舞，不惜珊瑚持与人。","春窗曙灭九微火，九微片片飞花璅。","戏罢曾无理曲时，妆成秪是薰香坐。","城中相识尽繁华，日夜经过赵李家。","谁怜越女颜如玉，贫贱江头自浣纱。"]},{"id":"T00060","t":"辋川闲居赠裴秀才迪","a":"王维","c":["寒山转苍翠，秋水日潺湲。","倚杖柴门外，临风听暮蝉。","渡头余落日，墟里上孤烟。","复值接舆醉，狂歌五柳前。"]},{"id":"T00061","t":"酬张少府","a":"王维","c":["晚年唯好静，万事不关心。","自顾无长策，空知返旧林。","松风吹解带，山月照弹琴。","君问穷通理，渔歌入浦深。"]},{"id":"T00062","t":"送梓州李使君","a":"王维","c":["万壑树参天，千山响杜鹃。","山中一夜雨，树杪百重泉。","汉女输橦布，巴人讼芋田。","文翁翻教授，不敢倚先贤。"]},{"id":"T00063","t":"玉台体十二首 十一","a":"权德舆","c":["昨夜裙带解，今朝蟢子飞。","铅华不可弃，莫是藁砧归。"]},{"id":"T00064","t":"山石","a":"韩愈","c":["山石荦确行径微，黄昏到寺蝙蝠飞。","升堂坐阶新雨足，芭蕉叶大支子肥。","僧言古壁佛画好，以火来照所见稀。","铺床拂席置羹饭，疎粝亦足饱我饥。","夜深静卧百虫绝，清月出岭光入扉。","天明独去无道路，出入高下穷烟霏。","山红涧碧纷烂漫，时见松枥皆十围。","当流赤足蹋涧石，水声激激风吹衣。","人生如此自可乐，岂必局束为人鞿。","嗟哉吾党二三子，安得至老不更归。"]},{"id":"T00065","t":"八月十五夜赠张功曹","a":"韩愈","c":["纤云四卷天无河，清风吹空月舒波。","沙平水息声影绝，一桮相属君当歌。","君歌声酸辞且苦，不能听终泪如雨。","洞庭连天九疑高，蛟龙出没猩鼯号。","十生九死到官所，幽居默默如藏逃。","下床畏蛇食畏药，海气湿蛰熏腥臊。","昨者州前搥大鼓，嗣皇继圣登夔臯。","赦书一日行万里，罪从大辟皆除死。","迁者追廻流者还，涤瑕荡垢清朝班。","州家申名使家抑，坎轲祗得移荆蛮。","判司卑官不堪说，未免捶楚尘埃间。","同时辈流多上道，天路幽险难追攀。","君歌且休听我歌，我歌今与君殊科。"]},{"id":"T00066","t":"谒衡岳庙遂宿岳寺题门楼","a":"韩愈","c":["五岳祭秩皆三公，四方环镇嵩当中。","火维地荒足妖怪，天假神柄专其雄。","喷云泄雾藏半腹，虽有绝顶谁能穷。","我来正逢秋雨节，阴气晦昧无清风。","潜心默祷若有应，岂非正直能感通。","须臾静扫众峰出，仰见突兀撑青空。","紫盖连延接天柱，石廪腾掷堆祝融。","森然魄动下马拜，松柏一迳趋灵宫。","粉墙丹柱动光彩，鬼物图画填青红。","升阶伛偻荐脯酒，欲以菲薄明其衷。","庙令老人识神意，睢盱侦伺能鞠躬。","手持桮珓导我掷，云此最吉余难同。","窜逐蛮荒幸不死，衣食才足甘长终。","侯王将相望久绝，神纵欲福难为功。","夜投佛寺上高阁，星月掩暎云朣胧。","猿鸣钟动不知曙，杲杲寒日生于东。"]},{"id":"T00067","t":"已凉","a":"韩偓","c":["碧阑干外绣帘垂，猩血屏风画折枝。","八尺龙须方锦褥，已凉天气未寒时。"]},{"id":"T00068","t":"春宫怨","a":"杜荀鹤","c":["早被婵娟误，欲妆临镜慵。","承恩不在貌，教妾若为容。","风暖鸟声碎，日高花影重。","年年越溪女，相忆采芙蓉。"]},{"id":"T00069","t":"近试上张籍水部","a":"朱庆余","c":["洞房昨夜停红烛，待晓堂前拜舅姑。","[妆]罢低声问夫壻，画眉深浅入时无。"]},{"id":"T00070","t":"将赴吴兴登乐游原一绝","a":"杜牧","c":["清时有味是无能，闲爱孤云静爱僧。","欲把一麾江海去，乐游原上望昭陵。"]},{"id":"T00071","t":"赤壁","a":"杜牧","c":["折戟沈沙铁未销，自将磨洗认前朝。","东风不与周郎便，铜雀春深鏁二乔。"]},{"id":"T00072","t":"泊秦淮","a":"杜牧","c":["烟笼寒水月笼沙，夜泊秦淮近酒家。","商女不知亡国恨，隔江犹唱后庭花。"]},{"id":"T00073","t":"赠别二首 一","a":"杜牧","c":["娉娉褭褭十三余，豆蔻梢头二月初。","春风十里扬州路，卷上珠帘总不如。"]},{"id":"T00074","t":"赠别二首 二","a":"杜牧","c":["多情却似总无情，唯觉尊前笑不成。","蜡烛有心还惜别，替人垂泪到天明。"]},{"id":"T00075","t":"遣怀","a":"杜牧","c":["落魄江南载酒行，楚腰肠断掌中轻。","十年一觉扬州梦，赢得青楼薄幸名。"]},{"id":"T00076","t":"秋夕","a":"杜牧","c":["红烛秋光冷画屏，轻罗小扇扑流萤。","天阶夜色凉如水，坐看牵牛织女星。"]},{"id":"T00077","t":"金谷园","a":"杜牧","c":["繁华事散逐香尘，流水无情草自春。","日暮东风怨啼鸟，落花犹似堕楼人。"]},{"id":"T00078","t":"旅宿","a":"杜牧","c":["旅馆无良伴，凝情自悄然。","寒灯思旧事，断鴈警愁眠。","远梦归侵晓，家书到隔年。","湘江好烟月，门系钓鱼船。"]},{"id":"T00079","t":"早秋三首 一","a":"许浑","c":["遥夜泛清瑟，西风生翠萝。","残萤委玉露，早鴈拂银河。","高树晓还密，远山晴更多。","淮南一叶下，自觉老烟波。"]},{"id":"T00080","t":"秋日赴阙题潼关驿楼","a":"许浑","c":["红叶晚萧萧，长亭酒一瓢。","残云归太华，疎雨过中条。","树色随山迥，河声入海遥。","帝乡明日到，犹自梦渔樵。"]},{"id":"T00081","t":"寄人 一","a":"张泌","c":["别梦依依到谢家，小廊回合曲阑斜。","多情只有春庭月，犹为离人照落花。"]},{"id":"T00082","t":"陇西行四首 二","a":"陈陶","c":["誓扫匈奴不顾身，五千貂锦丧胡尘。","可怜无定河边骨，犹是春闺梦里人。"]},{"id":"T00083","t":"颂古三十二首  其二三","a":"释明辩","c":["打起黄莺儿，莫教枝上啼。","几回惊妾梦，不得到辽西。"]},{"id":"T00084","t":"后宫词","a":"白居易","c":["泪湿罗巾梦不成，夜深前殿按歌声。","红颜未老恩先断，斜倚薰笼坐到明。"]},{"id":"T00085","t":"喜见外弟又言别","a":"李益","c":["十年离乱后，长大一相逢。","问姓惊初见，称名忆旧容。","别来沧海事，语罢暮天钟。","明日巴陵道，秋山又几重。"]},{"id":"T00086","t":"江南词","a":"李益","c":["嫁得瞿塘贾，朝朝悮妾期。","早知潮有信，嫁与弄潮儿。"]},{"id":"T00087","t":"夜上受降城闻笛","a":"李益","c":["回乐峰前沙似雪，受降城下月如霜。","不知何处吹芦管，一夜征人尽望乡。"]},{"id":"T00088","t":"听筝","a":"李端","c":["鸣筝金粟柱，素手玉房前。","欲得周郎顾，时时误拂弦。"]},{"id":"T00089","t":"贼平后送人北归","a":"司空曙","c":["世乱同南去，时清独北还。","他乡生白发，旧国见青山。","晓月过残垒，繁星宿故关。","寒禽与衰草，处处伴愁颜。"]},{"id":"T00090","t":"云阳馆与韩绅宿别","a":"司空曙","c":["故人江海别，几度隔山川。","乍见翻疑梦，相悲各问年。","孤灯寒照雨，湿竹暗浮烟。","更有明朝恨，离杯惜共传。"]},{"id":"T00091","t":"喜外弟卢纶见宿","a":"司空曙","c":["静夜四无邻，荒居旧业贫。","雨中黄叶树，灯下白头人。","以我独沈久，愧君相见频。","平生自有分，况是蔡家亲。"]},{"id":"T00092","t":"听弹琴","a":"刘长卿","c":["泠泠七丝上，静听松风寒。","古调虽自爱，今人多不弹。"]},{"id":"T00093","t":"送方外上人","a":"刘长卿","c":["孤云将野鹤，岂向人间住。","莫买沃洲山，时人已知处。"]},{"id":"T00094","t":"送灵澈上人","a":"刘长卿","c":["苍苍竹林寺，杳杳钟声晚。","荷笠带夕阳，青山独归远。"]},{"id":"T00095","t":"新年作","a":"刘长卿","c":["乡心新岁切，天畔独潸然。","老至居人下，春归在客先。","岭猨同旦暮，江柳共风烟。","已是长沙傅，从今又几年。"]},{"id":"T00096","t":"秋日登吴公台上寺远眺寺即陈将吴明彻战场","a":"刘长卿","c":["古台摇落后，秋日望乡心。","野寺人来少，云峰水隔深。","夕阳依旧垒，寒磬满空林。","惆怅南朝事，长江独至今。"]},{"id":"T00097","t":"寻南溪常山道人隐居","a":"刘长卿","c":["一路经行处，莓苔见履痕。","白云依静渚，春草闭闲门。","过雨看松色，随山到水源。","溪花与禅意，相对亦忘言。"]},{"id":"T00098","t":"饯别王十一南游","a":"刘长卿","c":["望君烟水阔，挥手泪沾巾。","飞鸟没何处，青山空向人。","长江一帆远，落日五湖春。","谁见汀洲上，相思愁白苹。"]},{"id":"T00099","t":"江州重别薛六柳八二员外","a":"刘长卿","c":["生涯岂料承优诏，世事空知学醉歌。","江上月明胡鴈过，淮南木落楚山多。","寄身且喜沧洲近，顾影无如白发何。","今日龙钟人共弃，媿君犹遣慎风波。"]},{"id":"T00100","t":"长沙过贾谊宅","a":"刘长卿","c":["三年谪宦此栖迟，万古惟留楚客悲。","秋草独寻人去后，寒林空见日斜时。","汉文有道恩犹薄，湘水无情吊岂知。","寂寂江山摇落处，怜君何事到天涯。"]},{"id":"T00101","t":"自夏口至鹦鹉洲夕望岳阳寄源中丞","a":"刘长卿","c":["[汀]洲无浪复无烟，楚客相思益渺然。","汉口夕阳斜渡鸟，洞庭秋水远连天。","孤城背岭寒吹角，独戍临江夜泊船。","贾谊上书忧汉室，长沙谪去古今怜。"]},{"id":"T00102","t":"赋得","a":"刘长卿","c":["莺啼燕语报新年，马邑龙堆路几千。","家住层城临汉苑，[心]随明月到胡天。","机中锦字论长恨，楼上花枝笑独眠。","为问元戎窦车骑，何时返斾勒燕然。"]},{"id":"T00103","t":"九日登望仙台呈刘明府容","a":"崔曙","c":["汉文皇帝有高台，此日登临曙色开。","三晋云山皆北向，二陵风雨自东来。","关门令尹谁能识，河上仙翁去不回。","且欲近寻彭泽宰，陶然共醉菊花杯。"]},{"id":"T00104","t":"凉州词二首 一","a":"王翰","c":["葡萄美酒夜光杯，欲饮琵琶马上催。","醉卧沙场君莫笑，古来征战几人回。"]},{"id":"T00105","t":"秋登兰山寄张五","a":"孟浩然","c":["北山白云里，隐者自怡悦。","相望试登高，心飞逐鸟灭。","愁因薄暮起，兴是清秋发。","时见归村人，沙行渡头歇。","天边树若荠，江畔舟如月。","何当载酒来，共醉重阳节。"]},{"id":"T00106","t":"夏日南亭怀辛大","a":"孟浩然","c":["山光忽西落，池月渐东上。","散发乘夕凉，开轩卧闲敞。","荷风送香气，竹露滴清响。","欲取鸣琴弹，恨无知音赏。","感此怀故人，中宵劳梦想。"]},{"id":"T00107","t":"宿业师山房期丁大不至","a":"孟浩然","c":["夕阳度西岭，群壑倏已暝。","松月生夜凉，风泉满清听。","樵人归欲尽，烟鸟栖初定。","之子期宿来，孤琴候萝迳。"]},{"id":"T00108","t":"夜归鹿门山歌","a":"孟浩然","c":["山寺钟鸣昼已昏，渔梁渡头争渡喧。","人随沙路向江村，余亦乘舟归鹿门。","鹿门月照开烟树，忽到庞公栖隐处。","岩扉松径长寂寥，惟有幽人夜来去。"]},{"id":"T00109","t":"望洞庭湖赠张丞相","a":"孟浩然","c":["八月湖水平，涵虚混太清。","气蒸云梦泽，波撼岳阳城。","欲济无舟楫，端居耻圣明。","坐观垂钓者，空有羡鱼情。"]},{"id":"T00110","t":"秦中感秋寄远上人","a":"孟浩然","c":["一丘常欲卧，三径苦无资。","北土非吾愿，东林怀我师。","黄金然桂尽，壮志逐年衰。","日夕凉风至，闻蝉但益悲。"]},{"id":"T00111","t":"宿桐庐江寄广陵旧游","a":"孟浩然","c":["山暝闻猿愁，沧江急夜流。","风鸣两岸叶，月照一孤舟。","建德非吾土，维扬忆旧游。","还将两行泪，遥寄海西头。"]},{"id":"T00112","t":"早寒江上有怀","a":"孟浩然","c":["木落雁南度，北风江上寒。","我家襄水上，遥隔楚云端。","乡泪客中尽，孤帆天际看。","迷津欲有问，平海夕漫漫。"]},{"id":"T00113","t":"留别王侍御维","a":"孟浩然","c":["寂寂竟何待，朝朝空自归。","欲寻芳草去，惜与故人违。","当路谁相假，知音世所稀。","秪应守索寞，还掩故园扉。"]},{"id":"T00114","t":"清明日宴梅道士房","a":"孟浩然","c":["林卧愁春尽，开轩览物华。","忽逢青鸟使，邀入赤松家。","丹灶初开火，仙桃正落花。","童颜若可驻，何惜醉流霞。"]},{"id":"T00115","t":"与诸子登岘山","a":"孟浩然","c":["人事有代谢，往来成古今。","江山留胜迹，我辈复登临。","水落鱼梁浅，天寒梦泽深。","羊公碑字在，读罢泪沾襟。"]},{"id":"T00116","t":"过故人庄","a":"孟浩然","c":["故人具鸡黍，邀我至田家。","绿树村边合，青山郭外斜。","开筵面场圃，把酒话桑麻。","待到重阳日，还来就菊花。"]},{"id":"T00117","t":"岁暮归南山","a":"孟浩然","c":["北阙休上书，南山归敝庐。","不才明主弃，多病故人疎。","白发催年老，青阳逼岁除。","永怀愁不寐，松月夜窗虚。"]},{"id":"T00118","t":"岁除夜有怀","a":"孟浩然","c":["迢递三巴路，羁危万里身。","乱山残雪夜，孤灯异乡人。","渐与骨肉远，转于奴仆亲。","那堪正飘泊，来日岁华新。"]},{"id":"T00119","t":"春晓","a":"孟浩然","c":["春眠不觉晓，处处闻啼鸟。","夜来风雨声，花落知多少。"]},{"id":"T00120","t":"宿建德江","a":"孟浩然","c":["移舟泊烟渚，日暮客愁新。","野旷天低树，江清月近人。"]},{"id":"T00121","t":"蜀道难","a":"李白","c":["噫吁戏！危乎高哉！蜀道之难难于上青天！蚕丛及鱼凫，开国何茫然。","尔来四万八千岁，不与秦塞通人烟。","西当太白有鸟道，可以横绝峨眉巅。","地崩山摧壮士死，然后天梯石栈相钩连。","上有六龙回日之高标，下有冲波逆折之回川。","黄鹤之飞尚不得过，猨猱欲度愁攀援。","青泥何盘盘，百步九折萦岩峦。","扪参历井仰胁息，以手抚膺坐长叹。","问君西游何时还？畏途巉岩不可攀。","但见悲鸟号古木，雄飞雌从绕林间。","又闻子规啼夜月，愁空山，蜀道之难难于上青天，使人听此凋朱颜。","连峰去天不盈尺，枯松倒挂倚绝壁。","飞湍瀑流争喧豗，砅厓转石万壑雷。","其险也如此，嗟尔远道之人胡为乎来哉！劒阁峥嵘而崔嵬，一夫当关，万夫莫开。","所守或匪亲，化为狼与豺。","朝避猛虎，夕避长蛇。","磨牙吮血，杀人如麻。","锦城虽云乐，不如早还家。","蜀道之难难于上青天，侧身西望长咨嗟。"]},{"id":"T00122","t":"将进酒","a":"李白","c":["君不见黄河之水天上来，奔流到海不复回。","君不见高堂明镜悲白发，朝如青丝暮成雪。","人生得意须尽欢，莫使金樽空对月。","天生我材必有用，千金散尽还复来。","烹羊宰牛且为乐，会须一饮三百杯。","岑夫子，丹丘生，将进酒，君莫停。","与君歌一曲，请君为我侧耳听。","钟鼓馔玉不足贵，但愿长醉不愿醒。","古来圣贤皆寂寞，惟有饮者留其名。","陈王昔时宴平乐，斗酒十千恣讙谑。","主人何为言少钱，径须沽取对君酌。","五花马，千金裘，呼儿将出换美酒，与尔同销万古愁。"]},{"id":"T00123","t":"客夜与故人偶集","a":"戴叔伦","c":["天秋月又满，城阙夜千重。","还作江南会，翻疑梦里逢。","风枝惊暗鹊，露草覆寒蛩。","羁旅长堪醉，相留畏晓钟。"]},{"id":"T00124","t":"和张仆射塞下曲 一","a":"卢纶","c":["鹫翎金仆姑，燕尾绣蝥弧。","独立扬新令，千营共一呼。"]},{"id":"T00125","t":"和张仆射塞下曲 二","a":"卢纶","c":["林暗草惊风，将军夜引弓。","平明寻白羽，没在石棱中。"]},{"id":"T00126","t":"和张仆射塞下曲 三","a":"卢纶","c":["月黑鴈飞高，单于夜遁逃。","欲将轻骑逐，大雪满弓刀。"]},{"id":"T00127","t":"和张仆射塞下曲 四","a":"卢纶","c":["野幕敞琼筵，羌戎贺劳旋。","醉和金甲舞，雷鼓动山川。"]},{"id":"T00128","t":"晚次鄂州","a":"卢纶","c":["云开远见汉阳城，犹是孤帆一日程。","估客昼眠知浪静，舟人夜语觉潮生。","三湘衰鬓逢秋色，万里归心对月明。","旧业已随征战尽，更堪江上鼓鼙声。"]},{"id":"T00129","t":"李端公","a":"卢纶","c":["故关衰草遍，离别自堪悲。","路出寒云外，人归暮雪时。","少孤为客早，多难识君迟。","掩泪空相向，风尘何处期。"]},{"id":"T00130","t":"过香积寺","a":"王维","c":["不知香积寺，数里入云峰。","古木无人迳，深山何处钟。","泉声咽危石，日色冷青松。","薄暮空潭曲，安禅制毒龙。"]},{"id":"T00131","t":"山居秋暝","a":"王维","c":["空山新雨后，天气晚来秋。","明月松间照，清泉石上流。","竹喧归浣女，莲动下渔舟。","随意春芳歇，王孙自可留。"]},{"id":"T00132","t":"终南别业","a":"王维","c":["中岁颇好道，晚家南山陲。","兴来每独往，胜事空自知。","行到水穷处，坐看云起时。","偶然值林叟，谈笑无还期。"]},{"id":"T00133","t":"归嵩山作","a":"王维","c":["清川带长薄，车马去闲闲。","流水如有意，暮禽相与还。","荒城临古渡，落日满秋山。","迢递嵩高下，归来且闭关。"]},{"id":"T00134","t":"终南山","a":"王维","c":["太乙近天都，连山接海隅。","白云回望合，青霭入看无。","分野中峰变，阴晴众壑殊。","欲投人处宿，隔水问樵夫。"]},{"id":"T00135","t":"汉江临泛","a":"王维","c":["楚塞三湘接，荆门九派通。","江流天地外，山色有无中。","郡邑浮前浦，波澜动远空。","襄阳好风日，留醉与山翁。"]},{"id":"T00136","t":"奉和圣制从蓬莱向兴庆阁道中留春雨中春望之作应制","a":"王维","c":["渭水自萦秦塞曲，黄山旧遶汉宫斜。","銮舆迥出千门柳，阁道廻看上苑花。","云里帝城双凤阙，雨中春树万人家。","为乘阳气行时令，不是宸游玩物华。"]},{"id":"T00137","t":"和贾舍人早朝大明宫之作","a":"王维","c":["绛帻鸡人送晓筹，尚衣方进翠云裘。","九天阊阖开宫殿，万国衣冠拜冕旒。","日色才临仙掌动，香烟欲傍衮龙浮。","朝罢须裁五色诏，佩声归向凤池头。"]},{"id":"T00138","t":"酬郭给事","a":"王维","c":["洞门高阁霭余辉，桃李阴阴柳絮飞。","禁里疎钟官舍晚，省中啼鸟吏人稀。","晨摇玉佩趋金殿，夕奉天书拜琐闱。","强欲从君无那老，将因卧病解朝衣。"]},{"id":"T00139","t":"积雨辋川庄作","a":"王维","c":["积雨空林烟火迟，蒸藜炊黍饷东菑。","漠漠水田飞白鹭，阴阴夏木啭黄鹂。","山中习静观朝槿，松下清斋折露葵。","野老与人争席罢，海鸥何事更相疑。"]},{"id":"T00140","t":"辋川集 鹿柴","a":"王维","c":["空山不见人，但闻人语响。","返景入深林，复照青苔上。"]},{"id":"T00141","t":"辋川集 竹里馆","a":"王维","c":["独坐幽篁里，弹琴复长啸。","深林人不知，明月来相照。"]},{"id":"T00142","t":"杂诗三首 二","a":"王维","c":["君自故乡来，应知故乡事。","来日绮窗前，寒梅着花未。"]},{"id":"T00143","t":"相思","a":"王维","c":["红豆生南国，秋来发故枝。","愿君多采撷，此物最相思。"]},{"id":"T00144","t":"九月九日忆山东兄弟","a":"王维","c":["独在异乡为异客，每逢佳节倍思亲。","遥知兄弟登高处，遍插茱萸少一人。"]},{"id":"T00145","t":"渭城曲","a":"王维","c":["渭城朝雨浥轻尘，客舍青青杨柳春。","劝君更尽一杯酒，西出阳关无故人。"]},{"id":"T00146","t":"崔九欲往南山马上口号与别","a":"裴迪","c":["归山深浅去，须尽丘壑美。","莫学武陵人，暂游桃源里。"]},{"id":"T00147","t":"寻西山隐者不遇","a":"丘为","c":["绝顶一茅茨，直[上]三十里。","扣关无僮仆，窥室唯案几。","若非巾柴车，应是钓秋水。","差池不相见，黾勉空仰止。","草色新雨中，松声晚牕里。","及兹契幽绝，自足荡心耳。","虽无宾主意，颇得清净理。","兴尽方下山，何必待之子。"]},{"id":"T00148","t":"黄鹤楼","a":"崔颢","c":["昔人已乘白云去，此地空余黄鹤楼。","黄鹤一去不复返，白云千载空悠悠。","晴川历历汉阳树，春草萋萋鹦鹉洲。","日暮乡关何处是，烟波江上使人愁。"]},{"id":"T00149","t":"行经华阴","a":"崔颢","c":["岧嶤太华俯咸京，天外三峰削不成。","武帝祠前云欲散，仙人掌上雨初晴。","河山北枕秦关险，驿树西连汉畤平。","借问路傍名利客，无如此处学长生。"]},{"id":"T00150","t":"长干曲四首 一","a":"崔颢","c":["君家何处住？妾住在横塘。","停船暂借问，或恐是同乡。"]},{"id":"T00151","t":"长干曲四首 二","a":"崔颢","c":["家临九江水，来去九江侧。","同是长干人，自小不相识。"]},{"id":"T00152","t":"望蓟门","a":"祖咏","c":["燕台一望客心惊，箫鼓喧喧汉将营。","万里寒光生积雪，三边曙色动危旌。","沙场烽火连胡月，海畔云山拥蓟城。","少小虽非投笔吏，论功还欲请长缨。"]},{"id":"T00153","t":"终南望余雪","a":"祖咏","c":["终南阴岭秀，积雪浮云端。","林表明霁色，城中增暮寒。"]},{"id":"T00154","t":"古从军行","a":"李颀","c":["白日登山望烽火，黄昏饮马傍交河。","行人刁斗风沙暗，公主琵琶幽怨多。","野云万里无城郭，雨雪纷纷连大漠。","胡鴈哀鸣夜夜飞，胡儿眼泪双双落。","闻道玉门犹被遮，应将性命逐轻车。","年年战骨埋荒外，空见蒲桃入汉家。"]},{"id":"T00155","t":"琴歌","a":"李颀","c":["主人有酒欢今夕，请奏鸣琴广陵客。","月照城头乌半飞，霜凄万树风入衣。","铜𬬻华烛烛增辉，初弹渌水后楚妃。","一声已动物皆静，四座无言星欲稀。","清淮奉使千余里，敢告云山从此始。"]},{"id":"T00156","t":"送陈章甫","a":"李颀","c":["四月南风大麦黄，枣花未落桐阴长。","青山朝别暮还见，嘶马出门思旧乡。","陈侯立身何坦荡，虬须虎眉仍大颡。","腹中贮书一万卷，不肯低头在草莽。","东门酤酒饮我曹，心轻万事皆鸿毛。","醉卧不知白日暮，有时空望孤云高。","长河浪头连天黑，津口停舟渡不得。","郑国游人未及家，洛阳行子空叹息。","闻道故林相识多，罢官昨日今如何。"]},{"id":"T00157","t":"听安万善吹觱篥歌","a":"李颀","c":["南山截竹为觱篥，此乐本自龟兹出。","流传汉地曲转奇，凉州胡人为我吹。","傍邻闻者多叹息，远客思乡皆泪垂。","世人解听不解赏，长飙风中自来往。","枯桑老柏寒飕飗，九雏鸣凤乱啾啾。","龙吟虎啸一时发，万籁百泉相与秋。","忽然更作渔阳掺，黄云萧条白日暗。","变调如闻杨柳春，上林繁花照眼新。","岁夜高堂列明烛，美酒一杯声一曲。"]},{"id":"T00158","t":"古意","a":"李颀","c":["男儿事长征，少小幽燕客。","赌胜马蹄下，由来轻七尺。","杀人莫敢前，须如猬毛磔。","黄云陇底白雪飞，未得报恩不能归。","辽东小妇年十五，惯弹琵琶解歌舞。","今为羗笛出塞声，使我三军泪如雨。"]},{"id":"T00159","t":"听董大弹胡笳声兼寄语弄房给事","a":"李颀","c":["蔡女昔造胡笳声，一弹一十有八拍。","胡人落泪沾边草，汉使断肠对归客。","古戍苍苍烽火寒，大荒沈沈飞雪白。","先拂商弦后角羽，四郊秋叶惊摵摵。","董夫子，通神明，深山窃听来妖精。","言迟更速皆应手，将往复旋如有情。","空山百鸟散还合，万里浮云阴且晴。","嘶酸雏鴈失群夜，断绝胡儿恋母声。","川为净其波，鸟亦罢其鸣。","乌孙部落家乡远，逻娑沙尘哀怨生。","幽音变调忽飘洒，长风吹林雨堕瓦。","迸泉飒飒飞木末，野鹿呦呦走堂下。","长安城连东掖垣，凤凰池对青琐门。","高才脱略名与利，日夕望君抱琴至。"]},{"id":"T00160","t":"送魏万之京","a":"李颀","c":["朝闻游子唱离歌，昨夜微霜初渡河。","鸿鴈不堪愁里听，云山况是客中过。","关城树色催寒近，御苑砧声向晚多。","莫见长安行乐处，空令岁月易蹉跎。"]},{"id":"T00161","t":"春泛若耶溪","a":"綦毋潜","c":["幽意无断绝，此去随所偶。","晚风吹行舟，花路入溪口。","际夜转西壑，隔山望南斗。","潭烟飞溶溶，林月低向后。","生事且弥漫，愿为持竿叟。"]},{"id":"T00162","t":"塞下曲四首 一","a":"王昌龄","c":["蝉鸣空桑林，八月萧关道。","出塞入塞寒，处处黄芦草。","从来幽幷客，皆共尘沙老。","莫学游侠儿，矜夸紫骝好。"]},{"id":"T00163","t":"塞下曲四首 二","a":"王昌龄","c":["饮马渡秋水，水寒风似刀。","平沙日未没，黯黯见临洮。","昔日长城战，咸言意气高。","黄尘足今古，白骨乱蓬蒿。"]},{"id":"T00164","t":"同从弟销南斋玩月忆山阴崔少府","a":"王昌龄","c":["高卧南斋时，开帷月初吐。","清辉淡水木，演漾在窗户。","苒苒几盈虚，澄澄变今古。","美人清江畔，是夜越吟苦。","千里其如何，微风吹兰杜。"]},{"id":"T00165","t":"出塞二首 一","a":"王昌龄","c":["秦时明月汉时关，万里长征人未还。","但使龙城飞将在，不教胡马度阴山。"]},{"id":"T00166","t":"春宫曲","a":"王昌龄","c":["昨夜风开露井桃，未央前殿月轮高。","平阳歌舞新承宠，帘外春寒赐锦袍。"]},{"id":"T00167","t":"闺怨","a":"王昌龄","c":["闺中少妇不曾愁，春日凝妆上翠楼。","忽见陌头杨柳色，悔教夫壻觅封侯。"]},{"id":"T00168","t":"芙蓉楼送辛渐二首 一","a":"王昌龄","c":["寒雨连天夜入湖，平明送客楚山孤。","洛阳亲友如相问，一片冰心在玉壶。"]},{"id":"T00169","t":"宿王昌龄隐居","a":"常建","c":["清溪深不测，隐处唯孤云。","松际露微月，清光犹为君。","茅亭宿花影，药院滋苔纹。","余亦谢时去，西山鸾鹤群。"]},{"id":"T00170","t":"清平调 一","a":"李白","c":["云想衣裳花想容，春风拂槛露华浓。","若非群玉山头见，会向瑶台月下逢。"]},{"id":"T00171","t":"清平调 二","a":"李白","c":["一枝红艳露凝香，云雨巫山枉断肠。","借问汉宫谁得似，可怜飞燕倚新妆。"]},{"id":"T00172","t":"清平调 三","a":"李白","c":["名花倾国两相欢，常得君王带笑看。","解得春风无限恨，沈香亭北倚阑干。"]},{"id":"T00173","t":"还乡偶书  其二","a":"黄拱","c":["少小离家老大回，乡音难改鬓毛衰。","儿童相见不相识，借问客从何处来。"]},{"id":"T00174","t":"长恨歌","a":"白居易","c":["汉皇重色思倾国，御宇多年求不得。","杨家有女初长成，养在深闺人未识。","天生丽质难自弃，一朝选在君王侧。","回眸一笑百媚生，六宫粉黛无颜色。","春寒赐浴华清池，温泉水滑洗凝脂。","侍儿扶起娇无力，始是新承恩泽时。","云鬓花颜金步摇，芙蓉帐暖度春宵。","春宵苦短日高起，从此君王不早朝。","承欢侍宴无闲暇，春从春游夜专夜。","后宫佳丽三千人，三千宠爱在一身。","金屋妆成娇侍夜，玉楼宴罢醉和春。","姊妹弟兄皆列土，可怜光彩生门户。","遂令天下父母心，不重生男重生女。","骊宫高处入青云，仙乐风飘处处闻。","缓歌慢舞凝丝竹，尽日君王看不足。","渔阳鞞鼓动地来，惊破霓裳羽衣曲。","九重城阙烟尘生，千乘万骑西南行。","翠华摇摇行复止，西出都门百余里。","六军不发无奈何，宛转蛾眉马前死。","花钿委地无人收，翠翘金雀玉搔头。","君王掩面救不得，回看血泪相和流。","黄埃散漫风萧索，云栈萦纡登劒阁。","峨嵋山下少人行，旌旗无光日色薄。","蜀江水碧蜀山青，圣主朝朝暮暮情。","行宫见月伤心色，夜雨闻铃肠断声。","天旋日转回龙驭，到此踌躇不能去。","马嵬坡下泥土中，不见玉颜空死处。","君臣相顾尽沾衣，东望都门信马归。","归来池苑皆依旧，太液芙蓉未央柳。","芙蓉如面柳如眉，对此如何不泪垂？","春风桃李花开夜，秋雨梧桐叶落时。","西宫南苑多秋草，宫叶满阶红不埽。","棃园弟子白发新，椒房阿监青娥老。","夕殿萤飞思悄然，孤灯挑尽未成眠。","迟迟钟鼓初长夜，耿耿星河欲曙天。","鸳鸯瓦冷霜华重，翡翠衾寒谁与共。","悠悠生死别经年，魂魄不曾来入梦。","临邛道士鸿都客，能以精诚致魂魄。","为感君王展转思，遂教方士殷勤觅。","排空驭气奔如电，升天入地求之徧。","上穷碧落下黄泉，两处茫茫皆不见。","忽闻海上有仙山，山在虚无缥缈间。","楼阁玲珑五云起，其中绰约多仙子。","中有一人字太真，雪肤花貌参差是。","金阙西厢叩玉扃，转教小玉报双成。","闻道汉家天子使，九华帐里梦魂惊。","揽衣推枕起裴回，珠箔银屏逦迤开。","云鬓半偏新睡觉，花冠不整下堂来。","风吹仙袂飘飖举，犹似霓裳羽衣舞。","玉容寂莫泪阑干，棃花一枝春带雨。","含情凝睇谢君王，一别音容两渺茫。","昭阳殿里恩爱绝，蓬莱宫中日月长。","回头下望人寰处，不见长安见尘雾。","唯将旧物表深情，钿合金钗寄将去。","钗留一股合一扇，钗擘黄金合分钿。","但教心似金钿坚，天上人间会相见。","临别殷勤重寄词，词中有誓两心知。","七月七日长生殿，夜半无人私语时。","在天愿作比翼鸟，在地愿为连理枝。","天长地久有时尽，此恨緜緜无绝期。"]},{"id":"T00175","t":"琵琶引","a":"白居易","c":["浔阳江头夜送客，枫叶荻花秋索索。","主人下马客在船，举酒欲饮无管弦。","醉不成欢惨将别，别时茫茫江浸月。","忽闻水上琵琶声，主人忘归客不发。","寻声暗问弹者谁，琵琶声停欲语迟。","移船相近邀相见，添酒回灯重开宴。","千呼万唤始出来，犹抱琵琶半遮面。","转轴拨弦三两声，未成曲调先有情。","弦弦掩抑声声思，似诉平生不得意。","低眉信手续续弹，说尽心中无限事。","轻拢慢撚抹复挑，初为霓裳后六幺。","大弦嘈嘈如急雨，小弦切切如私语。","嘈嘈切切错杂弹，大珠小珠落玉盘。","间关莺语花底滑，幽咽泉流水下滩。","水泉冷涩弦疑绝，疑绝不通声暂歇。","别有幽愁暗恨生，此时无声胜有声。","银缾乍破水浆迸，铁骑突出刀枪鸣。","曲终收拨当心画，四弦一声如裂帛。","东舟西舫悄无言，唯见江心秋月白。","沈吟放拨插弦中，整顿衣裳起敛容。","自言本是京城女，家在虾蟇陵下住。","十三学得琵琶成，名蜀教坊第一部。","曲罢曾教善才伏，妆成每被秋娘妬。","五陵年少争缠头，一曲红绡不知数。","钿头云箆击节碎，血色罗帬飜酒污。","今年欢笑复明年，秋月春风等闲度。","弟走从军阿姨死，暮去朝来颜色故。","门前冷落鞍马稀，老大嫁作商人妇。","商人重利轻别离，前月浮梁买茶去。","去来江口守空船，绕船月明江水寒。","夜深忽梦少年事，梦啼妆泪红阑干。","我闻琵琶已叹息，又闻此语重唧唧。","同是天涯沦落人，相逢何必曾相识。","我从去年辞帝京，谪居卧病浔阳城。","浔阳小处无音乐，终岁不闻丝竹声。","住近湓江地低湿，黄芦苦竹绕宅生。","其间旦暮闻何物，杜鹃啼血猨哀鸣。","春江花朝秋月夜，往往取酒还独倾。","岂无山歌与村笛，呕哑嘲哳难为听。","今夜闻君琵琶语，如听仙乐耳暂明。","莫辞更坐弹一曲，为君飜作琵琶行。","感我此言良久立，却坐促弦弦转急。","凄凄不似向前声，满座重闻皆掩泣。","座中泣下谁最多，江州司马青衫湿。"]},{"id":"T00176","t":"赋得古原草送别","a":"白居易","c":["离离原上草，一岁一枯荣。","野火烧不尽，春风吹又生。","远芳侵古道，晴翠接荒城。","又送王孙去，萋萋满别情。"]},{"id":"T00177","t":"自河南经乱关内阻饥兄弟离散各在一处因望月有感聊书所怀寄上浮梁大兄於潜七兄乌江十五兄兼示符离及下邽弟妹","a":"白居易","c":["时难年饥世业空，弟兄羇旅各西东。","田园寥落干戈后，骨肉流离道路中。","吊影分为千里鴈，辞根散作九秋蓬。","共看明月应垂泪，一夜乡心五处同。"]},{"id":"T00178","t":"问刘十九","a":"白居易","c":["绿螘新醅酒，红泥小火垆。","晚来天欲雪，能饮一杯无。"]},{"id":"T00179","t":"寻隐者不遇","a":"贾岛","c":["松下问童子，言师采药去。","只在此山中，云深不知处。"]},{"id":"T00180","t":"利州南渡","a":"温庭筠","c":["澹然空水对斜晖，曲岛苍茫接翠微。","波上马嘶看櫂去，柳边人歇待船归。","数丛沙草群鸥散，万顷江田一鹭飞。","谁解乘舟寻范蠡，五湖烟水独忘机。"]},{"id":"T00181","t":"瑶瑟怨","a":"温庭筠","c":["冰簟银床梦不成，碧天如水夜云轻。","雁声远过潇湘去，十二楼中月自明。"]},{"id":"T00182","t":"送人东游","a":"温庭筠","c":["荒戍落黄叶，浩然离故关。","高风汉阳渡，初日郢门山。","江上几人在，天涯孤櫂还。","何当重相见，尊酒慰离颜。"]},{"id":"T00183","t":"苏武庙","a":"温庭筠","c":["苏武魂销汉使前，古祠高树两茫然。","云边雁断胡天月，陇上羊归塞草烟。","廻日楼台非甲帐，去时冠劒是丁年。","茂陵不见封侯印，空向秋波哭逝川。"]},{"id":"T00184","t":"渡汉江","a":"李频","c":["岭外音书绝，经年复历春。","近乡情更怯，不敢问来人。"]},{"id":"T00185","t":"贫女","a":"秦韬玉","c":["蓬门未识绮罗香，拟托良媒益自伤。","谁爱风流高格调，共怜时世俭梳妆。","敢将十指夸偏巧，不把双眉鬬画长。","苦恨年年压金线，为他人作嫁衣裳。"]},{"id":"T00186","t":"春宫怨","a":"周朴","c":["早被婵娟误，欲妆临镜慵。","承恩不在貌，教妾若为容。","风暖鸟声碎，日高花影重。","年年越溪女，相忆采芙蓉。"]},{"id":"T00187","t":"孤鴈 二","a":"崔涂","c":["几行归去尽，片影独何之。","暮雨相呼失，寒塘独下迟。","渚云低暗度，关月冷遥随。","未必逢矰缴，孤飞自可疑。"]},{"id":"T00188","t":"巴山道中除夜书怀","a":"崔涂","c":["迢遰三巴路，羇危万里身。","乱山残雪夜，孤烛异乡春。","渐与骨肉远，转于僮仆亲。","那堪正漂泊，明日岁华新。"]},{"id":"T00189","t":"宫词二首 一","a":"张祜","c":["故国三千里，深宫二十年。","一声河满子，双泪落君前。"]},{"id":"T00190","t":"赠内人","a":"张祜","c":["禁门宫树月痕过，媚眼唯看宿燕窠。","斜拔玉钗灯影畔，剔开红焰救飞蛾。"]},{"id":"T00191","t":"集灵台二首 一","a":"张祜","c":["日光斜照集灵台，红树花迎晓露开。","昨夜上皇新授箓，太真含笑入帘来。"]},{"id":"T00192","t":"集灵台二首 二","a":"张祜","c":["虢国夫人承主恩，平明骑马入宫门。","却嫌脂粉汚颜色，淡扫蛾眉朝至尊。"]},{"id":"T00193","t":"题金陵渡","a":"张祜","c":["金陵津渡小山楼，一宿行人自可愁。","潮落夜江斜月里，两三星火是瓜州。"]},{"id":"T00194","t":"宫词","a":"朱庆余","c":["寂寂花时闭院门，美人相并立琼轩。","含情欲说宫中事，鹦鹉前头不敢言。"]},{"id":"T00195","t":"石鼓歌","a":"韩愈","c":["张生手持石鼓文，劝我试作石鼓歌。","少陵无人谪仙死，才薄将奈石鼓何。","周纲陵迟四海沸，宣王愤起挥天戈。","大开明堂受朝贺，诸侯劒佩鸣相磨。","搜于岐阳骋雄俊，万里禽兽皆遮罗。","镌功勒成告万世，凿石作鼓隳嵯峨。","从臣才艺咸第一，拣选撰刻留山阿。","雨淋日炙野火燎，鬼物守护烦㧑呵。","公从何处得纸本，毫发尽备无差讹。","辞严义密读难晓，字体不类隶与科。","年深岂免有缺画，快劒斫断生蛟鼍。","鸾翔凤翥众僊下，珊瑚碧树交枝柯。","金绳铁索锁纽壮，古鼎跃水龙腾梭。","陋儒编诗不收入，二雅褊迫无委蛇。","孔子西行不到秦，掎摭星宿遗羲娥。","嗟予好古生苦晚，对此涕泪双滂沱。","忆昔初蒙博士徴，其年始改称元和。","故人从军在右辅，为我度量掘臼科。","濯冠沐浴告祭酒，如此至宝存岂多。","氊包席裹可立致，十鼓祗载数骆驼。","荐诸太庙比郜鼎，光价岂止百倍过。","圣恩若许留太学，诸生讲解得切磋。","观经鸿都尚填咽，坐见举国来奔波。","剜苔剔藓露节角，安置妥帖平不颇。","大厦深簷与盖覆，经历久远期无佗。","中朝大官老于事，讵肯感激徒媕婀。","牧童敲火牛砺角，谁复著手为摩挲。","日销月铄就埋没，六年西顾空吟哦。","羲之俗书趁姿媚，数纸尚可博白鹅。","继周八代争战罢，无人收拾理则那。","方今太平日无事，柄任儒术崇丘轲。","安能以此上论列，愿借辨口如悬河。","石鼓之歌止于此，呜呼吾意其蹉跎。"]},{"id":"T00196","t":"秋夜曲","a":"王涯","c":["桂魄初生秋露微，轻罗已薄未更衣。","银筝夜久殷勤弄，心怯空房不忍归。"]},{"id":"T00197","t":"晨诣超师院读禅经","a":"柳宗元","c":["汲井漱寒齿，清心拂尘服。","闲持贝叶书，步出东斋读。","真源了无取，妄迹世所逐。","遗言冀可冥，缮性何由熟。","道人庭宇静，苔色连深竹。","日出雾露余，青松如膏沐。","澹然离言说，悟悦心自足。"]},{"id":"T00198","t":"登柳州城楼寄漳汀封连四州","a":"柳宗元","c":["城上高楼接大荒，海天愁思正茫茫。","惊风乱飐芙蓉水，密雨斜侵薜荔墙。","岭树重遮千里目，江流曲似九廻肠。","共来百越文身地，犹自音书滞一乡。"]},{"id":"T00199","t":"溪居","a":"柳宗元","c":["久为簪组累，幸此南夷谪。","闲依农圃邻，偶似山林客。","晓耕翻露草，夜榜响溪石。","来往不逢人，长歌楚天碧。"]},{"id":"T00200","t":"江雪","a":"柳宗元","c":["千山鸟飞绝，万迳人踪灭。","孤舟蓑笠翁，独钓寒江雪。"]},{"id":"T00201","t":"渔翁","a":"柳宗元","c":["渔翁夜傍西岩宿，晓汲清湘燃楚竹。","烟销日出不见人，[欸]乃一声山水绿。","回看天际下中流，岩上无心云相逐。"]},{"id":"T00202","t":"蜀先主庙","a":"刘禹锡","c":["天地英雄气，千秋尚凛然。","势分三足鼎，业复五铢钱。","得相能开国，生儿不象贤。","凄凉蜀故妓，来舞魏宫前。"]},{"id":"T00203","t":"月夜","a":"杜甫","c":["今夜鄜州月，闺中只独看。","遥怜小儿女，未解忆长安。","香雾云鬟湿，清辉玉臂寒。","何时倚虚幌，双照泪痕干。"]},{"id":"T00204","t":"春望","a":"杜甫","c":["国破山河在，城春草木深。","感时花溅泪，恨别鸟惊心。","烽火连三月，家书抵万金。","白头搔更短，浑欲不胜簪。"]},{"id":"T00205","t":"春宿左省","a":"杜甫","c":["花隐掖垣暮，啾啾栖鸟过。","星临万户动，月傍九霄多。","不寝听金钥，因风想玉珂。","明朝有封事，数问夜如何。"]},{"id":"T00206","t":"至德二载甫自京金光门出问道归凤翔乾元初从左拾遗移华州掾与亲故别因出此门有悲往事","a":"杜甫","c":["此道昔归顺，西郊胡正繁。","至今残破胆，应有未招魂。","近得归京邑，移官岂至尊。","无才日衰老，驻马望千门。"]},{"id":"T00207","t":"月夜忆舍弟","a":"杜甫","c":["戍鼓断人行，秋边一雁声。","露从今夜白，月是故乡明。","有弟皆分散，无家问死生。","寄书长不避，况乃未休兵。"]},{"id":"T00208","t":"天末忆李白","a":"杜甫","c":["凉风起天末，君子意如何。","鸿雁几时到，江湖秋水多。","文章憎命达，魑魅喜人过。","应共冤魂语，投诗赠汩罗。"]},{"id":"T00209","t":"蜀相","a":"杜甫","c":["丞相祠堂何处寻，锦官城外柏森森。","映堦碧草自春色，隔叶黄鹂空好音。","三顾频烦天下计，两朝开济老臣心。","出师未捷身先死，长使英雄泪满襟。"]},{"id":"T00210","t":"客至","a":"杜甫","c":["舍南舍北皆春水，但见群鸥日日来。","花径不曾缘客扫，蓬门今始为君开。","盘餐市远无兼味，樽酒家贫只旧醅。","肯与邻翁相对饮，隔篱呼取尽余桮。"]},{"id":"T00211","t":"野望","a":"杜甫","c":["西山白雪三奇戍，南浦清江万里桥。","海内风尘诸弟隔，天涯涕泪一身遥。","唯将迟暮供多病，未有涓埃荅圣朝。","跨马出郊时极目，不堪人事日萧条。"]},{"id":"T00212","t":"奉济驿重送严公四韵","a":"杜甫","c":["远送从此别，青山空复情。","几时桮重把，昨夜月同行。","列郡讴歌惜，三朝出入荣。","江村独归处，寂寞养残生。"]},{"id":"T00213","t":"闻官军收河南河北","a":"杜甫","c":["劒外忽传收蓟北，初闻涕泪满衣裳。","却看妻子愁何在，漫卷诗书喜欲狂。","白日放歌须纵酒，青春作伴好还乡。","即从巴峡穿巫峡，便下襄阳向洛阳。"]},{"id":"T00214","t":"登高","a":"杜甫","c":["风急天高猨啸哀，渚清沙白鸟飞回。","无边落木萧萧下，不尽长江衮衮来。","万里悲秋常作客，百年多病独登台。","艰难苦恨繁霜鬓，潦倒新停浊酒桮。"]},{"id":"T00215","t":"别房太尉墓","a":"杜甫","c":["他乡复行役，驻马别孤坟。","近泪无干土，低空有断云。","对碁陪谢傅，把劒觅徐君。","唯见林花落，鸎啼送客闻。"]},{"id":"T00216","t":"登楼","a":"杜甫","c":["花近高楼伤客心，万方多难此登临。","锦江春色来天地，玉垒浮云变古今。","北极朝廷终不改，西山寇盗莫相侵。","可怜后主还祠庙，日暮聊为梁甫吟。"]},{"id":"T00217","t":"宿府","a":"杜甫","c":["清秋幕府井梧寒，独宿江城蜡炬残。","永夜角声悲自语，中天月色好谁看。","风尘荏苒音书绝，关塞萧条行路难。","已忍伶俜十年事，强移栖息一枝安。"]},{"id":"T00218","t":"旅夜书怀","a":"杜甫","c":["细草微风岸，危樯独夜舟。","星垂平野阔，月涌大江流。","名岂文章著，官因老病休。","飘飘何所似，天地一沙鸥。"]},{"id":"T00219","t":"阁夜","a":"杜甫","c":["岁暮阴阳催短景，天涯霜雪霁寒宵。","五更鼓角声悲壮，三峡星河影动摇。","野哭几家闻战伐，夷歌数处起渔樵。","卧龙跃马终黄土，人事依依漫寂寥。"]},{"id":"T00220","t":"八阵图","a":"杜甫","c":["功盖三分国，名高八阵图。","江流石不转，遗恨失吞吴。"]},{"id":"T00221","t":"咏怀古迹五首 一","a":"杜甫","c":["支离东北风尘际，漂泊西南天地间。","三峡楼台淹日月，五溪衣服共云山。","羯胡事主终无赖，词客衰时且未还。","庾信平生最萧瑟，暮年诗赋动江关。"]},{"id":"T00222","t":"咏怀古迹五首 二","a":"杜甫","c":["摇落深知宋玉悲，风流儒雅亦吾师。","怅望千秋一洒泪，萧条异代不同时。","江山故宅空文藻，云雨荒台岂梦思。","最是楚宫俱泯灭，舟人指点到今疑。"]},{"id":"T00223","t":"咏怀古迹五首 三","a":"杜甫","c":["群山万壑赴荆门，生长明妃尚有村。","一去紫台连朔漠，独留青冢向黄昏。","画图省识春风面，环佩空归月夜魂。","千载琵琶作胡语，分明怨恨曲中论。"]},{"id":"T00224","t":"咏怀古迹五首 四","a":"杜甫","c":["蜀主窥吴幸三峡，崩年亦在永安宫。","翠华想像空山里，玉殿虚无野寺中。","古庙杉松巢水鹤，岁时伏腊走村翁。","武侯祠屋常邻近，一体君臣祭祀同。"]},{"id":"T00225","t":"咏怀古迹五首 五","a":"杜甫","c":["诸葛大名垂宇宙，宗臣遗像肃清高。","三分割据纡筹策，万古云霄一羽毛。","伯仲之间见伊吕，指挥若定失萧曹。","福移汉祚难恢复，志决身歼军务劳。"]},{"id":"T00226","t":"江南逢李龟年","a":"杜甫","c":["歧王宅里寻常见，崔九堂前几度闻。","正是江南好风景，落花时节又逢君。"]},{"id":"T00227","t":"登岳阳楼","a":"杜甫","c":["昔闻洞庭水，今上岳阳楼。","吴楚东南坼，乾坤日夜浮。","亲朋无一字，老病有孤舟。","戎马关山北，凭轩涕泗流。"]},{"id":"T00228","t":"虢国夫人","a":"杜甫","c":["虢国夫人承主恩，平明上马入宫门。","却嫌脂粉涴颜色，澹埽蛾眉朝至尊。"]},{"id":"T00229","t":"望月怀远","a":"张九龄","c":["海上生明月，天涯共此时。","情人怨遥夜，竟夕起相思。","灭烛怜光满，披衣觉露滋。","不堪盈手赠，还寝梦佳期。"]},{"id":"T00230","t":"题大庾岭北驿","a":"宋之问","c":["阳月南飞雁，传闻至此回。","我行殊未已，何日复归来？江静潮初落，林昏瘴不开。","明朝望乡处，应见陇头梅。"]},{"id":"T00231","t":"渡汉江","a":"宋之问","c":["岭外音书断，经冬复历春。","近乡情更怯，不敢问来人。"]},{"id":"T00232","t":"新年作","a":"宋之问","c":["乡心新岁切，天畔独澘然。","老至居人下，春归在客先。","岭猨同旦暮，江柳共风烟。","已似长沙傅，从今又几年。"]},{"id":"T00233","t":"杜少府之任蜀州","a":"王勃","c":["城阙辅三秦，风烟望五津。","与君离别意，同是宦游人。","海内存知己，天涯若比隣。","无为在岐路，儿女共沾巾。"]},{"id":"T00234","t":"和晋陵陆丞早春游望","a":"杜审言","c":["独有宦游人，偏惊物候新。","云霞出海曙，梅柳渡江春。","淑气催黄鸟，晴光转绿苹。","忽闻歌古调，归思欲沾巾。"]},{"id":"T00235","t":"登楼","a":"朱斌","c":["白日依山尽，黄河入海流。","欲穷千里目，更上一层楼。"]},{"id":"T00236","t":"送李少府贬峡中王少府贬长沙","a":"高适","c":["嗟君此别意何如，驻马衔桮问谪居。","巫峡啼猿数行泪，衡阳归雁几封书。","青枫江上秋天远，白帝城边古木疎。","圣代即今多雨露，暂时分手莫踌躇。"]},{"id":"T00237","t":"望岳","a":"杜甫","c":["岱宗夫如何，齐鲁青未了。","造化钟神秀，阴阳割昏晓。","荡胷生曾云，决眦入归鸟。","会当凌绝顶，一览众山小。"]},{"id":"T00238","t":"兵车行","a":"杜甫","c":["车辚辚，马萧萧，行人弓箭各在腰。","耶娘妻子走相送，尘埃不见咸阳桥。","牵衣顿足阑道哭，哭声直上干云霄。","道傍过者问行人，行人但云点行频。","或从十五北防河，便至四十西营田。","去时里正与裹头，归来头白还戍边。","边亭流血成海水，武皇开边意未已。","君不闻汉家山东二百州，千村万落生荆杞。","纵有健妇把锄犂，禾生陇亩无东西。","况复秦兵耐苦战，被驱不异犬与鸡。","长者虽有问，役夫敢申恨。","且如今年冬，未休关西卒。","县官急索租，租税从何出？信知生男恶，反是生女好。","生女犹是嫁比邻，生男埋没随百草。","君不见青海头，古来白骨无人收。","新鬼烦冤旧鬼哭，天阴雨湿声啾啾。"]},{"id":"T00239","t":"赠卫八处士","a":"杜甫","c":["人生不相见，动如参与商。","今夕复何夕，共此灯烛光。","少壮能几时，鬓发各已苍。","访旧半为鬼，惊呼热中肠。","焉知二十载，重上君子堂。","昔别君未婚，儿女忽成行。","怡然敬父执，问我来何方。","问荅乃未已，儿女罗酒浆。","夜雨剪春韭，新炊间黄粱。","主称会面难，一举累十觞。","十觞亦不醉，感子故意长。","明日隔山岳，世事两茫茫。"]},{"id":"T00240","t":"丽人行","a":"杜甫","c":["三月三日天气新，长安水边多丽人。","态浓意远淑且真，肌理细腻骨肉匀。","绣罗衣裳照暮春，蹙金孔雀银麒麟。","头上何所有，翠微㔩叶垂鬓唇。","背后何所见，珠压腰衱稳称身。","就中云幕椒房亲，赐名大国虢与秦。","紫驼之峰出翠釜，水精之盘行素鳞。","犀箸厌饫久未下，銮刀缕切空纷纶。","黄门飞鞚不动尘，御厨络绎送八珍。","箫鼓哀吟感鬼神，宾从杂遝实要津。","后来鞍马何逡巡，当轩下马入锦茵。","杨花雪落覆白苹，青鸟飞去衔红巾。","炙手可热势绝伦，慎莫近前丞相嗔。"]},{"id":"T00241","t":"哀江头","a":"杜甫","c":["少陵野老吞声哭，春日潜行曲江曲。","江头宫殿锁千门，细柳新蒲为谁绿。","忆昔霓旌下南苑，苑中万物生颜色。","昭阳殿里第一人，同辇随君侍君侧。","辇前才人带弓箭，白马嚼啮黄金勒。","翻身向天仰射云，一箭正坠双飞翼。","明眸皓齿今何在，血污游魂归不得。","清渭东流劒阁深，去住彼此无消息。","人生有情泪沾臆，江水江花岂终极。","黄昏胡骑尘满城，欲往城南忘南北。"]},{"id":"T00242","t":"哀王孙","a":"杜甫","c":["长安城头头白乌，夜飞延秋门上呼。","又向人家啄大屋，屋底达官走避胡。","金鞭断折九马死，骨肉不待同驰驱。","腰下实玦青珊瑚，可怜王孙泣路隅。","问之不肯道姓名，但道困苦乞为奴。","已经百日窜荆棘，身上无有完肌肤。","高帝子孙尽隆准，龙种自与常人殊。","豺狼在邑龙在野，王孙善保千金躯。","不敢长语临交衢，且为王孙立斯须。","昨夜东风吹血腥，东来橐驼满旧都。","朔方健儿好身手，昔何勇锐今何愚。","窃闻天子已传位，贤德北服南单于。","花门剺面请雪耻，慎勿出口他人狙。","哀哉王孙慎勿疎，五陵佳气无时无。"]},{"id":"T00243","t":"佳人","a":"杜甫","c":["绝代有佳人，幽居在空谷。","自云良家子，零落依草木。","关中昔丧败，兄弟遭杀戮。","官高何足论，不得收骨肉。","世情恶衰歇，万事随转烛。","夫壻轻薄儿，新人已如玉。","合昏尚知时，鸳鸯不独宿。","但见新人笑，那闻旧人哭。","在山泉水清，出山泉水浊。","侍婢卖珠回，牵萝补茅屋。","摘花不插发，采柏动盈匊。","天寒翠袖薄，日暮倚修竹。"]},{"id":"T00244","t":"梦李白二首 一","a":"杜甫","c":["死别已吞声，生别常恻恻。","江南瘴疠地，逐客无消息。","故人入我梦，明我长相忆。","恐非平生魂，路远不可测。","魂来枫叶青，魂返关塞黑。","君今在罗网，何以有羽翼。","落月满屋梁，犹疑照颜色。","水深波浪阔，无使蛟龙得。"]},{"id":"T00245","t":"梦李白二首 二","a":"杜甫","c":["浮云终日行，游子久不至。","三夜频梦君，情亲见君意。","告归常局促，苦道来不易。","江湖多风波，舟楫恐失坠。","出门搔白首，若负平生志。","冠盖满京华，斯人独顦顇。","孰云网恢恢，将老身反累。","千秋万岁名，寂莫身后事。"]},{"id":"T00246","t":"韦讽录事宅观曹将军画马图","a":"杜甫","c":["国初已来画鞍马，神妙独数江都王。","将军得名三十载，人间又见真乘黄。","曾貌先帝照夜白，龙池十日飞霹雳。","内府殷红马脑盌，倢伃传诏才人索。","盌赐将军拜舞归，轻纨细绮相追飞。","贵戚权门得笔迹，始觉屏障生光辉。","昔日太宗拳毛䯄，近时郭家师子花。","今之新图有二马，复令识者久叹嗟。","此皆骑战一敌万，缟素漠漠开风沙。","其余七匹亦殊绝，迥若寒空动烟雪。","霜蹄蹴踏长楸间，马官厮养森成列。","可怜九马争神骏，顾视清高气深稳。","借问苦心爱者谁，后有韦讽前支遁。","忆昔巡幸新丰宫，翠华拂天来向东。","腾骧磊落三万匹，皆与此图筋骨同。","自从献宝朝河宗，无复射蛟江水中。","君不见金粟堆前松柏里，龙媒去尽鸟呼风。"]},{"id":"T00247","t":"丹青引赠曹将军霸","a":"杜甫","c":["将军魏武之子孙，于今为庶为清门。","英雄割据虽已矣，文彩风流犹尚存。","学书初学卫夫人，但恨无过王右军。","丹青不知老将至，富贵于我如浮云。","开元之中常引见，承恩数上南熏殿。","凌烟功臣少颜色，将军下笔开生面。","良相头上进贤冠，猛将腰间大羽箭。","褒公鄂公毛发动英姿飒爽来酣战。","先帝天马玉花骢，画工如山貌不同。","是日牵来赤墀下，迥立阊阖生长风。","诏谓将军拂绢素，意匠惨澹经营中。","斯须九重真龙出，一洗万古凡马空。","玉花却在御榻上，榻上庭前屹相向。","至尊含笑催赐金，圉人太仆皆惆怅。","弟子韩干早入室，亦能画马穷殊相。","干惟画肉不画骨，忍使骅骝气凋丧。","将军画善盖有神，必逢佳士亦写真。","即今飘泊干戈际，屡貌寻常行路人。","途穷反遭俗眼白，世上未有如公贫。","但看古来盛名下，终日坎𡒄缠其身。"]},{"id":"T00248","t":"寄韩谏议","a":"杜甫","c":["今我不乐思岳阳，身欲奋飞病在床。","美人娟娟隔秋水，濯足洞庭望八荒。","鸿飞冥冥日月白，青枫叶赤天雨霜。","玉京群帝集北斗，或骑骐𬴊翳凤皇。","芙蓉旌旗烟雾乐，影动倒景摇潇湘。","星宫之君醉琼浆，羽人稀少不在旁。","似闻昨者赤松子，恐是汉代韩张良。","昔随刘氏定长安，帷幄未改神惨伤。","国家成败吾岂敢，色难腥腐餐风香。","周南留滞古所惜，南极老人应寿昌。","美人胡为隔秋水，焉得置之贡玉堂。"]},{"id":"T00249","t":"古柏行","a":"杜甫","c":["孔明庙前有老柏，柯如青铜根如石。","霜皮溜雨四十围，黛色参天二千尺。","君臣已与时际会，树木犹为人爱惜。","云来气接巫峡长，月出寒通雪山白。","忆昨路绕锦亭东，先主武侯同閟宫。","崔嵬枝干郊原古，窈窕丹青户牖空。","落落盘踞虽得地，冥冥孤高多烈风。","扶持自是神明力，正直原因造化功。","大厦如倾要梁栋，万牛回首丘山重。","不露文章世已惊，未辞剪伐谁能送。","苦心岂免容蝼蚁，香叶终经宿鸾凤。","志士幽人莫怨嗟，古来材大难为用。"]},{"id":"T00250","t":"观公孙大娘弟子舞劒器行","a":"杜甫","c":["昔有佳人公孙氏，一舞劒气动四方。","观者如山色沮丧，天地为之久低昂。","㸌如羿射九日落，矫如群帝骖龙翔。","来如雷霆收震怒，罢如江海凝清光。","绛唇珠袖两寂莫，况有弟子传芬芳。","临颍美人在白帝，妙舞此曲神扬扬。","与余问答既有以，感时抚事增惋伤。","先帝侍女八千人，公孙劒器初第一。","五十年间似反掌，风尘倾动昏王室。","棃园子弟散如烟，女乐余姿映寒日。","金粟堆南木已拱，瞿唐石城草萧瑟。","玳筵急管曲复终，乐极哀来月东出。","老夫不知其所往，足茧荒山转愁疾。"]},{"id":"T00251","t":"寄人二首  其一","a":"张佖","c":["别梦依依到谢家，小廊回合曲阑斜。","多情只有春庭月，犹为离人照落花。"]},{"id":"T00252","t":"杂曲歌辞 盖罗缝 一","a":"不详","c":["秦时明月汉时关，万里征人尚未还。","但愿龙庭神将在，不教胡马渡阴山。"]},{"id":"T00253","t":"杂曲歌辞 婆罗门","a":"杨敬述进","c":["回乐峰前沙似雪，受降城外月如霜。","不知何处吹芦管？一夜征人尽望乡。"]},{"id":"T00254","t":"杂曲歌辞 清平调 一","a":"李白","c":["云想衣裳花想容，春风拂槛露华浓。","若非群玉山头见，会向瑶台月下逢。"]},{"id":"T00255","t":"杂曲歌辞 清平调 二","a":"李白","c":["一枝红艳露凝香，云雨巫山枉断肠。","借问汉宫谁得似，可怜飞燕倚新妆。"]},{"id":"T00256","t":"杂曲歌辞 清平调 三","a":"李白","c":["名花倾国两相欢，长得君王带笑看。","解释春风无限恨，沈香亭北倚阑干。"]},{"id":"T00257","t":"杂曲歌辞 渭城曲","a":"王维","c":["谓城朝雨浥轻尘，客舍青青柳色春。","劝君更尽一杯酒，西出阳关无故人。"]},{"id":"T00258","t":"杂曲歌辞 金缕衣","a":"不详","c":["劝君莫惜金缕衣，劝君惜取少年时。","花开堪折直须折，莫待无花空折枝。"]},{"id":"T00259","t":"感遇十二首 一","a":"张九龄","c":["兰叶春葳蕤，桂华秋皎洁。","欣欣此生意，自尔为佳节。","谁知林栖者，闻风坐相悦。","草木有本心，何求美人折。"]},{"id":"T00260","t":"感遇十二首 二","a":"张九龄","c":["幽林归独卧，滞虑洗孤清。","持此谢高鸟，因之传远情。","日夕怀空意，人谁感至精。","飞沈理自隔，何所慰吾诚。"]},{"id":"T00261","t":"感遇十二首 四","a":"张九龄","c":["孤鸿海上来，池潢不敢顾。","侧见双翠鸟，巢在三珠树。","矫矫珍木巅，得无金丸惧。","美服患人指，高明逼神恶。","今我游冥冥，弋者何所慕。"]},{"id":"T00262","t":"感遇十二首 七","a":"张九龄","c":["江南有丹橘，经冬犹绿林。","岂伊地气暖，自有岁寒心。","可以荐嘉客，奈何阻重深。","运命唯所遇，循环不可寻。","徒言树桃李，此木岂无阴。"]},{"id":"T00263","t":"寻陆鸿渐不遇","a":"皎然","c":["移家虽带郭，野径入桑麻。","近种篱边菊，秋来未著花。","扣门无犬吠，欲去问西家。","报道山中去，归时每日斜。"]},{"id":"T00264","t":"西塞山怀古","a":"刘禹锡","c":["西晋楼船下益州，金陵王气黯然收。","千寻铁锁沈江底，一片降旛出石头。","人世几回伤往事，山形依旧枕江流。","今逢四海为家日，故垒萧萧芦荻秋。"]},{"id":"T00265","t":"金陵五题 乌衣巷","a":"刘禹锡","c":["朱雀桥边野草花，乌衣巷口夕阳斜。","旧时王谢堂前燕，飞入寻常百姓家。"]},{"id":"T00266","t":"和乐天春词","a":"刘禹锡","c":["新妆面面下朱楼，深锁春光一院愁。","行到中庭数花朵，蜻蜓飞上玉搔头。"]},{"id":"T00267","t":"列女操","a":"孟郊","c":["梧桐相待老，鸳鸯会双死。","贞女贵狥夫，舍生亦如此。","波澜誓不起，妾心井中水。"]},{"id":"T00268","t":"游子吟","a":"孟郊","c":["慈母手中线，游子身上衣。","临行密密缝，意恐迟迟归。","谁言寸草心，报得三春晖。"]},{"id":"T00269","t":"度南涧","a":"蔡襄","c":["隠隠飞桥隔野烟，石矶西畔问渔船。","桃花尽日随流水，洞在清溪何处边。"]},{"id":"T00270","t":"谷口书斋寄杨补阙","a":"钱起","c":["泉壑带茅茨，云霞生薜帷。","竹怜新雨后，山爱夕阳时。","闲鹭栖常早，秋花落更迟。","家童扫萝迳，昨与故人期。"]},{"id":"T00271","t":"送僧归日本","a":"钱起","c":["上国随缘住，来途若梦行。","浮天沧海远，去世法舟轻。","水月通禅观，鱼龙听梵声。","惟怜一灯影，万里眼中明。"]},{"id":"T00272","t":"赠阙下裴舍人","a":"钱起","c":["二月黄莺飞上林，春城紫禁晓阴阴。","长乐钟声花外尽，龙池柳色雨中深。","阳和不散穷途恨，霄汉长怀捧日新。","献赋十年犹未遇，羞将白发对华簪。"]},{"id":"T00273","t":"和张仆射塞下曲","a":"钱起","c":["月黑雁飞高，单于夜遁逃。","欲将轻骑逐，大雪满弓刀。"]},{"id":"T00274","t":"贼退示官吏","a":"元结","c":["昔岁逢太平，山林二十年。","泉源在庭户，洞壑当门前。","井税有常期，日[晏]犹得眠。","忽然遭世变，数岁亲戎旃。","今来典斯郡，山夷又纷然。","城小贼不屠，人贫伤可怜。","是以陷隣境，此州独见全。","使臣将王命，岂不如贼焉。","今彼徴敛者，迫之如火煎。","谁能绝人命，以作时世贤。","思欲委符节，引竿自刺船。","将家就鱼麦，归老江湖边。"]},{"id":"T00275","t":"石鱼湖上醉歌","a":"元结","c":["石鱼湖，似洞庭，夏水欲满君山青。","山为樽，水为沼，酒徒历历坐洲岛。","长风连日作大浪，不能废人运酒舫。","我持长瓢坐巴丘，酌饮四坐以散愁。"]},{"id":"T00276","t":"枫桥夜泊","a":"张继","c":["月落乌啼霜满天，江枫渔父对愁眠。","姑苏城外寒山寺，夜半钟声到客船。"]},{"id":"T00277","t":"酬程延秋夜即事见赠","a":"韩翃","c":["长簟迎风早，空城澹月华。","星河秋一雁，砧杵夜千家。","节候看应晚，心期卧亦赊。","向来吟秀句，不觉已鸣鸦。"]},{"id":"T00278","t":"同题仙游观","a":"韩翃","c":["仙台下见五城楼，风物凄凄宿雨收。","山色遥连秦树晚，砧声近报汉宫秋。","疎松影落空坛静，细草香闲小洞幽。","何用别寻方外去，人间亦自有丹丘。"]},{"id":"T00279","t":"寒食","a":"韩翃","c":["春城无处不飞花，寒食东风御柳斜。","日暮汉宫传蜡烛，轻烟散入五侯家。"]},{"id":"T00280","t":"寄李儋元锡","a":"韦应物","c":["去年花里逢君别，今日花开已一年。","世事茫茫难自料，春愁黯黯独成眠。","身多疾病思田里，邑有流亡愧俸钱。","闻道欲来相问讯，西楼望月几廻圆。"]},{"id":"T00281","t":"寄全椒山中道士","a":"韦应物","c":["今朝郡斋冷，忽念山中客。","涧底束荆薪，归来煮白石。","欲持一瓢酒，远慰风雨夕。","落叶满空山，何处寻行迹。"]},{"id":"T00282","t":"秋夜寄丘二十二员外","a":"韦应物","c":["怀君属秋夜，散步咏凉天。","山空松子落，幽人应未眠。"]},{"id":"T00283","t":"赋得暮雨送李胄","a":"韦应物","c":["楚江微雨里，建业暮钟时。","漠漠帆来重，冥冥鸟去迟。","海门深不见，浦树远含滋。","相送情无限，沾襟比散丝。"]},{"id":"T00284","t":"送杨氏女","a":"韦应物","c":["永日方戚戚，出门复悠悠。","女子今有行，大江溯轻舟。","尔辈况无恃，抚念益慈柔。","幼为长所育，两别泣不休。","对此结中肠，义往难复留。","自小阙内训，事姑贻我忧。","赖兹托令门，仁恤庶无尤。","贫俭诚所尚，资从岂待周。","孝恭遵妇道，容止顺其猷。","别离在今晨，见尔当何秋。","居闲始自遣，临感忽难收。","归来视幼女，零泪缘缨流。"]},{"id":"T00285","t":"长安遇冯著","a":"韦应物","c":["客从东方来，衣上灞陵雨。","问客何为来，采山因买斧。","冥冥花正开，飏飏燕新乳。","昨别今已春，鬓丝生几缕。"]},{"id":"T00286","t":"夕次盱眙县","a":"韦应物","c":["落帆逗淮镇，停舫临孤驿。","浩浩风起波，冥冥日沈夕。","人归山郭暗，雁下芦洲白。","独夜忆秦关，听钟未眠客。"]},{"id":"T00287","t":"东郊","a":"韦应物","c":["吏舍跼终年，出郊旷清曙。","杨柳散和风，青山澹吾虑。","依丛适自憩，缘涧还复去。","微雨霭芳原，春鸠鸣何处？乐幽心屡止，遵事迹犹遽。","终罢斯结庐，慕陶真可庶。"]},{"id":"T00288","t":"滁州西涧","a":"韦应物","c":["独怜幽草涧边生，上有黄鹂深树鸣。","春潮带雨晚来急，野渡无人舟自横。"]},{"id":"T00289","t":"和晋陵陆丞早春游望","a":"韦应物","c":["独有宦游人，偏惊物候新。","云霞出海曙，梅柳渡江春。","淑气催黄鸟，晴光照绿苹。","忽闻歌苦调，归思欲沾巾。"]},{"id":"T00290","t":"与高适薛据慈恩寺浮图","a":"岑参","c":["塔势如涌出，孤高耸天宫。","登临出世界，磴道盘虚空。","突兀压神州，峥嵘如鬼工。","四角碍白日，七层摩苍穹。","下窥指高鸟，俯听闻惊风。","连山若波涛，奔凑似朝东。","青槐夹驰道，宫馆何玲珑。","秋色从西来，苍然满关中。","五陵北原上，万古青蒙蒙。","净理了可悟，胜因夙所宗。","誓将挂冠去，觉道资无穷。"]},{"id":"T00291","t":"白雪歌送武判官归京","a":"岑参","c":["北风卷地白草折，胡天八月即飞雪。","忽然一夜春风来，千树万树梨花开。","散入珠帘湿罗幕，狐裘不煖锦衾薄。","将军角弓不得控，都护铁衣冷难着。","瀚海阑干百丈冰，愁云黪淡万里凝。","中军置酒饮归客，胡琴琵琶与羌笛。","纷纷暮雪下辕门，风掣红旗冻不翻。","轮台东门送君去，去时雪满天山路。","山回路转不见君，雪上空留马行处。"]},{"id":"T00292","t":"轮台歌奉送封大夫出师西征","a":"岑参","c":["轮台城头夜吹角，轮台城北旄头落。","羽书昨夜过渠黎，单于已在金山西。","戍楼西望烟尘黑，汉兵屯在轮台北。","上将拥旄西出征，平明吹笛大军行。","四边伐鼓雪海涌，三军大呼阴山动。","虏塞兵气连云屯，战场白骨缠草根。","劒河风急雪片阔，沙口石冻马蹄脱。","亚相勤王甘苦辛，誓将报主静边尘。","古来青史谁不见，今见功名胜古人。"]},{"id":"T00293","t":"走马川行奉送出师西征","a":"岑参","c":["君不见走马川行雪海边，平沙莽莽黄入天。","轮台九月风夜吼，一川碎石大如斗，随风满地石乱走。","匈奴草黄马正肥，金山西见烟尘飞。","汉家大将西出师，将军金甲夜不脱。","半夜军行戈相拨，风头如刀面如割。","马毛带雪汗气蒸，五花连钱旋作冰。","幕中草檄砚水凝，虏骑闻之应胆慑。","料知短兵不敢接，车师西门伫献捷。"]},{"id":"T00294","t":"寄左省杜拾遗","a":"岑参","c":["联步趋丹陛，分曹限紫微。","晓随天仗入，暮惹御香归。","白发悲花落，青云羡鸟飞。","圣朝无阙事，自觉谏书稀。"]},{"id":"T00295","t":"奉和中书舍人贾至早朝大明宫","a":"岑参","c":["鸡鸣紫陌曙光寒，莺啭皇州春色阑。","金阙晓钟开万户，玉阶仙仗拥千官。","花迎劒珮星初落，柳拂旌旗露未干。","独有凤皇池上客，阳春一曲和皆难。"]},{"id":"T00296","t":"逢入京使","a":"岑参","c":["故园东望路漫漫，双袖龙钟泪不干。","马上相逢无纸笔，凭君传语报平安。"]},{"id":"T00297","t":"访羊尊师","a":"孙革","c":["松下问童子，言师采药去。","只在此山中，云深不知处。"]},{"id":"T00298","t":"书边事","a":"张乔","c":["调角断清秋，征人倚戍楼。","春风对青冢，白日落梁州。","大汉无兵阻，穷边有客游。","蕃情似此水，长愿向南流。"]},{"id":"T00299","t":"行路难三首 一","a":"李白","c":["金樽清酒斗十千，玉盘珍羞直万钱。","停杯投筯不能食，拔劒四顾心茫然。","欲渡黄河冰塞川，将登太行雪满山。","闲来垂钓碧溪上，忽复乘舟梦日边。","行路难，行路难，多岐路，今安在。","长风破浪会有时，直挂云帆济沧海。"]},{"id":"T00300","t":"行路难三首 二","a":"李白","c":["大道如青天，我独不得出。","羞逐长安社中儿，赤鸡白狗赌梨栗。","弹劒作歌奏苦声，曳裾王门不称情。","淮阴市井笑韩信，汉朝公卿忌贾生。","君不见昔时燕家重郭隗，拥篲折节无嫌猜。","剧辛乐毅感恩分，输肝剖胆效英才。","昭王白骨萦烂草，谁人更扫黄金台。","行路难，归去来。"]},{"id":"T00301","t":"行路难三首 三","a":"李白","c":["有耳莫洗颍川水，有口莫食首阳蕨。","含光混世贵无名，何用孤高比云月。","吾观自古贤达人，功成不退皆殒身。","子胥既弃吴江上，屈原终投湘水滨。","陆机雄才岂自保，李斯税驾苦不早。","华亭鹤唳讵可闻，上蔡苍鹰何足道。","君不见吴中张翰称达生，秋风忽忆江东行。","且乐生前一杯酒，何须身后千载名。"]},{"id":"T00302","t":"长相思","a":"李白","c":["长相思，在长安，络纬秋啼金井阑。","微霜凄凄簟色寒，孤灯不明思欲绝。","卷帷望月空长叹，美人如花隔云端。","上有青冥之长天，下有渌水之波澜。","天长路远魂飞苦，梦魂不到关山难。","长相思，摧心肝。"]},{"id":"T00303","t":"关山月","a":"李白","c":["明月出天山，苍茫云海间。","长风几万里，吹度玉门关。","汉下白登道，胡窥青海湾。","由来征战地，不见有人还。","[戍]客望边色，思归多苦颜。","高楼当此夜，叹息未应闲。"]},{"id":"T00304","t":"玉阶怨","a":"李白","c":["玉阶生白露，夜久侵罗袜。","却下水晶帘，玲珑望秋月。"]},{"id":"T00305","t":"清平调词三首 一","a":"李白","c":["云想衣裳花想容，春风拂槛露华浓。","若非群玉山头见，会向瑶台月下逢。"]},{"id":"T00306","t":"清平调词三首 二","a":"李白","c":["一枝秾艳露凝香，云雨巫山枉断肠。","借问汉宫谁得似，可怜飞燕倚新妆。"]},{"id":"T00307","t":"静夜思","a":"李白","c":["床前看月光，疑是地上霜。","举头望山月，低头思故乡。"]},{"id":"T00308","t":"春思","a":"李白","c":["燕草如碧丝，秦桑低绿枝。","当君怀归日，是妾断肠时。","春风不相识，何事入罗帏。"]},{"id":"T00309","t":"子夜吴歌 春歌","a":"李白","c":["秦地罗敷女，采桑绿水边。","素手青条上，红妆白日鲜。","蚕饥妾欲去，五马莫留连。"]},{"id":"T00310","t":"子夜吴歌 夏歌","a":"李白","c":["镜湖三百里，菡萏发荷花。","五月西施采，人看隘若耶。","回舟不待月，归去越王家。"]},{"id":"T00311","t":"子夜吴歌 秋歌","a":"李白","c":["长安一片月，万户捣衣声。","秋风吹不尽，总是玉关情。","何日平胡虏，良人罢远征。"]},{"id":"T00312","t":"子夜吴歌 冬歌","a":"李白","c":["明朝驿使发，一夜絮征袍。","素手抽针冷，那堪把剪刀。","裁缝寄远道，几日到临洮。"]},{"id":"T00313","t":"赠孟浩然","a":"李白","c":["吾爱孟夫子，风流天下闻。","红颜弃轩冕，白首卧松云。","醉月频中圣，迷花不事君。","高山安可仰，徒此揖清芬。"]},{"id":"T00314","t":"庐山谣寄卢侍御虚舟","a":"李白","c":["我本楚狂人，凤歌笑孔丘。","手持绿玉杖，朝别黄鹤楼。","五岳寻仙不辞远，一生好入名山游。","庐山秀出南斗傍，屏风九叠云锦张，影落明湖青黛光。","金阙前开二峰长，银河倒挂三石梁。","香炉瀑布遥相望，回厓沓嶂凌苍苍。","翠影红霞映朝日，鸟飞不到吴天长。","登高壮观天地间，大江茫茫去不还。","黄云万里动风色，白波九道流雪山。","好为庐山谣，兴因庐山发。","闲窥石镜清我心，谢公行处苍苔没。","早服还丹无世情，琴心三叠道初成。","遥见仙人彩云里，手把芙蓉朝玉京。","先期汗漫九垓上，愿接卢敖游太清。"]},{"id":"T00315","t":"梦游天姥吟留别","a":"李白","c":["海客谈瀛洲，烟涛微茫信难求。","越人语天姥，云霓明灭或可覩。","天姥连天向天横，势拔五岳掩赤城。","天台四万八千丈，对此欲倒东南倾。","我欲因之梦吴越，一夜飞度镜湖月。","湖月照我影，送我至剡溪。","谢公宿处今尚在，渌水荡漾清猨啼。","脚著谢公屐，身登青云梯。","半壁见海日，空中闻天鸡。","千岩万转路不定，迷花倚石忽已暝。","熊咆龙吟殷岩泉，栗深林兮惊层巅。","云青青兮欲雨，水澹澹兮生烟。","列缺霹雳，丘峦崩摧。","洞天石扇，訇然中开。","青冥浩荡不见底，日月照耀金银台。","霓为衣兮风为马，云之君兮纷纷而来下。","虎鼓瑟兮鸾回车，仙之人兮列如麻。","忽魂悸以魄动，怳惊起而长嗟。","惟觉时之枕席，失向来之烟霞。","世间行乐亦如此，古来万事东流水。","别君去时何时还，且放白鹿青崖间，须行即骑访名山。","安能摧眉折腰事权贵？使我不得开心颜。"]},{"id":"T00316","t":"金陵酒肆留别","a":"李白","c":["风吹柳花满店香，吴姬压酒唤客尝。","金陵子弟来相送，欲行不行各尽觞。","请君试问东流水，别意与之谁短长。"]},{"id":"T00317","t":"黄鹤楼送孟浩然之广陵","a":"李白","c":["故人西辞黄鹤楼，烟花三月下扬州。","孤帆远影碧山尽，唯见长江天际流。"]},{"id":"T00318","t":"渡荆门送别","a":"李白","c":["渡远荆门外，来从楚国游。","山随平野尽，江入大荒流。","月下飞天镜，云生结海楼。","仍连故乡水，万里送行舟。"]},{"id":"T00319","t":"送友人","a":"李白","c":["青山横北郭，白水遶东城。","此地一为别，孤蓬万里征。","浮云游子意，落日故人情。","挥手自兹去，萧萧班马鸣。"]},{"id":"T00320","t":"宣州谢朓楼饯别校书叔云","a":"李白","c":["弃我去者昨日之日不可留，乱我心者今日之日多烦忧。","长风万里送秋雁，对此可以酣高楼。","蓬莱文章建安骨，中间小谢又清发。","俱怀逸兴壮思飞，欲上青天览日月。","抽刀断水水更流，举杯销愁愁更愁。","人生在世不称意，明朝散发弄扁舟。"]},{"id":"T00321","t":"下终南山过斛斯山人宿置酒","a":"李白","c":["暮从碧山下，山月随人归。","却顾所来径，苍苍横翠微。","相携及田家，童稚开荆扉。","绿竹入幽径，青萝拂行衣。","欢言得所憩，美酒聊共挥。","长歌吟松风，曲尽河星稀。","我醉君复乐，陶然共忘机。"]},{"id":"T00322","t":"登金陵凤凰台","a":"李白","c":["凤凰台上凤凰游，凤去台空江自流。","吴宫花草埋幽径，晋代衣冠成古丘。","三山半落青天外，二水中分白鹭洲。","总为浮云能蔽日，长安不见使人愁。"]},{"id":"T00323","t":"早发白帝城","a":"李白","c":["朝辞白帝彩云间，千里江陵一日还。","两岸猨声啼不尽，轻舟已过万重山。"]},{"id":"T00324","t":"夜泊牛渚怀古","a":"李白","c":["牛渚西江夜，青天无片云。","登舟望秋月，空忆谢将军。","余亦能高咏，斯人不可闻。","明朝挂帆席，枫叶落纷纷。"]},{"id":"T00325","t":"月下独酌四首 一","a":"李白","c":["花间一壶酒，独酌无相亲。","举杯邀明月，对影成三人。","月既不解饮，影徒随我身。","暂伴月将影，行乐须及春。","我歌月裴回，我舞影零乱。","醒时同交欢，醉后各分散。","永结无情游，相期邈云汉。"]},{"id":"T00326","t":"听蜀僧濬弹琴","a":"李白","c":["蜀僧抱绿绮，西下峨眉峰。","为我一挥手，如听万壑松。","客心洗流水，余响入霜钟。","不觉碧山暮，秋云暗几重。"]},{"id":"T00327","t":"怨情","a":"李白","c":["美人卷珠帘，深坐颦蛾眉。","但见泪痕湿，不知心恨谁。"]},{"id":"T00328","t":"淮上喜会梁川故人","a":"韦应物","c":["江汉曾为客，相逢每醉还。","浮云一别后，流水十年间。","欢笑情如旧，萧疎鬓已斑。","何因北归去，淮上对秋山。"]},{"id":"T00329","t":"郡斋雨中与诸文士燕集","a":"韦应物","c":["兵卫森画戟，宴寝凝清香。","海上风雨至，逍遥池阁凉。","烦疴近消散，嘉宾复满堂。","自慙居处崇，未覩斯民康。","理会是非遣，性达形迹忘。","鲜肥属时禁，蔬果幸见尝。","俯饮一杯酒，仰聆金玉章。","神欢体自轻，意欲凌风翔。","吴中盛文史，群彦今汪洋。","方知大藩地，岂曰财赋疆。"]},{"id":"T00330","t":"初发扬子寄元大校书","a":"韦应物","c":["凄凄去亲爱，泛泛入烟雾。","归棹洛阳人，残钟广陵树。","今朝此为别，何处还相遇。","世事波上舟，沿洄安得住。"]},{"id":"T00331","t":"相和歌辞 江南曲","a":"李益","c":["嫁得瞿塘贾，朝朝误妾期。","早知潮有信，嫁与弄潮儿。"]},{"id":"T00332","t":"相和歌辞 燕歌行","a":"高适","c":["汉家烟尘在东北，汉将辞家破残贼。","男儿本自重横行，天子非常赐颜色。","𪭢金伐鼓下榆关，旌旗逶迤碣石间。","校尉羽书飞瀚海，单于猎火照狼山。","山川萧条极边土，胡骑凭凌杂风雨。","战士军前半死生，美人帐下犹歌舞。","大漠穷秋塞草衰，孤城落日鬬兵稀。","身当恩遇常轻敌，力尽关山未解围。","铁衣远戍辛勤久，玉箸应啼别离后。","少妇城南欲断肠，征人蓟北空回首。","边风飘飘那可度，绝域苍茫更何有。","杀气三日作阵云，寒声一夜传刁斗。","相看白刃血纷纷，死节从来岂顾勋。","君不见沙场征战苦，至今犹忆李将军。"]},{"id":"T00333","t":"相和歌辞 从军行","a":"李颀","c":["白日登山望烽火，昏黄饮马傍交河。","行人刁斗风砂暗，公主琵琶幽怨多。","野营万里无城郭，雨雪纷纷连大漠。","胡雁哀鸣夜夜飞，胡儿眼泪双双落。","闻道玉门犹被遮，应将性命逐轻车。","年年战骨埋荒外，空见蒲萄入汉家。"]},{"id":"T00334","t":"相和歌辞 蜀道难","a":"李白","c":["噫吁嚱！危乎高哉！蜀道之难难于上青天！蚕丛及鱼凫，开国何茫然。","尔来四万八千岁，乃与秦塞通人烟。","西当太白有鸟道，可以横绝峨眉巅。","地崩山摧壮士死，然后天梯石栈方钩连。","上有六龙回日之高标，下有冲波逆折之回川。","黄鹤之飞尚不得，猨猱欲度愁攀缘。","青泥何盘盘，百步九折萦岩峦。","扪参历井仰胁息，以手抚膺坐长叹。","问君西游何时还？畏途巉岩不可攀。","但见悲鸟号枯木，雄飞呼雌绕林间。","又闻子规啼夜月，愁空山，蜀道之难难于上青天！使人听此雕朱颜。","连峰去天不盈尺，枯松倒挂倚绝壁。","飞湍瀑流相喧豗，砅崖转石万壑雷。","其崄也若此，嗟尔远道之人胡为乎来哉？劒阁峥嵘而崔嵬，一夫当关，万夫莫开。","所守或匪亲，化为狼与豺。","朝避猛虎，夕避长蛇。","磨牙吮血，杀人如麻。","锦城虽云乐，不如早还家。","蜀道之难难于上青天，侧身西望长咨嗟。"]},{"id":"T00335","t":"相和歌辞 长信怨 二","a":"王昌龄","c":["奉帚平明金殿开，暂将团扇共裴回。","玉颜不及寒鵶色，犹带昭阳日影来。"]},{"id":"T00336","t":"相和歌辞 玉阶怨","a":"李白","c":["玉阶生白露，夜久侵罗袜。","却下水精帘，玲珑望秋月。"]},{"id":"T00337","t":"相和歌辞 子夜四时歌四首 春歌","a":"李白","c":["秦地罗敷女，采桑绿水边。","素手青条上，红妆白日鲜。","蚕饥妾欲去，五马莫留连。"]},{"id":"T00338","t":"相和歌辞 子夜四时歌四首 夏歌","a":"李白","c":["镜湖三百里，菡萏发荷花。","五月西施采，人看隘若邪。","回舟不待月，归去越王家。"]},{"id":"T00339","t":"相和歌辞 子夜四时歌四首 秋歌","a":"李白","c":["长安一片月，万户捣衣声。","秋风吹不尽，总是玉关情。","何日平胡虏？良人罢远征。"]},{"id":"T00340","t":"相和歌辞 子夜四时歌四首 冬歌","a":"李白","c":["明朝驿使发，一夜絮征袍。","素手抽针冷，那堪把剪刀。","裁缝寄远道，几日到临洮。"]},{"id":"T00341","t":"琴曲歌辞 列女操","a":"孟郊","c":["梧桐相待老，鸳鸯会双死。","贞妇贵徇夫，舍生亦如此。","波澜誓不起，妾心井中水。"]},{"id":"T00342","t":"杂曲歌辞 游子吟","a":"孟郊","c":["慈母手中线，游子身上衣。","临行密密缝，意恐迟迟归。","谁言寸草心，报得三春晖。"]},{"id":"T00343","t":"杂曲歌辞 丽人行","a":"杜甫","c":["三月三日天气新，长安水边多丽人。","态浓意远淑且真，肌理细腻骨肉匀。","绣罗衣裳照暮春，蹙金孔雀银麒麟。","头上何所有？翠微㔩叶垂鬓唇。","背后何所见？珠压腰衱稳称身。","就中云幕椒房亲，赐名大国虢与秦。","紫𫘞之峰出翠釜，水晶之盘行素鳞。","犀筯厌饫久未下，鸾刀缕切空纷纶。","黄门飞鞚不动尘，御厨丝络送八珍。","箫鼓哀吟感鬼神，宾从杂遝实要津。","后来鞍马何逡巡，当轩下马入锦茵。","杨花雪落覆白苹，青鸟飞去衔红巾。","炙手可热势绝伦，慎莫近前丞相嗔。"]},{"id":"T00344","t":"杂曲歌辞 长相思三首 一","a":"李白","c":["长相思，在长安，络纬秋啼金井栏。","微霜凄凄簟色寒，孤灯不明思欲绝。","卷帷望月空长叹，美人如花隔云端。","上有青冥之长天，下有绿水之波澜。","天长路远魂飞苦，梦魂不到关山难。","长相思，摧心肝。"]},{"id":"T00345","t":"杂曲歌辞 长相思三首 二","a":"李白","c":["日色已尽花含烟，月明欲素愁不眠。","赵瑟初停凤凰柱，蜀琴欲奏鸳鸯弦。","此曲有意无人传，愿随春风寄燕然，忆君迢迢隔青天。","昔日横波目，今成流泪泉。","不信妾肠断，归来看取明镜前。"]},{"id":"T00346","t":"杂曲歌辞 行路难三首 一","a":"李白","c":["金尊清酒斗十千，玉盘珍羞直万钱。","停杯投筯不能食，拔劒四顾心茫然。","欲渡黄河冰塞川，将登太行雪暗天。","闲来垂钓坐溪上，忽复乘舟梦日边。","行路难，行路难，多岐路，今安在？长风破浪会有时，直挂云帆济沧海。"]},{"id":"T00347","t":"杂曲歌辞 行路难三首 二","a":"李白","c":["大道如青天，我独不得出。","羞逐长安社中儿，赤鸡白狗赌梨栗。","弹劒作歌奏苦声，曳裾王门不称情。","淮阴市井笑韩信，汉朝公卿忌贾生。","君不见昔时燕家重郭隗，拥篲折腰无嫌猜。","剧辛乐毅感恩分，输肝剖胆效英才。","昭王白骨萦蔓草，谁人更扫黄金台。","行路难，归去来。"]},{"id":"T00348","t":"杂曲歌辞 行路难三首 三","a":"李白","c":["有耳莫洗颍川水，有口莫食首阳蕨。","含光混世贵无名，何用孤高比云月。","吾观自古贤达人，功成不退皆殒身。","子胥既弃吴江上，屈原终投湘水滨。","陆机才多岂自保，李斯税驾苦不早。","华亭鹤唳讵可闻，上蔡苍鹰何足道？君不见吴中张翰称达士，秋风忽忆江东行。","且乐生前一杯酒，何须身后千载名。"]},{"id":"T00349","t":"杂曲歌辞 长干曲四首 一","a":"崔颢","c":["君家定何处？妾住在横塘。","停舟暂借问，或恐是同乡。"]},{"id":"T00350","t":"杂曲歌辞 长干曲四首 二","a":"崔颢","c":["家临九江水，去来九江侧。","同是长干人，生小不相识。"]},{"id":"T00351","t":"杂曲歌辞 长干行二首 一","a":"李白","c":["妾发初覆额，折花门前剧。","郎骑竹马来，遶床弄青梅。","同居长干里，两小无嫌猜。","十四为君妇，羞颜尚不开。","低头向暗壁，千唤不一回。","十五始展眉，愿同尘与灰。","常存抱柱信，岂上望夫台。","十六君远行，瞿塘滟预堆。","五月不可触，猨鸣天上哀。","门前迟行迹，一一生绿苔。","苔深不能扫，落叶秋风早。","八月蝴蝶来，双飞西园草。","感此伤妾心，坐愁红颜老。","早晚下三巴，预将书报家。","相迎不道远，直至长风沙。"]},{"id":"T00352","t":"杂曲歌辞 独不见","a":"沈佺期","c":["卢家小妇郁金堂，海燕双栖玳瑁梁。","九月寒砧催下叶，十年征戍忆辽阳。","白狼河北音书断，丹凤城南秋夜长。","谁知含愁独不见，使妾明月照流黄。"]},{"id":"T00353","t":"杂曲歌辞 秋夜曲","a":"王涯","c":["桂魄初生秋露微，轻罗已薄未更衣。","银筝夜久殷勤弄，心怯空房不忍归。"]},{"id":"T00354","t":"春思","a":"皇甫冉","c":["莺啼燕语报新年，马邑龙堆路几千。","家住秦城邻汉苑，心随明月到胡天。","机中锦字论长恨，楼上花枝笑独眠。","为问元戎窦车骑，何时反斾勒燕然。"]},{"id":"T00355","t":"夜月","a":"刘方平","c":["更深月色半人家，北斗阑干南斗斜。","今夜偏知春气暖，虫声新透绿窗纱。"]},{"id":"T00356","t":"春怨","a":"刘方平","c":["纱窗日落渐黄昏，金屋无人见泪痕。","寂寞空庭春欲晚，梨花满地不开门。"]},{"id":"T00357","t":"登鹳雀楼","a":"王之涣","c":["白日依山尽，黄河入海流。","欲穷千里目，更上一层楼。"]},{"id":"T00358","t":"凉州词二首 一","a":"王之涣","c":["黄河远上白云间，一片孤城万仞山。","羌笛何须怨杨柳，春光不度玉门关。"]},{"id":"T00359","t":"阙题","a":"刘眘虚","c":["道由白云尽，春与青溪长。","时有落花至，远随流水香。","闲门向山路，深柳读书堂。","幽映每白日，清辉照衣裳。"]},{"id":"T00360","t":"征怨","a":"柳中庸","c":["岁岁金河复玉关，朝朝马策与刀环。","三春白雪归青冢，万里黄河遶黑山。"]},{"id":"T00361","t":"送李端","a":"严维","c":["故关衰草遍，离别正堪悲。","路出寒云外，人归暮雪时。","少孤为客早，多难识君迟。","揜泣空相向，风尘何所期。"]},{"id":"T00362","t":"宫词五首 二","a":"顾况","c":["玉楼天半起笙歌，风送宫嫔笑语和。","月殿影开闻夜漏，水精帘卷近银河。"]},{"id":"T00363","t":"鼓吹曲辞 上之回","a":"李白","c":["三十六离宫，楼台与天通。","阁道步行月，美人愁烟空。","恩疎宠不及，桃李伤春风。","淫乐意何极，金舆向回中。","万乘出黄道，千旗扬彩虹。","前军细柳北，后骑甘泉东。","岂问渭川老，宁邀襄野童。","秋暮瑶池宴，归来乐未穷。"]},{"id":"T00364","t":"横吹曲辞 前出塞九首 一","a":"杜甫","c":["戚戚去故里，悠悠赴交河。","公家有程期，亡命婴祸罗。","君已富土境，开边一何多？","弃绝父母恩，吞声行负戈。"]},{"id":"T00365","t":"横吹曲辞 陇头吟","a":"王维","c":["长安少年游侠客，夜上戍楼看太白。","陇头明月迥临关，陇上行人夜吹笛。","关西老将不胜愁，驻马听之双泪流。","身经大小百余战，麾下偏裨万户侯。","苏武才为典属国，节旄空尽海西头。"]},{"id":"T00366","t":"横吹曲辞 长安道","a":"白居易","c":["花枝缺处青楼开，艳歌一曲酒一杯。","美人劝我急行乐，自古朱颜不再来。","君不见外州客，长安道，一回来，一回老。"]},{"id":"T00367","t":"相和歌辞 江南曲","a":"李商隐","c":["郎船安两桨，侬舸动双桡。","埽黛开宫额，裁裙约楚腰。","乖期方积思，临醉欲拚娇。","莫以采菱唱，欲羡秦台箫。"]},{"id":"T00368","t":"琴曲歌辞 别鹤","a":"杜牧","c":["分飞共所从，六翮势摧风。","声断碧云外，影孤明月中。","青田归路远，月桂旧巢空。","矫翼知何处，天涯不可穷。"]},{"id":"T00369","t":"横吹曲辞 出塞 二","a":"王昌龄","c":["白花垣上望京师，黄河水流无尽时。","穷秋旷野行人绝，马首东来知是谁。"]},{"id":"T00370","t":"相和歌辞 大堤行","a":"孟浩然","c":["大堤行乐处，车马相驰突。","岁岁春草生，踏青二三月。","王孙挟珠弹，游女矜罗韈。","携手今莫同，江花为谁发。"]},{"id":"T00371","t":"鼓吹曲辞 凯歌六首 一","a":"岑参","c":["汉将承恩西破戎，捷书先奏未央宫。","天子预开麟阁待，祗今谁数贰师功。"]},{"id":"T00372","t":"相和歌辞 秋胡行","a":"高适","c":["妾本邯郸未嫁时，容华倚翠人未知。","一朝结发从君子，将妾迢迢东路陲。","时逢大道无难阻，君方游宦从陈汝。","蕙楼独卧频度春，彩落辞君几徂暑。","三月垂杨蚕未眠，携笼结侣南陌边。","道逢行子不相识，赠妾黄金买少年。","妾家夫壻轻离久，寸心誓与长相守。","愿言行路莫多情，送妾贞心在人口。","日暮蚕饥相命归，携笼端饰来庭闱。","劳心苦力终无恨，所冀君恩那可依。","闻说行人已归止，乃是向来赠金子。","相看颜色不复言，相顾怀慙有何已。","从来自隐无疑背，直为君情也相会。","如何咫尺仍有情，况复迢迢千里外。","此时顾恩不顾身，念君此日赴河津。","莫道向来不得意，故欲留规诫后人。"]},{"id":"T00373","t":"相和歌辞 阿娇怨","a":"刘禹锡","c":["望见葳蕤举翠华，试开金屋埽庭花。","须臾宫女传来信，云幸平阳公主家。"]},{"id":"T00374","t":"鼓吹曲辞 鼓吹铙歌 晋阳武","a":"柳宗元","c":["晋阳武，奋义威。","炀之渝，德焉归。","氓毕屠，绥者谁。","皇烈烈，专天机。","号以仁，扬其旗。","日之升，九土晞。","斥田圻，流洪辉。","有其二，翼余隋。","斮枭骜，连熊螭。","枯以肉，勍者羸。","后土荡，玄穹弥。","合之育，莽然施。","惟德辅，庆无期。"]},{"id":"T00375","t":"鼓吹曲辞 芳树","a":"韦应物","c":["迢迢芳园树，列映清池曲。","对此伤人心，还如故时绿。","风条洒余霭，露叶承新旭。","佳人不再攀，下有往来躅。"]},{"id":"T00376","t":"鼓吹曲辞 芳树","a":"元稹","c":["芳树已寥落，孤英尤可嘉。","可怜团团叶，盖覆深深花。","游蠭竞攒刺，鬬雀亦纷拏。","天生细碎物，不爱好光华。","非无歼殄法，念尔有生涯。","春雷一声发，惊燕亦惊蛇。","清池养神蔡，已复长虾蟆。","雨露贵平施，吾其春草芽。"]},{"id":"T00377","t":"相和歌辞 猛虎行","a":"韩愈","c":["猛虎虽云恶，亦各有匹侪。","群行深谷间，百兽望风低。","身食黄熊父，子食赤豹麛。","择肉于熊罴，肎视兔与貍。","正昼当谷眠，眼有百步威。","自矜无当对，气性纵以乖。","朝怒杀其子，暮还飧其妃。","匹侪四散走，猛虎还孤栖。","狐鸣门四旁，乌鹊从噪之。","出逐猴入居，虎不知所归。","谁云猛虎恶，中路正悲啼。","豹来衔其尾，熊来攫其颐。","猛虎死不辞，但慙前所为。","虎坐无助死，况如汝细微。","故当结以信，亲当结以私。","亲故且不保，人谁信汝为。"]},{"id":"T00378","t":"鼓吹曲辞 艾如张","a":"李贺","c":["锦襜褕，绣裆襦，强强饮啄哺尔雏。","陇东卧穟满风雨，莫信龙媒陇西去。","齐人织网如素空，张在野春平碧中。","网丝漠漠无形影，误尔触之伤首红。","艾叶绿花谁翦刻，中藏祸机不可测。"]},{"id":"T00379","t":"杂曲歌辞 壮士吟","a":"贾岛","c":["壮士不曾悲，悲即无回期。","如何易水上，未歌先泪垂。"]},{"id":"T00380","t":"横吹曲辞 雍台歌","a":"温庭筠","c":["太子池南楼百尺，八窗新树疎帘隔。","黄金铺首画钩陈，羽葆亭童拂交戟。","盘纡阑楯临高台，帐殿临流鸾扇开。","早雁声鸣细波起，映花卤簿龙飞回。"]},{"id":"T00381","t":"相和歌辞 王昭君","a":"刘长卿","c":["自矜妖艳色，不顾丹青人。","那知粉缋能相负，却使容华飜误身。","上马辞君嫁骄虏，玉颜对人啼不语。","北风雁急浮清秋，万里独见黄河流。","纤腰不复汉宫宠，双蛾长向胡天愁。","琵琶弦中苦调多，萧萧羌笛声相和。","可怜一曲传乐府，能使千秋伤绮罗。"]},{"id":"T00382","t":"横吹曲辞 折杨柳","a":"张九龄","c":["纤纤折杨柳，持此寄情人。","一枝何足贵，怜是故园春。","迟景那能久，流芳不及新。","更愁征戍客，鬓老边城尘。"]},{"id":"T00383","t":"横吹曲辞 出塞","a":"陈子昂","c":["忽闻天上将，关塞重横行。","始返楼兰国，还向朔方城。","黄金装战马，白羽集神兵。","星月开天阵，山川列地营。","晚风吹画角，春色耀飞旌。","宁知班定远，独是一书生。"]},{"id":"T00384","t":"鼓吹曲辞 巫山高二首 一","a":"孟郊","c":["巴山上峡重复重，阳台碧峭十二峰。","荆王猎时逢暮雨，夜卧高丘梦神女。","轻红流烟湿艳姿，行云飞去明星稀。","目极魂断望不见，猨啼三声泪沾衣。"]},{"id":"T00385","t":"相和歌辞 采莲曲","a":"贺知章","c":["稽山罢雾郁嵯峨，镜水无风也自波。","莫言春度芳菲尽，别有中流采芰荷。"]},{"id":"T00386","t":"鼓吹曲辞 朱鹭","a":"张籍","c":["翩翩兮朱鹭，来泛春塘栖绿树。","羽毛如翦色如染，远飞欲下双翅敛。","避人引子入深壍，动处水纹开滟滟。","谁知豪家网尔躯，不如饮啄江海隅。"]},{"id":"T00387","t":"横吹曲辞 陇头水","a":"王建","c":["陇水何年陇头别，不在山中亦呜咽。","征人塞耳马不行，未到陇头闻水声。","谓是西流入蒲海，还闻北海绕龙城。","陇东陇西多屈曲，野麋饮水长簇簇。","胡兵夜回水傍住，忆著来时磨劒处。","向前无井复无泉，放马回看陇头树。"]},{"id":"T00388","t":"相和歌辞 从军行","a":"卢纶","c":["二十在边城，军中得勇名。","卷旗收败马，断碛拥残兵。","覆阵乌鸢起，烧山草木明。","塞闲思远猎，师老厌分营。","雪岭无人迹，冰河足雁声。","李陵甘此没，惆怅汉公卿。"]},{"id":"T00389","t":"横吹曲辞 紫骝马","a":"李益","c":["争场看鬬鸡，白鼻紫䯄嘶。","漳水春归晚，丛台日向低。","歇鞍珠作汗，试劒玉如泥。","为谢红梁燕，年年妾独栖。"]},{"id":"T00390","t":"琴曲歌辞  秋思","a":"司空曙","c":["静与嬾相偶，年将衰共催。","前途欢不集，往事恨空来。","昼景委红叶，月华铺绿苔。","沈思更何有？结坐玉琴哀。"]},{"id":"T00391","t":"鼓吹曲辞 巫山高","a":"皇甫冉","c":["巫峡见巴东，迢迢半出空。","云藏神女馆，雨到楚王宫。","朝暮泉声落，寒暄树色同。","清猨不可听，偏在九秋中。"]},{"id":"T00392","t":"相和歌辞 江南曲","a":"韩翃","c":["长乐花枝雨点消，江城日暮好相邀。","春楼不闭葳蕤锁，绿水回通宛转桥。"]},{"id":"T00393","t":"帝京篇十首 一","a":"太宗皇帝","c":["秦川雄帝宅，函谷壮皇居。","绮殿千寻起，离宫百雉余。","连甍遥接汉，飞观迥凌虚。","云日隐层阙，风烟出绮疎。"]},{"id":"T00394","t":"太子纳妃太平公主出降","a":"高宗皇帝","c":["龙楼光曙景，鲁馆启朝扉。","艳日浓妆影，低星降婺辉。","玉庭浮瑞色，银牓藻祥徽。","云转花萦盖，霞飘叶缀旗。","雕轩回翠陌，宝驾归丹殿。","鸣珠佩晓衣，镂璧轮开扇。","华冠列绮筵，兰醑申芳宴。","环阶凤乐陈，玳席珍羞荐。","蝶舞袖香新，歌分落素尘。","欢凝欢懿戚，庆叶庆初姻。","暑阑炎气息，凉早吹疎频。","方期六合泰，共赏万年春。"]},{"id":"T00395","t":"过晋阳宫","a":"明皇帝","c":["缅想封唐处，实惟建国初。","俯察伊晋野，仰观乃参虚。","井邑龙斯跃，城池凤翔余。","林塘犹沛泽，台榭宛旧居。","运革祚中否，时迁命兹符。","顾循承丕构，怵惕多忧虞。","尚恐威不逮，复虑化未孚。","岂徒劳辙迹，所期训戎车。","习俗问黎人，亲巡慰里闾。","永言念成功，颂德临康衢。","长怀经纶日，叹息履庭隅。","艰难安可忘，欲去良踟蹰。"]},{"id":"T00396","t":"中和节日宴百僚赐诗","a":"德宗皇帝","c":["韶年启仲序，初吉谐良辰。","肇兹中和节，式庆天地春。","欢酣朝野同，生德区宇均。","云开洒膏露，草疏芳河津。","岁华今载阳，东作方肆勤。","慙非熏风唱，曷用慰吾人。"]},{"id":"T00397","t":"曳鼎歌","a":"则天皇后","c":["羲农首出，轩昊膺期。","唐虞继踵，汤禹乘时。","天下光宅，海内雍熙。","上玄降鉴，方建隆基。"]},{"id":"T00398","t":"奉和圣制立春日侍宴内殿出翦彩花应制","a":"上官昭容","c":["密叶因裁吐，新花逐翦舒。","攀条虽不谬，摘橤讵知虚。","春至由来发，秋还未肯疎。"]},{"id":"T00399","t":"九月十日偶书","a":"后主煜","c":["晚雨秋阴酒乍醒，感时心绪杳难平。","黄花冷落不成艳，红叶飕飗竞鼓声。","背世返能厌俗态，偶缘犹未忘多情。","自从双鬓斑斑白，不学安仁却自惊。"]},{"id":"T00400","t":"丈人观","a":"蜀太后徐氏","c":["早与元妃慕至化，同跻灵岳访真仙。","当时信有壶中景，今日亲来洞里天。","仪仗影空寥廓外，金丝声揭翠微巅。","惟慙未致华胥理，徒卜升平万万年。"]},{"id":"T00401","t":"丈人观","a":"蜀太妃徐氏","c":["获陪翠辇喜殊常，同涉仙坛岂厌长。","不羡乘鸾入烟雾，此中便是五云乡。"]},{"id":"T00402","t":"郊庙歌辞 祀圜丘乐章 豫和","a":"褚亮","c":["上灵睠命膺会昌，盛德殷荐叶辰良。","景福降兮圣德远，玄化穆兮天历长。"]},{"id":"T00403","t":"郊庙歌辞 封泰山乐章 豫和 一","a":"张说","c":["款泰坛，柴泰清。","受天命，报天成。","竦皇心，荐乐声。","志上达，歌下迎。"]},{"id":"T00404","t":"郊庙歌辞 武后明堂乐章 外办将出","a":"武则天","c":["总章陈昔典，衢室礼惟神。","宏规则天地，神用叶陶钧。","负扆三春旦，充庭万宇宾。","顾己诚虚薄，空慙亿兆人。"]},{"id":"T00405","t":"郊庙歌辞 五郊乐章 黄帝宫音","a":"魏征","c":["黄中正位，含章居贞。","既长六律，兼和五声。","毕陈万舞，乃荐斯牲。","神其下降，永祚休平。"]},{"id":"T00406","t":"郊庙歌辞 祀风师乐章 迎神","a":"包佶","c":["太皞御气，句芒肇功。","苍龙青旗，爰候祥风。","律以和应，神以感通。","鼎俎修蚃，时惟礼崇。"]},{"id":"T00407","t":"郊庙歌辞 祭汾阴乐章 寿和","a":"苏颋","c":["礼物斯具，乐章乃陈。","谁其作主，皇考圣真。","对越在天，圣明佐神。","窅然汾上，厚泽如春。"]},{"id":"T00408","t":"郊庙歌辞 禅社首乐章 顺和","a":"贺知章、源乾曜","c":["至哉含柔德，万物资以生。","常顺称厚载，流谦通变盈。","圣心事能察，增广陈厥诚。","黄祇僾如在，泰折俟咸亨。"]},{"id":"T00409","t":"郊庙歌辞 享龙池乐章 第一章","a":"姚崇","c":["恭闻帝里生灵沼，应报明君鼎业新。","既协翠泉光宝命，还符白水出真人。","此时舜海潜龙跃，此地尧河带马巡。","独有前池一小雁，叨承旧惠入天津。"]},{"id":"T00410","t":"郊庙歌辞 享龙池乐章 第三章","a":"沈佺期","c":["龙池跃龙龙已飞，龙德[光]天天不违。","池开天汉分黄道，龙向天门入紫微。","邸第楼台多气色，君王凫雁有光辉。","为报寰中百川水，来朝此地莫东归。"]},{"id":"T00411","t":"郊庙歌辞 享龙池乐章 第六章","a":"崔日用","c":["龙兴白水汉兴符，圣主时乘运斗枢。","岸上丰茸五花树，波中的皪千金珠。","操环昔闻迎夏启，发匣先来瑞有虞。","风色云光随隐见，赤云神化象江湖。"]},{"id":"T00412","t":"郊庙歌辞 享龙池乐章 第八章","a":"李乂","c":["星分邑里四人居，水洊源流万顷余。","魏国君王称象处，晋家藩邸化龙初。","青蒲暂似游梁马，绿藻还疑宴镐鱼。","自有神灵滋液地，年年云物史官书。"]},{"id":"T00413","t":"郊庙歌辞 享太庙乐章 永和","a":"魏征、褚亮","c":["於穆烈祖，弘此丕基。","永言配命，子孙保之。","百神既洽，万国在兹。","是用孝享，神其格思。"]},{"id":"T00414","t":"郊庙歌辞 德明兴圣庙乐章 迎神","a":"李舒","c":["元尊九德，佐尧光宅。","烈祖太宗，方周作伯。","响怀霜露，乐变金石。","白云清风，髣髴来格。"]},{"id":"T00415","t":"郊庙歌辞 仪坤庙乐章 永和","a":"徐彦伯","c":["猗若清庙，肃肃荧荧。","国荐严祀，坤兴淑灵。","有几在室，有乐在庭。","临兹孝享，百禄惟宁。"]},{"id":"T00416","t":"郊庙歌辞 仪坤庙乐章 昭升","a":"薛稷","c":["阳灵配德，阴魄昭升。","尧坛凤下，汉室龙兴。","伣天作对，前旒是凝。","化行南国，道盛西陵。","造舟集灌，无德而称。","我粢既絜，我醴既澄。","阴阴灵庙，光灵若凭。","德馨惟享，孝思烝烝。"]},{"id":"T00417","t":"郊庙歌辞 仪坤庙乐章 寿和","a":"徐坚","c":["於穆清庙，肃雍严祀。","合福受厘，介以繁[祉]。"]},{"id":"T00418","t":"郊庙歌辞 享惠昭太子庙乐章 送神","a":"王涯","c":["威仪毕陈，备乐将阕。","苞茅酒缩，膋萧香彻。","宫臣展事，肃雍在列。","迎精送往，厥鉴昭晰。"]},{"id":"T00419","t":"郊庙歌辞 梁郊祀乐章 庆和 一","a":"赵光逢、张衮","c":["就阳位，升圆丘。","佩双玉，御大裘。","膺天命，拥神休。","万灵感，百禄遒。"]},{"id":"T00420","t":"鼓吹曲辞 上之回","a":"卢照邻","c":["回中道路险，萧关烽候多。","五营屯北地，万乘出西河。","单于拜玉玺，天子按雕戈。","振旅汾川曲，秋风横大歌。"]},{"id":"T00421","t":"鼓吹曲辞 战城南二首 一","a":"僧贯休","c":["万里桑干傍，茫茫古蕃壤。","将军貌顦顇，抚劒悲年长。","胡兵尚陵逼，久住亦非强。","邯郸少年辈，个个有伎俩。","拖枪半夜去，雪片大如掌。"]},{"id":"T00422","t":"鼓吹曲辞 巫山高","a":"李端","c":["巫山十二峰，皆在碧虚中。","回合云藏日，霏微雨带风。","猨声寒过水，树色暮连空。","愁向高唐望，清秋见楚宫。"]},{"id":"T00423","t":"鼓吹曲辞 巫山高","a":"僧齐己","c":["巫山高，巫女妖。","雨为暮兮云为朝，楚王顦顇魂欲销。","秋猨嗥嗥日将夕，红霞紫烟凝老壁。","千岩万壑花皆坼，但恐芳菲无正色。","不知今古行人行，几人经此无秋情。","云深庙远不可觅，十二峰头插天碧。"]},{"id":"T00424","t":"鼓吹曲辞 临高台","a":"王勃","c":["临高台，高台迢递绝浮埃。","瑶轩绮构何崔嵬，鸾歌凤吹清且哀。","俯瞰长安道，萋萋御沟草。","斜对甘泉路，苍苍茂陵树。","高台四望同，帝乡佳气郁葱葱。","紫阁丹楼纷照曜，璧房锦殿相玲珑。","东弥长乐观，西指未央宫。","赤城映朝日，绿树摇春风。","旗亭百队开新市，甲第千甍分戚里。","朱轮翠盖不胜春，叠树层楹相对起。","复有青楼大道中，绣户文窗雕绮栊。","锦衣昼不襞，罗帏夕未空。","歌屏朝揜翠，妆镜晚窥红。","为吾安宝髻，蛾眉罢花丛。","狭路尘间黯将暮，云间月色明如素。","鸳鸯池上两两飞，凤皇楼下双双度。","物色正如此，佳期那不顾。","银鞍绣毂盛繁华，可怜今夜宿倡家。","倡家少妇不须嚬，东园桃李片时春。","君看旧日高台处，柏梁铜雀生黄尘。"]},{"id":"T00425","t":"横吹曲辞 陇头水","a":"杨师道","c":["陇头秋月明，陇水带关城。","笳添离别曲，风送断肠声。","映雪峰犹暗，乘冰马屡惊。","雾中寒雁至，沙上转蓬轻。","天山传羽檄，汉地急征兵。","阵开都护道，劒聚伏波营。","于兹觉无度，方共濯胡缨。"]},{"id":"T00426","t":"横吹曲辞 陇头水 一","a":"僧皎然","c":["陇头心欲绝，陇水不堪闻。","碎影摇枪垒，寒声咽帐军。","素从盐海积，绿带柳城分。","日落天边望，逶迤入塞云。"]},{"id":"T00427","t":"横吹曲辞 陇头水","a":"鲍溶","c":["陇头水，千古不堪闻。","生归苏属国，死别李将军。","细响风凋草，清哀雁落云。"]},{"id":"T00428","t":"横吹曲辞 入关","a":"张祜","c":["都城连百二，雄险北回环。","地势遥尊岳，河流侧让关。","秦皇曾虎视，汉祖亦龙颜。","何事枭凶辈，干戈自不闲。"]},{"id":"T00429","t":"横吹曲辞 入塞","a":"刘希夷","c":["将军陷虏围，边务息戎机。","霜雪交河尽，旌旗入塞飞。","晓光随马度，春色伴人归。","课绩朝明主，临轩拜武威。"]},{"id":"T00430","t":"横吹曲辞 折杨柳","a":"乔知之","c":["可怜濯濯春杨柳，攀折将来就纤手。","妾容与此同盛衰，何必君恩独能久。"]},{"id":"T00431","t":"横吹曲辞 折杨柳","a":"刘宪","c":["沙塞三河道，金闺二月春。","碧烟杨柳色，红粉绮罗人。","露叶怜啼脸，风花思舞巾。","攀持君不见，为听曲中新。"]},{"id":"T00432","t":"横吹曲辞 折杨柳","a":"崔湜","c":["二月风光半，三边戍不还。","年华妾自惜，杨柳为君攀。","落絮缘衫袖，垂条拂髻鬟。","那堪音信断，流涕望阳关。"]},{"id":"T00433","t":"横吹曲辞 折杨柳","a":"韦承庆","c":["万里边城地，三春杨柳节。","叶似镜中眉，花如关外雪。","征人远乡思，倡妇高楼别。","不忍掷年华，含情寄攀折。"]},{"id":"T00434","t":"横吹曲辞 关山月","a":"崔融","c":["月生西海上，气逐边风壮。","万里度关山，苍茫非一状。","汉兵开郡国，胡马窥亭障。","夜夜闻悲笳，征人起南望。"]},{"id":"T00435","t":"横吹曲辞 长安道","a":"崔颢","c":["长安甲第高入云，谁家居住霍将军。","日晚朝回拥宾从，路傍拜揖何纷纷。","莫言炙手手可热，须臾火尽灰亦灭。","莫言贫贱即可欺，人生富贵自有时。","一朝天子赐颜色，世上悠悠应始知。"]},{"id":"T00436","t":"横吹曲辞 长安道","a":"顾况","c":["长安道，人无衣，马无草，何不归来山中老。"]},{"id":"T00437","t":"横吹曲辞 长安道","a":"聂夷中","c":["此地无驻马，夜中犹走轮。","所以路旁草，少于衣上尘。"]},{"id":"T00438","t":"横吹曲辞 长安道","a":"薛能","c":["汲汲复营营，东西连两京。","关𦈡古若在，山岳累应成。","各自有身事，不相知姓名。","交驰喧众类，分散入重城。","此路去无尽，万方人始生。","空余片言苦，来往觅刘桢。"]},{"id":"T00439","t":"相和歌辞 江南曲","a":"宋之问","c":["妾住越城南，离居不自堪。","采花惊曙鸟，摘叶𫗪春蚕。","嬾结茱萸带，愁安玳瑁簪。","侍臣消瘦尽，日暮碧江潭。"]},{"id":"T00440","t":"相和歌辞 江南曲","a":"丁仙芝","c":["长干斜路北，近浦是儿家。","有意来相访，明朝出浣纱。","发向横塘口，船开值急流。","知郎旧时意，且请拢船头。","昨暝逗南陵，风声波浪阻。","入浦不逢人，归家谁信汝。","未晓已成妆，乘潮去茫茫。","因从京口渡，使报邵陵王。","始下芙蓉楼，言发琅邪岸。","急为打船开，恶许傍人见。"]},{"id":"T00441","t":"相和歌辞 江南曲","a":"陆龟蒙","c":["为爱江南雪，涉江聊采苹。","水深烟浩浩，空对双车轮。","车轮明月团，车盖浮云盘。","云月徒自好，水中行路难。","遥遥洛阳道，夹岸生春草。","寄语櫂船郎，莫夸风浪好。"]},{"id":"T00442","t":"相和歌辞 挽歌","a":"孟云卿","c":["草草门巷喧，涂车俨成位。","冥寞何所须，尽我生人意。","北邙路非远，此别终天地。","临穴频抚棺，至哀反无泪。","尔形未衰老，尔息犹童穉。","骨肉不可离，皇天若容易。","房帷即虚张，庭宇为哀次。","薤露歌若斯，人生尽如寄。"]},{"id":"T00443","t":"相和歌辞 对酒","a":"崔国辅","c":["行行日将夕，荒村古冢无人迹。","朦胧荆棘一鸟飞，屡唱提壶酤酒吃。","古人不达酒不足，遗恨精灵传此曲。","寄言当代诸少年，平生且尽杯中渌。"]},{"id":"T00444","t":"相和歌辞 陌上桑","a":"常建","c":["翳翳陌上桑，南枝交北堂。","美人金梯出，素手自提筐。","非但畏蚕饥，盈盈娇路傍。"]},{"id":"T00445","t":"相和歌辞 王昭君","a":"骆宾王","c":["敛容辞豹尾，缄怨度龙鳞。","金钿明汉月，玉箸染胡尘。","妆镜菱花暗，愁眉柳叶嚬。","惟有清笳曲，时闻芳树春。"]},{"id":"T00446","t":"相和歌辞 王昭君","a":"上官仪","c":["玉关春色晚，金河路几千。","琴悲桂条上，笛怨柳花前。","雾掩临妆月，风惊入鬓蝉。","缄书待还使，泪尽白云天。"]},{"id":"T00447","t":"相和歌辞 王昭君","a":"董思恭","c":["琵琶马上弹，行路曲中难。","汉月正南远，燕山直北寒。","髻鬟风拂散，眉黛雪沾残。","斟酌红颜尽，何劳镜里看。"]},{"id":"T00448","t":"相和歌辞 王昭君三首 一","a":"郭元振","c":["自嫁单于国，长衔汉掖悲。","容颜日顦顇，有甚画图时。"]},{"id":"T00449","t":"相和歌辞 王昭君","a":"储光羲","c":["日暮惊沙乱雪飞，傍人相劝易罗衣。","强来前帐看歌舞，共待单于夜猎归。"]},{"id":"T00450","t":"相和歌辞 王昭君","a":"令狐楚","c":["锦车天外去，毳幕云中开。","魏阙苍龙远，萧关赤雁哀。"]},{"id":"T00451","t":"相和歌辞 王昭君","a":"张仲素","c":["仙娥今下嫁，骄子自同和。","劒戟归田尽，牛羊绕塞多。"]},{"id":"T00452","t":"相和歌辞 昭君词","a":"张文琮","c":["戒途飞万里，回首望三秦。","忽见天山雪，还疑上苑春。","玉痕垂泪粉，罗袂拂胡尘。","为得胡中曲，还悲远嫁人。"]},{"id":"T00453","t":"相和歌辞 铜雀台","a":"郑愔","c":["日斜漳浦望，风起邺台寒。","玉座平生晚，金尊妓吹阑。","舞余依帐泣，歌罢向陵看。","萧索松风暮，愁烟入井阑。"]},{"id":"T00454","t":"相和歌辞 铜雀妓","a":"王适","c":["日暮铜雀迥，幽声玉座清。","萧森松柏望，委郁绮罗情。","君恩不再重，妾舞为谁轻。"]},{"id":"T00455","t":"相和歌辞 铜雀妓","a":"袁晖","c":["君爱本相饶，从来事舞腰。","那堪攀玉座，肠断望陵朝。","怨著情无主，哀凝曲不调。","况临松日暮，悲吹坐萧萧。"]},{"id":"T00456","t":"相和歌辞 铜雀妓","a":"刘商","c":["魏主矜蛾眉，美人美于玉。","高台无昼夜，歌舞竟未足。","盛色如转圜，夕阳落深谷。","仍令身殁后，尚足平生欲。","红粉横泪痕，调弦空向屋。","举头君不在，唯见西陵木。","玉辇岂再来，娇鬟为谁绿。","那堪秋风里，更舞阳春曲。","曲终情不胜，阑干向西哭。","台边生野草，来去罥罗縠。","况复陵寝间，双双见麋鹿。"]},{"id":"T00457","t":"相和歌辞 燕歌行","a":"陶翰","c":["请君留楚调，听我吟燕歌。","家在辽水头，边风意气多。","出身为汉将，正值戎未和。","雪中凌天山，冰上渡交河。","大小百余战，封侯竟蹉跎。","归来霸陵下，故旧无相过。","雄劒委尘匣，空门唯雀罗。","玉𥮾还赵女，宝瑟付齐娥。"]},{"id":"T00458","t":"相和歌辞 从军行二首 一","a":"虞世南","c":["涂山烽候惊，弭节度龙城。","冀马楼兰将，燕犀上谷兵。","劒寒花不落，弓晓月逾明。","凛凛严霜节，冰壮黄河绝。","蔽日卷征蓬，浮天散飞雪。","全兵值月满，精骑乘胶折。","结发早驱驰，辛苦事旌麾。","马冻重关冷，轮摧九折危。","独有西山将，年年属数奇。"]},{"id":"T00459","t":"琴曲歌辞 湘夫人","a":"李颀","c":["九嶷日已暮，三湘云复愁。","窅蔼罗袂色，潺湲江水流。","佳期来北渚，捐玦在芳洲。"]},{"id":"T00460","t":"相和歌辞 从军行","a":"戎昱","c":["昔从李都尉，双鞬照马蹄。","擒生黑山北，杀敌黄云西。","太白沈虏地，边草复萋萋。","归来邯郸市，百尺青楼梯。","感激然诺重，平生胆力齐。","芳筵暮歌发，艳粉轻鬟低。","半醉秋风起，铁骑门前嘶。","远戍报烽火，孤城严鼓鼙。","挥鞭望尘去，少妇莫含啼。"]},{"id":"T00461","t":"相和歌辞 饮马长城窟行","a":"王翰","c":["长安少年无远图，一生惟羡执金吾。","骐𬴊前殿拜天子，走马为君西击胡。","胡沙猎猎吹人面，汉虏相逢不相见。","遥闻鼙鼓动地来，传道单于夜犹战。","此时顾恩宁顾身，为君一行摧万人。","壮士挥戈回白日，单于溅血染朱轮。","回来饮马长城窟，长安道傍多白骨。","问之耆老何代人，云是秦王筑城卒。","黄昏塞北无人烟，鬼哭啾啾声沸天。","无罪见诛功不赏，孤魂流落此城边。","当昔秦王按劒起，诸侯膝行不敢视。","富国彊兵二十年，筑怨兴徭九千里。","秦王筑城何太愚，天实亡秦非北胡。","一朝祸起萧墙内，渭水咸阳不复都。"]},{"id":"T00462","t":"相和歌辞 怨诗二首 一","a":"薛奇童","c":["日晚梧桐落，微寒入禁垣。","月悬三雀观，霜度万秋门。","艳舞矜新宠，愁容泣旧恩。","不堪深殿里，帘外欲黄昏。"]},{"id":"T00463","t":"相和歌辞 怨歌行","a":"吴少微","c":["城南有怨妇，含怨倚兰丛。","自谓二八时，歌舞入汉宫。","皇恩弄幸玉堂中，绿陌黄花催夜酒。","锦衣罗袂逐春风，建章西宫焕若神。","燕赵美女二千人，君王厌德不忘新。","况群艳冶纷来陈，是时别君不再见。","三十三春长信殿，长信重门昼掩关。","清房晓帐幽且闲，绮窗虫网氛尘色。","文轩莺对桃李颜，天王贵宫不贮老。","浩然泪陨今来还，自怜转晚暮。","试逐佳游芳草路，小腰丽女夺人奇。","金鞍少年曾不顾，归来谁为夫。","请谢西家妇，莫辞先醉解罗襦。"]},{"id":"T00464","t":"相和歌辞 长门怨","a":"李华","c":["弱体鸳鸯荐，啼妆翡翠衾。","鸦鸣秋殿晓，人静禁门深。","每忆椒房宠，那堪永巷阴。","日惊罗带缓，非复旧来心。"]},{"id":"T00465","t":"相和歌辞 春江花月夜二首 一","a":"张子容","c":["林花发岸口，气色动江新。","此夜江中月，流光花上春。","分明石潭里，宜照浣纱人。"]},{"id":"T00466","t":"相和歌辞 襄阳曲","a":"施肩吾","c":["大堤女儿郎莫寻，三三五五结同心。","清晨对镜冶容色，意欲取郎千万金。"]},{"id":"T00467","t":"相和歌辞 采莲女","a":"阎朝隐","c":["采莲女，采莲舟，春日春江碧水流。","莲衣承玉钏，莲刺罥银钩。","薄暮敛容歌一曲，氛氲香气满汀洲。"]},{"id":"T00468","t":"杂曲歌辞 妾薄命","a":"武平一","c":["有女妖且丽，裴回湘水湄。","水湄兰杜芳，采之将寄谁。","瓠犀发皓齿，双蛾嚬翠眉。","红脸如开莲，素肤若凝脂。","绰约多逸态，轻盈不自持。","常矜绝代色，复恃倾城姿。","子夫前入侍，飞燕复当时。","正悦掌中舞，宁哀团扇诗。","洛川昔云遇，高唐今尚违。","幽合禽雀噪，闲阶草露滋。","流景一何速，年华不可追。","解佩安何赠，怨咽空自悲。"]},{"id":"T00469","t":"杂曲歌辞 妾薄命","a":"李百药","c":["团扇秋风起，长门夜月明。","羞闻拊背人，恨说舞腰轻。","太常应已醉，刘君恒带酲。","横陈每虚设，吉梦竟何成。"]},{"id":"T00470","t":"杂曲歌辞 妾薄命","a":"杜审言","c":["草绿长门闭，苔青永巷幽。","宠移新爱夺，泣下故情留。","啼鸟惊残梦，飞花搅独愁。","自怜春色罢，团扇复迎秋。"]},{"id":"T00471","t":"杂曲歌辞 少年行三首 一","a":"李嶷","c":["十八羽林郎，戎衣事汉王。","臂鹰金殿侧，挟弹玉舆旁。","驰道春风起，陪游出建章。"]},{"id":"T00472","t":"杂曲歌辞 长安少年行十首 一","a":"李廓","c":["金紫少年郎，绕街鞍马光。","身从左中尉，官属右春坊。","刬戴扬州帽，重熏异国香。","垂鞭踏青草，来去杏园芳。"]},{"id":"T00473","t":"杂曲歌辞 东飞伯劳歌","a":"李峤","c":["传书青鸟迎箫凤，巫岭荆台数通梦。","谁家窈窕住园楼，五马千金照陌头。","罗裙玉佩当轩出，点翠施红竞春日。","佳人二八盛舞歌，羞将百万呈双娥。","庭前芳树朝夕改，空驻妍华欲谁待。"]},{"id":"T00474","t":"杂曲歌辞 行路难五首 一","a":"贺兰进明","c":["君不见嵒下井，百尺不及泉。","君不见山上蒿，数寸凌云烟。","人生相命亦如此，何苦太息自忧煎。","但愿亲友长含笑，相逢莫吝杖头钱。","寒夜邀欢须秉烛，岂得空思花柳年。"]},{"id":"T00475","t":"杂曲歌辞 古别离","a":"王缙","c":["下阶欲离别，相对映兰丛。","含辞未及吐，泪落兰丛中。","高堂静秋日，罗衣飘暮风。","谁能待明月，回首见床空。"]},{"id":"T00476","t":"杂曲歌辞 茱萸女","a":"万楚","c":["山阴柳家女，九日采茱萸。","复得东邻伴，双为陌上姝。","插花向高髻，结子置长裾。","作性恒迟缓，非关诧丈夫。","平明折林树，日入反城隅。","侠客邀罗袖，行人挑短书。","蛾眉自有主，年少莫踟蹰。"]},{"id":"T00477","t":"杂曲歌辞 江上曲","a":"李嘉祐","c":["江上澹澹芙蓉花，江口蛾眉独浣纱。","可怜应是阳台女，坐对鸬鹚娇不语。","掩面羞看北地人，回首忽作空山雨。","苍梧秋色不堪论，千载依依帝子魂。","君看峰上斑斑竹，尽是湘妃泣泪痕。"]},{"id":"T00478","t":"杂曲歌辞 昔昔盐 垂柳覆金堤","a":"赵嘏","c":["新年垂柳色，袅袅对空闺。","不畏芳菲好，自缘离别嗁。","因风飘玉户，向日映金堤。","驿使何时度？还将赠陇西。"]},{"id":"T00479","t":"杂曲歌辞 堂堂 一","a":"李义府","c":["镂月成歌扇，裁云作舞衣。","自怜回雪影，好取洛川归。"]},{"id":"T00480","t":"杂曲歌辞 伊州 歌第一","a":"盖嘉运","c":["秋风明月独离居，荡子从戎十载余。","征人去日殷勤属，归鴈来时数寄书。"]},{"id":"T00481","t":"杂曲歌辞 踏歌词 一","a":"崔液","c":["彩女迎金屋，仙姬出画堂。","鸳鸯裁锦袖，翡翠帖花黄。","歌响舞分行，艳色动流光。"]},{"id":"T00482","t":"杂歌谣辞 步虚词 一","a":"韦渠牟","c":["玉简真人降，金书道箓通。","烟霞方蔽日，云雨已生风。","四极威仪异，三天使命同。","那将人世恋，不去上清宫。"]},{"id":"T00483","t":"早春桂林殿应诏","a":"陈叔达","c":["金铺照春色，玉律动年华。","朱楼云似盖，丹桂雪如花。","水岸衔阶转，风条出柳斜。","轻舆临太液，湛露酌流霞。"]},{"id":"T00484","t":"奉和执契静三边应诏","a":"许敬宗","c":["玄塞隔阴戎，朱光分昧谷。","地游穷北际，云崖尽西陆。","星次绝轩台，风衢乖禹服。","寰区无所外，天覆今咸育。","窜苗犹有孽，戮负自贻辜。","疎网妖鲵漏，盘薮怪禽逋。","髯飞尚假息，乳视暂稽诛。","干灵振玉弩，神略运璇枢。","日羽廓游气，天阵清华野。","升晅光西夜，驰恩溢东泻。","挥袂静昆炎，开关纳流赭。","锦轺凌右地，华缨羇大夏。","清台映罗叶，玄沚控瑶池。","驼鹿输珍贶，树羽飨来仪。","辍肴观化宇，栖籞萃条支。","熏风交阆阙，就日泛蒙漪。","充庭延饮至，绚简敷春藻。","迎姜已创图，命力方论道。","昔托游河乘，再备商山皓。","欣逢德化流，思效登封草。"]},{"id":"T00485","t":"古意六首 一","a":"王绩","c":["幽人在何所？紫岩有仙躅。","月下横宝琴，此外将安欲。","材抽峄山干，徽点昆丘玉。","漆抱蛟龙唇，丝缠凤凰足。","前弹广陵罢，后以明光续。","百金买一声，千金传一曲。","世无钟子期，谁知心所属。"]},{"id":"T00486","t":"上之回","a":"陈子良","c":["承平重游乐，诏跸上之回。","属车响流水，清笳转落梅。","岭云盖道转，岩花映绶开。","下辇便高宴，何如在瑶台。"]},{"id":"T00487","t":"奉和上元酺宴应诏","a":"杨炯","c":["甲乙遇灾年，周隋送上弦。","妖星六丈出，沴气七重悬。","赤县空无主，苍生欲问天。","龟龙开宝命，云火昭灵庆。","万物覩真人，千秋逢圣政。","祖宗玄泽远，文武休光盛。","大号域中平，皇威天下惊。","参辰昭文物，宇宙浃声名。","汉后三章令，周王五伐兵。","匈奴穷地角，本自远正朔。","骄子起天街，由来亏礼乐。","一衣扫风雨，再战夷屯剥。","清明日月旦，萧索烟云涣。","寒暑既平分，阴阳复贞观。","惟神谐妙物，乃圣符幽赞。","下武发祯祥，平阶属会昌。","金泥封日观，璧水匝明堂。","业盛勋华德，兴包天地皇。","孝思义罔极，易礼光前式。","天焕三辰辉，灵书五云色。","敬时穷发歛，卜代盈千亿。","五纬聚华轩，重光入望园。","公卿论至道，天子拜昌言。","雷解初开出，星空即便元。","瑶台凉景荐，银阙秋阴遍。","百戏骋鱼龙，千门壮宫殿。","深仁洽蛮徼，恺乐周寰县。","宣室召群臣，明庭礼百神。","仰德还符日，沾恩更似春。","襄城非牧竖，楚国有巴人。"]},{"id":"T00488","t":"初春行宫侍宴应制","a":"苏味道","c":["温液吐涓涓，跳波急应弦。","簪裾承睿赏，花柳发韶年。","圣酒千钟洽，宸章七曜悬。","微臣从此醉，还似梦钧天。"]},{"id":"T00489","t":"古劒篇","a":"郭震","c":["君不见昆吾铁冶飞炎烟，红光紫气俱赫然。","良工锻炼凡几年，铸得宝劒名龙泉。","龙泉颜色如霜雪，良工咨嗟叹奇绝。","琉璃玉匣吐莲花，错镂金环映明月。","正逢天下无风尘，幸得周防君子身。","精光黯黯青蛇色，文章片片绿龟鳞。","非直结交游侠子，亦曾亲近英雄人。","何言中路遭弃捐，零落漂沦古狱边。","虽复尘埋无所用，犹能夜夜气冲天。"]},{"id":"T00490","t":"奉和九日幸临渭亭登高应制得月字","a":"韦元旦","c":["云物开千里，天行乘九月。","丝言丹凤池，斾转苍龙阙。","灞水欢娱地，秦京游侠窟。","欣承解愠词，圣酒黄花发。"]},{"id":"T00491","t":"汾阴后土祠作","a":"李适","c":["昔予读旧史，遍覩汉世君。","武皇实稽古，建兹百代勋。","号令垂懋典，旧经备阙文。","西巡历九嶷，舳舻被江滨。","勒兵十八万，旌旗何纷纷。","朅来茂陵下，英声不复闻。","我行岁方晏，极望山河分。","神光终冥漠，鼎气独氛氲。","揽涕步脽上，登高见彼汾。","雄图今安在，飞飞有白云。"]},{"id":"T00492","t":"奉和圣制夏日游石淙山","a":"武三思","c":["此地岩壑数千重，吾君驾鹤□乘龙。","掩暎叶光含翡翠，参差石影带芙蓉。","白日将移冲叠𪩘，玄云欲度碍高峰。","对酒鸣琴追野趣，时闻清吹入长松。"]},{"id":"T00493","t":"偶游龙门北溪忽怀骊山别业因以言志示弟淑奉呈诸大僚","a":"韦嗣立","c":["幽谷杜陵边，风烟别几年。","偶来伊水曲，溪嶂觉依然。","傍浦怜芳树，寻崖爱绿泉。","岭云随马足，山鸟向人前。","地合心俱静，言因理自玄。","短才叨重寄，尸禄愧妨贤。","每挹挂冠侣，思从初服旋。","稻粱仍欲报，岁月坐空捐。","助岳无纤块，输溟谢末涓。","还悟北辕失，方求南涧田。"]},{"id":"T00494","t":"九日幸临渭亭登高应制得开字","a":"卢藏用","c":["上月重阳满，中天万乘来。","萸依佩里发，菊向酒边开。","圣泽烟云动，宸文象纬回。","小臣无以荅，愿奉亿千杯。"]},{"id":"T00495","t":"九日幸临渭亭登高应制得酒字","a":"马怀素","c":["睿赏叶通三，宸游契重九。","兰将叶布席，菊用香浮酒。","落日下桑榆，秋风歇杨柳。","幸齐东户庆，希荐南山寿。"]},{"id":"T00496","t":"陪张燕公登南楼","a":"赵冬曦","c":["抑郁何以欢，阴氛亦登望。","孤岛轻雾里，行舟白波上。","目劳西北云，心醉东南嶂。","昔日青谿子，胡然此无状。"]},{"id":"T00497","t":"初出京邑有怀旧林","a":"卢僎","c":["赋生期独得，素业守微班。","外忝文学知，鸿渐鹓鹭间。","内倾水木趣，筑室依近山。","晨趋天日[晏]，夕卧江海闲。","松风生坐隅，仙禽舞亭湾。","曙云林下客，霁月池上颜。","虽曰坐郊园，静默非人寰。","时步苍龙阙，宁异白云关。","语济岂时顾，默善忘世攀。","世网余何触，天涯谪南蛮。","回首思洛阳，喟然悲贞艰。"]},{"id":"T00498","t":"赠皇甫侍御赴都八首 一","a":"元希声","c":["东南之美，生于会稽。","牛斗之气，蓄于昆溪。","有瑶者玉，连城是齐。","有威者凤，非梧不栖。"]},{"id":"T00499","t":"奉和圣制立春日侍宴内殿出剪彩花应制","a":"赵彦昭","c":["剪彩迎初候，攀条故写真。","花随红意发，叶就绿情新。","嫩色惊衔燕，轻香误采人。","应为熏风拂，能令芳树春。"]},{"id":"T00500","t":"奉和九日幸临渭亭登高应制得余字","a":"萧至忠","c":["望幸三秋暮，登高九日初。","朱旗巡汉苑，翠帟俯秦墟。","宠极萸房遍，恩深菊酎余。","承欢何以荅，万亿奉宸居。"]},{"id":"T00501","t":"百子池","a":"张谔","c":["旧闻百子汉家池，汉家渌水今逶迤。","宫女厌镜笑窥池，身前影后不相见。"]},{"id":"T00502","t":"登翅头山题俨公石壁","a":"包融","c":["晨登翅头山，山曛黄雾起。","却瞻迷向背，直下失城市。","暾日衔东郊，朝光生邑里。","扫除诸烟氛，照出众楼雉。","青为洞庭山，白是太湖水。","苍茫远郊树，倏忽不相似。","万象以区别，森然共盈几。","坐令开心胸，渐觉落尘滓。","北岩千余仞，结庐谁家子。","愿陪中峰游，朝暮白云里。"]},{"id":"T00503","t":"奉使登终南山","a":"王湾","c":["常爱南山游，因而尽原隰。","数朝至林岭，百仞登嵬岌。","石壮马径穷，苔色步缘入。","物奇春状改，气远天香集。","虚洞策杖鸣，低云拂衣湿。","倚岩见庐舍，入户欣拜揖。","问性矜勤劳，示心教澄习。","玉英时共饭，芝草为余拾。","境绝人不行，潭深鸟空立。","一乘从此授，九转兼是给。","辞处若轻飞，憩来唯吐吸。","闲襟超已胜，回路倏而及。","烟色松上深，水流山下急。","渐平逢车骑，向晚睨城邑。","峰在野趣繁，尘飘宦情澁。","辛苦久为吏，劳生何妄执。","日暮怀此山，悠然赋斯什。"]},{"id":"T00504","t":"南山","a":"贺朝","c":["湖北雨初晴，湖南山尽见。","岩岩石帆影，如得海风便。","仙穴茅山峰，彩云时一见。","邀君共探此，异箓残几卷。"]},{"id":"T00505","t":"和左司张员外自洛使入京中路先赴长安逢立春日赠韦侍御等诸公","a":"孙逖","c":["拜郎登省闼，奉使驰车乘。","遥瞻使者星，便是郎官应。","台妙时相许，皇华德弥称。","二陕听风谣，三秦望形胜。","此中暌益友，是日多诗兴。","寒尽岁阴催，春归物华证。"]},{"id":"T00506","t":"赠程秘书","a":"卢象","c":["客自岐阳来，吐音若鸣凤。","孤飞畏不偶，独立谁见用。","忽从被褐中，召入承明宫。","圣人借颜色，言事无不通。","殷勤拯黎庶，感激论诸公。","将相猜贾谊，图书归马融。","顾余久寂寞，一岁麒麟阁。","且共歌太平，勿嗟名宦薄。"]},{"id":"T00507","t":"嵩山十志十首 其一","a":"卢鸿一","c":["山为宅兮草为堂，芝兰兮药房。","罗蘼芜兮拍薜荔，荃壁兮兰砌。","蘼芜薜荔兮成草堂，阴阴邃兮馥馥香。","中有人兮信宜常，读金书兮饮玉浆，童颜幽操兮不易长。"]},{"id":"T00508","t":"书殿赐宴应制","a":"徐安贞","c":["校文常近日，赐宴忽升天。","酒正传桮至，饔人捧案前。","玉阶鸣溜水，清阁引归烟。","共惜芸香暮，春风几万年。"]},{"id":"T00509","t":"青龙寺昙壁上人院集","a":"裴迪","c":["灵境信为绝，法堂出尘氛。","自然成高致，向下看浮云。","迤逦峰岫列，参差闾井分。","林端远堞见，风末疎钟闻。","吾师久禅寂，在世超人群。"]},{"id":"T00510","t":"题农父庐舍","a":"丘为","c":["东风何时至，已绿湖上山。","湖上春已早，田家日不闲。","沟塍流水处，耒耜平芜间。","薄暮饭牛罢，归来还闭关。"]},{"id":"T00511","t":"古意二首 一","a":"祖咏","c":["夫差日淫放，举国求妃嫔。","自谓得王宠，代间无美人。","碧罗象天阁，坐辇乘芳春。","宫女数千骑，常游江水滨。","年深玉颜老，时薄花妆新。","拭泪下金殿，娇多不顾身。","生前妬歌舞，死后同灰尘。","冢墓令人哀，哀于铜雀台。"]},{"id":"T00512","t":"冬夜寓居寄储太祝","a":"綦毋潜","c":["自为洛阳客，夫子吾知音。","尽义能下士，时人无此心。","奈何离居夜，巢鸟悲空林。","愁坐至月上，复闻南邻砧。"]},{"id":"T00513","t":"题杼山癸亭得暮字","a":"颜真卿","c":["杼山多幽绝，胜事盈跬步。","前者虽登攀，淹留恨晨暮。","及兹纡胜引，曾是美无度。","歘构三癸亭，实为陆生故。","高贤能剏物，疏凿皆有趣。","不越方丈间，居然云霄遇。","巍峨倚修岫，旷望临古渡。","左右苔石攒，低昂桂枝蠹。","山僧狎猨狖，巢鸟来枳椇。","俯视何楷台，傍瞻戴颙路。","迟回未能下，夕照明村树。"]},{"id":"T00514","t":"江有枫一篇十章 一","a":"萧颖士","c":["江有枫，其叶蒙蒙。","我友自东，于以游从。"]},{"id":"T00515","t":"古意","a":"崔曙","c":["绿笋总成竹，红花亦成子。","能当此时好，独自幽闺里。","夜夜苦更长，愁来不如死。"]},{"id":"T00516","t":"读后汉逸人传二首 一","a":"张谓","c":["子陵没已久，读史思其贤。","谁谓颍阳人，千秋如比肩。","尝闻汉皇帝，曾是旷周旋。","名位苟无心，对君犹可眠。","东过富春渚，乐此佳山川。","夜卧松下月，朝看江上烟。","钓时如有待，钓罢应忘筌。","生事在林壑，悠悠经暮年。","于今七里濑，遗迹尚依然。","高台竟寂寞，流水空潺湲。"]},{"id":"T00517","t":"天长节","a":"梁锽","c":["日月生天久，年年庆一回。","时平祥不去，寿远节长来。","连吹千家笛，同朝百郡杯。","愿持金殿镜，处处照遗才。"]},{"id":"T00518","t":"送泉州李使君之任","a":"包何","c":["傍海皆荒服，分符重汉臣。","云山百越路，市井十洲人。","执玉来朝远，还珠入贡频。","连年不见雪，到处即行春。"]},{"id":"T00519","t":"奉陪韦中丞使君游鹤林寺","a":"皇甫曾","c":["古寺传灯久，层城闭阁闲。","香花同法侣，旌斾入深山。","寒磬虚空里，孤云起灭间。","谢公忆高卧，徒御欲东还。"]},{"id":"T00520","t":"鼓吹曲辞 战城南","a":"李白","c":["去年战桑干源，今年战葱河道。","洗兵条支海上波，放马天山雪中草。","万里长征战，三军尽衰老。","匈奴以杀戮为耕作，古来唯见白骨黄沙田。","秦家筑城备胡处，汉家还有烽火然。","烽火然不息，征战无已时。","野战格鬬死，败马号鸣向天悲。","乌鸢啄人肠，衔飞上挂枯树枝。","士卒涂草莽，将军空尔为。","乃知兵者是凶器，圣人不得已而用之。"]},{"id":"T00521","t":"横吹曲辞 前出塞九首 二","a":"杜甫","c":["出门日已远，不受徒旅欺。","骨肉恩岂断，男儿死无时。","走马脱辔头，手中挑青丝。","捷下万仞冈，俯身试搴旗。"]},{"id":"T00522","t":"横吹曲辞 出塞","a":"王维","c":["居延城外猎天骄，白草连天野火烧。","暮云空碛时驱马，秋日平原好射雕。","护羌校尉朝乘障，破虏将军夜渡辽。","玉靶角弓珠勒马，汉家将赐霍嫖姚。"]},{"id":"T00523","t":"相和歌辞 挽歌","a":"白居易","c":["丹旐何飞扬，素骖亦悲鸣。","晨光照闾巷，輀车俨欲行。","萧条九月天，哀挽出重城。","借问送者谁，妻子与弟兄。","苍苍上古原，峨峨开新茔。","含酸一恸哭，异口同哀声。","旧垄转芜绝，新坟日罗列。","春风草绿北邙山，此地年年生死别。"]},{"id":"T00524","t":"相和歌辞 王昭君","a":"李商隐","c":["毛延寿画欲通神，忍为黄金不为人。","马上琵琶行万里，汉宫长有隔生春。"]},{"id":"T00525","t":"杂曲歌辞 少年行二首 一","a":"杜牧","c":["官为骏马监，职帅羽林儿。","两绶藏不见，落花何处期？","猎敲白玉镫，怒袖紫金锤。","田窦长留醉，苏辛曲护岐。","豪持出塞节，笑别远山眉。","捷报云台贺，公卿拜寿巵。"]},{"id":"T00526","t":"相和歌辞 长歌行","a":"王昌龄","c":["旷野饶悲风，飕飕黄蒿草。","系马停白杨，谁知我怀抱。","所是同袍者，相逢尽衰老。","况登汉家陵，南望长安道。","下有枯树根，上有鼷鼠窠。","高皇子孙尽，千古无人过。","宝玉频发掘，精灵其奈何？","人生须达命，有酒且长歌。"]},{"id":"T00527","t":"从张丞相游南纪城猎戏赠裴迪张参军","a":"孟浩然","c":["从禽非吾乐，不好云梦田。","岁暮登城望，偏令相思悬。","公卿有几几，车骑何翩翩。","世禄金张贵，官曹幕府贤。","顺时行杀气，飞刃争割鲜。","十里届宾馆，徵声匝妓筵。","高标回落日，平楚散芳烟。","何意狂歌客，从公亦在旃。"]},{"id":"T00528","t":"鼓吹曲辞 凯歌六首 二","a":"岑参","c":["官军西出过楼兰，营幕傍临月窟寒。","蒲海晓霜凝劒尾，葱山夜雪扑旌竿。"]},{"id":"T00529","t":"杂曲歌辞 蓟门行五首 一","a":"高适","c":["边城十一月，雨雪乱霏霏。","元戎号令严，人马亦轻肥。","羌胡无尽日，征战几人归。"]},{"id":"T00530","t":"相和歌辞 团扇郎","a":"刘禹锡","c":["团扇复团扇，奉君清暑殿。","秋风入庭树，从此不相见。","上有乘鸾女，苍苍虫网遍。","明年入怀袖，别是机中练。"]},{"id":"T00531","t":"鼓吹曲辞 鼓吹铙歌 兽之穷","a":"柳宗元","c":["兽之穷，奔大麓。","天厚黄德，狙犷服。","甲之櫜弓，弭矢箙。","皇旅靖，敌逾蹙。","自亡其徒，匪予戮。","屈𧹁猛，虔栗栗。","縻以尺组，噉以秩。","黎之阳，土茫茫。","富兵戎，盈仓箱。","乏者德，莫能享。","驱豺兕，授我疆。"]},{"id":"T00532","t":"鼓吹曲辞 有所思","a":"韦应物","c":["借问江上柳，青青为谁春。","空游昨日地，不见昨日人。","缭绕万家井，往来车马尘。","莫道无相识，要非心所亲。"]},{"id":"T00533","t":"相和歌辞  董逃行","a":"元稹","c":["董逃董逃董卓逃，揩铿戈甲声劳嘈。","剜剜深脐脂燄燄，人皆数叹曰。","尔独不忆年年取我身上膏，膏销骨尽烟火死。","长安城中贼毛起，城门四走公卿士。","走劝刘虞作天子，刘虞不敢作天子。","曹瞒纂乱从此始，董逃董逃人莫喜。","胜负飜环相枕倚，缝缀难成裁破易。","何况曲针不能伸巧指，欲学裁缝须准拟。"]},{"id":"T00534","t":"琴曲歌辞 拘幽操","a":"韩愈","c":["目揜揜兮其凝其盲，耳肃肃兮听不闻声。","朝不日出兮夜不见月与星，有知无知兮为死为生。","呜呼！臣罪当诛兮天王圣明。"]},{"id":"T00535","t":"鼓吹曲辞 上之回","a":"李贺","c":["上之回，大旗喜。","悬虹彗，挞凤尾。","劒匣破，舞蛟龙。","蚩尤死，鼓逢逢。","天高庆雷齐坠地，地无惊烟海千里。"]},{"id":"T00536","t":"相和歌辞 公无渡河","a":"温庭筠","c":["黄河怒浪连天来，大响谹谹如殷雷。","龙伯驱风不敢上，百川喷雪高崔嵬。","二十五弦何太哀？请公勿渡立裴回。","下有狂蛟锯为尾，裂帆截櫂磨霜齿。","神锥凿石塞神潭，白马𫎺𧽼赤尘起。","公乎跃马扬玉鞭，灭没高蹄日千里。"]},{"id":"T00537","t":"相和歌辞 铜雀台","a":"刘长卿","c":["娇爱更何日？高台空数层。","含啼映双袖，不忍看西陵。","漳河东流无复来，百花辇路为苍苔。","青楼月夜长寂寞，碧云日暮空裴回。","君不见邺中万事非昔时，古人何在今人悲。","春风不逐君王去，草色年年旧宫路。","宫中歌舞已浮云，空指行人往来处。"]},{"id":"T00538","t":"奉和圣制烛龙斋祭","a":"张九龄","c":["上帝临下，鉴亦有光。","孰云阴隲，惟圣克彰。","六月徂暑，四郊愆阳。","我后其勤，告于坛场。","精意允溢，群灵鼓舞。","蔚兮朝云，沛然时雨。","雨我原田，亦既有年。","烛龙煌煌，明宗报祀。","于以助之，天人帝子。","闻诗有训，国风兹始。"]},{"id":"T00539","t":"庆云章","a":"陈子昂","c":["昆仑元气，实生庆云。","大人作矣，五色氤氲。","昔在帝妫，南风既薰。","丛芳烂熳，郁郁纷纷。","旷矣千祀，庆云来止。","玉叶金柯，祚我天子。","非我天子，庆云谁昌。","非我圣母，庆云谁光。","庆云光矣，周道昌矣。","九万八千，天授皇年。"]},{"id":"T00540","t":"鼓吹曲辞 巫山高二首 二","a":"孟郊","c":["见尽数万里，不闻三声猨。","但飞萧萧雨，中有亭亭魂。","千载楚襄恨，遗文宋玉言。","至今青冥里，云结深闺门。"]},{"id":"T00541","t":"唐禅社首乐章 顺和","a":"贺知章","c":["至哉含柔德，万物资以生。","常顺称厚载，流谦通变盈。","圣心事能察，增广陈厥诚。","黄祇僾如在，泰折俟咸亨。"]},{"id":"T00542","t":"横吹曲辞 陇头","a":"张籍","c":["陇头已断人不行，胡骑夜入凉州城。","汉家处处格鬬死，一朝尽没陇西地。","驱我边人胡中去，散放牛羊食禾黍。","去年中国养子孙，今著毡裘学胡语。","谁能更使李轻车，收取凉州属汉家。"]},{"id":"T00543","t":"横吹曲辞 望行人","a":"王建","c":["自从江树秋，日日上江楼。","梦见离珠浦，书来在桂州。","不同鱼比目，终恨水分流。","久不开明镜，多应是白头。"]},{"id":"T00544","t":"相和歌辞 长门怨","a":"卢纶","c":["空宫古廊殿，寒月照斜晖。","卧听未央曲，满箱歌舞衣。"]},{"id":"T00545","t":"相和歌辞 置酒行","a":"李益","c":["置酒命所欢，凭觞遂为戚。","日往不再来，兹辰坐成昔。","百龄非长久，五十将半百。","胡为劳我形，已须还复白。","西山鸾鹤顾，矫矫烟雾翮。","明霞发金丹，阴洞潜水碧。","安得凌风羽，崦嵫驻灵魄。","兀然坐衰老，慙叹东陵柏。"]},{"id":"T00546","t":"横吹曲辞 出塞","a":"皇甫冉","c":["吹角出塞门，前瞻即胡地。","三军尽回首，皆洒望乡泪。","转念关山长，行看风景异。","由来征戍客，各负轻生义。"]},{"id":"T00547","t":"杂曲歌辞 少年行","a":"韩翃","c":["千点斓斒喷玉骢，青丝结尾绣缠騣。","鸣鞭晚出章台路，叶叶春依杨柳风。"]},{"id":"T00548","t":"帝京篇十首 二","a":"太宗皇帝","c":["岩廊罢机务，崇文聊驻辇。","玉匣启龙图，金绳披凤篆。","韦编断仍续，缥帙舒还卷。","对此乃淹留，欹案观坟典。"]},{"id":"T00549","t":"七夕宴悬圃二首 一","a":"高宗皇帝","c":["羽盖飞天汉，凤驾越层峦。","俱叹三秋阻，共敍一宵欢。","璜亏夜月落，靥碎晓星残。","谁能重操杼，纤手濯清澜。"]},{"id":"T00550","t":"行次成皋途经先圣擒建德之所缅思功业感而赋诗","a":"明皇帝","c":["有隋政昏虐，群雄已交争。","先圣按劒起，叱咤风云生。","饮马河洛竭，作气嵩华惊。","克敌睿图就，擒俘帝道亨。","顾慙嗣宝历，恭承天下平。","幸过翦鲸地，感慕神且英。"]},{"id":"T00551","t":"中和节赐百官燕集因示所怀","a":"德宗皇帝","c":["至化恒在宥，保和兹息人。","推诚抚诸夏，与物长为春。","仲月风景暖，禁城花柳新。","芳时协金奏，赐宴同群臣。","丝竹岂云乐，忠贤惟所亲。","庶洽朝野意，旷然天地均。"]},{"id":"T00552","t":"唐享昊天乐 第一","a":"则天皇后","c":["太阴凝至化，真耀蕴轩仪。","德迈娥台敞，仁高[姒]幄披。","扪天遂启极，梦日乃升曦。"]},{"id":"T00553","t":"九月九日上幸慈恩寺登浮图群臣上菊花寿酒","a":"上官昭容","c":["帝里重阳节，香园万乘来。","却邪萸入佩，献寿菊传杯。","墖类承天涌，门疑待佛开。","睿词悬日月，长得仰昭回。"]},{"id":"T00554","t":"秋莺","a":"后主煜","c":["残莺何事不知秋，横过幽林尚独游。","老舌百般倾耳听，深黄一点入烟流。","栖迟背世同悲鲁，浏亮如笙碎在缑。","莫更留连好归去，露华凄冷蓼花愁。"]},{"id":"T00555","t":"玄都观","a":"蜀太后徐氏","c":["千寻绿嶂夹流溪，登眺因知海岳低。","瀑布迸舂青石碎，轮茵横翦翠峰齐。","步黏苔藓龙桥滑，日闭烟罗鸟径迷。","莫道穹天无路到，此山便是碧云梯。"]},{"id":"T00556","t":"玄都观","a":"蜀太妃徐氏","c":["登寻丹壑到玄都，接日红霞照座隅。","即向周回岩下看，似看曾进画图无。"]},{"id":"T00557","t":"郊庙歌辞 祀圜丘乐章 太和","a":"褚亮","c":["穆穆我后，道应千龄。","登三处大，得一居贞。","礼惟崇德，乐以和声。","百神仰止，天下文明。"]},{"id":"T00558","t":"郊庙歌辞 封泰山乐章 豫和 二","a":"张说","c":["亿上帝，临下庭。","骑日月，陪列星。","嘉祝信，大糦馨。","澹神心，醉皇灵。"]},{"id":"T00559","t":"郊庙歌辞 武后明堂乐章 皇帝行","a":"武则天","c":["仰膺历数，俯顺讴歌。","远安迩肃，俗阜时和。","化光玉镜，讼息金科。","方兴典礼，永戢干戈。"]},{"id":"T00560","t":"郊庙歌辞 五郊乐章 黄帝宫音 肃和","a":"魏征","c":["眇眇方舆，苍苍圜盖。","至哉枢纽，宅中图大。","气调四序，风和万籁。","祚我明德，时雍道泰。"]},{"id":"T00561","t":"郊庙歌辞 祀风师乐章 奠币登歌","a":"包佶","c":["旨酒告絜，青苹应候。","礼陈瑶币，乐献金奏。","弹弦自昔，解冻惟旧。","仰瞻肸蚃，群祥来凑。"]},{"id":"T00562","t":"郊庙歌辞 享龙池乐章 第七章","a":"苏颋","c":["西京凤邸跃龙泉，佳气休光镇在天。","轩后雾图今已得，秦王水劒昔常传。","恩鱼不似昆明钓，瑞鹤长如太液仙。","愿侍巡游同旧里，更闻箫鼓济楼船。"]},{"id":"T00563","t":"郊庙歌辞 禅社首乐章 太和","a":"贺知章、源乾曜","c":["肃我成命，于昭黄祇。","裘冕而祀，陟降在斯。","五音克备，八音聿施。","缉熙肆靖，厥心匪离。"]},{"id":"T00564","t":"奉和圣制夏日游石淙山","a":"姚崇","c":["二室三涂光地险，均霜揆日处天中。","石泉石镜恒留月，山鸟山花竞逐风。","周王久谢瑶池赏，汉主悬慙玉树宫。","别有祥烟伴佳气，能随轻辇共葱葱。"]},{"id":"T00565","t":"鼓吹曲辞 巫山高二首 一","a":"沈佺期","c":["巫山峰十二，环合隐昭回。","俯眺琵琶峡，平看云雨台。","古槎天外倚，瀑水日边来。","何忽啼猨夜，荆王枕席开。"]},{"id":"T00566","t":"奉和九月九日登慈恩寺浮图应制","a":"崔日用","c":["紫宸欢每洽，绀殿法初隆。","菊泛延龄酒，兰吹解愠风。","咸英调正乐，香梵徧秋空。","临幸浮天瑞，重阳日再中。"]},{"id":"T00567","t":"招谕有怀赠同行人","a":"李乂","c":["远游冒艰阻，深入劳存谕。","春去辞国门，秋还在边戍。","轩车行未返，节序催难驻。","陌上悲转蓬，园中想芳树。","蜀山自纷纠，岷水恒奔注。","临泛多苦怀，登攀寡欢趣。","永夕飞淫雨，崇朝蒸毒雾。","不求绥岭桃，宁美邛乡蒟。","白浪行欲静，骢马何尝驱。","愿接轺斾尘，联翩东北骛。"]},{"id":"T00568","t":"郊庙歌辞 享太庙乐章 肃和","a":"魏征、褚亮","c":["大哉至德，允兹明圣。","格于上下，聿遵诚敬。","嘉乐斯登，鸣球以咏。","神其降止，式隆景命。"]},{"id":"T00569","t":"郊庙歌辞 德明兴圣庙乐章 登歌奠币","a":"李舒","c":["四时有典，百事来祭。","尊祖奉宗，严禋大帝。","礼先苍璧，奠币黝制。","于斯万年，熙成帝系。"]},{"id":"T00570","t":"鼓吹曲辞 芳树","a":"徐彦伯","c":["玉花珍簟上，金缕画屏开。","晓月怜筝柱，春风忆镜台。","筝柱春风吹晓月，芳树落花朝暝歇。","藳砧刀头未有时，攀条拭泪坐相思。"]},{"id":"T00571","t":"仪坤庙乐章二首 一","a":"薛稷","c":["阳灵配德，阴魄昭升。","尧坛凤下，汉室龙兴。","伣天作对，前旒是凝。","化行南国，道盛西陵。","造舟集灌，无德而称。","我粢既洁，我醴既澄。","阴阴灵庙，光灵若凭。","德馨惟飨，孝思烝烝。"]},{"id":"T00572","t":"相和歌辞 櫂歌行","a":"徐坚","c":["櫂女饰银钩，新妆下翠楼。","霜丝青桂檝，兰栧紫霞舟。","水落金陵曙，风起洞庭秋。","扣船过曲浦，飞帆越回流。","影入桃花浪，香飘杜若洲。","洲长殊未返，萧散云霞晚。","日下大江平，烟生归岸远。","岸远闻潮波，争途游戏多。","因声赵津女，来听采菱歌。"]},{"id":"T00573","t":"相和歌辞 从军行三首 一","a":"王涯","c":["旌甲从军久，风云识阵难。","今朝韩信计，日下斩成安。"]},{"id":"T00574","t":"郊庙歌辞 梁郊祀乐章 庆和 二","a":"赵光逢、张衮","c":["秉黄钺，建朱旗。","震八表，清二仪。","帝业显，王道夷。","受景命，启皇基。"]},{"id":"T00575","t":"鼓吹曲辞 战城南","a":"卢照邻","c":["将军出紫塞，冒顿在乌贪。","笳喧雁门北，阵翼龙城南。","雕弓夜宛转，铁骑晓参潭。","应须驻白日，为待战方酣。"]},{"id":"T00576","t":"鼓吹曲辞 战城南二首 二","a":"僧贯休","c":["碛中有阴兵，战马时惊蹶。","轻猛李陵心，摧残苏武节。","黄金锁子甲，风吹色如铁。","十载不封侯，茫茫向谁说。"]},{"id":"T00577","t":"横吹曲辞 折杨柳","a":"李端","c":["东城攀柳叶，柳叶低著草。","少壮莫轻年，轻年有人老。","柳发徧川岗，登高堪断肠。","雨烟轻漠漠，何树近君乡？","赠君折杨柳，颜色岂能久。","上客莫沾巾，佳人正回首。","新柳送君行，古柳伤君情。","突兀临荒渡，婆娑出旧营。","隋家两岸尽，陶宅五株平。","日暮偏愁望，春山有鸟声。"]},{"id":"T00578","t":"相和歌辞 猛虎行","a":"僧齐己","c":["磨尔牙，错尔爪，狐莫威，兔莫狡，饮来吞噬取肠饱。","横行不怕日月明，皇天产尔为生狞。"]},{"id":"T00579","t":"相和歌辞 铜雀妓 一","a":"王勃","c":["妾本深宫妓，曾城闭九重。","君王欢爱尽，歌舞为谁容。","锦衾不复襞，罗衣谁再缝。","高台西北望，流涕向青松。"]},{"id":"T00580","t":"陇头水","a":"杨师道","c":["陇头秋月明，陇水带关城。","笳添离别曲，风送断肠声。","映雪峰犹暗，乘冰马屡惊。","雾中寒雁至，沙上转蓬轻。","天山传羽檄，汉地急征兵。","阵开都护道，劒聚伏波营。","于兹觉无渡，方共濯胡缨。"]},{"id":"T00581","t":"横吹曲辞 陇头水 二","a":"僧皎然","c":["秦陇逼氐羌，征人去未央。","如何幽咽水，幷欲断君肠。","西注悲穷漠，东分忆故乡。","旅魂声搅乱，无梦到辽阳。"]},{"id":"T00582","t":"相和歌辞 苦战远征人","a":"鲍溶","c":["征人歌古曲，携手上河梁。","李陵死别处，杳杳玄冥乡。","忆昔从此路，连年征鬼方。","久行迷汉历，三洗氊衣裳。","百战身且在，微功信难忘。","远承云台议，非势孰敢当。","落日吊李广，白身过河阳。","闲弓失月影，劳劒无龙光。","去日始束发，今来发成霜。","虚名乃闲事，生见父母乡。","掩抑大风歌，裴回少年场。","诚哉古人言，鸟尽良弓藏。"]},{"id":"T00583","t":"横吹曲辞 折杨柳","a":"张祜","c":["红粉青楼曙，垂杨仲月春。","怀君重攀折，非妾妒腰身。","舞带萦丝断，娇娥向叶嚬。","横吹凡几曲，独自最愁人。"]},{"id":"T00584","t":"相和歌辞 江南曲八首 一","a":"刘希夷","c":["暮宿南洲草，晨行北岸林。","日悬沧海阔，水隔洞庭深。","烟景无留意，风波有异浔。","岁游难极目，春戏易为心。","朝夕无荣遇，芳菲已满襟。"]},{"id":"T00585","t":"相和歌辞 铜雀妓","a":"乔知之","c":["金阁惜分香，𫓪华不重妆。","空余歌舞地，犹是为君王。","哀弦调已绝，艳曲不须长。","共看西陵暮，秋烟生白杨。"]},{"id":"T00586","t":"奉和圣制立春日侍宴内殿出剪彩花应制","a":"刘宪","c":["上林宫馆好，春光独早知。","剪花疑始发，刻燕似新窥。","色浓轻雪点，香浅嫩风吹。","此日叨陪侍，恩荣得数枝。"]},{"id":"T00587","t":"相和歌辞 倢伃怨","a":"崔湜","c":["不分君恩断，新妆视镜中。","容华尚春日，娇爱已秋风。","枕席临窗晓，帏屏向月空。","年年后庭树，荣落在深宫。"]},{"id":"T00588","t":"折杨柳","a":"韦承庆","c":["万里边城地，三春杨柳节。","叶似镜中眉，花如关外雪。","征人远乡思，倡妇高楼别。","不忍掷年华，含情寄攀折。"]},{"id":"T00589","t":"关山月","a":"崔融","c":["月生西海上，气逐边风壮。","万里度关山，苍茫非一状。","汉兵开郡国，胡马窥亭障。","夜夜闻悲笳，征人起南望。"]},{"id":"T00590","t":"相和歌辞  相逢行","a":"崔颢","c":["妾年初二八，家住洛桥头。","玉户临驰道，朱门近御沟。","使君何假问，夫壻大长秋。","女弟新承宠，诸兄近拜侯。","春生百子殿，花发五城楼。","出入千门里，年年乐未休。"]},{"id":"T00591","t":"相和歌辞 短歌行六首 一","a":"顾况","c":["城边路，今人犂田昔人墓。","岸上沙，昔时江水今人家。","今人昔人共长叹，四气相催节回换。","明月皎皎入华池，白云离离度清汉。"]},{"id":"T00592","t":"相和歌辞 短歌行","a":"聂夷中","c":["八月木荫薄，十叶三堕枝。","人生过五十，亦已同此时。","朝出东郭门，嘉树郁参差。","暮出西郭门，原草已离披。","南邻好台榭，北邻善歌吹。","荣华忽消歇，四顾令人悲。","生死与荣辱，四者乃常期。","古人耻其名，没世无人知。","无言鬓似霜，勿谓发如丝。"]},{"id":"T00593","t":"相和歌辞 铜雀台","a":"薛能","c":["魏帝当时铜雀台，黄花深映棘丛开。","人生富贵须回首，此地岂无歌舞来。"]},{"id":"T00594","t":"相和歌辞 王子乔","a":"宋之问","c":["王子乔，爱神仙，七月七日上宾天。","白虎摇瑟凤吹笙，乘骑云气吸日精。","吸日精，长不归，遗庙今在而人非。","空望山头草，草露湿君衣。"]},{"id":"T00595","t":"和荐福寺英公新搆禅堂","a":"丁仙芝","c":["上人久弃世，中道自忘筌。","寂照出群有，了心清众缘。","所以于此地，筑馆开青莲。","果药罗砌下，烟虹垂户前。","咒中洒甘露，指处流香泉。","禅远目无事，体清宵不眠。","枳闻庐山法，松入汉阳禅。","一枕西山外，虚舟常浩然。"]},{"id":"T00596","t":"相和歌辞 江南曲 一","a":"陆龟蒙","c":["鱼戏莲叶间，参差隐叶扇。","䴔䴖鸀鳿窥，潋滟无因见。"]},{"id":"T00597","t":"杂曲歌辞 悲哉行","a":"孟云卿","c":["孤儿去慈亲，远客丧主人。","莫吟苦辛曲，谁忍闻可闻。","可闻不可说，去去无期别。","行人念前程，不待参辰没。","朝亦常苦饥，暮亦常苦饥。","飘飘万余里，贫贱多是非。","少年莫远游，远游多不归。"]},{"id":"T00598","t":"相和歌辞 王昭君","a":"崔国辅","c":["汉使南还尽，胡中妾独存。","紫台緜望绝，秋草不堪论。"]},{"id":"T00599","t":"送陆擢","a":"常建","c":["圣代多才俊，陆生何考槃。","南山高松树，不合空摧残。","九月湖上别，北风秋雨寒。","殷勤叹孤凤，早食金琅玕。"]},{"id":"T00600","t":"相和歌辞 从军行","a":"骆宾王","c":["平生一顾念，意气溢三军。","野日分戈影，天星合劒文。","弓弦抱汉月，马足践胡尘。","不求生入塞，唯当死报君。"]},{"id":"T00601","t":"奉和过旧宅应制","a":"上官仪","c":["石关清晚夏，璇舆御早秋。","神麾飏珠雨，仙吹响飞流。","沛水祥云泛，宛郊瑞气浮。","大风迎汉筑，藂烟入舜球。","翠梧临凤邸，滋兰带鹤舟。","偃伯歌玄化，扈跸颂王游。","遗簪谬昭奖，珥笔荷恩休。"]},{"id":"T00602","t":"相和歌辞 三妇艳诗","a":"董思恭","c":["大妇裁纨素，中妇弄明珰。","小妇多姿态，登楼红粉妆。","丈人且安坐，初日渐流光。"]},{"id":"T00603","t":"相和歌辞 王昭君三首 二","a":"郭元振","c":["厌践冰霜域，嗟为边塞人。","思从汉南猎，一见汉家尘。"]},{"id":"T00604","t":"相和歌辞 猛虎行","a":"储光羲","c":["寒亦不忧雪，饥亦不食人。","人血岂不甘，所恶伤明神。","太室为我宅，孟门为我邻。","百兽为我膳，五龙为我宾。","蒙马一何威，浮江亦以仁。","彩章耀朝日，牙爪雄武臣。","高云逐气浮，厚地随声振。","君能贾余勇，日夕长相亲。"]},{"id":"T00605","t":"相和歌辞 从军行五首 一","a":"令狐楚","c":["荒鸡隔水啼，汗马逐风嘶。","终日随征斾，何时罢鼓鼙。"]},{"id":"T00606","t":"杂曲歌辞 秋夜曲","a":"张仲素","c":["丁丁漏水夜何长，漫漫轻云露月光。","秋壁暗虫通夕响，寒衣未寄莫飞霜。"]},{"id":"T00607","t":"相和歌辞 蜀道难","a":"张文琮","c":["梁山镇地险，积石阻云端。","深谷下寥廓，层岩上郁盘。","飞梁架绝岭，栈道接危峦。","揽辔独长息，方知斯路难。"]},{"id":"T00608","t":"侍宴长宁公主东庄应制","a":"郑愔","c":["公门袭汉环，主第称秦玉。","池架祥鳣序，山吹鸣凤曲。","拂席萝薜垂，回舟芰荷触。","平阳妙舞处，日暮清歌续。"]},{"id":"T00609","t":"杂曲歌辞 古离别","a":"王适","c":["昔岁惊杨柳，高楼悲独守。","今年芳树枝，孤栖怨别离。","珠帘昼不卷，罗幔晓长垂。","苦调琴先觉，愁容镜独知。","频来鴈度无消息，罢去鸳文何用织。","夜还罗帐空有情，春著帬腰自无力。","青轩桃李落纷纷，紫庭兰蕙日氛氲。","已能顦顇今如此，更复含情一待君。"]},{"id":"T00610","t":"相和歌辞 长门怨","a":"袁晖","c":["早知君爱歇，本自无萦妬。","谁使恩情深，今来反相误。","愁眠罗帐晓，泣坐金闺暮。","独有梦中魂，犹言意如故。"]},{"id":"T00611","t":"琴曲歌辞 胡笳十八拍 第一拍","a":"刘商","c":["汉室将衰兮四夷不宾，动干戈兮征战频。","哀哀父母生育我，见离乱兮当此辰。","纱窗对镜未经事，将谓珠帘能蔽身。","一朝虏骑入中国，苍黄处处逢胡人。","忽将薄命委锋镝，可惜红颜随虏尘。"]},{"id":"T00612","t":"古塞下曲","a":"陶翰","c":["进军飞狐北，穷寇势将变。","日落沙尘昏，背河更一战。","骍马黄金勒，雕弓白羽箭。","射杀左贤王，归奏未央殿。","欲言塞下事，天子不召见。","东出咸阳门，哀哀泪如霰。"]},{"id":"T00613","t":"相和歌辞 从军行二首 二","a":"虞世南","c":["爟火发金微，连营出武威。","孤城寒云起，绝阵虏尘飞。","侠客吸龙劒，恶少缦胡衣。","朝摩骨都垒，夜解谷蠡围。","萧关远无极，蒲海广难依。","沙磴离旌断，晴川候马归。","交河梁已毕，燕山斾欲飞。","方知万里相，侯服有光辉。"]},{"id":"T00614","t":"杂曲歌辞 缓歌行","a":"李颀","c":["小来托身攀贵游，倾财破产无所忧。","暮拟经过石渠署，朝将出入铜龙楼。","结交杜陵轻薄子，谓言可生复可死。","一沈一浮会有时，弃我翻然如脱屣。","男儿立身须自彊，十五闭户颍水阳。","业就功成见明主，击钟鼎食坐华堂。","二八蛾眉梳堕马，美酒清歌曲房下。","文昌宫中赐锦衣，长安陌上退朝归。","五侯宾从莫敢视，三省官僚揖者稀。","早知今日读书是，悔作从来任侠非。"]},{"id":"T00615","t":"相和歌辞 苦哉行五首 一","a":"戎昱","c":["彼鼠侵我厨，纵貍授梁肉。","鼠虽为君却，貍食自须足。","冀雪大国耻，飜是大国辱。","膻腥逼绮罗，甎瓦杂珠玉。","登楼非骋望，目笑是心哭。","何意天乐中，至今奏胡曲。"]},{"id":"T00616","t":"相和歌辞 蛾眉怨","a":"王翰","c":["君不见宜春苑中九华殿，飞阁连连直如发。","白日全含朱鸟窗，流云半入苍龙阙。","宫中彩女夜无事，学凤吹箫弄清越。","珠帘北卷待凉风，绣户南开向明月。","忽闻天子忆蛾眉，宝凤衔花揲两螭。","传声走马开金屋，夹路鸣环上玉墀。","长乐彤庭宴华寝，三千美人曳光锦。","灯前含笑更罗衣，帐里承恩荐瑶枕。","不意君心半路回，求仙别作望仙台。","仓琅禁闼遥相忆，紫翠岩房昼不开。","欲向人间种桃实，先从海底觅蓬莱。","蓬莱可求不可上，孤舟缥缈知何往？","黄金作盘铜作茎，晴天白露掌中擎。","王母嫣然感君意，云车雨斾欲相迎。","飞帘观前空怨慕，少君何事须相误。","一朝埋没茂陵田，贱妾蛾眉不重顾。","宫车晚出向南山，仙卫逶迤去不还。","朝晡泣对麒麟树，树下苍苔日渐斑。","人生百年夜将半，对酒长歌莫长叹。","賸知白日不可思，一死一生何足算。"]},{"id":"T00617","t":"相和歌辞 怨诗二首 二","a":"薛奇童","c":["禁苑春风起，流莺绕合欢。","玉窗通日气，珠箔卷轻寒。","杨叶垂金砌，梨花入井阑。","君王好长袖，新作舞衣宽。"]},{"id":"T00618","t":"相和歌辞 长门怨","a":"吴少微","c":["月出映曾城，孤圜上太清。","君王春爱歇，枕席凉风生。","怨咽不能寝，踟蹰步前楹。","空阶白露色，百草寒虫鸣。","念昔金房里，犹嫌玉座轻。","如何娇所误，长夜泣恩情。"]},{"id":"T00619","t":"杂诗六首 一","a":"李华","c":["黄钟扣元音，律吕更循环。","邪气悖正声，郑卫生其间。","典乐忽涓微，波浪与天浑。","嘈嘈鸱枭动，好鸟徒緜蛮。","王吉归乡里，甘心长闭关。"]},{"id":"T00620","t":"相和歌辞 春江花月夜二首 二","a":"张子容","c":["交甫怜瑶佩，仙妃难重期。","沈沈绿江晚，惆怅碧云姿。","初逢花上月，言是弄珠时。"]},{"id":"T00621","t":"杂曲歌辞 少年行","a":"施肩吾","c":["醉骑白马走空衢，恶少皆称电不如。","五凤街头闲勒辔，半垂衫袖揖金吾。"]},{"id":"T00622","t":"琴曲歌辞 明月歌","a":"阎朝隐","c":["梅花雪白柳叶黄，云雾四起月苍苍，箭水泠冷刻漏长。","挥玉指，拂罗裳，为君一奏楚明光。"]},{"id":"T00623","t":"妾薄命","a":"武平一","c":["有女妖且丽，裴回湘水湄。","水湄兰杜芳，采之将寄谁。","瓠犀发皓齿，双蛾颦翠眉。","红脸如开莲，素肤若凝脂。","绰约多逸态，轻盈不自持。","尝矜绝代色，复恃倾城姿。","子夫前入侍，飞燕复当时。","正悦掌中舞，宁哀团扇诗。","洛川昔云遇，高唐今尚违。","幽合禽雀噪，闲阶草露滋。","流景一何速，年华不可追。","解佩安所赠，怨咽空自悲。"]},{"id":"T00624","t":"杂曲歌辞 少年子","a":"李百药","c":["少年飞翠盖，上路动金镳。","始酌文君酒，新吹弄玉箫。","少年不欢乐，何以尽芳朝。","千金笑里面，一搦抱中腰。","挂冠岂惮宿，迎拜不胜娇。","寄语少年子，无辞归路遥。"]},{"id":"T00625","t":"杂曲歌辞 大酺乐 一","a":"杜审言","c":["圣后乘干日，皇明御历辰。","紫宫初启坐，苍璧正临春。","雷雨垂膏泽，金钱赐下人。","诏酺欢赏徧，交泰覩惟新。"]},{"id":"T00626","t":"杂曲歌辞 少年行三首 二","a":"李嶷","c":["侍猎长杨下，承恩更射飞。","尘生马影灭，箭落鴈行稀。","薄暮归随仗，联翩入琐闱。"]},{"id":"T00627","t":"杂曲歌辞 长安少年行十首 二","a":"李廓","c":["追逐轻薄伴，闲游不著绯。","长拢出猎马，数换打毬衣。","晓日寻花去，春风带酒归。","青楼无昼夜，歌舞歇时稀。"]},{"id":"T00628","t":"杂曲歌辞 桃花行 一","a":"李峤","c":["岁去无言忽顦顇，时来含笑吐氛氲。","不能拥路迷仙客，故欲开蹊侍圣君。"]},{"id":"T00629","t":"杂曲歌辞 行路难五首 二","a":"贺兰进明","c":["君不见门前柳，荣曜暂时萧索久。","君不见陌上花，狂风吹去落谁家。","谁家思妇见之叹，蓬首不梳心历乱。","盛年夫壻长别离，岁暮相逢色凋换。"]},{"id":"T00630","t":"古离别","a":"王缙","c":["下阶欲离别，相对映兰丛。","含辞未及吐，泪落兰丛中。","高堂静秋日，罗衣飘暮风。","谁能待明月，回首见床空。"]},{"id":"T00631","t":"小山歌","a":"万楚","c":["人说淮南有小山，淮王昔日此登仙。","城中鸡犬皆飞去，山上坛场今宛然。","世人贵身不贵寿，共笑华阳洞天口。","不知金石变长年，谩在人间恋携手。","君能举帆至淮南，家住盱眙余先谙。","桐柏乱流平入海，茱萸一曲沸成潭。","忆记来时魂悄悄，想见仙山众峰小。","今日长歌思不堪，君行为报三青鸟。"]},{"id":"T00632","t":"江上曲","a":"李嘉祐","c":["江心澹澹芙蓉花，江口蛾眉独浣纱。","可怜应是阳台女，对坐鹭鸶娇不语。","掩面羞看北地人，回身忽作空山语。","苍梧秋色不堪论，千载依依帝子魂。","君看峰上斑斑竹，尽是湘妃泣泪痕。"]},{"id":"T00633","t":"杂曲歌辞 昔昔盐 蘼芜叶复齐","a":"赵嘏","c":["提筐红叶下，度日采蘼芜。","掬翠香盈袖，看花忆故夫。","叶齐谁复见，风暖恨偏孤。","一被春光累，容颜与昔殊。"]},{"id":"T00634","t":"杂曲歌辞 堂堂 二","a":"李义府","c":["嬾正鸳鸯被，羞褰玳瑁床。","春风别有意，密处也寻香。"]},{"id":"T00635","t":"杂曲歌辞 伊州 歌第二","a":"盖嘉运","c":["彤闱晓辟万鞍回，玉辂春游薄晚开。","渭北清光摇草树，州南嘉景入楼台。"]},{"id":"T00636","t":"杂曲歌辞 踏歌词 二","a":"崔液","c":["庭际花微落，楼前汉已横。","金壶催夜尽，罗袖拂寒轻。","乐笑畅欢情，未半著天明。"]},{"id":"T00637","t":"杂歌谣辞 步虚词 二","a":"韦渠牟","c":["羽驾正翩翩，云鸿最自然。","霞冠将月晓，珠佩与星连。","镂玉留新诀，雕金得旧编。","不知飞鸟学，更有几人仙。"]},{"id":"T00638","t":"后渚置酒","a":"陈叔达","c":["大渚初惊夜，中流沸鼓鼙。","寒沙满曲浦，夕雾上邪谿。","岸广凫飞急，云深鴈度低。","严关犹未遂，此夕待晨鸡。"]},{"id":"T00639","t":"奉和行经破薛举战地应制","a":"许敬宗","c":["混元分大象，长策挫修鲸。","于斯建宸极，由此创鸿名。","一戎干宇泰，千祀德流清。","垂衣凝庶绩，端拱铸群生。","复整瑶池驾，还临官渡营。","周游寻曩迹，旷望动天情。","帷宫面丹浦，帐殿瞩宛城。","虏场栖九穗，前歌被六英。","战地甘泉涌，阵处景云生。","普天沾凯泽，相携欣颂平。"]},{"id":"T00640","t":"古意六首 二","a":"王绩","c":["竹生大夏谿，苍苍富奇质。","绿叶吟风劲，翠茎犯霄密。","霜霰封其柯，鹓鸾食其实。","宁知轩辕后，更有伶伦出。","刀斧俄见寻，根株坐相失。","裁为十二管，吹作雄雌律。","有用虽自伤，无心复招疾。","不如山上草，离离保终吉。"]},{"id":"T00641","t":"新成安乐宫","a":"陈子良","c":["春色照兰宫，秦女坐牕中。","柳叶来眉上，桃花落脸红。","拂尘开扇匣，卷帐却薰笼。","衫薄偏憎日，裙轻更畏风。"]},{"id":"T00642","t":"广溪峡","a":"杨炯","c":["广溪三峡首，旷望兼川陆。","山路遶羊肠，江城镇鱼腹。","乔林百丈偃，飞水千寻瀑。","惊浪回高天，盘涡转深谷。","汉氏昔云季，中原争逐鹿。","天下有英雄，襄阳有龙伏。","常山集军旅，永安兴版筑。","池台忽已倾，邦家遽沦覆。","庸才若刘禅，忠佐为心腹。","设险犹可存，当无贾生哭。"]},{"id":"T00643","t":"单于川对雨二首 一","a":"苏味道","c":["崇朝遘行雨，薄晚屯密云。","缘阶起素沫，竟水聚圆文。","河柳低未举，山花落已芬。","清尊久不荐，淹留遂待君。"]},{"id":"T00644","t":"塞上","a":"郭震","c":["塞外虏尘飞，频年出武威。","死生随玉劒，辛苦向金微。","久戍人将老，长征马不肥。","仍闻酒泉郡，已合数重围。"]},{"id":"T00645","t":"奉和送金城公主适西蕃应制","a":"韦元旦","c":["柔远安夷俗，和亲重汉年。","军容旌节送，国命锦车传。","琴曲悲千里，箫声恋九天。","唯应西海月，来就掌珠圆。"]},{"id":"T00646","t":"荅宋十一崖口五渡见赠","a":"李适","c":["闻君访远山，跻险造幽绝。","眇然青云境，观奇弥年月。","登岭亦溯溪，孤舟事沿越。","崿嶂传彩翠，崖磴互欹缺。","石林上攒藂，金涧下明灭。","扪壁窥丹井，梯苔瞰乳穴。","忽枉岩中赠，对玩未尝辍。","殷勤独往事，委曲炼药说。","邀余名山期，从尔泛海澨。","岁晏秉宿心，斯言非徒设。"]},{"id":"T00647","t":"仙鹤篇","a":"武三思","c":["白鹤乘空何处来？青田紫盖本相依。","缑山七月虽长去，辽水千年会忆归。","缑山杳杳翔寥廓，辽水累累叹城郭。","经随羽客步丹丘，曾逐仙人游碧落。","迢迢碧落断氛埃，霞堂云阁几重开。","欲寻东海黄金灶，仍向西山白玉台。","九臯独唳方清切，五里惊群俄断绝。","月下分行似度云，风前飏影疑回雪。","风前月下路漫漫，水宿云翔去几般。","宛转能倾吴国市，裴回巧拂汉皇坛。","琴中作曲从来易，鼓里传声有甚难。","夜夜恒飞银汉曲，朝朝常饮玉池澜。","别有闻箫出紫烟，还如化履上青天。","霜毛忽控三神下，玉羽俄看二客旋。","燕雀终迷横海志，蜉蝣岂识在阴年。","莫言一举轻千里，为与三山送九仙。"]},{"id":"T00648","t":"奉和九日幸临渭亭登高应制得深字","a":"韦嗣立","c":["层观远沈沈，鸾旗九日临。","帷宫压水岸，步辇入烟岑。","枝上萸新采，樽中菊始斟。","愿陪欢乐事，长与岁时深。"]},{"id":"T00649","t":"奉和九月九日登慈恩寺浮图应制","a":"卢藏用","c":["化塔龙山起，中天凤辇迂。","彩旒牵画刹，杂珮冒香萸。","宝叶擎千座，金英渍百盂。","秋云飘圣藻，霄极捧连珠。"]},{"id":"T00650","t":"奉和九月九日登慈恩寺浮图应制","a":"马怀素","c":["季月启重阳，金舆陟宝坊。","御旗横日道，仙塔俨云庄。","帝跸千官从，干词七曜光。","顾慙文墨职，无以颂时康。"]},{"id":"T00651","t":"酬燕公出湖见寄","a":"赵冬曦","c":["纶綍有成命，旌麾不可攀。","湘川朝目断，荆阙夕波还。","果枉东瞻唱，兴言夕放闲。","携琴仙洞中，置酒㴩湖上。","芳景恣行乐，谪居忽如忘。","聚散本相因，离情自悲怅。","鸾翮非常戢，鹏天会昭旷。","永怀宛洛游，曾是弹冠望。"]},{"id":"T00652","t":"稍秋晓坐阁遇舟东下扬州既事寄上族父江阳令","a":"卢僎","c":["虎啸山城晚，猨鸣江树秋。","红林架落照，青峡送归流。","归流赴淮海，征帆下扬州。","族父江阳令，盛业继前修。","文掩崔亭伯，德齐陈太丘。","时哉惜未与，千载且为俦。","忆昔山阳会，长怀东上游。","称觞阮林下，赋雪谢庭幽。","道浓礼自略，气舒文转遒。","高情薄云汉，酣态坐芳洲。","接席复连轸，出入陪华辀。","独善与兼济，语默奉良筹。","岁月欢无已，风雨暗飕飕。","掌宪时持节，为邦邈海头。","子人惠虽树，苍生望且留。","微躬趋直道，神甸忝清猷。","仙台适西步，蛮徼忽南浮。","宇内皆安乐，天涯独远投。","忠信徒坚仗，神明岂默詶。","观生海漫漫，稽命天悠悠。","云昏巴子峡，月远吴王楼。","怀昔明不寐，悲令岁属周。","喟无排云翮，暂得抒离忧。","空洒沾红泪，万里逐行舟。"]},{"id":"T00653","t":"赠皇甫侍御赴都八首 二","a":"元希声","c":["猗嗟众珍，以况君子。","公侯之胄，必复其始。","利器长材，温仪峻峙。"]},{"id":"T00654","t":"奉和人日清晖阁宴群臣遇雪应制","a":"赵彦昭","c":["出震乘东陆，凭高御北辰。","祥云应早岁，瑞雪候初旬。","庭树千花发，阶蓂七叶新。","幸承今日宴，长奉万年春。"]},{"id":"T00655","t":"奉和九月九日登慈恩寺浮图应制","a":"萧至忠","c":["天跸三乘启，星舆六辔行。","登高凌宝塔，极目徧王城。","神衞空中遶，仙歌云外清。","重阳千万寿，率舞颂升平。"]},{"id":"T00656","t":"东封山下宴群臣","a":"张谔","c":["万里扈封峦，群公遇此欢。","幔城连夜静，霜仗满空寒。","辇路宵烟合，旌门晓月残。","明朝陪圣主，山下礼圆坛。"]},{"id":"T00657","t":"阮公啸台","a":"包融","c":["荒台森荆杞，蒙笼无上路。","传是古人迹，阮公长啸处。","至今清风来，时时动林树。","逝者共已远，升攀想遗趣。","静然荒榛门，久之若有悟。","灵光未歇灭，千载知仰慕。"]},{"id":"T00658","t":"晚夏马嵬卿叔池亭即事寄京都一二知己","a":"王湾","c":["忝职畿甸淹，滥陪时俊后。","才轻策疲劣，势薄常驱走。","牵役劳风尘，秉心在岩薮。","宗贤开别业，形胜代希偶。","竹绕清渭滨，泉流白渠口。","逡巡期赏会，挥忽变星斗。","逮此乘务闲，因而访幽叟。","入来殊景物，行复洗纷垢。","林静秋色多，潭深月光厚。","盛香莲近拆，新味瓜初剖。","滞拙怀隐沦，书之寄良友。"]},{"id":"T00659","t":"孤兴","a":"贺朝","c":["晴日暖珠箔，夭桃色正新。","红粉青镜中，娟娟可怜嚬。","君子在遐险，蕙心谁见珍。","罗幕空掩昼，玉颜静移春。","江瑟语幽独，再三情未申。","黄鹄千里翅，芳音迟所因。"]},{"id":"T00660","t":"和登会稽山","a":"孙逖","c":["稽山碧湖上，势入东溟尽。","烟景昼清明，九峰争隐嶙。","望中厌朱绂，俗内探玄牝。","野老听鸣驺，山童拥行轸。","仙花寒未落，古蔓柔堪引。","竹磵入山多，松崖向天近。","云从海天去，日就江村陨。","能赋丘尝闻，和歌参不敏。","冥搜信冲漠，多士期标准。","愿奉濯缨心，长谣反招隐。"]},{"id":"T00661","t":"家叔征君东溪草堂二首 一","a":"卢象","c":["开山十余里，青壁森相倚。","欲识尧时天，东溪白云是。","雷声转幽壑，云气杳流水。","涧影生龙蛇，岩端翳柽梓。","大道终不易，君恩曷能已。","鹤羡无老时，龟言摄生理。","浮年笑六甲，元化潜一指。","未暇扫云梯，空慙阮氏子。"]},{"id":"T00662","t":"嵩山十志十首 其二","a":"卢鸿一","c":["天门豁兮仙台耸，杰屹崒兮零澒涌。","穷三休兮旷一观，忽若登昆仑兮中期汗漫仙。","耸天关兮倒景台，鲨颢气兮轶嚣埃。","皎皎之子兮自独立，云可朋兮赮可吸，曾何荣辱之所及。"]},{"id":"T00663","t":"从驾温泉宫","a":"徐安贞","c":["神女调温液，年年待圣人。","试开临水殿，来洗属车尘。","暖气随明主，恩波浃近臣。","灵威自无极，从此献千春。"]},{"id":"T00664","t":"青雀歌","a":"裴迪","c":["动息自适性，不曾妄与燕雀群。","幸忝鹓鸾早相识，何时提携致青云。"]},{"id":"T00665","t":"泛若耶谿","a":"丘为","c":["结庐若耶里，左右若耶水。","无日不钓鱼，有时向城市。","溪中水流急，渡口水流宽。","每得樵风便，往来殊不难。","一川草长绿，四时那得辨。","短褐衣妻儿，余粮及鸡犬。","日暮鸟雀稀，稚子呼牛归。","住处无邻里，柴门独掩扉。"]},{"id":"T00666","t":"古意二首 二","a":"祖咏","c":["楚王竟何去，独自留巫山。","偏使世人见，迢迢江汉间。","驻舟春谿里，誓愿拜灵颜。","梦寐覩神女，金沙鸣珮环。","闲艳绝世姿，令人气力微。","含笑默不语，化作朝云飞。"]},{"id":"T00667","t":"题鹤林寺","a":"綦毋潜","c":["道林隐形胜，向背临层霄。","松覆山殿[冷]，花藏谿路遥。","珊珊宝幡挂，焰焰明灯烧。","迟日半空谷，春风连上潮。","少凭水木兴，暂令身心调。","愿谢携手客，兹山禅诵饶。"]},{"id":"T00668","t":"谢陆处士杼山折青桂花见寄之什","a":"颜真卿","c":["群子游杼山，山寒桂花白。","绿荑含素蕚，采折自逋客。","忽枉岩中诗，芳香润金石。","全高南越蠹，岂谢东堂策。","会惬名山期，从君恣幽觌。"]},{"id":"T00669","t":"江有枫一篇十章 二","a":"萧颖士","c":["山有槭，其叶漠漠。","我友徂北，于以休息。"]},{"id":"T00670","t":"宿大通和尚塔敬赠如上人兼呈常孙二山人","a":"崔曙","c":["支公已寂灭，影塔山上古。","更有真僧来，道场救诸苦。","一承微妙法，寓宿清净土。","身心能自观，色相了无取。","森森松映月，漠漠云近户。","岭外飞电明，夜来前山雨。","然灯见栖鸽，作礼闻信鼓。","晓霁南轩开，秋华净天宇。","愿言出世尘，谢尔申及甫。"]},{"id":"T00671","t":"读后汉逸人传二首 二","a":"张谓","c":["庞公南郡人，家在襄阳里。","何处偏来往，襄阳东陂是。","誓将业田种，终得保妻子。","何言二千石，乃欲劝吾仕。","鹳鹊巢茂林，鼋鼍穴深水。","万物从所欲，吾心亦如此。","不见鹿门山，朝朝白云起。","采药复采樵，优游终暮齿。"]},{"id":"T00672","t":"长门怨","a":"梁锽","c":["妾命何偏薄，君王去不归。","欲令遥见悔，楼上试春衣。","空殿看人入，深宫羡鸟飞。","翻悲因买赋，索镜照空辉。"]},{"id":"T00673","t":"和孟虔州闲斋即事","a":"包何","c":["古郡邻江岭，公庭半薜萝。","府僚闲不入，山鸟静偏过。","睥睨临花柳，栏干枕芰荷。","麦秋今欲至，君听两岐歌。"]},{"id":"T00674","t":"奉送杜侍御还京","a":"皇甫曾","c":["罢战回龙节，朝天上凤池。","寒生五湖道，春入万年枝。","召化多遗爱，胡清已畏知。","怀恩偏感别，堕泪向旌麾。"]},{"id":"T00675","t":"鼓吹曲辞 君马黄","a":"李白","c":["君马黄，我马白。","马色虽不同，人心本无隔。","共作游冶盘，双行洛阳陌。","长劒既照曜，高冠何赩赫。","各有千金裘，俱为五侯客。","猛虎落陷穽，壮夫时屈厄。","相知在急难，独好亦何益。"]},{"id":"T00676","t":"横吹曲辞 前出塞九首 三","a":"杜甫","c":["磨刀呜咽水，水赤刃伤手。","欲轻肠断声，心绪乱已久。","丈夫誓许国，愤惋复何有？","功名图麒麟，战骨当速朽。"]},{"id":"T00677","t":"相和歌辞 从军行","a":"王维","c":["吹角动行人，喧喧行人起。","笳鸣马嘶乱，争渡金河水。","日暮沙漠垂，战声烟尘里。","尽系名王颈，归来报天子。"]},{"id":"T00678","t":"相和歌辞 王昭君二首 一","a":"白居易","c":["满面胡沙满鬓风，眉销残黛脸销红。","愁苦辛勤顦顇尽，如今却似画图中。"]},{"id":"T00679","t":"杂曲歌辞 无愁果有愁曲","a":"李商隐","c":["东有青龙西白虎，中含福皇包世度。","玉壶渭水笑清潭，凿天不到牵牛处。","骐𬴊踏云天马狞，牛山撼碎珊瑚声。","秋娥点滴不成泪，十二玉楼无故钉。","推烟唾月抛千里，十番红桐一行死。","白杨别屋鬼迷人，空留暗记如蚕纸。","日暮向风牵短丝，血凝血散今谁是。"]},{"id":"T00680","t":"杂曲歌辞 少年行二首 二","a":"杜牧","c":["连环羁玉声光碎，绿锦蔽泥虬卷高。","春风细雨走马去，珠落璀璀白𦋺袍。"]},{"id":"T00681","t":"相和歌辞 从军行","a":"王昌龄","c":["向夕临大荒，朔风轸归虑。","平沙万里余，飞鸟宿何处？","虏骑猎长原，翩翩傍河去。","边声摇白草，海气生黄雾。","百战苦风尘，十年履霜露。","虽投定远笔，未坐将军树。","早知行路难，悔不理章句。"]},{"id":"T00682","t":"登江中孤屿赠白云先生王迥","a":"孟浩然","c":["悠悠清水江，水落沙屿出。","回潭石下深，绿筿岸傍密。","鲛人潜不见，渔父歌自逸。","忆与君别时，泛舟如昨日。","夕阳开返照，中坐兴非一。","南望鹿门山，归来恨如失。"]},{"id":"T00683","t":"鼓吹曲辞 凯歌六首 三","a":"岑参","c":["鸣笳擂鼓拥回军，破国平蕃昔未闻。","大夫鹊印摇边月，天将龙旗掣海云。"]},{"id":"T00684","t":"杂曲歌辞 蓟门行五首 二","a":"高适","c":["幽州多骑射，结发重横行。","一朝事将军，出入有声名。","纷纷猎秋草，相向角弓鸣。"]},{"id":"T00685","t":"相和歌辞 三阁词四首 一","a":"刘禹锡","c":["贵人三阁上，日晏未梳头。","不应有恨事，娇甚却成愁。"]},{"id":"T00686","t":"鼓吹曲辞 鼓吹铙歌 战武牢","a":"柳宗元","c":["战武牢，动河朔。","逆之助，图掎角。","怒鷇麛，抗乔岳。","翘萌牙，傲霜雹。","王谋内定，申掌握。","铺施芟夷，二主缚。","惮华戎，廓封略。","命之瞢，卑以斮。","归有德，唯先觉。"]},{"id":"T00687","t":"横吹曲辞 长安道","a":"韦应物","c":["汉家宫殿含云烟，两宫十里相连延。","晨霞出没弄丹阙，春雨依微自甘泉。","春雨依微春尚早，长安贵游爱芳草。","宝马横来下建章，香车却转避驰道。","贵游谁最贵，卫霍世难比。","何能蒙主恩？幸遇边尘起。","归来甲第拱皇居，朱门峨峨临九衢。","中有流苏合欢之宝帐，一百二十凤皇罗列含明珠。","下有锦铺翠被之粲烂，博山吐香五云散。","丽人绮阁情飘飖，头上鸳钗双翠翘。","低鬟曳袖回春雪，聚黛一声愁碧霄。","山珍海错弃藩篱，烹犊炰羔如折葵。","既请列侯封部曲，还将金印授庐儿。","欢荣若此何所苦，但苦白日西南驰。"]},{"id":"T00688","t":"相和歌辞 当来日大难","a":"元稹","c":["当来日大难行，前有坂，后有坑，大梁侧，小梁倾，两轴相绞，两轮相撑，大牛竖，小牛横，乌啄牛背，足跌力狞。","当来日大难行，太行虽险，险可使平。","轮轴自挠，牵制不停。","泥潦渐久，荆棘旋生。","行必不得，不如不行。"]},{"id":"T00689","t":"琴曲歌辞 越裳操","a":"韩愈","c":["雨之施，物以孳，我何意于彼为。","自周之先，其艰其勤。","以有疆宇，私我后人。","我祖在上，四方在下。","厥临孔威，敢戏以侮。","孰荒于门，孰治于田。","四海既均，越裳是臣。"]},{"id":"T00690","t":"鼓吹曲辞 巫山高","a":"李贺","c":["碧丛丛，高插天，大江翻澜神曳烟。","楚魂寻梦风飔然，晓风飞雨生苔钱。","瑶姬一去一千年，丁香笻竹啼老猨。","古祠近月蟾桂寒，椒花坠红湿云间。"]},{"id":"T00691","t":"相和歌辞 江南曲","a":"温庭筠","c":["妾家白苹浦，日上芙蓉檝。","轧轧摇桨声，移舟入茭叶。","溪长茭叶深，作底难相寻。","避郎郎不见，㶉𫛶自浮沈。","拾萍萍无根，采莲莲有子。","不作浮萍生，宁作藕花死。","岸傍骑马郎，乌帽紫游缰。","含愁复含笑，回首问横塘。","妾住金陵步，门前朱雀航。","流苏持作帐，芙蓉持作梁。","出入金犊幰，兄弟侍中郎。","前年学歌舞，定得郎相许。","连娟眉绕山，依约腰如杵。","凤管悲若咽，鸾弦娇欲语。","扇薄露红𫓪，罗轻压金缕。","明月西南楼，珠帘玳瑁钩。","横波巧能笑，弯蛾不识愁。","花开子留树，草长根依土。","早闻金沟远，底事归郎许。","不学杨白花，朝朝泪如雨。"]},{"id":"T00692","t":"相和歌辞 从军行六首 一","a":"刘长卿","c":["回看虏骑合，城下汉兵稀。","白刃两相向，黄云愁不飞。","手中无尺铁，徒欲突重围。"]},{"id":"T00693","t":"奉和圣制喜雨","a":"张九龄","c":["艰我稼穑，载育载亭。","随物应之，曷圣与灵。","谓我何凭，惟德之馨。","谁云天远，以诚必至。","太清无云，羲和顿辔。","于斯烝人，瞻彼非觊。","阴冥倏忽，沛泽咸洎。","何以致之，我后之感。","无皐无隰，黍稷黯黯。","无卉无木，敷芬黮黤。","黄龙勿来，鸣鸟不思。","人和年丰，皇心则怡。","岂与周宣，云汉徒诗。"]},{"id":"T00694","t":"感遇诗三十八首 一","a":"陈子昂","c":["微月生西海，幽阳始代升。","圆光正东满，阴魂已朝凝。","太极生天地，三元更废兴。","至精谅斯在，三五谁能征。"]},{"id":"T00695","t":"鼓吹曲辞 有所思","a":"孟郊","c":["桔槔烽火昼不灭，客路迢迢信难越。","古镇刀攒万片霜，寒江浪起千堆雪。","此时西去定如何，空使南心远凄切。"]},{"id":"T00696","t":"太和","a":"贺知章","c":["肃我成命，于昭黄衹。","裘冕而祀，陟降在斯。","五音克备，八变聿施。","缉熙肆靖，厥心匪离。"]},{"id":"T00697","t":"横吹曲辞 出塞","a":"张籍","c":["秋塞雪初下，将军远出师。","分营长记火，放马不收旗。","月冷边帐湿，沙昏夜探迟。","征人皆白首，谁见灭胡时。"]},{"id":"T00698","t":"横吹曲辞 关山月","a":"王建","c":["关山月，营开道白前军发。","冻轮当碛光悠悠，照见三堆两堆骨。","边风割面天欲明，金莎岭西看看没。"]},{"id":"T00699","t":"杂曲歌辞 妾薄命","a":"卢纶","c":["妾年初二八，两度嫁狂夫。","薄命今犹在，坚贞扫地无。"]},{"id":"T00700","t":"相和歌辞 从军有苦乐行","a":"李益","c":["劳者且勿歌，我欲送君觞。","从军有苦乐，此曲乐未央。","仆本居陇上，陇水断人肠。","东过秦宫路，宫路入咸阳。","时逢汉帝出，谏猎至长杨。","讵驰游侠窟，非结少年场。","一旦承嘉惠，轻命重恩光。","秉笔参帷帟，从军至朔方。","边地多阴风，草木自凄凉。","断绝海云去，出没胡沙长。","参差引雁翼，隐辚腾军装。","劒文夜如水，马汗冻成霜。","侠气五都少，矜功六郡良。","山河起目前，睚眦死路傍。","北逐驱獯虏，西临复旧疆。","昔还赋余资，今出乃赢粮。","一矢弢夏服，我弓不再张。","寄言丈夫雄，苦乐身自当。"]},{"id":"T00701","t":"相和歌辞 倢伃怨","a":"皇甫冉","c":["由来咏团扇，今与值秋风。","事逐时皆往，恩无日再中。","早鸿闻上苑，寒露下深宫。","颜色年年谢，相如赋岂工。"]},{"id":"T00702","t":"帝京篇十首 三","a":"太宗皇帝","c":["移步出词林，停舆欣武宴。","雕弓写明月，骏马疑流电。","惊雁落虚弦，啼猿悲急箭。","阅赏诚多美，于兹乃忘倦。"]},{"id":"T00703","t":"七夕宴悬圃二首 二","a":"高宗皇帝","c":["霓裳转云路，凤驾俨天潢。","亏星凋夜靥，残月落朝璜。","促欢今夕促，长离别后长。","轻梭聊驻织，掩泪独悲伤。"]},{"id":"T00704","t":"校猎义成喜逢大雪率题九韵以示群官","a":"明皇帝","c":["弧矢威天下，旌旗游近县。","一面施鸟罗，三驱教人战。","暮云成积雪，晓色开行殿。","皓然原隰同，不觉林野变。","北风勇士马，东日华组练。","触地银麞出，连山缟鹿见。","月兔落高矰，星狼下急箭。","既欣盈尺兆，复忆磻谿便。","岁丰将遇贤，俱荷皇天眷。"]},{"id":"T00705","t":"重阳日赐宴曲江亭赋六韵诗用清字","a":"德宗皇帝","c":["早衣对庭燎，躬化勤意诚。","时此万机暇，适与佳节幷。","曲池洁寒流，芳菊舒金英。","乾坤爽气满，台殿秋光清。","朝野庆年丰，高会多欢声。","永怀无荒戒，良士同斯情。"]},{"id":"T00706","t":"唐享昊天乐 第二","a":"则天皇后","c":["瞻紫极，望玄穹。","翘至恳，罄深衷。","听虽远，诚必通。","垂厚泽，降云宫。"]},{"id":"T00707","t":"彩书怨","a":"上官昭容","c":["叶下洞庭初，思君万里余。","露浓香被冷，月落锦屏虚。","欲奏江南曲，贪封蓟北书。","书中无别意，惟怅久离居。"]},{"id":"T00708","t":"病起题山舍壁","a":"后主煜","c":["山舍初成病乍轻，杖藜巾褐称闲情。","炉开小火深回暖，沟引新流几曲声。","暂约彭涓安朽质，终期宗远问无生。","谁能役役尘中累，贪合鱼龙搆强名。"]},{"id":"T00709","t":"丈人观谒先帝御容","a":"蜀太后徐氏","c":["圣帝归梧野，躬来谒圣颜。","旋登三径路，似陟九嶷山。","日照堆岚迥，云横积翠间。","期修封禅礼，方俟再跻攀。"]},{"id":"T00710","t":"游丈人观谒先帝御容","a":"蜀太妃徐氏","c":["共谒御容仪，还同在禁闱。","笙歌喧宝殿，彩仗耀金徽。","清泪沾罗袂，红霞拂绣衣。","九疑山水远，无路继湘妃。"]},{"id":"T00711","t":"郊庙歌辞 祀圜丘乐章 肃和","a":"褚亮","c":["闿阳播气，甄曜垂明。","有赫圜宰，深仁曲成。","日丽苍璧，烟开紫营。","聿遵干享，式降鸿祯。"]},{"id":"T00712","t":"郊庙歌辞 封泰山乐章 豫和 三","a":"张说","c":["相百辟，贡八荒。","九歌敍，万舞翔。","肃振振，铿皇皇。","帝欣欣，福穰穰。"]},{"id":"T00713","t":"郊庙歌辞 武后明堂乐章 皇嗣出入升降","a":"武则天","c":["至人光俗，大孝通神。","谦以表性，恭惟立身。","洪规载启，茂典方陈。","誉隆三善，祥开万春。"]},{"id":"T00714","t":"郊庙歌辞 五郊乐章 黄帝宫音 雍和","a":"魏征","c":["金县夕肆，玉俎朝陈。","飨荐黄道，芬流紫宸。","迺诚迺敬，载享载禋。","崇荐斯在，惟皇是宾。"]},{"id":"T00715","t":"郊庙歌辞 祀风师乐章 迎俎酌献","a":"包佶","c":["德盛昭临，迎拜巽方。","爰候发生，式荐馨香。","酌醴具举，工歌载扬。","神歆六律，恩降百祥。"]},{"id":"T00716","t":"杂曲歌辞 长相思","a":"苏颋","c":["君不见天津桥下东流水，东望龙门北朝市。","杨柳青青宛地垂，桃红李白花参差。","花参差，柳堪结，此时忆君心断绝。"]},{"id":"T00717","t":"郊庙歌辞 禅社首乐章 肃和","a":"贺知章、源乾曜","c":["黄祇是[祗]，我其夙夜。","寅畏诚絜，匪遑宁舍。","礼以琮玉，荐厥茅藉。","念兹降康，胡宁克暇。"]},{"id":"T00718","t":"故洛阳城侍宴应制","a":"姚崇","c":["游豫停仙跸，登临对晚晴。","川凫连倒影，岩鸟应虚声。","野奏风成曲，山居云作缨。","今朝丘壑上，高兴小蓬瀛。"]},{"id":"T00719","t":"鼓吹曲辞 巫山高二首 二","a":"沈佺期","c":["神女向高唐，巫山下夕阳。","裴回作行雨，婉娈逐荆王。","电影江前落，雷声峡外长。","霁云无处所，台馆晓苍苍。"]},{"id":"T00720","t":"奉和圣制送张说巡边","a":"崔日用","c":["轩相推风后，周官重夏卿。","庙谋能允迪，韬略又纵横。","吉日四黄马，宣王六月兵。","拟清鸡鹿塞，先指朔方城。","列将怀威抚，匈奴畏盛名。","去当推毂送，来伫出郊迎。","绝漠蓬将断，华筵槿正荣。","壮心看舞劒，别绪应悬旌。","睿锡承优旨，干文复宠行。","暂劳期永逸，赫矣振天声。"]},{"id":"T00721","t":"春日侍宴芙蓉园应制","a":"李乂","c":["水殿临丹籞，山楼绕翠微。","昔游人托乘，今幸帝垂衣。","涧筿缘峰合，岩花逗浦飞。","朝来江曲地，无处不光辉。"]},{"id":"T00722","t":"郊庙歌辞 享太庙乐章 雍和","a":"魏征、褚亮","c":["崇兹享祀，诚敬兼至。","乐以感灵，礼以昭事。","粢盛咸絜，牲牷孔备。","永言孝思，庶几不匮。"]},{"id":"T00723","t":"郊庙歌辞 德明兴圣庙乐章 迎俎","a":"李舒","c":["盛牲实俎，涓选休成。","鼎煁阳燧，玉盥阴精。","有𫗣嘉豆，既和大羹。","侑以清乐，细齐人情。"]},{"id":"T00724","t":"相和歌辞 胡无人行","a":"徐彦伯","c":["十月繁霜下，征人远凿空。","云摇锦更节，海照角端弓。","暗碛埋砂树，冲飙卷塞蓬。","方随膜拜入，歌舞玉门中。"]},{"id":"T00725","t":"仪坤庙乐章二首 二","a":"薛稷","c":["乾道既亨，坤元以贞。","肃雍攸在，辅佐斯成。","外睦九族，内光一庭。","克生睿哲，祚我休明。","钦若徽范，悠哉淑灵。","建兹清宫，于彼上京。","缩茅以献，絜秬惟馨。","实受其福，斯乎亿龄。"]},{"id":"T00726","t":"奉和圣制送张说赴集贤院学士赐宴赋得虚字","a":"徐坚","c":["崇文德化洽，新殿集贤初。","庸菲参高选，首滥承明庐。","殊私光辅弼，荣送列簪裾。","座引中厨馔，杯锡上尊余。","翠叶浓丹苑，晴空卷碧虚。","忝同文史地，愿草登封书。"]},{"id":"T00727","t":"相和歌辞 从军行三首 二","a":"王涯","c":["燕颔多奇相，狼头敢犯边。","寄言班定远，正是立功年。"]},{"id":"T00728","t":"郊庙歌辞 梁郊祀乐章 庆和 三","a":"赵光逢、张衮","c":["开九门，怀百神。","通肸蚃，接氤氲。","明粢荐，广乐陈。","奠嘉璧，燎芳薪。"]},{"id":"T00729","t":"鼓吹曲辞 巫山高","a":"卢照邻","c":["巫山望不极，望望下朝雰。","莫辨啼猿树，徒看神女云。","惊涛乱水脉，骤雨暗峰文。","沾裳即此地，况复远思君。"]},{"id":"T00730","t":"鼓吹曲辞 临高台","a":"僧贯休","c":["凉风吹远念，使我升高台。","宁知数片云，不是旧山来。","故人天一涯，久客殊未回。","雁来不得书，空寄声哀哀。"]},{"id":"T00731","t":"横吹曲辞 关山月","a":"李端","c":["露湿月苍苍，关头榆叶黄。","回轮照海远，分彩上楼长。","水冻频移幕，兵疲数望乡。","祗应城影外，万里共如霜。"]},{"id":"T00732","t":"相和歌辞 君子行","a":"僧齐己","c":["圣人不生，麟龙何瑞？","梧桐不高，凤皇何止？","吾闻古之有君子，行藏以时，进退求己。","荣必为天下荣，耻必为天下耻。"]},{"id":"T00733","t":"相和歌辞 铜雀妓 二","a":"王勃","c":["金凤邻铜雀，漳河望邺城。","君王无处所，台榭若平生。","舞筵纷可就，歌梁俨未倾。","西陵松槚冷，谁见绮罗情。"]},{"id":"T00734","t":"中书寓直咏雨简褚起居上官学士","a":"杨师道","c":["云暗苍龙阙，沈沈殊未开。","窗临凤凰沼，飒飒雨声来。","电影入飞阁，风威凌吹台。","长簷响奔溜，清簟肃浮埃。","早荷叶稍没，新篁枝半摧。","兹晨怅多绪，怀友自难裁。","况复重城内，日暮独裴回。","玉阶良史笔，金马掞天才。","高甍通散骑，复道驾蓬莱。","思君赠桃李，于此冀琼瓌。"]},{"id":"T00735","t":"相和歌辞 王昭君","a":"僧皎然","c":["自倚婵娟望主恩，谁知美恶忽相飜。","黄金不买汉宫貌，青冢空埋胡地魂。"]},{"id":"T00736","t":"相和歌辞 怨诗","a":"鲍溶","c":["女萝寄松柏，绿蔓花緜緜。","三五定君婚，结发早移天。","肃肃羊雁礼，泠泠琴瑟篇。","恭承采蘩祀，敢效同居贤。","皎日不留景，良时如逝川。","秋心还遗爱，春貌无归妍。","翠袖洗朱粉，碧阶对绮钱。","新人易如玉，废瑟难为弦。","寄羡蕣华木，荣名香阁前。","岂无摇落苦，贵与根蒂连。","希君旧光景，照妾薄暮年。"]},{"id":"T00737","t":"横吹曲辞 捉搦歌","a":"张祜","c":["门上关，墙上棘，窗中女子声唧唧，洛阳大道徒自直。","女子心在婆舍侧，呜呜笼鸟触四隅。","养男男娶妇，养女女嫁夫。","阿婆六十翁七十，不知女子长日泣，从他嫁去无悒悒。"]},{"id":"T00738","t":"相和歌辞 江南曲八首 二","a":"刘希夷","c":["艳唱潮初落，江花露未晞。","春洲惊翡翠，朱服弄芳菲。","画舫烟中浅，青阳日际微。","锦帆冲浪湿，罗袖拂行衣。","含情罢所采，相叹惜流晖。"]},{"id":"T00739","t":"相和歌辞 从军行","a":"乔知之","c":["南庭结白露，北风埽黄叶。","此时鸿燕来，惊鸣催思妾。","曲房理针线，平碪捣文练。","鸳绮裁易成，龙乡信难见。","窈窕九重闺，寂寞十年啼。","纱窗白云宿，罗幌月光栖。","云月晓微微，愁思流黄机。","玉霜冻珠履，金吹薄罗衣。","汉家已得地，君去将何事？","宛转结蚕书，寂寞无雁使。","生平荷恩信，本为容华进。","况复落红颜，蝉声催绿鬓。"]},{"id":"T00740","t":"奉和人日清晖阁宴群臣遇雪应制","a":"刘宪","c":["舆辇乘人日，登临上凤京。","风寻歌曲飏，雪向舞行萦。","千官随兴合，万福与时幷。","承恩长若此，微贱幸升平。"]},{"id":"T00741","t":"塞垣行","a":"崔湜","c":["疾风卷溟海，万里扬砂砾。","仰望不见天，昏昏竟朝夕。","是时军两进，东拒复西敌。","蔽山张旗鼓，间道潜锋镝。","精骑突晓围，奇兵袭暗壁。","十月边塞寒，四山沍阴积。","雨雪鴈南飞，风尘景西迫。","昔我事讨论，未尝怠经籍。","一朝弃笔砚，十年操矛戟。","岂要黄河誓，须勒燕然石。","可嗟牧羊臣，海上久为客。"]},{"id":"T00742","t":"寒食应制","a":"韦承庆","c":["凤城春色晚，龙禁早晖通。","旧火收槐燧，余寒入桂宫。","莺啼正隐叶，鸡鬬始开笼。","蔼蔼瑶山满，仙歌始乐风。"]},{"id":"T00743","t":"拟古","a":"崔融","c":["饮马临浊河，浊河深不测。","河水日东注，河源乃西极。","思君正如此，谁为生羽翼。","日夕大川阴，云霞千里色。","所思在河处，宛在机中织。","离梦当有魂，愁容定无力。","夙龄负奇志，中夜三叹息。","拔劒斩长榆，弯弓射小棘。","班张固非拟，衞霍行可即。","寄谢闺中人，努力加飧食。"]},{"id":"T00744","t":"琴曲歌辞 霍将军","a":"崔颢","c":["长安甲第高入云，谁家居住霍将军。","日晚朝回拥宾从，路傍揖拜何纷纷。","莫言炙手手可热，须臾火尽灰亦灭。","莫言贫贱即可欺，人生富贵自有时。","一朝天子赐颜色，世上悠悠应自知。"]},{"id":"T00745","t":"相和歌辞 短歌行六首 二","a":"顾况","c":["我欲升天天隔霄，我思渡水水无桥。","我欲上山山路险，我欲汲井井泉遥。","越人翠被今何夕，独立沙边江草碧。"]},{"id":"T00746","t":"相和歌辞 胡无人行","a":"聂夷中","c":["男儿徇大义，立节不沽名。","腰间悬陆离，大歌胡无行。","不读战国书，不览黄石经。","醉卧咸阳楼，梦入受降城。","更愿生羽翼，飞身入青冥。","请携天子劒，斫下旄头星。","自然胡无人，虽有无战争。","悠哉典属国，驱羊老一生。"]},{"id":"T00747","t":"舞曲歌辞 柘枝词 一","a":"薛能","c":["同营三十万，震鼓伐西羌。","战血黏秋草，征尘搅夕阳。","归来人不识，帝里独戎装。"]},{"id":"T00748","t":"琴曲歌辞 绿竹引","a":"宋之问","c":["青溪绿潭潭水侧，修竹婵娟同一色。","徒生仙实凤不游，老死空山人讵识。","妙年秉愿逃俗纷，归卧嵩丘弄白云。"]},{"id":"T00749","t":"赠朱中书","a":"丁仙芝","c":["十年种田滨五湖，十年遭涝尽为芜。","频年井税常不足，今年缗钱谁为输。","东邻转谷五之利，西邻贩缯日已贵。","而我守道不迁业，谁能肯敢效此事。","紫微侍郎白虎殿，出入通籍回天眷。","晨趋彩笔柏梁篇，昼出雕盘大官膳。","会应怜尔居素约，可即长年守贫贱。"]},{"id":"T00750","t":"相和歌辞 江南曲 二","a":"陆龟蒙","c":["鱼戏莲叶东，初霞射红尾。","傍临谢山侧，恰值清风起。"]},{"id":"T00751","t":"杂曲歌辞 古别离","a":"孟云卿","c":["朝日上高台，离人怨秋草。","但见万里天，不见万里道。","君行本遥远，苦乐良难保。","宿昔梦同衾，忧心梦颠倒。","含酸欲谁诉，转转伤怀抱。","结发年已迟，征行去何早。","寒暄有时谢，顦顇难再好。","人皆算年寿，死者何曾老。","少壮无见期，水深风浩浩。"]},{"id":"T00752","t":"相和歌辞 怨诗二首 一","a":"崔国辅","c":["楼前桃李疎，池上芙蓉落。","织锦犹未成，虫声入罗幕。"]},{"id":"T00753","t":"送李十一尉临溪","a":"常建","c":["泠泠花下琴，君唱渡江吟。","天际一帆影，预悬离别心。","以言神仙尉，因致瑶华音。","回轸抚商调，越溪澄碧林。"]},{"id":"T00754","t":"相和歌辞 櫂歌行","a":"骆宾王","c":["写月图黄罢，凌波拾翠通。","镜花摇芰日，衣麝入荷风。","叶密舟难荡，莲疎浦易空。","凤媒羞自托，鸳翼恨难穷。","秋帐灯花翠，倡楼粉色红。","相思无别曲，幷在櫂歌中。"]},{"id":"T00755","t":"早春桂林殿应诏","a":"上官仪","c":["步辇出披香，清歌临太液。","晓树流莺满，春堤芳草积。","风光翻露文，雪华上空碧。","花蝶来未已，山光暧将夕。"]},{"id":"T00756","t":"三妇艳","a":"董思恭","c":["大妇裁纨素，中妇弄明珰。","小妇多姿态，登楼红粉妆。","丈人且安坐，初日渐流光。"]},{"id":"T00757","t":"相和歌辞 王昭君三首 三","a":"郭元振","c":["闻有南河信，传闻杀画师。","始知君惠重，更遣画蛾眉。"]},{"id":"T00758","t":"相和歌辞 野田黄雀行","a":"储光羲","c":["啧啧野田雀，不知躯体微。","闲穿深蒿里，争食复争飞。","穷老一颓舍，枣多桑树稀。","无枣犹可食，无桑何以衣。","萧条空仓暮，相引时来归。","邪路岂不捷，渚田岂不肥。","水长路且坏，恻恻与心违。"]},{"id":"T00759","t":"相和歌辞 从军行五首 二","a":"令狐楚","c":["孤心眠夜雪，满眼是秋沙。","万里犹防塞，三年不见家。"]},{"id":"T00760","t":"杂曲歌辞 春江曲二首 一","a":"张仲素","c":["家寄征江岸，征人几岁游。","不知潮水信，每日到沙头。"]},{"id":"T00761","t":"同潘屯田冬日早朝","a":"张文琮","c":["假寐怀古人，夙兴瞻晓月。","通晨禁门启，冠盖趋朝谒。","霜霭清九衢，霞光照双阙。","纷纶文物纪，焕烂声明发。","腰劒动陆离，鸣玉和清越。"]},{"id":"T00762","t":"采莲曲","a":"郑愔","c":["锦䋏沙棠舰，罗带石榴帬。","绿潭采荷芰，清江日稍曛。","鱼鸟争唼喋，花叶相芬氲。","不觉芳洲暮，菱歌处处闻。"]},{"id":"T00763","t":"铜雀妓","a":"王适","c":["日暮铜雀迥，秋深玉座清。","萧森松柏望，委郁绮罗情。","君恩不再得，妾舞为谁轻。"]},{"id":"T00764","t":"长门怨","a":"袁晖","c":["早知君爱歇，本自无萦妒。","谁使恩情深，今来反相误。","愁眠罗帐晓，泣坐金闺暮。","独有梦中魂，犹言意如故。"]},{"id":"T00765","t":"琴曲歌辞 胡笳十八拍 第二拍","a":"刘商","c":["马上将余向绝域，厌生求死死不得。","戎羯腥膻岂是人，豺狼喜怒难姑息。","行尽天山足霜霰，风土萧条近胡国。","万里重阴鸟不飞，寒沙莽莽无南北。"]},{"id":"T00766","t":"燕歌行","a":"陶翰","c":["请君留楚调，听我吟燕歌。","家在辽水头，边风意气多。","出身为汉将，正值戎未和。","雪中凌天山，冰上渡交河。","大小百余战，封侯竟蹉跎。","归来灞陵下，故旧无相过。","雄劒委尘匣，空门垂雀罗。","玉簪还赵女，宝瑟付齐娥。","昔日不为乐，时哉今奈何。"]},{"id":"T00767","t":"相和歌辞 中妇织流黄","a":"虞世南","c":["寒闺织素锦，含怨敛双蛾。","综新交缕涩，经脆断丝多。","衣香逐举袖，钏动应鸣梭。","还恐裁缝罢，无信达交河。"]},{"id":"T00768","t":"杂曲歌辞 行路难","a":"李颀","c":["汉家名臣杨德祖，四代五公享茅土。","父兄子弟绾银黄，跃马鸣珂朝建章。","火浣单衣绣方领，茱萸锦带玉盘囊。","宾客填街复满坐，片言出口生辉光。","世人逐势争奔走，沥胆隳肝惟恐后。","当时一顾生青云，自谓生死长随君。","一朝谢病还乡里，穷巷苍茫绝知己。","秋风落叶闭重门，昨日论交竟谁是。","薄俗嗟嗟难重陈，深山麋鹿下为邻。","鲁连所以蹈沧海，古往今来称达人。"]},{"id":"T00769","t":"相和歌辞 苦哉行五首 二","a":"戎昱","c":["官军收洛阳，家住洛阳里。","夫壻与兄弟，目前见伤死。","吞声不许哭，还谴衣罗绮。","上马随匈奴，数秋黄尘里。","生为名家女，死作塞垣鬼。","乡国无还期，天津哭流水。"]},{"id":"T00770","t":"相和歌辞 子夜春歌","a":"王翰","c":["春气满林香，春游不可忘。","落花吹欲尽，垂柳折还长。","桑女淮南曲，金鞍塞北装。","行行小垂手，日暮渭川阳。"]},{"id":"T00771","t":"拟古","a":"薛奇童","c":["沙尘朝蔽日，失道还相遇。","寒影波上云，秋声月前树。","川气生晓夕，野阴乍烟雾。","沈沈滮池水，人马不敢渡。","吮痈世所薄，挟纩恩难顾。","不见古时人，中宵泪横注。"]},{"id":"T00772","t":"长门怨","a":"吴少微","c":["月出映层城，孤圆上太清。","君王眷爱歇，枕席凉风生。","怨咽不能寝，踟蹰步前楹。","空阶白露色，百草寒虫鸣。","念昔金房里，犹嫌玉座轻。","如何娇所误，长夜泣恩情。"]},{"id":"T00773","t":"杂诗六首 二","a":"李华","c":["玄黄与丹青，五气之正色。","圣人端其源，上下皆有则。","齐侯好紫衣，魏帝妇人饰。","女奴厌金翠，倾海未满臆。","何忍严子陵，羊裘死荆棘。"]},{"id":"T00774","t":"春江花月夜二首 一","a":"张子容","c":["林花发岸口，气色动江新。","此夜江中月，流光花上春。","分明石潭里，宜照浣纱人。"]},{"id":"T00775","t":"杂曲歌辞 壮士行","a":"施肩吾","c":["一斗之胆撑脏腑，如磥之筋碍臂骨。","有时误入千人丛，自觉一身横突兀。","当今四海无烟尘，胸襟被压不得伸。","冻枭残虿我不取，污我匣黑青蛇鳞。"]},{"id":"T00776","t":"侍从途中口号应制","a":"阎朝隐","c":["疵贱出山东，忠贞任土风。","因敷河朔藻，得奉洛阳宫。","一顾侍御史，再顾给事中。","常愿粉肌骨，特荅造化功。"]},{"id":"T00777","t":"奉和登骊山高顶寓目应制","a":"武平一","c":["銮舆上碧天，翠帟拖晴烟。","绝崿纡仙径，层岩敞御筵。","云披丹凤阙，日下黑龙川。","更覩南熏奏，流声入管弦。"]},{"id":"T00778","t":"杂曲歌辞 火凤辞 一","a":"李百药","c":["歌声扇里出，妆影扇中轻。","未能令掩笑，何处欲鄣声。","知音自不惑，得念是分明。","莫见双嚬敛，疑人含笑情。"]},{"id":"T00779","t":"杂曲歌辞 大酺乐 二","a":"杜审言","c":["毘陵震泽九州通，士女欢娱万国同。","伐鼓撞钟惊海上，新妆袨服照江东。","梅花落处疑残雪，柳叶开时任好风。","大德不官逢道泰，天长地久属年丰。"]},{"id":"T00780","t":"杂曲歌辞 少年行三首 三","a":"李嶷","c":["玉劒膝边横，金杯马上倾。","朝游茂陵道，暮宿凤凰城。","豪吏多猜忌，无劳问姓名。"]},{"id":"T00781","t":"杂曲歌辞 长安少年行十首 三","a":"李廓","c":["日高春睡足，帖马赏年华。","倒插银鱼袋，行随金犊车。","还携新市酒，远醉曲江花。","几度归侵黑，金吾送到家。"]},{"id":"T00782","t":"杂曲歌辞 桃花行 二","a":"李峤","c":["绮蕚成蹊遍籞芳，红英扑地满筵香。","莫将秋宴传王母，来比春华寿圣皇。"]},{"id":"T00783","t":"杂曲歌辞 行路难五首 三","a":"贺兰进明","c":["君不见荒树枝，春花落尽蜂不窥。","君不见梁上泥，秋风始高燕不栖。","荡子从军事征战，蛾眉婵娟空守闺。","独宿自然堪下泪，况复时闻乌夜啼。"]},{"id":"T00784","t":"青雀歌","a":"王缙","c":["林间青雀儿，来往翩翩绕一枝。","莫言不解衔环报，但闻君恩今若为。"]},{"id":"T00785","t":"题江潮庄壁","a":"万楚","c":["田家喜秋熟，岁[晏]林叶稀。","禾黍积场圃，𣙁梨垂户扉。","野闲犬时吠，日暮牛自归。","时复落花酒，茅斋堪解衣。"]},{"id":"T00786","t":"伤吴中","a":"李嘉祐","c":["馆娃宫中春已归，阖闾城头莺已飞。","复见花开人又老，横塘寂寂柳依依。","忆昔吴王在宫阙，馆娃满眼看花发。","舞袖朝欺陌上春，歌声夜怨江边月。","古来人事亦犹今，莫厌清觞与绿琴。","独向西山聊一笑，白云芳草自知心。"]},{"id":"T00787","t":"杂曲歌辞 昔昔盐 水溢芙蓉沼","a":"赵嘏","c":["渌沼春光后，青青草色浓。","绮罗惊翡翠，暗粉妒芙蓉。","云遍窗前见，荷翻镜里逢。","将心托流水，终日渺无从。"]},{"id":"T00788","t":"和边城秋气早","a":"李义府","c":["金微凝素节，玉律应清葭。","边马秋声急，征鸿晓阵斜。","关树凋凉叶，塞草落寒花。","雾暗长川景，云昏大漠沙。","谿深路难越，川平望超忽。","极望断烟飘，遥落惊蓬没。","霜结龙城吹，水照龟林月。","日色夏犹冷，霜华春未歇。","睿作高紫宸，分明映玄阙。"]},{"id":"T00789","t":"杂曲歌辞 伊州 歌第三","a":"盖嘉运","c":["闻道黄花戍，频年不解兵。","可怜闺里月，偏照汉家营。"]},{"id":"T00790","t":"踏歌词二首 一","a":"崔液","c":["彩女迎金屋，仙姬出画堂。","鸳鸯裁锦袖，翡翠贴花黄。","歌响舞分行，艳色动流光。"]},{"id":"T00791","t":"杂歌谣辞 步虚词 三","a":"韦渠牟","c":["上帝求仙使，真符取玉郎。","三才闲布象，二景郁生光。","骑吏排龙虎，笙歌走凤凰。","天高人不见，暗入白云乡。"]},{"id":"T00792","t":"听邻人琵琶","a":"陈叔达","c":["本是龙门桐，因妍入汉宫。","香缘罗袖里，声逐朱弦中。","虽有相思韵，翻将入塞同。","关山临却月，花蘂散回风。","为将金谷引，添令曲未终。"]},{"id":"T00793","t":"奉和入潼关","a":"许敬宗","c":["曦驭循黄道，星陈引翠旗。","济潼纡万乘，临河耀六师。","前旌弥陆海，后骑发通伊。","势逾回地轴，威盛转天机。","是节岁穷纪，关树荡凉飔。","仙露含灵掌，瑞鼎照川湄。","冲襟赏临睨，高咏入京畿。"]},{"id":"T00794","t":"古意六首 三","a":"王绩","c":["宝龟尺二寸，由来宅深水。","浮游五湖内，宛转三江里。","何不深复深，轻然至溱洧。","溱洧源流狭，春秋不濡轨。","渔人递往还，网罟相萦藟。","一朝失运会，刳肠血流死。","丰骨输庙堂，鲜腴籍笾簋。","弃置谁怨尤，自我招此否。","余灵寄明卜，复来钦所履。"]},{"id":"T00795","t":"夏晚寻于政世置酒赋韵","a":"陈子良","c":["聊从嘉遯所，酌醴共抽簪。","以兹山水地，留连风月心。","长榆落照尽，高柳暮蝉吟。","一返桃源路，别后难追寻。"]},{"id":"T00796","t":"巫峡","a":"杨炯","c":["三峡七百里，唯言巫峡长。","重岩窅不极，叠嶂凌苍苍。","绝壁横天险，莓苔烂锦章。","入夜分明见，无风波浪狂。","忠信吾所蹈，泛舟亦何伤。","可以涉砥柱，可以浮吕梁。","美人今何在？灵芝徒有芳。","山空夜猿啸，征客泪沾裳。"]},{"id":"T00797","t":"单于川对雨二首 二","a":"苏味道","c":["飞雨欲迎旬，浮云已送春。","还从濯枝后，来应洗兵辰。","气合龙祠外，声过鲸海滨。","伐邢知有属，已见静边尘。"]},{"id":"T00798","t":"寄刘校书","a":"郭震","c":["俗吏三年何足论，每将荣辱在朝昏。","才微易向风尘老，身贱难酬知己恩。","御苑残莺啼落日，黄山细雨湿归轩。","回首汉家丞相府，昨来谁得扫重门。"]},{"id":"T00799","t":"饯唐州高使君赴任","a":"韦元旦","c":["桐栢膺新命，芝兰惜旧游。","鸣臯夜鹤在，迁木早莺求。","传拥淮源路，尊空灞水流。","落花纷送远，春色引离忧。"]},{"id":"T00800","t":"饯许州宋司马赴任","a":"李适","c":["昔吾游箕山，朅来涉颍水。","复有许由庙，迢迢白云里。","闻君佐繁昌，临风怅怀此。","傥到平舆泉，寄谢干将里。"]},{"id":"T00801","t":"宴龙泓","a":"武三思","c":["登临开胜托，眺瞩尽良游。","岩崿萦纡上，澄潭屈曲流。","泛兰清兴洽，折桂野文遒。","别后相思处，崎岖碧涧幽。"]},{"id":"T00802","t":"奉和张岳州王潭州别诗二首 一","a":"韦嗣立","c":["茂先王佐才，作牧楚江隈。","登楼正欲赋，复遇仲宣来。","黄鹄飞将远，雕龙文为开。","宁知昔联事，听曲有余哀。"]},{"id":"T00803","t":"宋主簿鸣臯梦赵六予未及报而陈子云亡今追为此诗荅宋兼贻平昔游旧","a":"卢藏用","c":["暮川罕停波，朝云无留色。","故人琴与诗，可存不可识。","识心尚可亲，琴诗非故人。","鸣臯初梦赵，蜀国已悲陈。","感化伤沦灭，魂交惜未申。","冥期失幽报，兹理复今晨。","前嗟成后泣，已矣将何及。","旧感与新悲，虚怀酬昔时。","赵侯鸿宝气，独负青云姿。","群有含妙识，众象悬清机。","雄谈尽物变，精义解人颐。","在阴既独善，幽跃自为疑。","踠彼千里足，伤哉一尉欺。","陈生富清理，卓荦兼文史。","思缛巫山云，调逸岷江水。","铿锵哀忠义，感激怀知己。","负劒登蓟门，孤游入燕市。","浩歌去京国，归守西山趾。","幽居探元化，立言见千祀。","埋没经济情，良图竟云已。","坐忆平生游，十载怀嵩丘。","题书满古壁，采药遍岩幽。","子微化金鼎，仙笙不可求。","荣哉宋与陆，名宦美中州。","存亡一暌阻，岐路方悠悠。","自予事山海，及兹人世改。","传闻当世荣，皆入古人名。","无复平原赋，空余邻笛声。","泣对西州使，悲访北邙茔。","新坟蔓宿草，旧阙毁残铭。","为君成此曲，因言寄友生。","默语无穷事，凋伤共此情。"]},{"id":"T00804","t":"奉和送金城公主适西蕃应制","a":"马怀素","c":["帝子今何去？重姻适异方。","离情怆宸掖，别路遶关梁。","望绝园中柳，悲缠陌上桑。","空余愿黄鹤，东顾忆回翔。"]},{"id":"T00805","t":"奉和张燕公早霁南楼","a":"赵冬曦","c":["方曙跻南楼，凭轩肆遐瞩。","物华荡暄气，春景媚晴旭。","川霁湘山孤，林芳楚郊缛。","列岩重叠翠，远岸逶迤绿。","风帆摩天垠，鱼艇散弯曲。","鸿归鹤舞送，猨叫莺声续。","群动皆熙熙，噫予独羁束。","常钦才子意，忌𫛳伤踡跼。","雅尚骚人文，怀沙何迫促。","未知二贤意，去矣从所欲。"]},{"id":"T00806","t":"让帝挽歌词二首 一","a":"卢僎","c":["泰伯玄风远，延州德让行。","阖棺追大节，树羽册鸿名。","地户迎天仗，皇阶失帝兄。","还闻汉明主，遗劒泣东平。"]},{"id":"T00807","t":"赠皇甫侍御赴都八首 三","a":"元希声","c":["道心惟微，厥用允塞。","德辉不泯，而映邦国。","静以有神，动而作则。","九臯千里，其声不忒。"]},{"id":"T00808","t":"奉和七夕两仪殿会宴应制","a":"赵彦昭","c":["青女三秋节，黄姑七日期。","星桥度玉珮，云阁掩罗帷。","河气通仙掖，天文入睿词。","今宵望灵汉，应得见蛾眉。"]},{"id":"T00809","t":"奉和幸安乐公主山庄应制","a":"萧至忠","c":["西郊窈窕凤皇台，北渚平明法驾来。","匝地金声初度曲，周堂玉溜好传杯。","湾路分游画舟转，岸门相向碧亭开。","微臣此时承宴乐，髣髴疑从星汉回。"]},{"id":"T00810","t":"三日岐王宅","a":"张谔","c":["玉女贵妃生，嫛婗始发声。","金盆浴未了，绷子绣初成。","翡翠雕芳缛，真珠帖小缨。","何时学健步？鬬取落花轻。"]},{"id":"T00811","t":"酬忠公林亭","a":"包融","c":["江外有真隐，寂居岁已侵。","结庐近西术，种树久成阴。","人迹乍及户，车声遥隔林。","自言解尘事，咫尺能辎尘。","为道岂庐霍，会静由吾心。","方秋院木落，仰望日萧森。","持我兴来趣，采菊行相寻。","尘念到门尽，远情对君深。","一谈入理窟，再索破幽襟。","安得山中信，致书移尚禽。"]},{"id":"T00812","t":"丽正殿赐宴同勒天前烟年四韵应制","a":"王湾","c":["金殿忝陪贤，琼羞忽降天。","鼎罗仙掖里，觞拜琐闱前。","院逼青霄路，厨和紫禁烟。","酒酣空忭舞，何以荅昌年。"]},{"id":"T00813","t":"从军行","a":"贺朝","c":["朔胡乘月寇边城，军书插羽刺中京。","天子金坛拜飞将，单于玉塞振佳兵。","骑射先鸣推任侠，龙韬决胜伫时英。","闻有河湟客，愔愔理帷帟。","常山启霸图，汜水先天策。","衔珠浴铁向桑干，衅旗膏劒指乌丸。","鸣鸡已报关山晓，来雁遥传沙塞寒。","直为甘心从苦节，陇头流水鸣呜咽。","边树萧萧不觉春，天山漠漠长飞雪。","鱼丽阵接塞云平，雁翼营通海月明。","始看晋幕飞鹅入，旋闻齐垒啼乌声。","自从一戍燕支山，春光几度晋阳关。","金河未转青丝骑，玉筯应啼红粉颜。","鸿归燕相续，池边芳草绿。","已见氛清细柳营，莫更春歌落梅曲。","烽沈灶减静边亭，海[晏]山空肃已宁。","行望凤京旋凯捷，重来麟阁画丹青。"]},{"id":"T00814","t":"送杨法曹按括州","a":"孙逖","c":["东海天台山，南方缙云驿。","溪澄问人隐，岩险烦登陟。","潭壑随星使，轩车绕春色。","傥寻琪树人，为报长相忆。"]},{"id":"T00815","t":"家叔征君东溪草堂二首 二","a":"卢象","c":["今朝共游者，得性闲未归。","已到仙人家，莫惊鸥鸟飞。","水深严子钓，松挂巢父衣。","云气转幽寂，溪流无是非。","名理未足羡，腥臊讵所希。","自惟负贞意，何岁当食薇。"]},{"id":"T00816","t":"嵩山十志十首 其三","a":"卢鸿一","c":["紫岩隈兮青谿侧，云松烟茑兮千古色。","芳靃蘼兮荫蒙茏，幽人构馆兮在其中。","靃蘼蒙茏兮开樾馆，卧风霄兮坐赮旦。","粤有宾兮时戾止，樵苏不爨兮清淡已，永岁终朝兮常若此。"]},{"id":"T00817","t":"送吕向补阙西岳勒碑","a":"徐安贞","c":["圣作西山颂，君其出使年。","勒碑悬日月，驱传接云烟。","寒尽函关路，春归洛水边。","别离能几许，朝暮玉墀前。"]},{"id":"T00818","t":"游感化寺昙兴上人山院","a":"裴迪","c":["不远灞陵边，安居向十年。","入门穿竹径，留客听山泉。","鸟啭深林里，心闲落照前。","浮名竟何益，从此愿栖禅。"]},{"id":"T00819","t":"湖中寄王侍御","a":"丘为","c":["日日湖水上，好登湖上楼。","终年不向郭，过午始梳头。","尝自爱桮酒，得无相献酬。","小僮能脍鲤，少妾事莲舟。","每有南浦信，仍期后月游。","方春转摇荡，孤兴时淹留。","骢马真傲吏，翛然无所求。","晨趋玉阶下，心许沧江流。","少别如昨日，何言经数秋。","应知方外事，独往非悠悠。"]},{"id":"T00820","t":"渡淮河寄平一","a":"祖咏","c":["天色混波涛，岸阴匝村墅。","微微汉祖庙，隐隐江陵渚。","云树森已重，时明郁相拒。"]},{"id":"T00821","t":"题栖霞寺","a":"綦毋潜","c":["南山势回合，灵境依此住。","殿转云崖阴，僧探石泉度。","龙蛇争翕习，神鬼皆密护。","万壑奔道场，群峰向双树。","天花飞不著，水月白成路。","今日观身我，归心复何处。"]},{"id":"T00822","t":"赠裴将军","a":"颜真卿","c":["大君制六合，猛将清九垓。","战马若龙虎，腾凌何壮哉。","将军临八荒，烜赫耀英材。","劒舞若游电，随风萦且回。","登高望天山，白云正崔巍。","入阵破骄虏，威名雄震雷。","一射百马倒，再射万夫开。","匈奴不敢敌，相呼归去来。","功成报天子，可以画麟台。"]},{"id":"T00823","t":"江有枫一篇十章 三","a":"萧颖士","c":["想彼槭矣，亦类其枫。","矧伊怀人，而忘其东。"]},{"id":"T00824","t":"送薛据之宋州","a":"崔曙","c":["无媒嗟失路，有道亦乘流。","客处不堪别，异乡应共愁。","我生早孤贱，沦落居此州。","风土至今忆，山河皆昔游。","一从文章事，两京春复秋。","君去问相识，几人今白头。"]},{"id":"T00825","t":"同孙构免官后登蓟楼","a":"张谓","c":["昔在五陵时，年少心亦壮。","尝矜有奇骨，必是封侯相。","东走到营州，投身似边将。","一朝去乡国，十载履亭障。","部曲皆武夫，功成不相让。","犹希虏尘动，更取林胡帐。","去年大将军，忽负乐生谤。","北别伤士卒，南迁死炎瘴。","濩落悲无成，行登蓟丘上。","长安三千里，日夕西南望。","寒沙榆塞没，秋水滦河涨。","策马从此辞，云山保闲放。"]},{"id":"T00826","t":"美人春卧","a":"梁锽","c":["妾家巫峡阳，罗幌寝兰堂。","晓日临窗久，春风引梦长。","落钗仍挂鬓，微汗欲消黄。","纵使朦胧觉，魂犹逐楚王。"]},{"id":"T00827","t":"同李郎中净律院梡子树","a":"包何","c":["本梡稀难识，沙门种则生。","叶殊经写字，子为佛称名。","滤水浇新长，燃灯暖更荣。","亭亭无别意，只是劝修行。"]},{"id":"T00828","t":"酬郑侍御秋夜见寄","a":"皇甫曾","c":["摇落空林夜，河阳兴已生。","未辞公府步，知结远山情。","高柳风难定，寒泉月助明。","袁公方卧雪，尺素及柴荆。"]},{"id":"T00829","t":"鼓吹曲辞 有所思","a":"李白","c":["我思仙人，乃在碧海之东隅。","海寒多天风，白波连山倒蓬壶。","长鲸喷涌不可涉，抚心茫茫泪如珠。","西来青鸟东飞去，愿寄一书谢麻姑。"]},{"id":"T00830","t":"横吹曲辞 前出塞九首 四","a":"杜甫","c":["送徒既有长，远戍亦有身。","生死向前去，不劳吏怒嗔。","路逢相识人，附书与六亲。","哀哉两决绝，不复同苦辛。"]},{"id":"T00831","t":"相和歌辞 陇西行","a":"王维","c":["十里一走马，五里一扬鞭。","都护军书至，匈奴围酒泉。","关山正飞雪，烽戍断无烟。"]},{"id":"T00832","t":"相和歌辞 王昭君二首 二","a":"白居易","c":["汉使却回凭寄语，黄金何日赎蛾眉？君王若问妾颜色，莫道不如宫里时。"]},{"id":"T00833","t":"杂曲歌辞 杨柳枝 一","a":"李商隐","c":["暂凭樽酒送无憀，莫损愁眉与细腰。","人世死前唯有别，春风争拟惜长条。"]},{"id":"T00834","t":"相和歌辞 从军行 二","a":"王昌龄","c":["烽火城西百尺楼，黄昏独上海风秋。","更吹横笛关山月，谁解金闺万里愁。"]},{"id":"T00835","t":"晚春卧病寄张八","a":"孟浩然","c":["南陌春将晚，北窗犹卧病。","林园久不游，草木一何盛。","狭迳花障迷，闲庭竹扫净。","翠羽戏兰苕，赪鳞动荷柄。","念我平生好，江乡远从政。","云山阻梦思，衾枕劳歌咏。","歌咏复何为，同心恨别离。","世途皆自媚，流俗寡相知。","贾谊才空逸，安仁鬓欲丝。","遥情每东注，奔晷复西驰。","常恐填沟壑，无由振羽仪。","穷通若有命，欲向论中推。"]},{"id":"T00836","t":"鼓吹曲辞 凯歌六首 四","a":"岑参","c":["月落辕门鼓角鸣，千群面缚出蕃城。","洗兵鱼海云迎阵，秣马龙堆月照营。"]},{"id":"T00837","t":"杂曲歌辞 蓟门行五首 三","a":"高适","c":["蓟门逢古老，独立思氛氲。","一身既零丁，头鬓白纷纷。","勋庸今已矣，不识霍将军。"]},{"id":"T00838","t":"相和歌辞 三阁词四首 二","a":"刘禹锡","c":["珠箔曲琼钩，子细见扬州。","北兵那得度，浪语判悠悠。"]},{"id":"T00839","t":"鼓吹曲辞 鼓吹铙歌 泾水黄","a":"柳宗元","c":["泾水黄，陇野茫。","负太白，腾天狼。","有鸟鸷立，羽翼张。","钩喙决前，巨趯傍。","怒飞饥啸，翾不可当。","老雄死，子复良。","巢岐饮渭，肆翱翔。","顿地纮，提天纲。","列缺掉帜，招摇耀铓。","鬼神来助，梦嘉祥。","脑涂原野，魂飞扬。","星辰复，恢一方。"]},{"id":"T00840","t":"相和歌辞 相逢行","a":"韦应物","c":["二十登汉朝，英声迈今古。","适从东方来，又欲谒明主。","犹酣新丰酒，尚带霸陵雨。","邂逅两相逢，别来间寒暑。","宁知白日晚，暂向花间语。","忽闻长乐钟，走马东西去。"]},{"id":"T00841","t":"相和歌辞 决绝[词]三首 一","a":"元稹","c":["乍可为天上牵牛织女星，不愿为庭前红槿枝。","七月七日一相见，故心终不移。","那能朝开暮飞去，一任东西南北吹。","分不两相守，恨不两相思。","对面且如此，背面当何知。","春风撩乱伯劳语，此时抛去时。","握手苦相问，竟不言后期。","君情既决绝，妾意已参差。","借如死生别，安得长苦悲。"]},{"id":"T00842","t":"琴曲歌辞","a":"韩愈","c":["我家于豳，自我先公。","伊我承绪，敢有不同。","今狄之人，将土我疆。","民为我战，谁使死伤。","彼岐有岨，我往独处。","人莫余追，无思我悲。"]},{"id":"T00843","t":"鼓吹曲辞 将进酒","a":"李贺","c":["将进酒，将进酒。","酒中有毒酖主父，言之主父伤主母。","母为妾地父妾天，仰天俯地不忍言。","佯为僵踣主父前，主父不知加妾鞭。","旁人知妾为主说，主将泪洗鞭头血。","推摧主母牵下堂，扶妾遣升堂上床。","将进酒，酒中无毒令主寿。","愿主回思归主母，遣妾如此事主父。","妾为此事人偶知，自慙不密方自悲。","主今颠倒安置妾，贪天僭地谁不为。"]},{"id":"T00844","t":"相和歌辞 懊恼曲","a":"温庭筠","c":["藕丝作线难胜针，蘂粉染黄那得深。","玉白兰芳不相顾，倡楼一笑轻千金。","莫言自古皆如此，健劒刜钟铅绕指。","三秋庭绿尽迎霜，惟有荷花守红死。","西江小吏朱斑轮，柳缕吐芽香玉春。","两股金钗已相许，不令独作空城尘。","悠悠楚水流如马，恨紫愁红满平野。","野土千年怨不平，至今烧作鸳鸯瓦。"]},{"id":"T00845","t":"相和歌辞 从军行六首 二","a":"刘长卿","c":["落日更萧条，北方动枯草。","将军追虏骑，夜失阴山道。","战败仍树勋，韩彭但空老。"]},{"id":"T00846","t":"南郊文武出入舒和之乐","a":"张九龄","c":["祝史辞正，人神庆叶。","福以德昭，享以诚接。","六变云备，百礼斯浃。","祀事孔明，祚流万叶。"]},{"id":"T00847","t":"感遇诗三十八首 二","a":"陈子昂","c":["兰若生春夏，芊蔚何青青。","幽独空林色，朱蕤冒紫茎。","迟迟白日晚，袅袅秋风生。","岁华尽摇落，芳意竟何成。"]},{"id":"T00848","t":"横吹曲辞 折杨柳 一","a":"孟郊","c":["杨柳多短枝，短枝多别离。","赠远累攀折，柔条安得垂。","青春有定节，离别无定时。","但恐人别促，不怨来迟迟。","莫言短枝条，中有长相思。","朱颜与绿杨，幷在别离期。"]},{"id":"T00849","t":"太和 肃和","a":"贺知章","c":["黄祇是祗，我其夙夜。","夤畏诚絜，匪遑宁舍。","礼以琮玉，荐厥茅藉。","念兹降康，胡宁克暇。"]},{"id":"T00850","t":"横吹曲辞 望行人","a":"张籍","c":["秋风窗下起，旅雁向南飞。","日日出门望，家家行客归。","无因见边使，空待寄寒衣。","独闭青楼暮，烟深鸟雀稀。"]},{"id":"T00851","t":"相和歌辞 公无渡河","a":"王建","c":["渡头恶天两岸远，波涛塞川如叠坂。","幸无白刃驱向前，何用将身自弃捐。","蛟龙啮尸鱼食血，黄泥直下无青天。","男儿纵轻妇人语，惜君性命还须取。","妇人无力挽断衣，舟沈身死悔难追，公无渡河公自为。"]},{"id":"T00852","t":"杂曲歌辞 天长地久词 一","a":"卢纶","c":["玉砌红花树，香风不敢吹。","春光解天意，偏发殿南枝。"]},{"id":"T00853","t":"相和歌辞 宫怨","a":"李益","c":["露湿晴花宫殿香，月明歌吹在昭阳。","似将海水添宫漏，共滴长门一夜长。"]},{"id":"T00854","t":"帝京篇十首 四","a":"太宗皇帝","c":["鸣笳临乐馆，眺听欢芳节。","急管韵朱弦，清歌凝白雪。","彩凤肃来仪，玄鹤纷成列。","去兹郑卫声，雅音方可悦。"]},{"id":"T00855","t":"过温汤","a":"高宗皇帝","c":["温渚停仙跸，丰郊驻晓旌。","路曲回输影，岩虚传漏声。","暖溜惊湍驶，寒空碧雾轻。","林黄疎叶下，野白曙霜明。","眺听良无已，烟霞断续生。"]},{"id":"T00856","t":"赐诸州刺史以题座右","a":"明皇帝","c":["眷言思共理，鉴梦想维良。","猗欤此推择，声绩著周行。","贤能既俟进，黎献实伫康。","视人当如子，爱人亦如伤。","讲学试诵论，阡陌劝耕桑。","虚誉不可饰，清知不可忘。","求名迹易见，安贞德自彰。","讼狱必以情，教民贵有常。","恤惸且存老，抚弱复绥强。","勉哉各祗命，知予眷万方。"]},{"id":"T00857","t":"九月十八赐百僚追赏因书所怀","a":"德宗皇帝","c":["雨霁霜气肃，天高云日明。","繁林已坠叶，寒菊仍舒荣。","懿此秋节时，更延追赏情。","池台列广宴，丝竹传新声。","至乐非外奖，浃欢同中诚。","庶敦朝野意，永使风化清。"]},{"id":"T00858","t":"唐享昊天乐 第三","a":"则天皇后","c":["干仪混成冲邃，天道下济高明。","闿阳晨披紫阙，太一晓降黄庭。","圜坛敢申昭报，方璧冀展虔情。","丹襟式敷衷恳，玄鉴庶察微诚。"]},{"id":"T00859","t":"驾幸三会寺应制","a":"上官昭容","c":["释子谈经处，轩臣刻字留。","故台遗老识，残简圣皇求。","驻跸怀千古，开襟望九州。","四山缘塞合，二水夹城流。","宸翰陪瞻仰，天杯接献酬。","太平词藻盛，长愿纪鸿休。"]},{"id":"T00860","t":"送邓王二十弟从益牧宣城","a":"后主煜","c":["且维轻舸更迟迟，别酒重倾惜解携。","浩浪侵愁光荡漾，乱山凝恨色高低。","君驰桧楫情何极，我凭阑干日向西。","咫尺烟江几多地，不须怀抱重凄凄。"]},{"id":"T00861","t":"题金华宫","a":"蜀太后徐氏","c":["再到金华顶，玄都访道回。","云披分景象，黛锁显楼台。","雨涤前山净，风吹去路开。","翠屏夹流水，何必羡蓬莱。"]},{"id":"T00862","t":"题金华宫","a":"蜀太妃徐氏","c":["碧烟红雾漾人衣，宿雾苍苔石径危。","风巧解吹松上曲，蝶娇频采脸边脂。","同寻僻境思携手，暗指遥山学画眉。","好把身心清净处，角冠霞帔事希夷。"]},{"id":"T00863","t":"郊庙歌辞 祀圜丘乐章 雍和","a":"褚亮","c":["钦惟大帝，[载]仰皇穹。","始命田烛，爰启郊宫。","云门骇听，雷鼓鸣空。","神其介祀，景祚斯融。"]},{"id":"T00864","t":"郊庙歌辞 封泰山乐章 豫和 四","a":"张说","c":["高在上，道光明。","物资始，德难名。","承眷命，牧苍生。","寰宇谧，太阶平。"]},{"id":"T00865","t":"郊庙歌辞 武后明堂乐章 迎送王公","a":"武则天","c":["千官肃事，万国朝宗。","载延百辟，爰集三宫。","君臣德合，鱼水斯同。","睿图方永，周历长隆。"]},{"id":"T00866","t":"郊庙歌辞 五郊乐章 黄帝宫音 舒和","a":"魏征","c":["御征乘宫出郊甸，安歌率舞递将迎。","自有云门符帝赏，犹持雷鼓答天成。"]},{"id":"T00867","t":"郊庙歌辞 祀风师乐章 亚献终献","a":"包佶","c":["膋芗备，玉帛陈。","风动物，乐感神。","三献终，百神臻。","草木荣，天下春。"]},{"id":"T00868","t":"祭汾阴乐章","a":"苏颋","c":["礼物斯具，乐章乃陈。","谁其作主，皇考圣真。","对越在天，圣明佐神。","窅然汾上，厚泽如春。"]},{"id":"T00869","t":"郊庙歌辞 禅社首乐章 雍和","a":"贺知章、源乾曜","c":["夙夜宥密，不敢宁宴。","五齐既陈，八音在县。","粢盛以洁，房俎斯荐。","惟德惟馨，尚兹克徧。"]},{"id":"T00870","t":"春日洛阳城侍宴","a":"姚崇","c":["南山开宝历，北渚对芳蹊。","的历风梅度，参差露草低。","尧樽临上席，舜乐下前溪。","任重由来醉，乘酣志转迷。"]},{"id":"T00871","t":"鼓吹曲辞 芳树","a":"沈佺期","c":["何地早芳菲？宛在长门殿。","夭桃色若绶，秾李光如练。","啼鸟弄花疎，游蠭饮香徧。","叹息春风起，飘零君不见。"]},{"id":"T00872","t":"奉和立春游苑迎春应制","a":"崔日用","c":["乘时迎气正璇衡，灞浐烟氛向晚清。","剪绮裁红妙春色，宫梅殿柳识天情。","瑶筐彩燕先呈端，金缕晨鸡未学鸣。","圣泽阳和宜宴乐，年年捧日向东城。"]},{"id":"T00873","t":"奉和登骊山高顶寓目应制","a":"李乂","c":["崖𪩘万寻悬，居高敞御筵。","行戈疑驻日，步辇若登天。","城阙雾中近，关河云外连。","谬陪登岱驾，欣奉济汾篇。"]},{"id":"T00874","t":"郊庙歌辞 享太庙乐章 长发舞","a":"魏征、褚亮","c":["睿哲维唐，长发其祥。","帝命斯祐，王业克昌。","配天载德，就日重光。","本支百代，申锡无疆。"]},{"id":"T00875","t":"郊庙歌辞 德明兴圣庙乐章 德明酌献","a":"李舒","c":["清庙奕奕，和乐雍雍。","器尊牺象，礼属宗公。","白水方祼，黄流在中。","谟明之德，万古清风。"]},{"id":"T00876","t":"相和歌辞 班倢伃","a":"徐彦伯","c":["君恩忽断绝，妾思终未央。","巾栉不可见，枕席空余香。","窗暗网罗白，阶秋苔藓黄。","应门寂已闭，流涕向昭阳。"]},{"id":"T00877","t":"九日幸临渭亭登高应制得历字","a":"薛稷","c":["暮节乘原野，宣游俯崖壁。","秋登华实满，气严鹰隼击。","仙菊含霜泛，圣藻临云锡。","愿陪九九辰，长奉千千历。"]},{"id":"T00878","t":"奉和圣制送张说巡边","a":"徐坚","c":["至德抚遐荒，神兵赴朔方。","帝思元帅重，爰择股肱良。","累相承安世，深筹协子房。","寄崇专斧钺，礼备设坛场。","鼙鼓喧雷电，戈劒凛风霜。","四𬴂将戒道，十乘启先行。","圣锡加恒数，天文耀宠光。","出郊开帐饮，寅饯盛离章。","雨濯梅林润，风清麦野凉。","燕山应勒颂，麟阁伫名扬。"]},{"id":"T00879","t":"相和歌辞 从军行三首 三","a":"王涯","c":["旄头夜落捷书飞，来奏金门著赐衣。","白马将军频破敌，黄龙戍卒几时归。"]},{"id":"T00880","t":"郊庙歌辞 梁郊祀乐章 庆和 四","a":"赵光逢、张衮","c":["膺宝图，执左契。","德应天，圣飨帝。","荐表衷，荷灵惠。","寿万年，祚百世。"]},{"id":"T00881","t":"鼓吹曲辞 芳树","a":"卢照邻","c":["芳树本多奇，年华复在斯。","结翠成新幄，开红满旧枝。","风归花历乱，日度影参差。","容色朝朝落，思君君不知。"]},{"id":"T00882","t":"横吹曲辞 出塞曲 一","a":"僧贯休","c":["埽尽狂胡迹，回戈望故关。","相逢唯死鬬，岂易得生还。","纵宴参胡乐，收兵过雪山。","不封十万户，此事亦应闲。"]},{"id":"T00883","t":"横吹曲辞 雨雪曲","a":"李端","c":["天山一丈雪，杂雨夜霏霏。","湿马胡歌乱，经烽汉火微。","丁零苏武别，疎勒范羌归。","若著关头过，长榆叶定稀。"]},{"id":"T00884","t":"相和歌辞  苦寒行","a":"僧齐己","c":["冰峰撑空寒矗矗，雪凝水冻埋海陆。","杀物之性，伤人之欲。","既不能断绝蒺藜荆棘之根株，又不能展凤皇麒麟之拳跼。","如此则何如为和煦，为膏雨。","自然天下之荣枯，融融于万户。"]},{"id":"T00885","t":"相和歌辞 江南弄","a":"王勃","c":["江南弄，巫山连楚梦，行雨行云几相送。","瑶轩金谷上春时，玉童仙女无见期。","紫露香烟眇难托，清风明月遥相思。","遥相思，草徒绿，为听双飞凤凰曲。"]},{"id":"T00886","t":"阙题","a":"杨师道","c":["汉家伊洛九重城，御路浮桥万里平。","桂户雕梁连绮翼，虹梁绣柱映丹楹。","朝光欲动千门曙，丽日初照百花明。","燕赵蛾眉旧倾国，楚宫腰细本传名。","二月桑津期结伴，三春淇水逐关情。","兰丛有意飞双蝶，柳叶无趣隐啼莺。","扇里细妆将夜并，风前独舞共花荣。","两鬟百万谁论价，一笑千金判是轻。","不为披图来侍寝，非因主第奉身迎。","羊车讵畏青门闭，兔月今宵照后庭。"]},{"id":"T00887","t":"相和歌辞 短歌行","a":"僧皎然","c":["古人若不死，吾亦何所悲。","萧萧烟雨九原上，白杨青松葬者谁。","贵贱同一尘，死生同一指。","人生在世共如此，何异浮云与流水。","短歌行，短歌无穷日已倾。","邺宫梁苑徒有名，春草秋风伤我情。","何为不学金仙侣？一悟空王无死生。"]},{"id":"T00888","t":"相和歌辞 采莲曲二首 一","a":"鲍溶","c":["弄舟朅来南塘水，荷叶映身摘莲子。","暑衣清净鸳鸯喜，作浪舞花惊不起。","殷勤护惜纤纤指，水菱初熟多新刺。"]},{"id":"T00889","t":"横吹曲辞 白鼻䯄","a":"张祜","c":["为底胡姬酒，长来白鼻䯄。","摘莲抛水上，郎意在浮花。"]},{"id":"T00890","t":"相和歌辞 江南曲八首 三","a":"刘希夷","c":["君为陇西客，妾遇江南春。","朝游含灵果，夕采弄风苹。","果气时不歇，苹花日自新。","以此江南物，持赠陇西人。","空盈万里怀，欲赠竟无因。"]},{"id":"T00891","t":"杂曲歌辞 定情篇","a":"乔知之","c":["共君结新婚，岁寒心未卜。","相与游春园，各随情所逐。","君念菖蒲花，妾感苦寒竹。","菖花多艳姿，寒竹有贞叶。","此时妾比君，君心不如妾。","簪玉步河堤，妖韶援绿{𥫗/戢}。","凫鴈将子游，莺燕从双栖。","君念春光好，妾向春光嗁。","君时不得意，妾弃还金闺。","结言本同心，悲懽何未齐。","怨咽前致辞，愿得中所悲。","人间丈夫易，世路妇难为。","始经天月照，终若流星驰。","长信佳丽人，失意非蛾眉。","庐江小吏妇，非关织作迟。","本愿长相对，今已长相思。","复有游宦子，结援从梁陈。","燕居崇三朝，去来历九春。","誓心妾终始，蚕桑奉所亲。","归愿未克从，黄金赠路人。","洁妇怀明义，从泛河之津。","于今千万年，谁当问水滨。","更忆倡家楼，夫壻事封侯。","去时思灼灼，去罢心悠悠。","不怜妾岁晏，千载陇西头。","以兹常惕惕，百虑恒盈积。","由来共结褵，几人同匪石。","故岁雕梁燕，双去今来只。","今日玉庭梅，朝红暮成碧。","碧荣始芬敷，黄叶已[淅]沥。","何用念芳春，芳春有流易。","何用重懽娱，懽娱俄戚戚。","家本巫山阳，归去路何长。","敍言情未尽，采菉已盈筐。","桑榆日映物，草色盈高冈。","下有碧流水，上有丹桂香。","桂枝不须折，碧流清且洁。","赠君比芳菲，受惠常不灭。","赠君泪潺湲，相思无断绝。","妾有秦家镜，宝匣装珠玑。","鉴来年二八，不记易阴晖。","妾无光寂寂，委照影依依。","今日持为赠，相识莫相违。"]},{"id":"T00892","t":"奉和七夕宴两仪殿应制","a":"刘宪","c":["秋吹过双阙，星仙动二灵。","更深移月镜，河浅度云𫐌。","殿上呼方朔，人间失武丁。","天文兹夜里，光映紫微庭。"]},{"id":"T00893","t":"送梁卿王郎中使东蕃吊册","a":"崔湜","c":["梁侯上卿秀，王子中台杰。","赠册绥九夷，旌旃下双阙。","西堂礼乐送，南陌轩车别。","征路入海云，行舟溯江月。","兹邦久钦化，历载归朝谒。","皇心谅所嘉，寄尔宣风烈。"]},{"id":"T00894","t":"凌朝浮江旅思","a":"韦承庆","c":["天晴上初日，春水送孤舟。","山远疑无树，潮平似不流。","岸花开且落，江鸟没还浮。","羁望伤千里，长歌遣四愁。"]},{"id":"T00895","t":"西征军行遇风","a":"崔融","c":["北风卷尘沙，左右不相识。","飒飒吹万里，昏昏同一色。","马烦莫敢进，人急未遑食。","曹木春更悲，天景昼相匿。","夙龄慕忠义，雅尚存孤直。","览史怀浸骄，读诗叹孔棘。","及兹戎旅地，忝从书记职。","兵气腾北荒，军声振西极。","坐觉威灵远，行看氛祲息。","愚臣何以报，倚马申微力。"]},{"id":"T00896","t":"杂曲歌辞 渭城少年行","a":"崔颢","c":["洛阳二月梨花飞，秦地行人春忆归。","扬鞭走马城南陌，朝逢驿使秦川客。","驿使前日发章台，传道长安春早来。","棠梨宫中燕初至，葡萄馆里花正开。","念此使人归更早，三月便达长安道。","长安道上春可怜，摇风荡日曲河边。","万户楼台临渭水，五陵花柳满秦川。","秦川寒食盛繁华，游子春来喜见花。","鬬鸡下杜尘初合，走马章台日半斜。","章台帝城称贵里，青楼日晚歌钟起。","贵里豪家白马骄，五陵年少不相饶。","双双挟弹来金市，两两鸣鞭上渭桥。","渭城桥头酒新熟，金鞍白马谁家宿。","可怜锦瑟筝琵琶，玉台清酒就君家。","小妇春来不解羞，娇歌一曲杨柳花。"]},{"id":"T00897","t":"相和歌辞 短歌行六首 三","a":"顾况","c":["新系青丝百尺绳，心在君家辘轳上。","我心皎洁君不知，辘轳一转一惆怅。"]},{"id":"T00898","t":"相和歌辞 杂怨三首 一","a":"聂夷中","c":["生在绮罗下，岂识渔阳道。","良人自戍来，夜夜梦中到。","渔阳万里远，近于中门限。","中门逾有时，渔阳常在眼。"]},{"id":"T00899","t":"舞曲歌辞 柘枝词 二","a":"薛能","c":["悬军征拓羯，内地隔萧关。","日色昆仑上，风声朔漠间。","何当千万骑，飒飒贰师还。"]},{"id":"T00900","t":"息夫人","a":"宋之问","c":["可怜楚破息，肠断息夫人。","仍为泉下骨，不作楚王嫔。","楚王宠莫盛，息君情更亲。","情亲怨生别，一朝俱杀身。"]},{"id":"T00901","t":"戏赠姚侍御","a":"丁仙芝","c":["繁霜晓幕鸣柏乌，待子兽炭然金炉。","重门启锁紫髯胡，新披骢马陇西驹。","头戴獬豸急晨趋，明光殿前见天子，今日应弹佞幸夫。"]},{"id":"T00902","t":"相和歌辞 江南曲 三","a":"陆龟蒙","c":["鱼戏莲叶西，盘盘舞波急。","潜依曲岸凉，正对斜光入。"]},{"id":"T00903","t":"杂曲歌辞 生别离","a":"孟云卿","c":["结发生别离，相思复相保。","何知日已久，五变庭中草。","眇眇天海途，悠悠吴江岛。","但恐不出门，出门无远道。","远道行既难，家贫衣服单。","严风吹积雪，晨起鼻何酸。","人生各有恋，岂不怀所安。","分明天上日，生死誓同欢。"]},{"id":"T00904","t":"相和歌辞 怨诗二首 二","a":"崔国辅","c":["妾有罗衣裳，秦王在时作。","为舞春风多，秋来不堪著。"]},{"id":"T00905","t":"江上琴兴","a":"常建","c":["江上调玉琴，一弦清一心。","泠泠七弦遍，万木澄幽阴。","能使江月白，又令江水深。","始知梧桐枝，可以徽黄金。"]},{"id":"T00906","t":"杂曲歌辞 从军中行路难二首 一","a":"骆宾王","c":["君不见封狐雄虺自成群，冯深负固结妖氛。","玉玺分兵征恶少，金坛受律动将军。","将军拥旄宣庙略，战士横行静夷落。","长驱一息背铜梁，直指三巴逾劒阁。","阁道岧嶤上戍楼，劒门遥裔俯灵丘。","邛关九折无平路，江水双源有急流。","征役无期返，他乡岁华晚。","杳杳丘陵出，苍苍林薄远。","途危紫盖峰，路涩青泥坂。","去去指哀牢，行行入不毛。","绝壁千里险，连山四望高。","中外分区宇，夷夏殊风土。","交趾枕南荒，昆弥临北户。","川源饶毒雾，溪谷多淫雨。","行潦四时流，崩查千岁古。","漂梗飞蓬不自安，扪藤引葛度危峦。","昔时闻道从军乐，今日方知行路难。","苍江绿水东流驶，炎洲丹徼南中地。","南中南斗映星河，秦川秦塞阻烟波。","三春边地风光少，五月泸中瘴疠多。","朝驱疲斥候，夕息倦谁何。","向月弯繁弱，连星转太阿。","重义轻生怀一顾，东伐西征凡几度。","夜夜朝朝斑鬓新，年年岁岁戎衣故。","灞城隅，滇池水，天涯望转积，地际行无已。","徒觉炎凉节物非，不知关山千万里。","弃置勿重陈，重陈多苦辛。","且悦清笳杨柳曲，讵忆芳园桃李人。","绛节朱旗分白羽，丹心白刃酬明主。","但令一技君王识，谁惮三边征战苦。","行路难，行路难，岐路几千端。","无复归云冯短翰，望日想长安。"]},{"id":"T00907","t":"安德山池宴集","a":"上官仪","c":["上路抵平津，后堂罗荐陈。","缔交开狎赏，丽席展芳辰。","密树风烟积，回塘荷芰新。","雨霁虹桥晚，花落凤台春。","翠钗低舞席，文杏散歌尘。","方惜流觞满，夕鸟已城𬮱。"]},{"id":"T00908","t":"感怀","a":"董思恭","c":["野郊怆新别，河桥非旧饯。","惨日映峰沈，愁云随盖转。","哀笳时断续，悲旌乍舒卷。","望望情何极，浪浪泪空泫。","无复昔时人，芳春共谁遣。"]},{"id":"T00909","t":"相和歌辞 子夜四时歌六首 春歌二首 一","a":"郭元振","c":["青楼含日光，绿池起风色。","赠子同心花，殷勤此何极。"]},{"id":"T00910","t":"相和歌辞 采莲曲","a":"储光羲","c":["浅渚荷花繁，深塘菱叶疎。","独往方自得，耻邀淇上姝。","广江无术阡，大泽绝方隅。","浪中海童语，流下鲛人居。","春雁时隐舟，新荷复满湖。","采采乘日暮，不思贤与愚。"]},{"id":"T00911","t":"相和歌辞 从军行五首 三","a":"令狐楚","c":["却望冰河阔，前登雪岭高。","征人几多在，又拟战临洮。"]},{"id":"T00912","t":"杂曲歌辞 春江曲二首 二","a":"张仲素","c":["乘晓南湖去，参差叠浪横。","前洲在何处？雾里鴈嘤嘤。"]},{"id":"T00913","t":"蜀道难","a":"张文琮","c":["梁山镇地险，积石阻云端。","深谷下寥廓，层岩上郁盘。","飞梁驾绝岭，栈道接危峦。","揽辔独长息，方知斯路难。"]},{"id":"T00914","t":"夜游曲","a":"郑愔","c":["汉室欢娱盛，魏国文雅遒。","许史多暮宿，应陈从夜游。","西园䜩公子，北里召王侯。","讵似将军猎，空嗟亭尉留。"]},{"id":"T00915","t":"蜀中言怀","a":"王适","c":["独坐年将暮，常怀志不通。","有时须问影，无事却书空。","弃置如天外，平生似梦中。","蓬心犹是客，华髪欲成翁。","迹滞魂逾窘，情乖路转穷。","别离同夜月，愁思隔秋风。","老少悲颜驷，盈虚悟翟公。","时来不可问，何用求童蒙。"]},{"id":"T00916","t":"铜雀妓","a":"袁晖","c":["君爱本相饶，从来似舞腰。","那堪攀玉座，肠断望陵朝。","怨著情无主，哀凝曲不调。","况临松日暮，悲吹坐萧萧。"]},{"id":"T00917","t":"琴曲歌辞 胡笳十八拍 第三拍","a":"刘商","c":["如羇囚兮在缧绁，忧虑万端无处说。","使余力兮翦余发，食余肉兮饮余血。","诚知杀身愿如此，以余为妻不如死。","早被蛾眉累此身，空悲弱质柔如水。"]},{"id":"T00918","t":"望太华赠卢司仓","a":"陶翰","c":["行吏到西华，乃观三峰壮。","削成元气中，杰出天河上。","如有飞动色，不知青冥状。","巨灵安在哉，厥迹犹可望。","方此顾行旅，末由饬仙装。","葱茏记星坛，明灭数云嶂。","良友垂真契，宿心所微尚。","敢投归山吟，霞径一相访。"]},{"id":"T00919","t":"相和歌辞 饮马长城窟行","a":"虞世南","c":["驰马渡河干，流深马渡难。","前逢锦车使，都护在楼兰。","轻骑犹衔勒，疑兵尚解鞍。","温池下绝涧，栈道接危峦。","拓地勋未赏，亡城律讵宽。","有月关犹暗，经春陇尚寒。","云昏无复影，冰合不闻湍。","怀君不可遇，聊持报一餐。"]},{"id":"T00920","t":"杂歌谣辞 郑樱桃歌","a":"李颀","c":["石季龙，僭天禄。","擅雄豪，美人姓郑名樱桃。","樱桃美颜香且泽，娥娥侍寝专宫掖。","后庭卷衣三万人，翠眉清镜不得亲。","官军女骑一千匹，繁花照耀漳河春。","织成花映红纶巾，红旗掣曳卤簿新。","鸣鼙走马接飞鸟，铜[驮]琴瑟随去尘。","凤阳重门如意馆，百尺金梯倚银汉。","自言富贵不可量，女为公主男为王。","赤花双簟珊瑚床，盘龙斗帐琥珀光。","淫昏伪位神所恶，灭石者陵终不误。","邺城苍苍白露微，世事飜覆黄云飞。"]},{"id":"T00921","t":"相和歌辞 苦哉行五首 三","a":"戎昱","c":["登楼望天衢，目极泪盈睫。","彊笑无笑容，须妆旧花靥。","昔年买奴仆，奴仆来碎叶。","岂意未死间，自为匈奴妾。","一生忽至此，万事痛苦业。","得出塞垣飞，不如彼蜂蝶。"]},{"id":"T00922","t":"赠唐祖二子","a":"王翰","c":["鸿飞遵枉渚，鹿鸣思故群。","物情尚劳爱，况乃予别君。","别时花始发，别后兰再薰。","瑶觞滋白露，宝瑟凝凉氛。","裴徊北林月，怅望南山云。","云月渺千里，音徽不可闻。"]},{"id":"T00923","t":"和李起居秋夜之作","a":"薛奇童","c":["过庭闻礼日，趋侍记言回。","独卧玉窗前，卷帘残雨来。","高秋南斗转，凉夜北堂开。","水影入朱户，萤光生绿苔。","简成良史笔，年是洛阳才。","莫重白云意，时人许上台。"]},{"id":"T00924","t":"和崔侍御日用游开化寺阁","a":"吴少微","c":["左宪多才雄，故人尤鸷鹗。","护赠单于使，休轺太原郭。","馆次厌烦歊，清怀寻寂寞。","西缘十里余，北上开化阁。","初入云树间，冥蒙未昭廓。","渐出栏榥外，万里秋景焯。","岁晏风落山，天寒水归壑。","览物颂幽景，三乘动玄钥。","但敷利解言，永用忘昏著。"]},{"id":"T00925","t":"杂诗六首 三","a":"李华","c":["甘酸不私人，元和运五行。","生人受其用，味正心亦平。","爪牙相践伤，日与性命争。","圣人不能绝，钻燧与炮烹。","嗜欲乘此炽，百金资一倾。","正销神耗衰，邪胜体充盈。","颜子有余乐，瓢中寒水清。"]},{"id":"T00926","t":"春江花月夜二首 二","a":"张子容","c":["交甫怜瑶珮，仙妃难重期。","沈沈绿江晚，惆怅碧云姿。","初逢花上月，言是弄珠时。"]},{"id":"T00927","t":"杂曲歌辞 古别离二首 一","a":"施肩吾","c":["古人谩歌西飞燕，十年不见狂夫面。","三更风作切梦刀，万转愁成系肠线。","所嗟不及牛女星，一年一度得相见。"]},{"id":"T00928","t":"奉和圣制夏日游石淙山","a":"阎朝隐","c":["金台隐隐陵黄道，玉辇亭亭下绛雰。","千种冈峦千种树，一重岩壑一重云。","花落风吹红的历，藤垂日晃绿葐蒀。","五百里内贤人聚，愿陪阊阖侍天文。"]},{"id":"T00929","t":"幸梨园观打毬应制","a":"武平一","c":["令节重遨游，分镳应彩毬。","骖驔廻上苑，蹀躞绕通沟。","影就红尘没，光随赭汗流。","赏阑清景暮，歌舞乐时休。"]},{"id":"T00930","t":"杂曲歌辞 火凤辞 二","a":"李百药","c":["佳人靓晚妆，清唱动兰房。","影入含风扇，声飞照日梁。","娇嚬眉际敛，逸韵口中香。","自有横陈分，应怜秋夜长。"]},{"id":"T00931","t":"南海乱石山作","a":"杜审言","c":["涨海积稽天，群山高嶪地。","相传称乱石，图典失其事。","悬危悉可惊，大小都不类。","乍将云岛极，还与星河次。","上耸忽如飞，下临仍欲坠。","朝暾赩丹紫，夜魄炯青翠。","穹崇雾雨蓄，幽隐灵仙閟。","万寻挂鹤巢，千丈垂猿臂。","昔去景风涉，今来姑洗至。","观此得咏歌，长时想精异。"]},{"id":"T00932","t":"少年行三首 一","a":"李嶷","c":["十八羽林郎，戎衣侍汉王。","臂鹰金殿侧，挟弹玉舆傍。","驰道春风起，陪游出建章。"]},{"id":"T00933","t":"杂曲歌辞 长安少年行十首 四","a":"李廓","c":["好胜耽长行，天明烛满楼。","留人看独脚，赌马换偏头。","乐奏曾无歇，杯巡不暂休。","时时遥冷笑，怪客有春愁。"]},{"id":"T00934","t":"杂曲歌辞 桃花行 三","a":"李峤","c":["源水丛花无数开，丹跗红蕚间青梅。","从今结子三千岁，预喜仙游复摘来。"]},{"id":"T00935","t":"杂曲歌辞 行路难五首 四","a":"贺兰进明","c":["君不见云间月，暂盈还复缺。","君不见林下风，声远意难穷。","亲故平生欲聚散，欢娱未尽尊酒空。","自叹青青陵上柏，岁寒能与几人同。"]},{"id":"T00936","t":"同王昌龄裴迪游青龙寺昙壁上人兄院集和兄维","a":"王缙","c":["林中空寂舍，阶下终南山。","高卧一床上，回看六合间。","浮云几处灭，飞鸟何时还？","问义天人接，无心世界闲。","谁知大隐者，兄弟自追攀。"]},{"id":"T00937","t":"咏帘","a":"万楚","c":["玳瑁昔称华，玲珑薄绛纱。","钩衔门势曲，节乱水纹斜。","日弄长飞鸟，风摇不卷花。","自当分内外，非是为骄奢。"]},{"id":"T00938","t":"夜闻江南人家赛神因题即事","a":"李嘉祐","c":["南方淫祀古风俗，楚妪解唱迎神曲。","鎗鎗铜鼓芦叶深，寂寂琼筵江水绿。","雨过风清洲渚闲，椒浆醉尽迎神还。","帝女凌空下湘岸，番君隔浦向尧山。","月隐回塘犹自舞，一门依倚神之祜。","韩康灵药不复求，扁鹊医方曾莫覩。","逐客临江空自悲，月明流水无已时。","听此迎神送神曲，携觞欲吊屈原祠。"]},{"id":"T00939","t":"杂曲歌辞 昔昔盐 花飞桃李蹊","a":"赵嘏","c":["远期难可托，桃李自依依。","花径无容迹，戎裘未下机。","随风开又落，度日扫还飞。","欲折枝枝赠，那知归不归。"]},{"id":"T00940","t":"招谕有怀赠同行人","a":"李义府","c":["远游冒艰阻，深入劳存谕。","春去辞国门，秋还在边戍。","轩车行未返，节序催难驻。","陌上悲转蓬，园中想芳树。","蜀山自纷纠，岷水恒奔注。","临泛多苦怀，登攀寡欢趣。","永夕飞淫雨，崇朝蒸毒雾。","不求绥岭桃，宁美邛乡蒟。","白狼行欲静，骢马何常驱。","愿接轺斾尘，联翩东北骛。"]},{"id":"T00941","t":"杂曲歌辞 伊州 歌第四","a":"盖嘉运","c":["千里东归客，无心忆旧游。","挂帆游白水，高枕到青州。"]},{"id":"T00942","t":"踏歌词二首 二","a":"崔液","c":["庭际花微落，楼前汉已横。","金台催夜尽，罗袖拂寒轻。","乐笑畅欢情，未半著天明。"]},{"id":"T00943","t":"杂歌谣辞 步虚词 四","a":"韦渠牟","c":["鸾鹤共徘徊，仙官使者催。","香花三洞启，风雨百神来。","凤篆文初定，龙泥印已开。","何须生羽翼，始得上瑶台。"]},{"id":"T00944","t":"州城西园入斋祠社","a":"陈叔达","c":["升坛预洁祀，诘早肃分司。","达气风霜积，登光日色迟。","农教先八政，阳和秩四时。","祈年服垂冕，告币动褰帷。","瘗地尊余奠，人天庶有资。","椒兰卒清酌，簠簋彻香萁。","折俎分归胙，充庭降受厘。","方凭知礼节，况奉化雍熙。"]},{"id":"T00945","t":"奉和春日望海","a":"许敬宗","c":["韩夷愆奉賮，凭险乱天常。","乃神弘庙畧，横海剪吞航。","电野清玄菟，腾笳振白狼。","连云飞巨舰，编石架浮梁。","周游临大壑，降望极遐荒。","桃门通山抃，蓬渚降霓裳。","惊涛含蜃阙，骇浪掩晨光。","青丘绚春组，丹谷耀华桑。","长驱七萃卒，成功百战场。","俄且旋戎路，饮至肃岩廊。"]},{"id":"T00946","t":"古意六首 四","a":"王绩","c":["松生北岩下，由来人径绝。","布叶捎云烟，插根拥岩穴。","自言生得地，独负凌云洁。","何时畏斤斧，几度经霜雪。","风惊西北枝，雹陨东南节。","不知岁月久，稍觉枝干折。","藤萝上下碎，枝干纵横裂。","行当糜烂尽，坐共灰尘灭。","宁关匠石顾，岂为王孙折。","盛衰自有时，圣贤未尝屑。","寄言悠悠者，无为嗟大耋。"]},{"id":"T00947","t":"入蜀秋夜宿江渚","a":"陈子良","c":["我行逢日暮，弭櫂独维舟。","水雾一边起，风林两岸秋。","山阴黑断碛，月影素寒流。","故乡千里外，何以慰羁愁。"]},{"id":"T00948","t":"西陵峡","a":"杨炯","c":["绝壁耸万仞，长波射千里。","盘薄荆之门，滔滔南国纪。","楚都昔全盛，高丘烜望祀。","秦兵一旦侵，夷陵火潜起。","四维不复设，关塞良难恃。","洞庭且忽焉，孟门终已矣。","自古天地辟，流为峡中水。","行旅相赠言，风涛无极已。","及余践斯地，瓌奇信为美。","江山若有灵，千载伸知己。"]},{"id":"T00949","t":"正月十五夜","a":"苏味道","c":["火树银花合，星桥铁锁开。","暗尘随马去，明月逐人来。","游伎皆秾李，行歌尽落梅。","金吾不禁夜，玉漏莫相催。"]},{"id":"T00950","t":"同徐员外除太子舍人寓直之作","a":"郭震","c":["太子擅元良，宫臣命伟长。","除荣辞会府，直宿总书坊。","露湿幽岩桂，风吹便坐桑。","阁连云一色，池带月重光。","叶死兰无气，荷枯水不香。","遥闻秋兴作，言是晋中郎。"]},{"id":"T00951","t":"早朝","a":"韦元旦","c":["震维芳月季，宸极众星尊。","珮玉朝三陛，鸣珂度九门。","挈壶分早漏，伏槛耀初暾。","北倚苍龙阙，西临紫凤垣。","词庭草欲奏，温室树无言。","鳞翰空为忝，长怀圣主恩。"]},{"id":"T00952","t":"奉和圣制九日侍宴应制得高字","a":"李适","c":["禁苑秋光入，宸游霁色高。","萸房颁彩笥，菊蘂荐香醪。","后骑萦堤柳，前旌拂御桃。","王枚俱得从，浅浅愧飞毫。"]},{"id":"T00953","t":"凝碧池侍宴应制得出水槎","a":"武三思","c":["彼木生何代，为槎复几年。","欲乘银汉曲，先泛玉池边。","拥溜根横岸，沈波影倒悬。","无劳问蜀客，此处即高天。"]},{"id":"T00954","t":"奉和张岳州王潭州别诗二首 二","a":"韦嗣立","c":["昔时陪二贤，缨冕会神仙。","一去驰江海，相逢共播迁。","无因千里驾，忽覩四愁篇。","览讽欢何已，欢终徒怆然。"]},{"id":"T00955","t":"饯唐州高使君赴任","a":"卢藏用","c":["饯酒临丰树，褰帷出鲁阳。","蕙兰春已晚，桐柏路犹长。","祖逖方城镇，安期外氏乡。","从来二千石，天子命唯良。"]},{"id":"T00956","t":"饯许州宋司马赴任","a":"马怀素","c":["颍川开郡邑，角宿分躔野。","君非仲举才，谁是题舆者。","悯悯琴上鹤，萧萧路傍马。","严程若可留，别袂希再把。"]},{"id":"T00957","t":"㴩湖作","a":"赵冬曦","c":["三湖返入两山间，畜作㴩湖弯复弯。","暑雨奔流潭正满，微霜及潦水初还。","水还波卷谿潭涸，绿草芊芊岸崭岝。","适来飞櫂共回旋，已复扬鞭恣行乐。","道旁耆老步跹跹，楚言兹事不知年。","试就湖边披草径，莫疑东海变桑田。","君讶今时尽陵陆，我看明岁更沦涟。","来今自昔无终始，人事回环常若是。","应思阙下声华日，谁谓江潭旅游子。","初贞正喜固当然，往蹇来誉宜可俟。","盈虚用舍轮舆旋，勿学灵均远问天。"]},{"id":"T00958","t":"让帝挽歌词二首 二","a":"卢僎","c":["朝天驰马绝，册帝□宫祖。","恍惚陵庙新，萧条池馆古。","万化一朝空，哀乐此路同。","西园有明月，修竹韵悲风。"]},{"id":"T00959","t":"赠皇甫侍御赴都八首 四","a":"元希声","c":["粤在古昔，分官厥初。","刺邪矫枉，非贤勿居。","棱棱直指，烈烈方书。","苍玉鸣珮，绣衣登车。"]},{"id":"T00960","t":"奉和九日幸临渭亭登高应制","a":"赵彦昭","c":["秋豫凝仙览，宸游转翠华。","呼鹰下鸟路，戏马出龙沙。","紫菊宜新寿，丹萸辟旧邪。","须陪长久宴，岁岁奉吹花。"]},{"id":"T00961","t":"送张亶赴朔方应制","a":"萧至忠","c":["命将择耆年，图功胜必全。","光辉万乘饯，威武二庭宣。","中衢横鼓角，旷野蔽旌旃。","推食天厨至，投醪御酒传。","凉风过鴈苑，杀气下鸡田。","分阃恩何极，临岐动睿篇。"]},{"id":"T00962","t":"满月","a":"张谔","c":["社金流茂祉，庭玉表奇才。","竹似因谈植，兰疑入梦栽。","乌将八子去，凤逐九雏来。","今夜明珠色，当随满月开。"]},{"id":"T00963","t":"送国子张主簿","a":"包融","c":["湖岸缆初解，莺啼别离处。","遥见舟中人，时时一回顾。","坐悲芳岁晚，花落青轩树。","春梦随我心，悠扬逐君去。"]},{"id":"T00964","t":"奉和贺监林月清酌","a":"王湾","c":["华月当秋满，朝英假兴同。","净林新霁入，规院小凉通。","碎影行筵里，摇花落酒中。","清宵凝爽意，倂此助文雄。"]},{"id":"T00965","t":"赋得游人久不归","a":"贺朝","c":["乡关眇天末，引领怅怀归。","羇旅久淫滞，物色屡芳菲。","稍觉出意尽，行看蓬鬓稀。","如何千里外，伫立沾裳衣。"]},{"id":"T00966","t":"葛山潭","a":"孙逖","c":["圆潭写流月，晴明涵万象。","仙翁何时还，绿水空荡漾。","凉哉草木腓，白露沾人衣。","犹醉空山里，时闻笙鹤飞。"]},{"id":"T00967","t":"乡试后自巩还田家因谢邻友见过之作","a":"卢象","c":["鸡鸣出东邑，马倦登南峦。","落日见桑柘，翳然丘中寒。","邻家多旧识，投暝来相看。","且问春税苦，兼陈行路难。","园场近阴壑，草木易凋残。","峰晴雪犹积，涧深冰已团。","浮名知何用，岁晏不成欢。","置酒共君饮，当歌聊自宽。"]},{"id":"T00968","t":"嵩山十志十首 其四","a":"卢鸿一","c":["临泱漭兮背青荧，吐云烟兮合窅冥。","怳欻翕兮杳幽霭，意缥缈兮群仙会。","窅冥仙会兮枕烟庭，竦魂形兮凝视听。","闻夫至诚必感兮祈此巅，契颢气，养丹田，终彷像兮觏灵仙。"]},{"id":"T00969","t":"送丹阳采访","a":"徐安贞","c":["郡县分南国，皇华出圣朝。","为怜乡櫂近，不道使车遥。","旧俗吴三让，遗风汉六条。","愿言除疾苦，天子听歌谣。"]},{"id":"T00970","t":"夏日过青龙寺谒操禅师","a":"裴迪","c":["安禅一室内，左右竹亭幽。","有法知不染，无言谁敢酬。","鸟飞争向夕，蝉噪已先秋。","烦暑自兹适，清凉何所求。"]},{"id":"T00971","t":"登润州城","a":"丘为","c":["天末江城晚，登临客望迷。","春潮平岛屿，残雨隔虹蜺。","鸟与孤帆远，烟和独树低。","乡山何处是？目断广陵西。"]},{"id":"T00972","t":"归汝坟山庄留别卢象","a":"祖咏","c":["淹留岁将[晏]，久废南山期。","旧业不见弃，还山从此辞。","沤麻入南涧，刈麦向东菑。","对酒鸡黍熟，闭门风雪时。","非君一延首，谁慰遥相思。"]},{"id":"T00973","t":"送储十二还庄城","a":"綦毋潜","c":["西坂何缭绕，青林问子家。","天寒噪野雀，日晚度城鸦。","寂历道傍树，曈昽原上霞。","兹情不可说，长恨隐沦赊。"]},{"id":"T00974","t":"赠僧皎然","a":"颜真卿","c":["秋意西山多，别岑萦左次。","缮亭历三癸，趾趾邻什寺。","元化隐灵踪，始君启高致。","诛榛养翘楚，鞭草理芳穗。","俯砌披水容，逼天扫峰翠。","境新耳目换，物远风尘异。","倚石忘世情，援云得真意。","嘉林幸勿剪，禅侣欣可庇。","卫法大臣过，佐游群英萃。","龙池护清激，虎节到深邃。","徒想嵊顶期，于今没遗记。"]},{"id":"T00975","t":"江有枫一篇十章 四","a":"萧颖士","c":["东可游矣，会之丘矣。","于山于水，于庙于寺。","于亭于里，君子游焉。","于以宴喜，其乐亹亹。"]},{"id":"T00976","t":"山下晚晴","a":"崔曙","c":["寥寥远天净，谿路何空蒙。","斜光照疎雨，秋气生白虹。","云尽山色暝，萧条西北风。","故林归宿处，一叶下梧桐。"]},{"id":"T00977","t":"代北州老翁荅","a":"张谓","c":["负薪老翁往北州，北望乡关生客愁。","自言老翁有三子，两人已向黄沙死。","如今小儿新长成，明年闻道又征兵。","定知此别必零落，不及相随同死生。","尽将田宅借邻伍，且复伶俜去乡士。","在生本求多子孙，及有谁知更辛苦。","近传天子尊武臣，强兵直欲静胡尘。","安边自合有长策，何必流离中国人。"]},{"id":"T00978","t":"名姝咏","a":"梁锽","c":["阿娇年未多，弱体性能和。","怕重愁拈镜，怜轻喜曳罗。","临津双洛浦，对月两嫦娥。","独有荆王殿，时时暮雨过。"]},{"id":"T00979","t":"同阎伯均宿道士观有述","a":"包何","c":["南国佳人去不回，洛阳才子更须媒。","绮琴白雪无心弄，罗幌清风到晓开。","冉冉修篁依户牖，迢迢列宿映楼台。","纵令奔月成仙去，且作行云入梦来。"]},{"id":"T00980","t":"酬窦拾遗秋日见呈","a":"皇甫曾","c":["孤城永巷时相见，衰柳闲门日半斜。","欲送近臣朝魏阙，犹怜残菊在陶家。"]},{"id":"T00981","t":"鼓吹曲辞 雉子班","a":"李白","c":["辟邪伎作鼓吹惊，雉子班之奏曲成。","喔咿振迅欲飞鸣，扇锦翼，雄风生。","双雌同饮啄，趫悍谁能争。","乍向草中耿介死，不求黄金笼下生。","天地至广大，何惜遂物情。","善卷让天子，务光亦逃名。","所贵旷士怀，朗然合太清。"]},{"id":"T00982","t":"横吹曲辞 前出塞九首 五","a":"杜甫","c":["迢迢万余里，领我赴三军。","军中异苦乐，主将宁尽闻。","隔河见胡骑，倏忽数百群。","我始为奴仆，几时树功勋。"]},{"id":"T00983","t":"相和歌辞 班倢伃三首 一","a":"王维","c":["玉窗萤影度，金殿人声绝。","秋夜守罗帏，孤灯耿不灭。"]},{"id":"T00984","t":"相和歌辞 短歌行二首 一","a":"白居易","c":["曈曈太阳如火色，上行千里下一刻。","出为白昼入为夜，圜转如珠住不得。","住不得，可奈何？为君举酒歌短歌。","歌声苦，词亦苦，四座少年君听取。","今夕未竟明夕催，秋风才往春风回。","人无根蔕时不驻，朱颜白日相隳颓。","劝君且强笑一面，劝君复强饮一杯。","人生不得长欢乐，年少须臾老到来。"]},{"id":"T00985","t":"杂曲歌辞 杨柳枝 二","a":"李商隐","c":["含烟惹雾每依依，万绪千条拂落晖。","为报行人休尽折，半留相送半迎归。"]},{"id":"T00986","t":"相和歌辞 从军行 三","a":"王昌龄","c":["琵琶起舞换新声，总是关山旧别情。","撩乱边愁弹不尽，高高秋月下长城。"]},{"id":"T00987","t":"入峡寄弟","a":"孟浩然","c":["吾昔与尔辈，读书常闭门。","未尝冒湍险，岂顾垂堂言。","自此历江湖，辛勤难具论。","往来行旅弊，开凿禹功存。","壁立千峰峻，潨流万壑奔。","我来凡几宿，无夕不闻猿。","浦上摇归恋，舟中失梦魂。","泪沾明月峡，心断鹡鸰原。","离阔星难聚，秋深露已繁。","因君下南楚，书此示乡园。"]},{"id":"T00988","t":"鼓吹曲辞 凯歌六首 五","a":"岑参","c":["蕃军遥见汉家营，满谷连山徧哭声。","万箭千刀一夜杀，平明流血浸空城。"]},{"id":"T00989","t":"杂曲歌辞 蓟门行五首 四","a":"高适","c":["茫茫长城外，日没更烟尘。","胡骑虽凭陵，汉兵不顾身。","古树满空塞，黄云愁杀人。"]},{"id":"T00990","t":"相和歌辞 三阁词四首 三","a":"刘禹锡","c":["沈香帖阁柱，金缕画门楣。","回首降幡下，已见黍离离。"]},{"id":"T00991","t":"鼓吹曲辞 鼓吹铙歌 奔鲸沛","a":"柳宗元","c":["奔鲸沛，荡海垠。","吐霓翳日，腥浮云。","帝怒下顾，哀垫昏。","[授]以神柄，推元臣。","手援天矛，截修鳞。","披攘蒙霿，开海门。","地平水静，浮天垠。","羲和显耀，乘清氛。","赫炎溥畅，融大钧。"]},{"id":"T00992","t":"杂曲歌辞 行路难","a":"韦应物","c":["荆山之白玉兮。","良工雕琢双环连，月蚀中央镜心穿。","故人赠妾初相结，恩在环中寻不绝。","人情厚薄苦须臾，昔似连环今似玦。","连环可碎不可离，如何物在人自移。","上客勿遽欢，听妾歌路难。","傍人见环环可怜，不知中有长恨端。"]},{"id":"T00993","t":"相和歌辞 决绝[词]三首 二","a":"元稹","c":["噫春冰之将泮，何余怀之独结。","有美一人，于焉旷绝。","一日不见，比一日于三年，况三年之旷别。","水得风兮小而已波，笋在苞兮高不见节。","矧桃李之当春，竞众人之攀折。","我自顾悠悠而若云，又安能保君皓皓之如雪。","感破镜之分明，覩泪痕之余血。","幸他人之既不我先，又安能使他人之终不我夺。","已焉哉！织女别黄姑，一年一度暂相见，彼此隔河何事无。"]},{"id":"T00994","t":"琴曲歌辞 履霜操","a":"韩愈","c":["父兮儿寒，母兮儿饥。","儿罪当笞，逐儿何为？","儿在中野，以宿以处。","四无人声，谁与儿语。","儿寒何衣，儿饥何食。","儿行于野，履霜以足。","母生众儿，有母怜之。","独无母怜，儿宁不悲。"]},{"id":"T00995","t":"相和歌辞 箜篌引","a":"李贺","c":["公乎公乎，提壶将焉如？","屈平沈湘不足慕，徐衍入海诚为愚。","公乎公乎，床有菅席盘有鱼。","北里有贤兄，东邻有小姑。","陇亩油油黍与葫，瓦甒浊醪蚁浮浮。","黍可食，醪可饮，公乎公乎其奈居。","被发奔流竟何如？贤兄小姑哭呜呜。"]},{"id":"T00996","t":"相和歌辞 春江花月夜","a":"温庭筠","c":["玉树歌阑海云黑，花庭忽作青芜国。","秦淮有水水无情，还向金陵漾春色。","杨家二世安九重，不御华芝嫌六龙。","百幅锦帆风力满，连天展尽金芙蓉。","珠翠丁星复明灭，龙头劈浪哀笳发。","千里涵空照水魂，万枝破鼻团香雪。","漏转霞高沧海西，颇黎枕上闻天鸡。","蛮弦代雁曲如语，一醉昏昏天下迷。","四方倾动烟尘起，犹在浓香梦魂里。","后主荒宫有晓莺，飞来只隔西江水。"]},{"id":"T00997","t":"相和歌辞 从军行六首 三","a":"刘长卿","c":["草枯秋塞上，望见渔阳郭。","胡马嘶一声，汉兵泪双落。","谁为吮痈者，此事令人薄。"]},{"id":"T00998","t":"奉和圣制幸晋阳宫","a":"张九龄","c":["隋季失天策，万方罹凶残。","皇祖称义旗，三灵皆获安。","圣期将申锡，王业成艰难。","盗移未改命，历在终履端。","彼汾惟帝乡，雄都信郁盘。","一月朔巡狩，群后陪清銮。","霸迹在沛庭，旧仪覩汉官。","唐风思何深？舜典敷更宽。","户蒙枌榆复，邑争牛酒欢。","缅惟翦商后，岂独微禹叹。","三后既在天，万年斯不刊。","尊祖实我皇，天文皆仰观。"]},{"id":"T00999","t":"感遇诗三十八首 三","a":"陈子昂","c":["苍苍丁零塞，今古缅荒途。","亭堠何摧兀，暴骨无全躯。","黄沙幕南起，白日隐西隅。","汉甲三十万，曾以事匈奴。","但见沙场死，谁怜塞上孤。"]},{"id":"T01000","t":"横吹曲辞 折杨柳 二","a":"孟郊","c":["楼上春风过，风前杨柳歌。","枝疎缘别苦，曲怨为年多。","花惊燕地雪，叶映楚池波。","谁堪别离此，征戍在交河。"]},{"id":"T01001","t":"太和 雍和","a":"贺知章","c":["夙夜宥密，不敢宁宴。","五齐既陈，八音在县。","粢盛以絜，房俎斯荐。","惟德惟馨，尚兹克徧。"]},{"id":"T01002","t":"横吹曲辞 关山月","a":"张籍","c":["秋月朗朗关山上，山中行人马蹄响。","关山秋来雨雪多，行人见月唱边歌。","海边漠漠天气白，胡儿夜度黄龙碛。","军中探骑暮出城，伏兵暗处低旌戟。","溪水连地霜草平，野𫘞寻水碛中鸣。","陇头风急雁不下，沙场苦战多流星。","可怜万国关山道，年年战骨多秋草。"]},{"id":"T01003","t":"相和歌辞 采桑","a":"王建","c":["鸟鸣桑叶间，叶绿条复柔。","攀看去手近，放下长长钩。","黄花盖野田，白马少年游。","所念岂回顾，良人在高楼。"]},{"id":"T01004","t":"杂曲歌辞 天长地久词 二","a":"卢纶","c":["虹桥千步廊，半在水中央。","天子方清暑，宫人重暮妆。"]},{"id":"T01005","t":"杂曲歌辞 汉宫少年行","a":"李益","c":["君不见上宫警夜营八屯，冬冬街鼓朝朱轩。","玉阶霜仗拥未合，少年排入铜龙门。","暗闻弦管九天上，宫漏沈沈清吹繁。","才明走马绝驰道，呼鹰挟弹通缭垣。","玉笼金琐养黄口，探雏取卵伴王孙。","分曹六博快一掷，迎欢先意笑语喧。","巧为柔媚学优孟，儒衣嬉戏冠沐猨。","晚来香街经柳市，行过倡市宿桃根。","相逢杯酒一言失，回朱点白闻至尊。","金张许史伺颜色，王侯将相莫敢论。","岂知人事无定势，朝欢暮戚如掌翻。","椒房宠移子爱夺，一夕秋风生戾园。","徒用黄金将买赋，宁知白玉暗成痕。","持杯收水水已覆，徙薪避火火更燔。","欲求四老张丞相，南山如天不可上。"]},{"id":"T01006","t":"帝京篇十首 五","a":"太宗皇帝","c":["芳辰追逸趣，禁苑信多奇。","桥形通汉上，峰势接云危。","烟霞交隐映，花鸟自参差。","何如肆辙迹？万里赏瑶池。"]},{"id":"T01007","t":"九月九日","a":"高宗皇帝","c":["端居临玉扆，初律启金商。","凤阙澄秋色，龙闱引夕凉。","野净山气敛，林疎风露长。","砌兰亏半影，岩桂发全香。","满盖荷凋翠，圆花菊散黄。","挥鞭争电烈，飞羽乱星光。","柳空穿石碎，弦虚侧月张。","怯猿啼落岫，惊雁断分行。","斜轮低夕景，归斾拥通庄。"]},{"id":"T01008","t":"送忠州太守康昭远等","a":"明皇帝","c":["端拱临中枢，缅怀共予理。","不有台阁英，孰振循良美。","分符侯甸内，拜手明庭里。","誓节期饮冰，调人方导水。","嘉声驰九牧，惠化光千祀。","时雨侔昔贤，芳猷贯前史。","伫尔颂中和，吾将令卿士。"]},{"id":"T01009","t":"送徐州张建封还镇","a":"德宗皇帝","c":["牧守寄所重，才贤生为时。","宣风自淮甸，授钺膺藩维。","入觐展遐恋，临轩慰来思。","忠诚在方寸，感激陈情词。","报国尔所向，恤人予是资。","欢宴不尽怀，车马当还期。","谷雨将应候，行春犹未迟。","勿以千里遥，而云无己知。"]},{"id":"T01010","t":"唐享昊天乐 第四","a":"则天皇后","c":["巍巍叡业广，赫赫圣基隆。","菲德承先顾，祯符萃眇躬。","铭开武岩侧，图荐洛川中。","微诚讵幽感，景命忽昭融。","有怀慙紫极，无以谢玄穹。"]},{"id":"T01011","t":"驾幸新丰温泉宫献诗三首 一","a":"上官昭容","c":["三冬季月景[龙]年，万乘观风出灞川。","遥看电跃龙为马，回瞩霜原玉作田。"]},{"id":"T01012","t":"渡中江望石城泣下","a":"后主煜","c":["江南江北旧家乡，三十年来梦一场。","吴苑宫闱今冷落，广陵台殿已荒凉。","云笼远岫愁千片，雨打归舟泪万行。","兄弟四人三百口，不堪闲坐细思量。"]},{"id":"T01013","t":"丹景山至德寺","a":"蜀太后徐氏","c":["周回云水游丹景，因与真妃眺上方。","晴日晓升金晃曜，寒泉夜落玉丁当。","松梢月转琴栖影，柏径风牵麝食香。","虔煠六铢宜铸祝，惟祈圣祉保遐昌。"]},{"id":"T01014","t":"和题丹景山至德寺","a":"蜀太妃徐氏","c":["丹景山头宿梵宫，玉轮金辂驻虚空。","军持无水注寒碧，兰若有花开晚红。","武士尽排青嶂下，内人皆在讲筵中。","我家帝子传王业，积善终期四海同。"]},{"id":"T01015","t":"郊庙歌辞 祀圜丘乐章 寿和","a":"褚亮","c":["八音斯奏，三献毕陈。","宝祚惟永，晖光日新。"]},{"id":"T01016","t":"郊庙歌辞 封泰山乐章 豫和 五","a":"张说","c":["天道无亲，至诚与邻。","山川遍礼，宫征维新。","玉帛非盛，聪明会真。","正斯一德，通乎百神。"]},{"id":"T01017","t":"郊庙歌辞 武后明堂乐章 登歌","a":"武则天","c":["礼崇宗祀，志表严禋。","笙镛合奏，文物维新。","敬遵茂典，敢择良辰。","絜诚斯著，奠谒方申。"]},{"id":"T01018","t":"郊庙歌辞 五郊乐章 青帝角音","a":"魏征","c":["鹤云旦起，鸟星昏集。","律候新风，阳开初蛰。","至德可飨，行潦斯挹。","锡以无疆，蒸人乃粒。"]},{"id":"T01019","t":"郊庙歌辞 祀风师乐章 送神","a":"包佶","c":["微穆敷华能应节，飘扬发彩宜行庆。","送迎灵驾神心享，跪拜灵坛礼容盛。","气和草木发萌芽，德畅禽鱼遂翔泳。","永望翠盖逐流云，自兹率土调春令。"]},{"id":"T01020","t":"奉和圣制行次成皐途经先圣擒建德之所感而成诗应制","a":"苏颋","c":["汉东不执象，河朔方鬬龙。","夏灭渐宁乱，唐兴终奋庸。","皇威正赫赫，兵气何匈匈。","用武三川震，归淳六代𬪩。","成臯覩王业，天下致人雍。","即此巡于岱，曾孙受命封。"]},{"id":"T01021","t":"郊庙歌辞 禅社首乐章 寿和","a":"贺知章、源乾曜","c":["惟以明发，有怀载殷。","乐盈而反，礼顺其禋。","立清以献，荐欲是亲。","於穆不已，裒对斯臻。"]},{"id":"T01022","t":"秋夜望月","a":"姚崇","c":["明月有余鉴，羁人殊未安。","桂含秋树晚，波入夜池寒。","灼灼云枝净，光光草露团。","所思迷所在，长望独长叹。"]},{"id":"T01023","t":"鼓吹曲辞 有所思","a":"沈佺期","c":["君子事行役，再空芳岁期。","美人旷延伫，万里浮云思。","园槿绽红艳，郊桑柔绿滋。","坐看长夏晚，秋月生罗帏。"]},{"id":"T01024","t":"奉和圣制春日幸望春宫应制","a":"崔日用","c":["东郊风物正熏馨，素浐凫鹥戏绿汀。","凤阁斜通平乐观，龙旗直逼望春亭。","光风摇动兰英紫，淑气依迟柳色青。","渭浦明晨修禊事，群公倾贺水心铭。"]},{"id":"T01025","t":"奉和七夕两仪殿会宴应制","a":"李乂","c":["桂宫明月夜，兰殿起秋风。","云汉弥年阻，星筵此夕同。","倏来疑有处，旋去已成空。","睿作钧天响，魂飞在梦中。"]},{"id":"T01026","t":"郊庙歌辞 享太庙乐章 大基舞","a":"魏征、褚亮","c":["猗与祖业，皇矣帝先。","翦商德厚，封唐庆延。","在姬犹稷，方晋喻宣。","基我鼎运，于万斯年。"]},{"id":"T01027","t":"郊庙歌辞 德明兴圣庙乐章 兴圣酌献","a":"李舒","c":["閟宫静谧，合乐周张。","泰尊始献，百末重觞。","震澹存诚，庶几迪尝。","遥源之祚，天汉灵长。"]},{"id":"T01028","t":"相和歌辞 采莲曲","a":"徐彦伯","c":["妾家越水边，摇艇入江烟。","既觅同心侣，复采同心莲。","折藕丝能脆，开花叶正圆。","春歌弄明月，归棹落花前。"]},{"id":"T01029","t":"慈恩寺九日应制","a":"薛稷","c":["宝宫星宿劫，香塔鬼神功。","王游盛尘外，睿览出区中。","日宇开初景，天词掩大风。","微臣谢时菊，薄采入芳丛。"]},{"id":"T01030","t":"奉和送金城公主适西蕃应制","a":"徐坚","c":["星汉下天孙，车服降殊蕃。","匣中词易切，马上曲虚繁。","关塞移朱帐，风尘暗锦轩。","箫声去日远，万里望河源。"]},{"id":"T01031","t":"琴曲歌辞 蔡氏五弄 游春曲二首 一","a":"王涯","c":["万树江边杏，新开一夜风。","满园深浅色，照在绿波中。"]},{"id":"T01032","t":"郊庙歌辞 梁郊祀乐章 庆和 五","a":"赵光逢、张衮","c":["惟德动天，有感必通。","秉兹一德，禋于六宗。","钦夤宝命，恭肃礼容。","来顾来享，永穆皇风。"]},{"id":"T01033","t":"横吹曲辞 陇头水","a":"卢照邻","c":["陇坂高无极，征人一望乡。","关河别去水，沙塞断归肠。","马系千年树，旌悬九月霜。","从来共呜咽，皆是为勤王。"]},{"id":"T01034","t":"横吹曲辞 出塞曲 二","a":"僧贯休","c":["玉帐将军意，慇懃把酒论。","功高宁在我，阵没与招魂。","塞色干戈束，军容喜气屯。","男儿今始是，敢出玉关门。"]},{"id":"T01035","t":"相和歌辞 度关山","a":"李端","c":["雁塞日初晴，胡关雪复平。","危竿缘广漠，古窦傍长城。","拔劒金星出，弯弧玉羽鸣。","谁知系虏者，贾谊是书生。"]},{"id":"T01036","t":"相和歌辞 善哉行","a":"僧齐己","c":["大鹏刷翮谢溟渤，青云万层高突出。","下视秋涛空渺弥，旧处鱼龙皆细物。","人生在世何容易，眼浊心昏信生死。","愿除嗜欲待身轻，携手同寻列仙事。"]},{"id":"T01037","t":"相和歌辞 采莲归","a":"王勃","c":["采莲归，绿水芙蓉衣，秋风起浪凫雁飞。","桂棹兰桡下长浦，罗裙玉腕摇轻橹。","叶屿花潭极望平，江讴越吹相思苦。","相思苦，佳期不可驻。","塞外征夫犹未还，江南采莲今已暮。","今已暮，摘莲花，今渠那必尽倡家。","官道城南把桑叶，何如江上采莲花？","莲花复莲花，花叶何重叠。","叶翠本羞眉，花红彊如颊。","佳人不兹期，怅望别离时。","牵花怜共蒂，折藕爱连丝。","故情何处所？新物徒华滋。","不惜南津交佩解，还羞北海雁书迟。","采莲歌有节，采莲夜未歇。","正逢浩荡江上风，又值徘徊江上月。","莲浦夜相逢，吴姬越女何丰茸。","共问寒江千里外，征客关山更几重。"]},{"id":"T01038","t":"初秋夜坐应诏","a":"杨师道","c":["玉琯凉初应，金壶夜渐阑。","沧池流稍洁，仙掌露方漙。","雁声风处断，树影月中寒。","爽气长空净，高吟觉思宽。"]},{"id":"T01039","t":"相和歌辞 铜雀妓","a":"僧皎然","c":["彊开尊酒向陵看，忆得君王旧日欢。","不觉余歌悲自断，非关艳曲转声难。"]},{"id":"T01040","t":"相和歌辞 采莲曲二首 二","a":"鲍溶","c":["采莲朅来水无风，莲潭如镜松如龙。","夏衫短袖交斜红，艳歌笑鬬新芙蓉，戏鱼住听莲花东。"]},{"id":"T01041","t":"相和歌辞 从军行","a":"张祜","c":["少年金紫就光辉，直指边城虎翼飞。","一卷旌收千骑虏，万全身出百重围。","黄云断塞寻鹰去，白草连天射雁归。","白首汉廷刀笔吏，丈夫功业本相依。"]},{"id":"T01042","t":"相和歌辞 江南曲八首 四","a":"刘希夷","c":["皓如楚江月，霭若吴岫云。","波中自皎镜，山上亦氛氲。","明月留照妾，轻云持赠君。","山川各离散，光气乃殊分。","天涯一为别，江北自相闻。"]},{"id":"T01043","t":"长信宫中树","a":"乔知之","c":["婀娜当轩树，䒠茸倚兰殿。","叶艳九春华，香摇五明扇。","余花鸟弄尽，新叶虫书徧。","零落心自知，芳菲君不见。"]},{"id":"T01044","t":"奉和九月九日圣制登慈恩寺浮图应制","a":"刘宪","c":["飞塔云霄半，清晨羽斾游。","登临凭季月，寥廓见中州。","御酒新寒退，天文瑞景留。","辟邪将献寿，兹日奉千秋。"]},{"id":"T01045","t":"饯唐州高使君赴任","a":"崔湜","c":["芳春桃李时，京都物华好。","为岳岂不贵，所悲涉远道。","远道不可思，宿昔梦见之。","赠君双佩刀，日夕视来期。"]},{"id":"T01046","t":"直中书省","a":"韦承庆","c":["清切凤皇池，扶疎鸡树枝。","唯应集鸾鹭，何为宿羁雌。","大造乾坤辟，深恩雨露垂。","昆蚑皆含养，驽骀亦驱驰。","木偶翻为用，芝泥忽滥窥。","九思空自勉，五字本无施。","徒喜逢千载，何阶荅二仪。","萤光向日尽，蚊力负山疲。","禁宇庭除阔，闲宵钟箭移。","暗花临户发，残月下帘欹。","白发随年改，丹心为主披。","命将时共泰，言与行俱危。","寄谢巢由客，尧年正在斯。"]},{"id":"T01047","t":"塞垣行","a":"崔融","c":["疾风卷溟海，万里扬沙砾。","仰望不见天，昏昏竟朝夕。","是时军两进，东拒复西敌。","蔽山张旗鼓，间道潜锋镝。","精骑突晓围，奇兵袭暗壁。","十月边塞寒，四山沍阴积。","雨雪鴈南飞，风尘景西迫。","昔我事讨论，未尝怠经籍。","一朝弃笔砚，十年操矛戟。","岂要黄河誓，须勒燕山石。","可嗟牧羊臣，海外久为客。"]},{"id":"T01048","t":"杂曲歌辞 游侠篇","a":"崔颢","c":["少年负胆气，好勇复知机。","仗劒出门去，孤城逢合围。","杀人辽水上，走马渔阳归。","错落金琐甲，蒙茸貂鼠衣。","还家行且猎，弓矢速如飞。","地迥鹰犬疾，草深狐兔肥。","腰间悬两绶，转眄生光辉。"]},{"id":"T01049","t":"相和歌辞 短歌行六首 四","a":"顾况","c":["何处春风吹晓幕？江南绿水通朱阁。","美人二八面如花，泣向东风畏花落。"]},{"id":"T01050","t":"相和歌辞 杂怨三首 二","a":"聂夷中","c":["良人昨日去，明日又不还。","别时各有泪，零落青楼前。"]},{"id":"T01051","t":"舞曲歌辞 柘枝词 三","a":"薛能","c":["意气成功日，春风起絮天。","楼台新邸第，歌舞小婵娟。","急破催摇曳，罗衫半脱肩。"]},{"id":"T01052","t":"初到陆浑山庄","a":"宋之问","c":["授衣感穷节，策马凌伊关。","归齐逸人趣，日觉秋琴闲。","寒露衰北阜，夕阳破东山。","浩歌步榛樾，栖鸟随我还。"]},{"id":"T01053","t":"余杭醉歌赠吴山人","a":"丁仙芝","c":["晓幕红襟燕，春城白项乌。","只来梁上语，不向府中趋。","城头坎坎鼓声曙，满庭新种樱桃树。","桃花昨夜撩乱开，当轩发色映楼台。","十千兑得余杭酒，二月春城长命杯。","酒后留君待明月，还将明月送君回。"]},{"id":"T01054","t":"相和歌辞 江南曲 四","a":"陆龟蒙","c":["鱼戏莲叶南，欹危午烟叠。","光摇越鸟巢，影乱吴娃檝。"]},{"id":"T01055","t":"古别离","a":"孟云卿","c":["朝日上高台，离人怨秋草。","但见万里天，不见万里道。","君行本迢远，苦乐良难保。","宿昔梦同衾，忧心常倾倒。","含酸欲谁诉，展转伤怀抱。","结发年已迟，征行去何早。","寒暄有时谢，憔悴难再好。","人皆算年寿，死者何曾老。","少壮无见期，水深风浩浩。"]},{"id":"T01056","t":"相和歌辞 倢伃怨","a":"崔国辅","c":["长信宫中草，年年愁处生。","故侵珠履迹，不使玉阶行。"]},{"id":"T01057","t":"湖中晚霁","a":"常建","c":["湖广舟自轻，江天欲澄霁。","是时清楚望，气色犹霾曀。","踟蹰金霞白，波上日初丽。","烟虹落镜中，树木生天际。","杳杳涯欲辨，蒙蒙云复闭。","言乘星汉明，又覩寰瀛势。","微兴从此惬，悠然不知岁。","试歌沧浪清，遂觉乾坤细。","岂念客衣薄，将期永投袂。","迟回渔父间，一鴈声嘹唳。"]},{"id":"T01058","t":"杂曲歌辞 从军中行路难二首 二","a":"骆宾王","c":["君不见玉关尘色暗边亭，铜鞮杂虏寇长城。","天子按劒征余勇，将军受脤事横行。","七德龙韬开玉帐，千里鼍鼓叠金钲。","阴山苦雾埋高垒，交河孤月照连营。","连营去去无穷极，拥斾遥遥过绝国。","阵云朝结晦天山，寒沙夕涨迷疎勒。","龙鳞水上开鱼贯，马首山前振雕翼。","长驱万里詟祁连，分麾三命武功宣。","百发乌号遥碎柳，七尺龙文迥照莲。","春来秋去移灰琯，兰闺柳市芳尘断。","鴈门迢遰尺书稀，鸳被相思双带缓。","行路难，誓令氛祲静皐兰。","但使封侯龙额贵，讵随中妇凤楼寒。"]},{"id":"T01059","t":"酬薛舍人万年宫晚景寓直怀友","a":"上官仪","c":["奕奕九成台，窈窕绝尘埃。","苍苍万年树，玲珑下冥雾。","池色摇晚空，岩花歛余煦。","清切丹禁静，浩荡文河注。","留连穷胜托，夙期暌善谑。","东望安仁省，西临子云阁。","长啸披烟霞，高步寻兰若。","金狄掩通门，雕鞍归骑喧。","燕姝对明月，荆艳促芳尊。","别有青山路，策杖访王孙。"]},{"id":"T01060","t":"守岁二首 一","a":"董思恭","c":["暮景斜芳殿，年华丽绮宫。","寒辞去冬雪，暖带入春风。","阶馥舒梅素，盘花卷烛红。","共欢新故岁，迎送一宵中。"]},{"id":"T01061","t":"相和歌辞 子夜四时歌六首 春歌二首 二","a":"郭元振","c":["陌头杨柳枝，已被春风吹。","妾心正断绝，君怀那得知。"]},{"id":"T01062","t":"相和歌辞 采菱曲","a":"储光羲","c":["浊水菱叶肥，清水菱叶鲜。","义不游浊水，志士多苦言。","潮没具区薮，潦深云梦田。","朝随北风去，暮逐南风还。","浦口多渔家，相与邀我船。","饭稻以终日，羹莼将永年。","方冬水物穷，又欲休山樊。","尽室相随从，所贵无忧患。"]},{"id":"T01063","t":"相和歌辞 从军行五首 四","a":"令狐楚","c":["胡风千里惊，汉月五更明。","纵有还家梦，犹闻出塞声。"]},{"id":"T01064","t":"杂曲歌辞 春游曲三首 一","a":"张仲素","c":["烟柳飞轻絮，风榆落小钱。","蒙蒙百花里，罗绮竞秋千。"]},{"id":"T01065","t":"昭君怨","a":"张文琮","c":["戒途飞万里，回首望三秦。","忽见天山雪，还疑上苑春。","玉痕垂粉泪，罗袂拂胡尘。","为得胡中曲，还悲远嫁人。"]},{"id":"T01066","t":"少年行","a":"郑愔","c":["颍川豪横客，咸阳轻薄儿。","田窦方贵幸，赵李新相知。","轩盖终朝集，笙竽此夜吹。","黄金盈箧笥，白日忽西驰。"]},{"id":"T01067","t":"古别离","a":"王适","c":["昔岁惊杨柳，高楼悲独守。","今年芳树枝，孤栖怨别离。","珠帘昼不卷，罗幔晓长垂。","苦调琴先觉，愁容镜独知。","频年雁度无消息，罢却鸳文何用织。","夜还罗帐空有情，春著裙腰自无力。","青轩桃李落纷纷，紫庭兰蕙日氛氲。","已能顦顇今如此，更复含情一待君。"]},{"id":"T01068","t":"正月闺情","a":"袁晖","c":["正月金闺里，微风绣户间。","晓魂怜别梦，春思逼啼颜。","遶砌梅堪折，当轩树未攀。","岁华庭北上，何日度阳关。"]},{"id":"T01069","t":"琴曲歌辞 胡笳十八拍 第四拍","a":"刘商","c":["山川路长谁记得，何处天涯是乡国？","自从惊怖少精神，不觉风霜损颜色。","夜中归梦来又去，朦胧岂解传消息。","漫漫胡天叫不闻，明明汉月应相识。"]},{"id":"T01070","t":"赠郑员外","a":"陶翰","c":["骢马拂绣裳，按兵辽水阳。","西分鴈门骑，北逐楼烦王。","闻道五军集，相邀百战场。","风沙暗天起，虏骑森已行。","儒服揖诸将，雄谋吞大荒。","金门来见谒，朱绂生辉光。","数年侍御史，稍迁尚书郎。","人生志气立，所贵功业昌。","何必守章句，终年事铅黄。","同时献赋客，尚在东陵傍。"]},{"id":"T01071","t":"相和歌辞 飞来双白鹤","a":"虞世南","c":["飞来双白鹤，奋翼远凌烟。","双栖集紫盖，一举背青田。","飏影过伊洛，流声入管弦。","鸣群倒景外，刷羽阆风前。","映海疑浮雪，拂涧泻飞泉。","燕雀宁知去，蜉蝣不识还。","何言别俦侣，从此间山川。","顾步已相失，裴回反自怜。","危心犹警露，哀响讵闻天。","无因振六翮，轻举复随仙。"]},{"id":"T01072","t":"湘夫人","a":"李颀","c":["九嶷日已暮，三湘云复愁。","窅霭罗袂色，潺湲江水流。","佳期来北渚，捐佩在芳洲。"]},{"id":"T01073","t":"相和歌辞 苦哉行五首 四","a":"戎昱","c":["妾家青河边，七叶承貂蝉。","身为最小女，偏得浑家怜。","亲戚不相识，幽闺十五年。","有时最远出，祗到中门前。","前年狂胡来，惧死飜生全。","今秋官军至，岂意遭戈鋋。","匈奴为先锋，长鼻黄发拳。","弯弓猎生人，百步牛羊膻。","脱身落虎口，不及归黄泉。","苦哉难重陈，暗哭苍苍天。"]},{"id":"T01074","t":"飞燕篇","a":"王翰","c":["孝成皇帝本娇奢，行幸平阳公主家。","可怜女儿三五许，䒠茸惜是一园花。","歌舞向来人不贵，一旦逢君感君意。","君心见赏不见忘，姊妹双飞入紫房。","紫房彩女不得见，专荣固宠昭阳殿。","红妆宝镜珊瑚台，青琐银簧云母扇。","日夕风传歌舞声，祗扰长信忧人情。","长信忧人气欲绝，君王歌吹终不歇。","朝弄琼箫下彩云，夜踏金梯上明月。","明月薄蚀阳精昏，娇妬倾城惑至尊。","已见白虹横紫极，复闻飞燕啄皇孙。","皇孙不死燕啄折，女弟一朝如火绝。","明明天子咸戒之，赫赫宗周襃姒灭。","古来贤圣叹狐裘，一国荒淫万国羞。","安得上方断马劒，斩取朱门公子头。"]},{"id":"T01075","t":"吴声子夜歌","a":"薛奇童","c":["净扫黄金堦，飞霜皓如雪。","下帘弹箜篌，不忍见秋月。"]},{"id":"T01076","t":"哭富嘉谟","a":"吴少微","c":["吾友适不死，於戏社稷臣。","直禄非造利，长怀大庇人。","乃通承明籍，遘此敦牂春。","药厉其可畏，皇穹故匪仁。","畴昔与夫子，孰云异天伦。","同病一相失，茫茫不重陈。","子之文章在，其殆尼父新。","鼓兴斡河岳，贞词毒鬼神。","可悲不可朽，车輤没荒榛。","圣主贤为宝，吁兹大国贫。"]},{"id":"T01077","t":"杂诗六首 四","a":"李华","c":["阴魄沦宇宙，太阳假其明。","臣道不敢专，由此见亏盈。","未闻东菑稼，一气嘉谷成。","上天降寒暑，地利乃可生。","葛藟附柔木，繁阴蔽曾原。","风霜摧枝干，不复庇本根。","女萝依松柏，然后得长存。"]},{"id":"T01078","t":"云阳驿陪崔使君邵道士夜宴","a":"张子容","c":["一尉东南远，谁知此夜欢。","诸侯倾皂盖，仙客整黄冠。","染翰灯花满，飞觞云气寒。","欣承国士遇，更借美人看。"]},{"id":"T01079","t":"杂曲歌辞 古别离二首 二","a":"施肩吾","c":["老母别爱子，少妻送征郎。","血流既四面，乃亦断二肠。","不愁寒无衣，不怕饥无粮。","惟恐征战不还乡，母化为鬼妻为孀。"]},{"id":"T01080","t":"鹦鹉猫儿篇","a":"阎朝隐","c":["霹雳引，丰隆鸣，猛兽噫气蛇吼声。","鹦鹉鸟，同资造化兮殊粹精。","鹔鹴毛，翡翠翼。","鹓雏延颈，鹍鸡弄色。","鹦鹉鸟，同禀阴阳兮异埏埴。","彼何为兮，隐隐振振。","此何为兮，绿衣翠襟。","彼何为兮，窘窘蠢蠢。","此何为兮，好貌好音。","彷彷兮徉徉，似妖姬躧步兮动罗裳。","趋趋兮跄跄，若处子回眸兮登玉堂。","爰有兽也，安其忍，觜其脇，距其胸，与之放旷浪浪兮，从从容容。","钩爪锯牙也，宵行昼伏无以当，遇之兮忘味。","抟击腾掷也，朝飞暮噪无以拒，逢之兮屏气。","由是言之，贪残薄则智慧作，贪残临之兮不复攫。","由是言之，智慧周则贪残囚，智慧犯之兮不复忧。","菲形陋质虽贱微，皇王顾遇长光辉。","离宫别馆临朝市，妙舞繁弦杂宫征。","嘉喜堂前景福内，合欢殿上明光里。","云母屏风文彩合，流苏斗帐香烟起。","承恩宴盼接宴喜，高视七头金骆驼。","平怀五尺铜狮子，国有君兮国有臣。","君为主兮臣为宾，朝有贤兮朝有德。","贤为君兮德为饰，千年万岁兮心转忆。"]},{"id":"T01081","t":"奉和幸白鹿观应制","a":"武平一","c":["玉府凌三曜，金坛驻六龙。","彩旒悬倒景，羽盖偃乔松。","玄圃灵芝秀，华池瑞液浓。","谬因沾舜渥，长愿奉尧封。"]},{"id":"T01082","t":"少年行","a":"李百药","c":["少年飞翠盖，上路勒金镳。","始酌文君酒，新吹弄玉箫。","少年不欢乐，何以尽芳朝。","千金笑里面，一搦掌中腰。","挂缨岂惮宿，落珥不胜娇。","寄语少年子，无辞归路遥。"]},{"id":"T01083","t":"送和西蕃使","a":"杜审言","c":["使出凤皇池，京师阳春晚。","圣朝尚边策，诏谕兵戈偃。","拜手明光殿，摇心上林苑。","种落逾青羌，关山度赤坂。","疆场及无事，雅歌而餐饭。","宁独锡和戎，更当封定远。"]},{"id":"T01084","t":"少年行三首 二","a":"李嶷","c":["侍猎长杨下，承恩更射飞。","尘生马影灭，箭落雁行稀。","薄暮随天仗，联翩入琐闱。"]},{"id":"T01085","t":"杂曲歌辞 长安少年行十首 五","a":"李廓","c":["遨游携艳妓，装束似男儿。","杯酒逢花住，笙歌簇马吹。","鸎声催曲急，春色讶归迟。","不以闻衔鼓，华筵待月移。"]},{"id":"T01086","t":"杂曲歌辞 桃花行 四","a":"李峤","c":["桃花灼灼有光辉，无数成蹊点更飞。","为见芳林含笑待，遂同温树不言归。"]},{"id":"T01087","t":"杂曲歌辞 行路难五首 五","a":"贺兰进明","c":["君不见东流水，一去无穷已。","君不见西郊云，日夕空氛氲。","群雁裴回不能去，一雁悲鸣复失群。","人生结交在终始，莫为升沈中路分。"]},{"id":"T01088","t":"别辋川别业","a":"王缙","c":["山月晓仍在，林风凉不绝。","殷勤如有情，惆怅令人别。"]},{"id":"T01089","t":"茱萸女","a":"万楚","c":["山阴柳家女，九日采茱萸。","复得东邻伴，双为陌上姝。","插枝著高髻，结子置长裾。","作性常迟缓，非关诧丈夫。","平明折林樾，日入返城隅。","侠客要罗袖，行人挑短书。","蛾眉自有主，年少莫踟蹰。"]},{"id":"T01090","t":"古兴","a":"李嘉祐","c":["十五小家女，双鬟人不如。","蛾眉暂一见，可直千金余。","自从得向蓬莱里，出入金舆乘玉趾。","梧桐树上春鸦鸣，晓伴君王犹未起。","莫道君恩长不休，婕妤团扇苦悲秋。","君看魏帝邺都里，惟有铜台漳水流。"]},{"id":"T01091","t":"杂曲歌辞 昔昔盐 采桑秦氏女","a":"赵嘏","c":["南陌采桑出，谁知妾姓秦。","独怜倾国貌，不负早莺春。","珠履荡花湿，龙钩折桂新。","使君那驻马，自有侍中人。"]},{"id":"T01092","t":"宣正殿芝草","a":"李义府","c":["明王敦孝感，宝殿秀灵芝。","色带朝阳净，光涵雨露滋。","且标宣德重，更引国恩施。","圣祚今无限，微臣乐未移。"]},{"id":"T01093","t":"杂曲歌辞 伊州 歌第五","a":"盖嘉运","c":["桂殿江乌对，雕屏海燕重。","秖应多酿酒，醉罢乐高钟。"]},{"id":"T01094","t":"代春闺","a":"崔液","c":["江南日暖鸿始来，柳条初碧叶半开。","玉关遥遥戍未回，金闺日夕生绿苔。","寂寂春花烟色暮，簷燕双双落花度。","青楼明镜昼无光，红帐罗衣徒自香。","妾恨十年长独守，君情万里在渔阳。"]},{"id":"T01095","t":"杂歌谣辞 步虚词 五","a":"韦渠牟","c":["羽节忽排烟，苏君已得仙。","命风驱日月，缩地走山川。","几处留丹灶，何时种玉田。","一朝骑白虎，直上紫微天。"]},{"id":"T01096","t":"春首","a":"陈叔达","c":["雪花联玉树，冰彩散瑶池。","翔禽遥出没，积翠远参差。"]},{"id":"T01097","t":"奉和元日应制","a":"许敬宗","c":["天正开初节，日观上重轮。","百灵滋景祚，万玉庆惟新。","待旦敷玄造，韬旒御紫宸。","武帐临光宅，文卫象钩陈。","广庭扬九奏，大帛丽三辰。","发生同化育，播物体陶钧。","霜空澄晓气，霞景莹芳春。","德辉覃率[土]，相贺奉还淳。"]},{"id":"T01098","t":"古意六首 五","a":"王绩","c":["桂树何苍苍，秋来花更芳。","自言岁寒性，不知露与霜。","幽人重其德，徙植临前堂。","连拳八九树，偃蹇二三行。","枝枝自相纠，叶叶还相当。","去来双鸿鹄，栖息两鸳鸯。","荣荫诚不厚，斤斧亦勿伤。","赤心许君时，此意那可忘。"]},{"id":"T01099","t":"赋得妓","a":"陈子良","c":["金谷多欢宴，佳丽正芳菲。","流霞席上满，回雪掌中飞。","明月临歌扇，行云接舞衣。","何必桃将李，别有待春晖。"]},{"id":"T01100","t":"从军行","a":"杨炯","c":["烽火照西京，心中自不平。","牙璋辞凤阙，铁骑绕龙城。","雪暗凋旗画，风多杂鼓声。","宁为百夫长，胜作一书生。"]},{"id":"T01101","t":"咏雾","a":"苏味道","c":["氤氲起洞壑，遥裔匝平畴。","乍似含龙劒，还疑映蜃楼。","拂林随雨密，度径带烟浮。","方谢公超步，终从彦辅游。"]},{"id":"T01102","t":"春江曲","a":"郭震","c":["江水春沈沈，上有双竹林。","竹叶坏水色，郎亦坏人心。"]},{"id":"T01103","t":"奉和立春游苑迎春应制","a":"韦元旦","c":["灞涘长安恒近日，殷正腊月早迎新。","池鱼戏叶仍含冻，宫女裁花已作春。","向苑云疑承翠幄，入林风若起青苹。","年年斗柄东无限，愿挹琼觞寿北辰。"]},{"id":"T01104","t":"游禁苑幸临渭亭遇雪应制","a":"李适","c":["长乐喜春归，披香瑞雪霏。","花从银合度，絮绕玉窗飞。","写曜衔天藻，呈祥拂御衣。","上林纷可望，无处不光辉。"]},{"id":"T01105","t":"奉和宴小山池赋得谿字应制","a":"武三思","c":["年光开碧沼，云色歛青谿。","冻解鱼方戏，风暄鸟欲啼。","岩泉飞野鹤，石镜舞山鸡。","柳发龙鳞出，松新麈尾齐。","九韶从此验，三月定应迷。"]},{"id":"T01106","t":"奉和初春幸太平公主南庄应制","a":"韦嗣立","c":["主第岩扃架鹊桥，天门阊阖降鸾镳。","历乱旌旗转云树，参差台榭入烟霄。","林间花杂平阳舞，谷里莺和弄玉箫。","已陪沁水追欢日，行奉茅山访道朝。"]},{"id":"T01107","t":"饯许州宋司马赴任","a":"卢藏用","c":["国为休征选，舆因仲举题。","山川襄野隔，朋酒灞亭暌。","零雨征轩骛，秋风别骥嘶。","骊歌一曲罢，愁望正凄凄。"]},{"id":"T01108","t":"饯唐州高使君赴任","a":"马怀素","c":["外牧资贤守，斯人奉帝俞。","淮南膺建隼，渭北暂分符。","坐叹烟波隔，行嗟物候殊。","何年升美课，回首北城隅。"]},{"id":"T01109","t":"和燕公岳州山城","a":"赵冬曦","c":["为吏恩犹旧，投沙惠此蒙。","江边悠尔处，泗上宛然同。","访道精言合，论经大义通。","鸣琴有真气，况已沐清风。"]},{"id":"T01110","t":"十月梅花书赠","a":"卢僎","c":["君不见巴乡气候与华别，年年十月梅花发。","上苑今应雪作花，宁知此地花为雪。","自从迁播落黔巴，三见江上开新花。","故园风花虚洛汭，穷峡凝雪度岁华。","花情纵似河阳好，客心倍伤边候早。","春候飒惊楼上梅，霜威未落江潭草。","江水侵天去不还，楼花覆帘空坐攀。","一向花前看白发，几回梦里忆红颜。","红颜白发云泥改，何异桑田移碧海。","却想华年故国时，唯余一片空心在。","空心吊影向谁陈，云台仙阁旧游人。","傥知巴树连冬发，应怜南国气长春。"]},{"id":"T01111","t":"赠皇甫侍御赴都八首 五","a":"元希声","c":["绰绰夫君，是膺柱下。","准绳有望，名器无假。","宠盖伯山，气雄公雅。","立朝正色，俟我能者。"]},{"id":"T01112","t":"奉和九月九日登慈恩寺浮屠应制","a":"赵彦昭","c":["出豫乘秋节，登高陟梵宫。","皇心满尘界，佛迹现虚空。","日月宜长寿，人天得大通。","喜闻题宝偈，受记莫由同。"]},{"id":"T01113","t":"陪幸长宁公主林亭","a":"萧至忠","c":["公主林亭地，清晨降玉舆。","画桥飞渡水，仙阁逈临虚。","新晴看蛱蝶，早夏摘芙蕖。","文酒娱游盛，忻叨侍从余。"]},{"id":"T01114","t":"岐王山亭","a":"张谔","c":["王家傍绿池，春色正相宜。","岂有楼台好，兼看草树奇。","石榴天上叶，椰子日南枝。","出入千门里，年年乐未移。"]},{"id":"T01115","t":"和陈校书省中玩雪","a":"包融","c":["芸阁朝来雪，飘飖正满空。","褰开明月下，校理落花中。","色向怀铅白，光因翰简融。","能令草玄者，回思入流风。"]},{"id":"T01116","t":"观搊筝","a":"王湾","c":["虚室有秦筝，筝新月复清。","弦多弄委曲，柱促语分明。","晓怨凝繁手，春娇入曼声。","近来唯此乐，传得美人情。"]},{"id":"T01117","t":"宿香山阁","a":"贺朝","c":["暝上春山阁，梯云宿半空。","轩窗闭潮海，枕席拂烟虹。","朱网防栖鸽，纱灯护夕虫。","一闻鸡唱晓，已见日曈曈。"]},{"id":"T01118","t":"丹阳行","a":"孙逖","c":["丹阳古郡洞庭阴，落日扁舟此路寻。","传是东南旧都处，金陵中断碧江深。","在昔风尘起，京都乱如毁。","双阙戎虏间，千门战场里。","传闻一马化为龙，南渡衣冠亦愿从。","石头横帝里，京口拒戎锋。","青枫林下回天跸，杜若洲前转国容。","都门不见河阳树，辇道唯闻建业钟。","中原悠悠几千里，欲扫欃枪未云已。","英雄倾夺何纷然，一盛一衰如逝川。","可怜宫观重江里，金镜相传三百年。","自从龙见圣人出，六合车书混为一。","昔年王气今何在，并向长安就尧日。","荆榛古木闭荒阡，共道繁华不复全。","赤县唯余江树月，黄图半入海人烟。","暮来山水登临遍，览古愁吟泪如霰。","唯有空城多白云，春风淡荡无人见。"]},{"id":"T01119","t":"青雀歌","a":"卢象","c":["啾啾青雀儿，飞来飞去仰天池。","逍遥饮啄安涯分，何假扶摇九万为。"]},{"id":"T01120","t":"嵩山十志十首 其五","a":"卢鸿一","c":["水攒冲兮石丛耸，焕云锦兮喷汹涌。","苔駮荦兮草夤缘，芳幂幂兮濑溅溅。","石攒丛兮云锦淙，波连珠兮文沓綘。","有洁冥者媚此幽，漱灵液兮乐天休，实获我心兮夫何求。"]},{"id":"T01121","t":"送王判官","a":"徐安贞","c":["明月开三峡，花源出五谿。","城池青壁里，烟火绿林西。","不畏王程促，惟愁仙路迷。","巴东下归櫂，莫待夜猨啼。"]},{"id":"T01122","t":"春日与王右丞过新昌里访吕逸人不遇","a":"裴迪","c":["恨不逢君出荷蓑，青松白屋更无他。","陶令五男曾不有，蒋生三径枉相过。","芙蓉曲沼春流满，薜荔成帷晚霭多。","闻说桃源好迷客，不如高卧眄庭柯。"]},{"id":"T01123","t":"寻庐山崔征君","a":"丘为","c":["日高鸡犬静，门掩向寒塘。","夜竹深茅宇，秋亭冷石床。","住山年已远，服药寿偏长。","虚弃浮生者，相逢益自伤。"]},{"id":"T01124","t":"夕次圃田店","a":"祖咏","c":["前路入郑郊，尚经百余里。","马烦时欲歇，客归程未已。","落日桑柘阴，遥村烟火起。","西还不遑宿，中夜渡泾水。"]},{"id":"T01125","t":"送章彝下第","a":"綦毋潜","c":["长安渭桥路，行客别时心。","献赋温泉毕，无媒魏阙深。","黄莺啼就马，白日暗归林。","三十名未立，君还惜寸阴。"]},{"id":"T01126","t":"咏陶渊明","a":"颜真卿","c":["张良思报韩，龚胜耻事新。","狙击不肯就，舍生悲缙绅。","呜呼陶渊明，奕叶为晋臣。","自以公相后，每怀宗国屯。","题诗庚子岁，自谓羲皇人。","手持山海经，头戴漉酒巾。","兴逐孤云外，心随还鸟泯。"]},{"id":"T01127","t":"江有枫一篇十章 五","a":"萧颖士","c":["粤东可居，彼吴之墟。","有田有庭，有朋有书。","有莼有鱼，君子居焉。","惟以宴醑，其乐徐徐。"]},{"id":"T01128","t":"颍阳东溪怀古","a":"崔曙","c":["灵溪氛雾歇，皎镜清心颜。","空色不映水，秋声多在山。","世人久疎旷，万物皆自闲。","白鹭寒更浴，孤云晴未还。","昔时让王者，此地闭玄关。","无以蹑高步，凄凉岑壑间。"]},{"id":"T01129","t":"湖上对酒行","a":"张谓","c":["夜坐不厌湖上月，昼行不厌湖上山。","眼前一尊又长满，心中万事如等闲。","主人有黍百余石，浊醪数斗应不惜。","即今相对不尽欢，别后相思复何益。","茱萸湾头归路赊，愿君且宿黄公家。","风光若此人不醉，参差辜负东园花。"]},{"id":"T01130","t":"艳女词","a":"梁锽","c":["露井桃花发，双双燕并飞。","美人姿态里，春色上罗衣。","自爱频开镜，时羞欲掩扉。","不知行路客，遥惹五香归。"]},{"id":"T01131","t":"送乌程王明府贬巴江","a":"包何","c":["一片孤帆无四邻，北风吹过五湖滨。","相看尽是江南客，独有君为岭外人。"]},{"id":"T01132","t":"韦使君宅海榴咏","a":"皇甫曾","c":["淮阳卧理有清风，腊月榴花带雪红。","闭阁寂寥常对此，江湖心在数枝中。"]},{"id":"T01133","t":"横吹曲辞 折杨柳","a":"李白","c":["垂杨拂绿水，摇艳东风年。","花明玉关雪，叶暖金窗烟。","美人结长恨，相对心凄然。","攀条折春色，远寄龙庭前。"]},{"id":"T01134","t":"横吹曲辞 前出塞九首 六","a":"杜甫","c":["挽弓当挽彊，用箭当用长。","射人先射马，擒贼先擒王。","杀人亦有限，列国自有疆。","苟能制侵陵，岂在多杀伤。"]},{"id":"T01135","t":"相和歌辞 班倢伃三首 二","a":"王维","c":["宫殿生秋草，君王恩幸疎。","那堪闻凤吹，门外度金舆。"]},{"id":"T01136","t":"相和歌辞 短歌行二首 二","a":"白居易","c":["世人求富贵，多为身嗜欲。","盛衰不自由，得失常相逐。","问君少年日，苦学将干禄。","负笈尘中游，抱书雪前宿。","布衾不周体，藜茄才充腹。","三十登宦途，五十被朝服。","奴温已挟纩，马肥初食粟。","未敢议欢游，尚为名检束。","耳目聋暗后，堂上调丝竹。","牙齿缺落时，盘中堆酒肉。","彼来此已去，外余中不足。","少壮与荣华，相避如寒燠。","青云去地远，白日终天速。","从古无奈何，短歌听一曲。"]},{"id":"T01137","t":"杂歌谣辞 李夫人歌 一","a":"李商隐","c":["一带不结心，两股方安髻。","慙愧白茅人，月没教星替。"]},{"id":"T01138","t":"相和歌辞 从军行 四","a":"王昌龄","c":["青海长云暗雪山，孤城遥望雁门关。","黄沙百战穿金甲，不破楼兰终不还。"]},{"id":"T01139","t":"湖中旅泊寄阎九司户防","a":"孟浩然","c":["桂水通百越，扁舟期晓发。","荆云蔽三巴，夕望不见家。","襄王梦行雨，才子谪长沙。","长沙饶瘴疠，胡为苦留滞。","久别思款颜，承欢怀接袂。","接袂杳无由，徒增旅泊愁。","清猿不可听，沿月下湘流。"]},{"id":"T01140","t":"鼓吹曲辞 凯歌六首 六","a":"岑参","c":["暮雨旌旗湿未干，胡尘白草日光寒。","昨日将军连晓战，蕃军只见马空鞍。"]},{"id":"T01141","t":"杂曲歌辞 蓟门行五首 五","a":"高适","c":["汉家能用武，开拓穷异域。","戍卒厌糠核，降胡饱衣食。","开亭试一望，吾欲涕沾臆。"]},{"id":"T01142","t":"相和歌辞 三阁词四首 四","a":"刘禹锡","c":["三人出眢井，一身登槛车。","朱门漫临水，不可见鲈鱼。"]},{"id":"T01143","t":"鼓吹曲辞 鼓吹铙歌 苞枿","a":"柳宗元","c":["苞枿𪒶矣，惟根之蟠。","弥巴蔽荆，负南极以安。","曰我旧梁氏，辑绥艰难。","江汉之阻，都邑固以完。","圣人作，神武用。","有臣勇智，奋不以众。","投迹死地，谋猷纵。","化敌为家，虑则中。","浩浩海裔，不威而同。","系缧降王，定厥功。","澶漫万里，宣唐风。","蛮夷九译，咸来从。","凯旋金奏，象形容。","震赫万国，罔不龚。"]},{"id":"T01144","t":"杂曲歌辞 三台二首 一","a":"韦应物","c":["一年一年老去，明日后日花开。","未报长安平定，万国岂得衔杯。"]},{"id":"T01145","t":"相和歌辞 决绝[词]三首 三","a":"元稹","c":["夜夜相抱眠，幽怀尚沈结。","那堪一年事，长遣一宵说。","但感久相思，何暇暂相悦。","虹桥薄夜成，龙驾侵晨列。","生憎野鹊往迟回，死恨天鸡识时节。","曙色渐曈昽，华星次明灭。","一去又一年，一年何时彻。","有此迢遰期，不如生死别。"]},{"id":"T01146","t":"琴曲歌辞 雉朝飞操","a":"韩愈","c":["雉之飞，于朝日。","群雌孤雄，意气横出。","当东而西，当啄而飞。","随飞随啄，群雌粥粥。","嗟我虽人，曾不如彼雉鸡。","生身七十年，无一妾与妃。"]},{"id":"T01147","t":"相和歌辞 江南曲","a":"李贺","c":["汀洲白苹草，柳恽乘马归。","江头樝树香，岸上蝴蝶飞。","酒杯若叶露，玉轸蜀桐虚。","朱楼通水陌，沙暖一双鱼。"]},{"id":"T01148","t":"相和歌辞 堂堂","a":"温庭筠","c":["钱塘岸上春如织，淼淼寒潮带晴色。","淮南游客马连嘶，碧草迷人归不得。","风飘客意如吹烟，纤指殷勤伤雁弦。","一曲堂堂红烛筵，金鲸泻酒如飞泉。"]},{"id":"T01149","t":"相和歌辞 从军行六首 四","a":"刘长卿","c":["目极雁门道，青青边草春。","一身事征战，匹马同辛勤。","末路成白首，功归天下人。"]},{"id":"T01150","t":"奉和圣制次成皐先圣擒建德之所","a":"张九龄","c":["天命诚有集，王业初惟艰。","翦商自文祖，夷项在兹山。","地识斩蛇处，河临饮马间。","威加昔运往，泽流今圣还。","尊祖颂先烈，赓歌安用攀。","绍成即我后，封岱出天关。"]},{"id":"T01151","t":"感遇诗三十八首 四","a":"陈子昂","c":["乐羊为魏将，食子殉军功。","骨肉且相薄，他人安得忠。","吾闻中山相，乃属放麑翁。","孤兽犹不忍，况以奉君终。"]},{"id":"T01152","t":"横吹曲辞 长安道","a":"孟郊","c":["胡风激秦树，贱子风中泣。","家家朱门开，得见不可入。","长安十二衢，投树鸟亦急。","高阁何人家？笙簧正喧吸。"]},{"id":"T01153","t":"太和 寿和","a":"贺知章","c":["惟以明发，有怀载殷。","乐盈而反，礼顺其禋。","立清以献，荐欲是亲。","於穆不已，裒对斯臻。"]},{"id":"T01154","t":"相和歌辞 江南曲","a":"张籍","c":["江南人家多橘树，吴姬舟上织白纻。","土地卑湿饶虫蛇，连木为牌入江住。","江村亥日长为市，落帆渡桥来浦里。","青莎覆城竹为屋，无井家家饮潮水。","长江午日酤春酒，高高酒旗悬江口。","倡楼两岸悬水栅，夜唱竹枝留北客。","江南风土欢乐多，悠悠处处尽经过。"]},{"id":"T01155","t":"相和歌辞 短歌行","a":"王建","c":["人初生，日初出。","上山迟，下山疾。","百年三万六千朝，夜里分将彊半日。","有歌有舞间早为，昨日健于今日时。","人家见生男女好，不知男女催人老。","短歌行，无乐声。"]},{"id":"T01156","t":"杂曲歌辞 天长地久词 三","a":"卢纶","c":["辞辇复当熊，倾心奉上宫。","君王若看貌，甘在众妃中。"]},{"id":"T01157","t":"杂曲歌辞 轻薄篇","a":"李益","c":["豪不必驰千骑，雄不在垂双鞬。","天生俊气自相逐，出与雕鹗同飞翻。","朝行九衢不得意，下鞭走马城西原。","忽闻燕雁一声去，回鞭挟弹平陵园。","归来青楼曲未半，美人玉色当金尊。","淮阴少年不相下，酒酣半笑倚市门。","安知我有不平色，白日欲顾红尘昏。","死生容易如反掌，得意失意由一言。","少年但饮莫相问，此中报讐亦报恩。"]},{"id":"T01158","t":"帝京篇十首 六","a":"太宗皇帝","c":["飞盖去芳园，兰桡游翠渚。","萍间日彩乱，荷处香风举。","桂楫满中川，弦歌振长屿。","岂必汾河曲，方为欢宴所。"]},{"id":"T01159","t":"谒慈恩寺题奘法师房","a":"高宗皇帝","c":["停轩观福殿，游目眺皇畿。","法轮含日转，花盖接云飞。","翠烟香绮阁，丹霞光宝衣。","幡虹遥合彩，定水迥分晖。","萧然登十地，自得会三归。"]},{"id":"T01160","t":"送李邕之任滑台","a":"明皇帝","c":["汉家重东郡，宛彼白马津。","黎庶既蕃殖，临之劳近臣。","远别初首路，今行方及春。","课成应第一，良牧尔当仁。"]},{"id":"T01161","t":"麟德殿宴百僚","a":"德宗皇帝","c":["忧勤承圣绪，开泰喜时康。","恭己临群后，垂衣御八荒。","务闲春向暮，朝罢日犹长。","紫殿初筵列，彤庭广乐张。","成功归辅弼，致理赖忠良。","共此欢娱事，千秋乐未央。"]},{"id":"T01162","t":"唐享昊天乐 第五","a":"则天皇后","c":["朝坛雾卷，曙岭烟沈。","爰设筐币，式表诚心。","筵辉丽璧，乐畅和音。","仰惟灵鉴，俯察翘襟。"]},{"id":"T01163","t":"驾幸新丰温泉宫献诗三首 二","a":"上官昭容","c":["鸾旗掣曳拂空回，羽骑骖驔蹑景来。","隐隐骊山云外耸，迢迢御帐日边开。"]},{"id":"T01164","t":"挽辞 一","a":"后主煜","c":["珠碎眼前珍，花凋世外春。","未销心里恨，又失掌中身。","玉笥犹残药，香匳已染尘。","前哀将后感，无泪可沾巾。"]},{"id":"T01165","t":"题彭州阳平化","a":"蜀太后徐氏","c":["寻真游胜境，巡礼到阳平。","水远波澜碧，山高气象清。","殿严孙氏貌，碑暗系师名。","夜月登坛醮，松风森磬声。"]},{"id":"T01166","t":"题彭州阳平化","a":"蜀太妃徐氏","c":["云浮翠辇届阳平，真似骖鸾到上清。","风起半厓闻虎啸，雨来当面见龙行。","晚寻水涧听松韵，夜上星坛看月明。","长恐前身居此境，玉皇教向锦城生。"]},{"id":"T01167","t":"郊庙歌辞 祀圜丘乐章 舒和","a":"褚亮","c":["叠璧凝影皇坛路，编珠流彩帝郊前。","已奏黄钟歌大吕，还符宝历祚昌年。"]},{"id":"T01168","t":"郊庙歌辞 封泰山乐章 豫和 六","a":"张说","c":["飨帝飨亲，维孝维圣。","缉熙懿德，敷扬成命。","华夷志同，笙镛礼盛。","明灵降止，感此诚敬。"]},{"id":"T01169","t":"郊庙歌辞 武后明堂乐章 配飨","a":"武则天","c":["笙镛间玉宇，文物昭清晖。","睟影临芳奠，休光下太微。","孝思期有感，明絜庶无违。"]},{"id":"T01170","t":"郊庙歌辞 五郊乐章 青帝角音 肃和","a":"魏征","c":["玄鸟司春，苍龙登岁。","节物变柳，光风转蕙。","瑶席降神，朱弦飨帝。","诚备祝嘏，礼殚珪币。"]},{"id":"T01171","t":"郊庙歌辞 祀雨师乐章 迎神","a":"包佶","c":["陟降左右，诚达幽圜。","作解之功，乐惟有年。","云𫐌戾止，洒雾飘烟。","惟馨展礼，爰列豆笾。"]},{"id":"T01172","t":"奉和圣制登蒲州逍遥楼应制","a":"苏颋","c":["在昔尧舜禹，遗尘成典谟。","圣皇东巡狩，况乃经此都。","楼观纷迤逦，河山几萦纡。","缅怀祖宗业，相继文武图。","尚德既无险，观风谅有孚。","岂如汾水上，箫鼓事游娱。"]},{"id":"T01173","t":"郊庙歌辞 禅社首乐章 福和","a":"贺知章、源乾曜","c":["穆穆天子，告成岱宗。","大裘如濡，执珽有颙。","乐以平志，礼以和容。","上帝临我，云胡肃邕。"]},{"id":"T01174","t":"夜渡江","a":"姚崇","c":["夜渚带浮烟，苍茫晦远天。","舟轻不觉动，缆急始知牵。","听草遥寻岸，闻香暗识莲。","唯看孤帆影，常似客心悬。"]},{"id":"T01175","t":"鼓吹曲辞 钓竿篇","a":"沈佺期","c":["朝日敛红烟，垂竿向绿川。","人疑天上坐，鱼似镜中悬。","避檝时惊透，猜钩每误牵。","湍危不理辖，潭静欲留船。","钓玉君徒尚，征金我未贤。","为看芳饵下，贪得会无全。"]},{"id":"T01176","t":"奉和人日重宴大明宫恩赐彩缕人胜应制","a":"崔日用","c":["新年宴乐坐东朝，钟鼓铿锽大乐调。","金屋瑶筐开宝胜，花笺彩笔颂春椒。","曲池苔色冰前液，上苑梅香雪里娇。","宸极此时飞圣藻，微臣窃抃预闻韶。"]},{"id":"T01177","t":"奉和春日游苑喜雨应诏","a":"李乂","c":["仙跸九成台，香筵万寿杯。","一旬初降雨，二月早闻雷。","叶向朝霁密，花含宿润开。","幸承天泽豫，无使日光催。"]},{"id":"T01178","t":"郊庙歌辞 享太庙乐章 大成舞","a":"魏征、褚亮","c":["周称王季，晋美帝文。","明明盛德，穆穆齐芬。","藏用四履，屈道三分。","铿锵钟石，载纪鸿勋。"]},{"id":"T01179","t":"郊庙歌辞 德明兴圣庙乐章 亚献终献","a":"李舒","c":["惟清惟肃，靡闻靡见。","举备九成，俛终三献。","庆彰曼寿，胙彻嘉荐。","瘗玉埋牲，礼神斯徧。"]},{"id":"T01180","t":"仪坤庙乐章 永和","a":"徐彦伯","c":["猗若清庙，肃肃荧荧。","国荐严祀，坤兴淑灵。","有几在室，有乐在庭。","临兹孝享，百禄惟宁。"]},{"id":"T01181","t":"早春鱼亭山","a":"薛稷","c":["春气动百草，纷荣时断续。","白云自高妙，裴回空山曲。","阳林花已红，寒涧苔未绿。","伊余息人事，萧寂无营欲。","客行虽云远，玩之聊自足。"]},{"id":"T01182","t":"饯许州宋司马赴任","a":"徐坚","c":["旧许星车转，神京祖帐开。","断烟伤别望，零雨送离杯。","辞燕依空遶，宾鸿入听哀。","分襟与秋气，日夕共悲哉。"]},{"id":"T01183","t":"琴曲歌辞 蔡氏五弄 游春曲二首 二","a":"王涯","c":["上苑何穷树，花开次第新。","香车与丝骑，风静亦生尘。"]},{"id":"T01184","t":"郊庙歌辞 梁郊祀乐章 庆和 六","a":"赵光逢、张衮","c":["天惟佑德，辟乃奉天。","交感斯在，昭事罔愆。","岁功已就，王道无偏。","于焉报本，是用告虔。"]},{"id":"T01185","t":"横吹曲辞 折杨柳","a":"卢照邻","c":["倡楼启曙扉，园柳正依依。","鸟鸣知岁隔，条变识春归。","露叶疑啼脸，风花乱舞衣。","攀折聊将寄，军中书信稀。"]},{"id":"T01186","t":"横吹曲辞 出塞曲 三","a":"僧贯休","c":["回首陇山头，连天草木秋。","圣君应入梦，半路遣封侯。","水不担阴雪，柴令倒戍楼。","归来麟阁上，春色满皇州。"]},{"id":"T01187","t":"相和歌辞 昭君词","a":"李端","c":["李陵初送子卿回，汉月明明照帐来。","忆著长安旧游处，千门万户玉楼台。"]},{"id":"T01188","t":"相和歌辞 野田黄雀行","a":"僧齐己","c":["双双野田雀，上下同饮啄。","暖去栖蓬蒿，寒归傍篱落。","殷勤避罗网，乍可遇雕鹗。","雕鹗虽不仁，分明在寥廓。"]},{"id":"T01189","t":"杂曲歌辞 秋夜长","a":"王勃","c":["秋夜长，殊未央。","月明白露澄清光，层城绮阁遥相望。","遥相望，川无梁。","北风受节鴈南翔，崇兰委质时菊芳。","鸣环曳履出长廊，为君秋夜捣衣裳。","纤罗对凤皇，丹绮双鸳鸯。","调砧乱杵思自伤，思自伤，征夫万里戍他乡。","鹤关音信断，龙门道路长。","所在天一方，寒衣徒自香。"]},{"id":"T01190","t":"赋终南山用风字韵应诏","a":"杨师道","c":["眷言怀隐逸，辍驾践幽丛。","白云飞夏雨，碧岭横春虹。","草绿长杨路，花疎五柞宫。","登临日将晚，兰桂起香风。"]},{"id":"T01191","t":"相和歌辞 从军行 一","a":"僧皎然","c":["候骑出纷纷，元戎霍冠军。","汉鞞秋聒地，羌火昼烧云。","万里戍城合，三边羽檄分。","乌孙驱未尽，肯顾辽阳勋。"]},{"id":"T01192","t":"琴曲歌辞 湘妃列女操","a":"鲍溶","c":["有虞夫人哭虞后，淑女何事又伤离。","竹上泪迹生不尽，寄哀云和五十丝。","云和经奏钧天曲，乍听宝琴遥嗣续。","三湘测测流急绿，秋夜露寒蜀帝飞。","枫林月斜楚臣宿，更疑川宫日黄昏。","暗携女手殷勤言，环佩玲珑有无间。","终疑既远双悄悄，苍梧旧云岂难召。","老猨心寒不可啸，目眄眄兮意蹉跎。"]},{"id":"T01193","t":"相和歌辞 雁门太守行","a":"张祜","c":["城头月没霜如水，趚趚蹋沙人似鬼。","灯前拭泪试香裘，长引一声残漏子。","驼囊泻酒酒一杯，前头啑血心不回。","寄语年少妻莫哀，鱼金虎竹天上来，雁门山边骨成灰。"]},{"id":"T01194","t":"相和歌辞 江南曲八首 五","a":"刘希夷","c":["舣舟乘潮去，风帆振草凉。","潮平见楚甸，天际望维扬。","洄溯经千里，烟波接两乡。","云明江屿出，日照海流长。","此中逢岁晏，浦树落花芳。"]},{"id":"T01195","t":"下山逢故夫","a":"乔知之","c":["妾身本薄命，轻弃城南隅。","庭前厌芍药，山上采蘼芜。","春风罥纨袖，零露湿罗襦。","羞将憔悴日，提笼逢故夫。"]},{"id":"T01196","t":"闰九月九日幸总持寺登浮图应制","a":"刘宪","c":["重阳登闰序，上界叶时巡。","驻辇天花落，开筵妓乐陈。","城端刹柱见，云表露盘新。","临睨光辉满，飞文动睿神。"]},{"id":"T01197","t":"冀北春望","a":"崔湜","c":["回首览燕赵，春生两河间。","旷然万里余，际海不见山。","雨歇青林润，烟空绿野闲。","问乡何处所，目送白云还。"]},{"id":"T01198","t":"南行别弟","a":"韦承庆","c":["澹澹长江水，悠悠远客情。","落花相与恨，到地一无声。"]},{"id":"T01199","t":"登东阳沈隐侯八咏楼","a":"崔融","c":["旦登西北楼，楼峻石墉厚。","宛生长定□，俯压三江口。","排阶衔鸟衡，交疏过牛斗。","左右会稽镇，出入具区薮。","越岩森其前，浙江漫其后。","此地实东阳，由来山水乡。","隐侯有遗咏，落简尚余芳。","具物昔未改，斯人今已亡。","粤余忝藩左，束髪事文场。","怅不见夫子，神期遥相望。"]},{"id":"T01200","t":"杂曲歌辞 行路难","a":"崔颢","c":["君不见建章宫中金明枝，万万长条拂地垂。","二月三月花如霰，九重幽深君不见。","艳彩朝含四宝宫，香风吹入朝云殿。","汉家宫女春未阑，爱此芳香朝暮看。","看去看来心不忘，攀折将安镜台上。","双双素手剪不成，两两红妆笑相向。","建章昨夜起春风，一花飞落长信宫。","长信丽人见花泣，忆此珍树何嗟及。","我昔初在昭阳时，朝折暮折登玉墀。","祗言岁岁长相对，不寤今朝遥相思。"]},{"id":"T01201","t":"相和歌辞 短歌行六首 五","a":"顾况","c":["临春风，听春鸟。","别时多，见时少。","愁人夜永不得眠，瑶井玉绳相向晓。"]},{"id":"T01202","t":"相和歌辞 杂怨三首 三","a":"聂夷中","c":["君泪濡罗巾，妾泪滴路尘。","罗巾今在手，日得随妾身。","路尘如因飞，得上君车轮。"]},{"id":"T01203","t":"杂曲歌辞 行路难","a":"薛能","c":["何处力堪殚？人心险万端。","藏山难测度，暗水自波澜。","对面如千里，回肠似七盘。","已经吴坂困，欲向鴈门难。","南北诚须泣，高深不可干。","无因善行止，车辙得平安。"]},{"id":"T01204","t":"夜饮东亭","a":"宋之问","c":["春泉鸣大壑，皓月吐层岑。","岑壑景色佳，慰我远游心。","暗芳足幽气，惊栖多众音。","高兴南山曲，长谣横素琴。"]},{"id":"T01205","t":"京中守岁","a":"丁仙芝","c":["守岁多然烛，通宵莫掩扉。","客愁当暗满，春色向明归。","玉斗巡初匝，银河落渐微。","开正献岁酒，千里间庭闱。"]},{"id":"T01206","t":"相和歌辞 江南曲 五","a":"陆龟蒙","c":["鱼戏莲叶北，澄阳动微涟。","回看帝子渚，稍背鄂君船。"]},{"id":"T01207","t":"今别离","a":"孟云卿","c":["结发生别离，相思复相保。","如何日已久，五变庭中草。","渺渺大海途，悠悠吴江岛。","但恐不出门，出门无远道。","远道行既难，家贫衣复单。","严风吹积雪，晨起鼻何酸。","人生各有志，岂不怀所安。","分明天上日，生死愿同欢。"]},{"id":"T01208","t":"相和歌辞 子夜冬歌","a":"崔国辅","c":["寂寥抱冬心，裁罗又褧褧。","夜久频挑灯，霜寒剪刀冷。"]},{"id":"T01209","t":"送楚十少府","a":"常建","c":["微风吹霜气，寒影明前除。","落日未能别，萧萧林木虚。","愁烟闭千里，仙尉其何如。","因送别鹤操，赠之双鲤鱼。","鲤鱼在金盘，别鹤哀有余。","心事则如此，请君开素书。"]},{"id":"T01210","t":"夏日游德州赠高四","a":"骆宾王","c":["日观邻全赵，星临俯旧吴。","鬲津开巨浸，稽阜镇名都。","紫云浮剑匣，青山孕宝符。","封疆恢霸道，问鼎竞雄图。","神光包四大，皇威震八区。","风烟通地轴，星象正天枢。","天枢限南北，地轴殊乡国。","辟门通舜宾，比屋封尧德。","言谢垂钩隐，来参负鼎职。","天子不见知，群公讵相识。","未展从东骏，空戢图南翼。","时命欲何言，抚膺长叹息。","叹息将如何，游人意气多。","白雪梁山曲，寒风易水歌。","泣魏伤吴起，思赵切廉颇。","凄断韩王剑，生死翟公罗。","罗悲翟公意，剑负韩王气。","骄饵去易论，忌途良可畏。","夙昔怀江海，平生混泾渭。","千载契风云，一言忘贱贵。","去去访林泉，空谷有遗贤。","言投爵里刺，来泛野人船。","缔交君赠缟，投分我忘筌。","成风郢匠斲，流水伯牙弦。","牙弦忘道术，漳滨恣闲逸。","聊安张蔚庐，讵扫陈蕃室。","虚室狎招寻，敬爱混浮沈。","一诺黄金信，三复白珪心。","霜松贞雅节，月桂朗冲襟。","灵台万顷濬，学府九流深。","谈玄明毁璧，拾紫陋籝金。","鹭涛开碧海，凤彩缀词林。","林虚星华映，水澈霞光净。","霞水两分红，川源四望通。","雾卷天山静，烟销太史空。","鸟声流向薄，蝶影乱芳丛。","柳阴低椠水，荷气上薰风。","风月芳菲节，物华纷可悦。","将欢促席赏，遽尔又归别。","积水带吴门，通波连禹穴。","赠言虽欲尽，机心庶应绝。","潘岳本自闲，梁鸿不因热。","一瓢欣狎道，三月聊栖拙。","栖拙隐金华，狎道访仙查。","放旷愚公谷，消散野人家。","一顷南山豆，五色东陵瓜。","野衣裁薜叶，山酒酌藤花。","白云离望远，青谿隐路赊。","傥忆幽岩桂，犹冀折疎麻。"]},{"id":"T01211","t":"奉和颍川公秋夜","a":"上官仪","c":["泬寥空色远，芸黄凄序变。","涸浦落遵鸿，长飙送巢燕。","千秋流夕景，万籁含宵唤。","峻雉聆金柝，层台切银箭。"]},{"id":"T01212","t":"守岁二首 二","a":"董思恭","c":["岁阴穷暮纪，献节启新芳。","冬尽今宵促，年开明日长。","冰销出镜水，梅散入风香。","对此欢终宴，倾壶待曙光。"]},{"id":"T01213","t":"相和歌辞 子夜四时歌六首 秋歌二首 一","a":"郭元振","c":["邀欢空伫立，望美频回顾。","何时复采菱？江中密相遇。"]},{"id":"T01214","t":"述韦昭应画犀牛","a":"储光羲","c":["遐方献文犀，万里随南金。","大邦柔远人，以之居山林。","食棘无秋冬，绝流无浅深。","双角前崭崭，三蹄下骎骎。","朝贤壮其容，未能辨其音。","有我衰鸟郎，新邑长鸣琴。","陛阁飞嘉声，丘甸盈仁心。","闲居命国工，作绘北堂阴。","眈眈若有神，庶比来仪禽。","昔有舞天庭，为君奏龙吟。"]},{"id":"T01215","t":"相和歌辞 从军行五首 五","a":"令狐楚","c":["暮雪连青海，阴云覆白山。","可怜班定远，出入玉门关。"]},{"id":"T01216","t":"杂曲歌辞 春游曲三首 二","a":"张仲素","c":["骋望登香阁，争高下砌台。","林间踏青去，席上意钱来。"]},{"id":"T01217","t":"咏水","a":"张文琮","c":["标名资上善，流派表灵长。","地图罗四渎，天文载五潢。","方流涵玉润，圆折动珠光。","独有蒙园吏，栖偃玩濠梁。"]},{"id":"T01218","t":"中宗降诞日长宁公主满月侍宴应制","a":"郑愔","c":["春殿猗兰美，仙阶柏树荣。","地逢芳节应，时覩圣人生。","月满增祥荚，天长发瑞灵。","南山遥可献，常愿奉皇明。"]},{"id":"T01219","t":"江上有怀","a":"王适","c":["湛湛江水见底清，荷花莲子傍江生。","采莲将欲寄同心，秋风落花空复情。","櫂歌数曲如有待，正见明月度东海。","海上云尽月苍苍，万里分辉满洛阳。","洛阳闺阁夜何央，蛾眉婵娟断人肠。","寂寥金屏空自掩，青荧银烛不生光。","应怜水宿洞庭子，今夕迢遥天一方。"]},{"id":"T01220","t":"二月闺情","a":"袁晖","c":["二月韶光好，春风香气多。","园中花巧笑，林里鸟能歌。","有恨离琴瑟，无情著绮罗。","更听春燕语，妾亦不如他。"]},{"id":"T01221","t":"琴曲歌辞 胡笳十八拍 第五拍","a":"刘商","c":["水头宿兮草头坐，风吹汉地衣裳破。","羊脂沐发长不梳，羔子皮裘领仍左。","狐襟貉袖腥复膻，昼披行兮夜披卧。","毡帐时移无定居，日月长兮不可过。"]},{"id":"T01222","t":"赠房侍御","a":"陶翰","c":["志士固不羁，与道常周旋。","进则天下仰，已之能晏然。","褐衣东府召，执简南台先。","雄义每特立，犯颜岂图全。","谪居东南远，逸气吟芳荃。","适会寥廓趣，清波更夤缘。","扁舟入五湖，发缆洞庭前。","浩荡临海曲，迢遥济江壖。","征奇忽忘返，遇兴将弥年。","乃悟范生智，足明渔父贤。","郡临新安渚，佳赏此城偏。","日夕对层岫，云霞映晴川。","闲居恋秋色，偃卧含贞坚。","倚伏聊自化，行藏互推迁。","君其振羽翮，岁晏将冲天。"]},{"id":"T01223","t":"相和歌辞 门有车马客行","a":"虞世南","c":["财雄重交结，戚里擅豪华。","曲台临上路，高门抵狭斜。","赭汗千金马，绣毂五香车。","白鹤随飞盖，朱鹭入鸣笳。","夏莲开劒水，春桃发露花。","轻裙染回雪，浮蚁泛流霞。","高谈辨飞兔，摛藻握灵蛇。","逢恩借羽翼，失路委泥沙。","暧暧风烟晚，路长归骑远。","日斜青琐第，尘飞金谷苑。","危弦促柱奏巴渝，遗簪堕珥解罗襦。","如何守直道，飜使谷名愚。"]},{"id":"T01224","t":"塞下曲","a":"李颀","c":["黄云雁门郡，日暮风沙里。","千骑黑貂裘，皆称羽林子。","金笳吹朔雪，铁马嘶云水。","帐下饮蒲萄，平生寸心是。"]},{"id":"T01225","t":"相和歌辞 苦哉行五首 五","a":"戎昱","c":["可汗奉亲诏，今月归燕山。","忽如乱刀劒，[搅]妾心肠间。","出户望北荒，迢迢玉门关。","生人为死别，有去无时还。","汉月割妾心，胡风凋妾颜。","去去断绝魂，叫天天不闻。"]},{"id":"T01226","t":"饮马长城窟行","a":"王翰","c":["长安少年无远图，一生惟羡执金吾。","麒麟前殿拜天子，走马西击长城胡。","胡沙猎猎吹人面，汉虏相逢不相见。","遥闻鼙鼓动地来，传道单于夜犹战。","此时顾恩宁顾身，为君一行摧万人。","壮士挥戈回白日，单于溅血染朱轮。","归来饮马长城窟，长城道傍多白骨。","问之耆老何代人，云是秦王筑城卒。","黄昏塞北无人烟，鬼哭啾啾声沸天。","无罪见诛功不赏，孤魂流落此城边。","当昔秦王按劒起，诸侯膝行不敢视。","富国强兵二十年，筑怨兴徭九千里。","秦王筑城何太愚，天实亡秦非北胡。","一朝祸起萧墙内，渭水咸阳不复都。"]},{"id":"T01227","t":"塞下曲","a":"薛奇童","c":["骄虏初南下，烟尘暗国中。","独召李将军，夜开甘泉宫。","一身许明主，万里总元戎。","霜甲卧不暖，夜半闻边风。","胡天早飞雪，荒徼多转蓬。","寒云覆水重，秋气连海空。","金鞍谁家子，上马鸣角弓。","自是幽幷客，非论爱立功。"]},{"id":"T01228","t":"过汉故城","a":"吴少微","c":["大汉昔未定，强秦犹擅场。","中原逐鹿罢，高祖郁龙骧。","经始谋帝座，兹焉壮未央。","规模窥栋宇，表里浚城隍。","群后崇长乐，中朝增建章。","句陈被兰锜，乐府奏芝房。","翡翠明珠帐，鸳鸯白玉堂。","清晨宝鼎食，闲夜郁金香。","天马来东道，佳人倾北方。","何其赫隆盛，自谓宝灵长。","历数有时尽，哀平嗟不昌。","冰坚成巨猾，火德遂颓纲。","奥位匪虚校，贪天竟速亡。","魂神吁社稷，豹虎鬬岩廊。","金狄移灞岸，铜盘向洛阳。","君王无处所，年代几荒凉。","宫阙谁家域，蓁芜罥我裳。","井田唯有草，海水变为桑。","昔在高门内，于今岐路傍。","余基不可识，古墓列成行。","狐兔惊魍魉，鸱鸟吓獝狂。","空城寒日晚，平野暮云黄。","烈烈樊青棘，萧萧吹白杨。","千秋幷万岁，空使咏歌伤。"]},{"id":"T01229","t":"杂诗六首 五","a":"李华","c":["孔光尊董贤，胡广惭李固。","儒风冠天下，而乃败王度。","绛侯与愽陆，忠朴受遗顾。","求名不考实，文弊反成蠹。"]},{"id":"T01230","t":"除夜乐城逢孟浩然","a":"张子容","c":["远客襄阳郡，来过海岸家。","樽开柏叶酒，灯发九枝花。","妙曲逢卢女，高才得孟嘉。","东山行乐意，非是竞繁华。"]},{"id":"T01231","t":"杂曲歌辞 起夜来","a":"施肩吾","c":["香销连理带，尘覆合欢杯。","嬾卧相思枕，愁吟起夜来。"]},{"id":"T01232","t":"三日曲水侍宴应制","a":"阎朝隐","c":["三月重三日，千春续万春。","圣泽如东海，天文似北辰。","荷叶珠盘净，莲花宝盖新。","陛下制万国，臣作水心人。"]},{"id":"T01233","t":"侍宴安乐公主新宅应制","a":"武平一","c":["紫汉秦楼敞，黄山鲁馆开。","簪裾分上席，歌舞列平台。","马既如龙至，人疑学凤来。","幸兹联棣萼，何以接邹枚。"]},{"id":"T01234","t":"渡汉江","a":"李百药","c":["东流既弥弥，南纪信滔滔。","水激沈碑岸，波骇弄珠皐。","含星映浅石，浮盖下奔涛。","溜阔霞光近，川长晓气高。","樯乌转轻翼，戏鸟落风毛。","客心既多绪，长歌且代劳。"]},{"id":"T01235","t":"蓬莱三殿侍宴奉敕咏终南山应制","a":"杜审言","c":["北斗挂城边，南山倚殿前。","云标金阙迥，树杪玉堂悬。","半岭通佳气，中峰绕瑞烟。","小臣持献寿，长此戴尧天。"]},{"id":"T01236","t":"少年行三首 三","a":"李嶷","c":["玉劒膝边横，金杯马上倾。","朝游茂陵道，夜宿凤凰城。","豪吏多猜忌，无劳问姓名。"]},{"id":"T01237","t":"杂曲歌辞 长安少年行十首 六","a":"李廓","c":["赏春惟逐胜，大宅可曾归。","不乐还逃席，多狂惯衩衣。","歌人踏月起，语燕卷帘飞。","好妇惟相妒，倡楼不醉稀。"]},{"id":"T01238","t":"杂曲歌辞 桃花行 五","a":"李峤","c":["红蕚竞妍春苑曙，粉茸新向御筵开。","长年愿奉西王宴，近侍慙无东朔才。"]},{"id":"T01239","t":"古意二首 一","a":"贺兰进明","c":["秦庭初指鹿，群盗满山东。","忤意皆诛死，所言谁肯忠。","武关犹未启，兵入望夷宫。","为祟非泾水，人君道自穷。"]},{"id":"T01240","t":"与卢员外象过崔处士兴宗林亭","a":"王缙","c":["身名不问十年余，老大谁能更读书。","林中独酌邻家酒，门外时闻长者车。"]},{"id":"T01241","t":"五日观妓","a":"万楚","c":["西施谩道浣春纱，碧玉今时鬬丽华。","眉黛夺将萱草色，红裙妬杀石榴花。","新歌一曲令人艳，醉舞双眸敛鬓斜。","谁道五丝能续命，却令今日死君家。"]},{"id":"T01242","t":"杂兴","a":"李嘉祐","c":["花间昔日黄鹂啭，妾向青楼已生怨。","花落黄鹂不复来，妾老君心亦应变。","君心比妾心，妾意旧来深。","一别十年无尺素，归时莫赠路傍金。"]},{"id":"T01243","t":"杂曲歌辞 昔昔盐 织锦窦家妻","a":"赵嘏","c":["当年谁不羡，分作窦家妻。","锦字行行苦，罗帷日日嗁。","岂知登陇远，祗恨下机迷。","直候阳关使，殷勤寄海西。"]},{"id":"T01244","t":"咏鹦鹉","a":"李义府","c":["牵弋辞重海，触网去层峦。","戢翼雕笼际，延思彩霞端。","慕侣朝声切，离群夜影寒。","能言殊可贵，相助忆长安。"]},{"id":"T01245","t":"杂曲歌辞 伊州 入破第一","a":"盖嘉运","c":["千门今夜晓初晴，万里天河彻帝京。","璨璨繁星驾秋色，棱棱霜气韵钟声。"]},{"id":"T01246","t":"上元夜六首 一","a":"崔液","c":["玉漏银壶且莫催，铁关金锁彻明开。","谁家见月能闲坐，何处闻灯不看来。"]},{"id":"T01247","t":"杂歌谣辞 步虚词 六","a":"韦渠牟","c":["静发降灵香，思神意智长。","虎存时促步，龙想更成章。","扣齿风雷响，挑灯日月光。","仙云在何处？髣髴满空堂。"]},{"id":"T01248","t":"初年","a":"陈叔达","c":["和风起天路，严气消冰井。","索索枝未柔，厌厌漏犹永。"]},{"id":"T01249","t":"奉和初春登楼即目应诏","a":"许敬宗","c":["旭日临重壁，天眷极中京。","春晖发芳甸，佳气满层城。","去鸟随看没，来云逐望生。","歌里非烟飏，琴上凯风清。","文波浮镂槛，摛景焕雕楹。","璇玑体宽政，隆栋象端衡。","创规虽有作，凝拱遂无营。","沐恩空改鬓，将何谢夏成。"]},{"id":"T01250","t":"古意六首 六","a":"王绩","c":["彩凤欲将归，提罗出郊访。","罗张大泽已，凤入重云飏。","朝栖昆阆木，夕饮蓬壶涨。","问凤那远飞，贤君坐相望。","凤言荷深德，微禽安足尚。","但使雏卵全，无令[矰]缴放。","皇臣力牧举，帝乐箫韶畅。","自有来巢时，明年阿阁上。"]},{"id":"T01251","t":"詶萧侍中春园听妓","a":"陈子良","c":["微雨散芳菲，中园照落晖。","红树摇歌扇，绿珠飘舞衣。","繁弦调对酒，杂引动思归。","愁人当此夕，羞见落花飞。"]},{"id":"T01252","t":"刘生","a":"杨炯","c":["卿家本六郡，年长入三秦。","白璧酬知己，黄金谢主人。","剑锋生赤电，马足起红尘。","日暮歌钟发，喧喧动四邻。"]},{"id":"T01253","t":"咏虹","a":"苏味道","c":["纡余带星渚，窈窕架天浔。","空因壮士见，还共美人沈。","逸照含良玉，神花藻瑞金。","独留长劒彩，终负昔贤心。"]},{"id":"T01254","t":"王昭君三首 一","a":"郭震","c":["自嫁单于国，长衔汉掖悲。","容颜日憔悴，有甚画图时。"]},{"id":"T01255","t":"奉和圣制春日幸望春宫应制","a":"韦元旦","c":["九重楼阁半山霞，四望韶阳春未赊。","侍跸妍歌临灞涘，留觞艳舞出京华。","危竿竞捧中街日，戏马争衔上苑花。","景色欢娱长若此，承恩不醉不还家。"]},{"id":"T01256","t":"奉和九日登慈恩寺浮图应制","a":"李适","c":["凤辇乘朝霁，鹦林对晚秋。","天文贝叶写，圣泽菊花浮。","塔似神功造，龛疑佛影留。","幸陪清汉跸，欣奉净居游。"]},{"id":"T01257","t":"奉和过梁王宅即目应制","a":"武三思","c":["岩居多水石，野宅满风烟。","本谓开三径，俄欣降九天。","穿林移步辇，拂岸转行旃。","凤竹初垂箨，龟河未吐莲。","愿持山作寿，恒用劫为年。"]},{"id":"T01258","t":"自汤还都经龙门北溪赠张左丞崔礼部崔光禄","a":"韦嗣立","c":["栖闲有愚谷，好事枉朝轩。","树接前驱拥，岩传后骑喧。","褰帘出野院，植杖候柴门。","既拂林下席，仍携池上樽。","深期契幽赏，实谓展欢言。","末眷诚未易，佳游时更敦。","俄看啸俦侣，各已共飞𬸣。","延睇尽朝日，长怀通夜魂。","空闻岸竹动，徒见浦花繁。","多愧春莺曲，相求意独存。"]},{"id":"T01259","t":"奉和立春游苑迎春应制","a":"卢藏用","c":["天游龙辇驻城𬮱，上苑迟光晚更新。","瑶台半入黄山路，玉槛傍临玄霸津。","梅香欲待歌前落，兰气先过酒上春。","幸预柏台称献寿，愿陪千亩及农晨。"]},{"id":"T01260","t":"奉和立春游苑迎春应制","a":"马怀素","c":["玄籥飞灰出洞房，青郊迎气肇初阳。","仙舆暂下宜春苑，御醴行开荐寿觞。","映水轻苔犹隐绿，缘堤弱柳未舒黄。","唯有裁花饰簪鬓，恒随圣藻狎年光。"]},{"id":"T01261","t":"和尹懋秋夜游㴩湖二首 一","a":"赵冬曦","c":["政理常多暇，方舟此溯洄。","吹笙虚洞荅，举楫便风催。","山暗云犹辨，潭幽月稍来。","清谿无数曲，未尽莫先回。"]},{"id":"T01262","t":"岁晚还京台望城阙成口号先赠交亲","a":"卢僎","c":["紫陌开行树，朱城出晚霞。","犹怜惯去国，疑是梦还家。","风弱知催柳，林青觉待花。","交亲望归骑，几处拥年华。"]},{"id":"T01263","t":"赠皇甫侍御赴都八首 六","a":"元希声","c":["载怀朋情，尝接闲宴。","好洽昆弟，官联州县。","如彼松竹，春荣冬蒨。","柯叶蔼然，不渝霜霰。"]},{"id":"T01264","t":"安乐公主移入新宅侍宴应制同用开字","a":"赵彦昭","c":["云物中京晓，天人外馆开。","飞桥象河汉，悬牓学蓬莱。","北阙临仙槛，南山送寿杯。","一窥轮奂毕，惭恧栋梁材。"]},{"id":"T01265","t":"陪幸五王宅","a":"萧至忠","c":["北斗枢机任，西京肺腑亲。","畴昔王门下，今兹制幸晨。","恩来山水被，圣作管弦新。","遶座薰红药，当轩暗绿筠。","摘荷才早夏，听鸟尚余春。","行漏金徒晓，风烟是观津。"]},{"id":"T01266","t":"岐王席上咏美人","a":"张谔","c":["半额画双蛾，盈盈烛下歌。","玉杯寒意少，金屋夜情多。","香艳王分帖，裙娇敕赐罗。","平阳莫相妬，唤出不如他。"]},{"id":"T01267","t":"和崔会稽咏王兵曹厅前涌泉势城中字","a":"包融","c":["茂德来征应，流泉入咏歌。","含灵符上善，作字表中和。","有草恒垂露，无风欲偃波。","为看人共水，清白定谁多。"]},{"id":"T01268","t":"晚春诣苏州敬赠武员外","a":"王湾","c":["苏台忆季常，飞櫂历江乡。","持此功曹掾，初离华省郎。","贵门生礼乐，明代秉文章。","嘉郡位先进，鸿儒名重扬。","爰从姻娅贬，岂失忠信防。","万里行骥足，十年暌凤翔。","回迁翊元圣，入拜伫惟良。","别业对南浦，群书满北堂。","意深投辖盛，才重接筵光。","陋学叨铅简，弱龄许翰场。","神驰劳旧国，颜展别殊方。","际晓杂氛散，残春众物芳。","烟和疎树满，雨续小谿长。","旅拙感成慰，通贤顾不忘。","从来琴曲罢，开匣为君张。"]},{"id":"T01269","t":"赠酒店胡姬","a":"贺朝","c":["胡姬春酒店，弦管夜锵锵。","红毾铺新月，貂裘坐薄霜。","玉盘初鲙鲤，金鼎正烹羊。","上客无劳散，听歌乐世娘。"]},{"id":"T01270","t":"山阴县西楼","a":"孙逖","c":["都邑西楼芳树间，逶迤霁色遶江山。","山月夜从公署出，江云晚对讼庭还。","谁知春色朝朝好，二月飞花满江草。","一见湖边杨柳风，遥忆青青洛阳道。"]},{"id":"T01271","t":"杂诗二首 一","a":"卢象","c":["家居五原上，征战是平生。","独负山西勇，谁当塞下名。","死生辽海战，雨雪蓟门行。","诸将封侯尽，论功独不成。"]},{"id":"T01272","t":"嵩山十志十首 其六","a":"卢鸿一","c":["霏微阴壑兮气腾虹，迤逦危磴兮上凌空。","青霞杪兮紫云垂，鸾歌凤舞兮吹参差。","鸾吹凤舞兮期仙磴，鸿驾迎兮瑶华赠。","山中人兮好神仙，想像闻此兮欲升烟，铸月炼液兮𥩟还年。"]},{"id":"T01273","t":"题襄阳图","a":"徐安贞","c":["画得襄阳郡，依然见昔游。","岘山思驻马，汉水忆回舟。","丹壑常含霁，青林不换秋。","图书空咫尺，千里意悠悠。"]},{"id":"T01274","t":"辋川集二十首 孟城坳","a":"裴迪","c":["结庐古城下，时登古城上。","古城非畴昔，今人自来往。"]},{"id":"T01275","t":"留别王维","a":"丘为","c":["归鞍白云外，缭绕出前山。","今日又明日，自知心不闲。","亲劳簪组送，欲趂莺花还。","一步一回首，迟迟向近关。"]},{"id":"T01276","t":"田家即事","a":"祖咏","c":["旧居东臯上，左右俯荒村。","樵路前傍岭，田家遥对门。","欢娱始披拂，惬意在郊原。","余霁荡川雾，新秋仍昼昏。","攀条憩林麓，引水开泉源。","稼穑岂云倦，桑麻今正繁。","方求静者赏，偶与潜夫论。","鸡黍何必具，吾心知道尊。"]},{"id":"T01277","t":"送崔员外黔中监选","a":"綦毋潜","c":["持衡出帝畿，星指夜郎飞。","神女云迎马，荆门雨湿衣。","听猿收泪罢，系鴈待书稀。","蛮貊虽殊俗，知君肝胆微。"]},{"id":"T01278","t":"三言拟五杂组二首 一","a":"颜真卿","c":["五杂组，绣与锦。","往复还，兴又寝。","不得已，病伏枕。"]},{"id":"T01279","t":"江有枫一篇十章 六","a":"萧颖士","c":["我朋在矣，彼陆之子。","如松如杞，淑问不已。"]},{"id":"T01280","t":"早发交崖山还太室作","a":"崔曙","c":["东林气微白，寒鸟急高翔。","吾亦自兹去，北山归草堂。","仲冬正三五，日月遥相望。","萧萧过颍上，昽昽辨少阳。","川冰生积雪，野火出枯桑。","独往路难尽，穷阴人易伤。","伤此无衣客，如何蒙雪霜。"]},{"id":"T01281","t":"赠乔琳","a":"张谓","c":["去年上策不见收，今年寄食仍淹留。","羡君有酒能便醉，羡君无钱能不忧。","如今五侯不爱客，羡君不问五侯宅。","如今七贵方自尊，羡君不过七贵门。","丈夫会应有知己，世上悠悠何足论。"]},{"id":"T01282","t":"狷氏子","a":"梁锽","c":["杏梁初照日，碧玉后堂开。","忆事临妆笑，春娇满镜台。","含声歌扉举，顾影舞腰回。","别有佳期处，青楼客夜来。"]},{"id":"T01283","t":"同舍弟佶班韦二员外秋苔对之成咏","a":"包何","c":["每看苔藓色，如向簿书闲。","幽思缠芳树，高情寄远山。","雨痕连地绿，日色出林斑。","却笑兴公赋，临危滑石间。"]},{"id":"T01284","t":"送普上人还阳羡","a":"皇甫曾","c":["花宫难久别，道者忆千灯。","残雪入林路，暮山归寺僧。","日光依嫩草，泉响滴春冰。","何用求方便，看心是一乘。"]},{"id":"T01285","t":"横吹曲辞 洛阳陌","a":"李白","c":["白玉谁家郎，回车渡天津。","看花东上陌，惊动洛阳人。"]},{"id":"T01286","t":"横吹曲辞 前出塞九首 七","a":"杜甫","c":["驱马天雨雪，军行入高山。","迳危抱寒石，指落曾冰间。","已去汉月远，何时筑城还？","浮云暮南征，可望不可攀。"]},{"id":"T01287","t":"相和歌辞 班倢伃三首 三","a":"王维","c":["怪来妆阁闭，朝下不相迎。","总向春园里，花间语笑声。"]},{"id":"T01288","t":"相和歌辞 反白头吟","a":"白居易","c":["炎炎者烈火，营营者小蝇。","火不热真玉，蝇不点清冰。","此苟无所受，彼莫能相仍。","乃知物性中，各有能不能。","古称怨报死，则人有所惩。","惩淫或应可，在道未为弘。","譬如蜩鷃徒，啾啾啅龙鹏。","宜当委之去，寥廓高飞腾。","岂能泥尘下，区区酬怨憎。","胡为作自苦，吞悲仍抚膺。"]},{"id":"T01289","t":"杂歌谣辞 李夫人歌 二","a":"李商隐","c":["剩结茱萸枝，多擘秋莲的。","独自有波光，彩囊盛不得。"]},{"id":"T01290","t":"相和歌辞 放歌行","a":"王昌龄","c":["南渡洛阳津，西望十二楼。","明堂坐天子，月朔朝诸侯。","清乐动千门，皇风被九州。","庆云从东来，泱漭抱日流。","升平贵论道，文墨将何求。","有诏征草泽，微臣献谋猷。","冠冕如星罗，拜揖曹与周。","望尘非吾事，入赋且迟留。","幸蒙国士识，因脱负薪裘。","今者放歌行，以慰梁父愁。","但营数斗禄，奉养毋丰羞。","若得金膏遂，飞云亦可俦。"]},{"id":"T01291","t":"大堤行寄万七","a":"孟浩然","c":["大堤行乐处，车马相驰突。","岁岁春草生，踏青二三月。","王孙挟珠弹，游女矜罗袜。","携手今莫同，江花为谁发。"]},{"id":"T01292","t":"相和歌辞 长门怨","a":"岑参","c":["君王嫌妾妬，闭妾在长门。","舞袖垂新宠，愁眉结旧恩。","绿钱生履迹，红粉湿啼痕。","羞被桃花笑，看春独不言。"]},{"id":"T01293","t":"杂曲歌辞 邯郸少年行","a":"高适","c":["邯郸城南游侠子，自矜生长邯郸里。","千场纵博家仍富，几度报讐身不死。","宅中歌笑日纷纷，门外车马如云屯。","未知肝胆向谁是，令人却忆平原君。","君不见今人交态薄，黄金用尽还疎索。","以兹感激辞旧游，更于时事无所求。","且与少年饮美酒，往来射猎西山头。"]},{"id":"T01294","t":"相和歌辞 贾客词","a":"刘禹锡","c":["贾客无定游，所游惟利幷。","眩俗杂良苦，乘时知重轻。","心计析秋毫，摇钩侔悬衡。","锥刀既无弃，转化日已盈。","邀福祷波神，施财游化城。","妻约雕金钏，女垂贯珠缨。","高赀比封君，奇货通幸卿。","趋时鸷鸟思，藏镪盘龙形。","大艑浮通川，高楼次旗亭。","行止皆有乐，关梁似无征。","农夫何为者？辛苦事寒耕。"]},{"id":"T01295","t":"鼓吹曲辞 鼓吹铙歌 河右平","a":"柳宗元","c":["河右澶漫，顽为之魁。","王师如雷震，昆仑以颓。","上聋下聪，骜不可回。","助雠抗有德，惟人之灾。","乃溃乃奋，执缚归厥命。","万室蒙其仁，一夫则病。","濡以鸿泽，皇之圣。","威畏德怀，功以定。","顺之于理，物咸遂厥性。"]},{"id":"T01296","t":"杂曲歌辞 三台二首 二","a":"韦应物","c":["冰泮寒塘始绿，雨余百草皆生。","朝来门合无事，晚下高斋有情。"]},{"id":"T01297","t":"相和歌辞 估客乐","a":"元稹","c":["估客无住著，有利身即行。","出门求火伴，入户辞父兄。","父兄相教示，求利莫求名。","求名有所避，求利无不营。","火伴相勒缚，卖假莫卖诚。","交关少交假，交假本生轻。","自兹相将去，誓死意不更。","一解市头语，便无乡里情。","𨱎石打臂钏，糯米炊项璎。","归来村中卖，敲作金玉声。","村中田舍娘，贵贱不敢争。","所费百钱本，已得十倍赢。","颜色转光净，饮食亦甘馨。","子本频蕃息，货赂日兼幷。","求珠驾沧海，采玉上荆衡。","北买党项马，西擒吐蕃鹦。","炎洲布火浣，蜀地锦织成。","越婢脂肉滑，奚僮眉眼明。","通算衣食费，不计远近程。","经营天下徧，却到长安城。","城中东西市，闻客次第迎。","迎客兼说客，多财为势倾。","客心本明黠，闻语心已惊。","先问十常侍，次求百公卿。","侯家与主第，点缀无不精。","归来始安坐，富与王家勍。","市卒酒肉臭，县胥家舍成。","岂惟绝言语，奔走极使令。","大儿贩材木，巧识梁栋形。","小儿贩盐卤，不入州县征。","一身偃市利，突若截海鲸。","钩距不敢下，下则牙齿横。","生为估客乐，判尔乐一生。"]},{"id":"T01298","t":"琴曲歌辞 猗兰操","a":"韩愈","c":["兰之猗猗，扬扬其香。","不采而佩，于兰何伤。","今天之旋，其曷为然。","我行四方，以日以年。","雪霜贸贸，荠麦之茂。","子如不伤，我不尔觏。","荠麦之茂，荠麦之有。","君子之伤，君子之守。"]},{"id":"T01299","t":"相和歌辞 日出行","a":"李贺","c":["白日下崐崘，发光如舒丝。","徒照葵藿心，不照游子悲。","折折黄河曲，日从中央转。","旸谷耳曾闻，若木眼不见。","奈何铄石，胡为销人。","羿弯弓属矢那不中，足令久不得奔，讵教晨光夕昏。"]},{"id":"T01300","t":"相和歌辞 三洲歌","a":"温庭筠","c":["团圆莫作波中月，洁白莫为枝上雪。","月随波动碎潾潾，雪似梅花不堪折。","李娘十六青丝发，画带双花为君结。","门前有路轻离别，惟恐归来旧香灭。"]},{"id":"T01301","t":"相和歌辞 从军行六首 五","a":"刘长卿","c":["倚劒白日暮，望乡登戍楼。","北风吹羌笛，此夜关山愁。","回首不无意，滹河空自流。"]},{"id":"T01302","t":"奉和圣制赐诸州刺史以题座右","a":"张九龄","c":["圣人合天德，洪覆在元元。","每劳苍生念，不以黄屋尊。","兴化俟群辟，择贤守列藩。","得人此为盛，咨岳今复存。","降鉴引君道，殷勤启政门。","容光无不照，有象必为言。","成宪知所奉，致理归其根。","肃肃禀玄猷，煌煌戒朱轩。","岂徒任遇重，兼尔宴锡繁。","载闻励臣节，持答明主恩。"]},{"id":"T01303","t":"感遇诗三十八首 五","a":"陈子昂","c":["市人矜巧智，于道若童蒙。","倾夺相夸侈，不知身所终。","曷见玄真子，观世玉壶中。","窅然遗天地，乘化入无穷。"]},{"id":"T01304","t":"相和歌辞 怨诗","a":"孟郊","c":["试妾与君泪，两处滴池水。","看取芙蓉花，今年为谁死。"]},{"id":"T01305","t":"太和 福和","a":"贺知章","c":["穆穆天子，告成岱宗。","大裘如濡，执珽有颙。","乐以平志，礼以和容。","上帝临我，云胡肃邕。"]},{"id":"T01306","t":"相和歌辞 楚妃叹","a":"张籍","c":["湘云初起江沈沈，君王遥在云梦林。","江南雨多旌旗暗，台下朝朝春水深。","章华殿前朝万国，君心独自终无极。","楚兵满地能逐禽，谁用一身继筋力。","西江若飜云梦中，麋鹿死尽应还宫。"]},{"id":"T01307","t":"相和歌辞 从军行","a":"王建","c":["汉军逐单于，日没处河曲。","浮云道傍起，行子车下宿。","枪城围鼓角，氊帐依山谷。","马上悬壶浆，刀头分顿肉。","来时高堂上，父母亲结束。","回首不见家，风吹破衣服。","金创生肢节，相与拔箭镞。","闻道西凉州，家家妇人哭。"]},{"id":"T01308","t":"杂曲歌辞 天长地久词 四","a":"卢纶","c":["云日呈祥礼物殊，北庭生献五单于。","塞天万里无飞鸟，可在边城用郅都。"]},{"id":"T01309","t":"杂曲歌辞 游子吟","a":"李益","c":["女羞夫壻荡，客耻主人贱。","遭遇同众流，低回愧相见。","君非青铜镜，何事空照面？","莫以衣上尘，不谓心如练。","人生当荣盛，待士勿言倦。","君看白日驰，何异弦上箭。"]},{"id":"T01310","t":"横吹曲辞 紫骝马","a":"李白","c":["紫骝行且嘶，双飜碧玉蹄。","临流不肎渡，似惜锦障泥。","白雪关山远，黄云海树迷。","挥鞭万里去，安得念春闺。"]},{"id":"T01311","t":"横吹曲辞 前出塞九首 八","a":"杜甫","c":["单于寇我垒，百里风尘昏。","雄劒四五动，彼军为我奔。","虏其名王归，系颈授辕门。","潜身备行列，一胜何足论。"]},{"id":"T01312","t":"相和歌辞 祠渔山神女歌 迎神","a":"王维","c":["坎坎击鼓，渔山之下。","吹洞箫，望极浦。","女巫进，纷屡舞。","陈瑶席，湛清酤。","风凄凄，又夜雨。","不知神之来兮不来，使我心兮苦复苦。"]},{"id":"T01313","t":"相和歌辞 怨诗","a":"白居易","c":["夺宠心那惯，寻思倚殿门。","不知移旧爱，何处作新恩。"]},{"id":"T01314","t":"杂歌谣辞 李夫人歌 三","a":"李商隐","c":["蛮丝系条脱，妍眼和香屑。","寿宫不惜铸南人，柔肠早被秋波割。","清澄有余幽素香，鳏鱼渴凤真珠房。","不知瘦骨类冰井，更许夜帘通晓霜。","土花漠碧云[茫茫]，黄河欲尽天苍黄。"]},{"id":"T01315","t":"相和歌辞 长信怨 一","a":"王昌龄","c":["金井梧桐秋叶黄，珠帘不卷夜来霜。","金炉玉枕无颜色，卧听南宫清漏长。"]},{"id":"T01316","t":"仲夏归汉南园寄京邑耆旧","a":"孟浩然","c":["尝读高士传，最嘉陶征君。","日耽田园趣，自谓羲皇人。","予复何为者，栖栖徒问津。","中年废丘壑，上国旅风尘。","忠欲事明主，孝思侍老亲。","归来当炎夏，耕稼不及春。","扇枕北窗下，采芝南涧滨。","因声谢同列，吾慕颍阳真。"]},{"id":"T01317","t":"北庭西郊候封大夫受降回军献上","a":"岑参","c":["胡地苜蓿美，轮台征马肥。","大夫讨匈奴，前月西出师。","甲兵未得战，降虏来如归。","橐𫘞何连连，穹帐亦累累。","阴山烽火灭，劒水羽书稀。","却笑霍嫖姚，区区徒尔为。","西郊候中军，平沙悬落晖。","驿马从西来，双节夹路驰。","喜鹊捧金印，蛟龙盘画旗。","如公未四十，富贵能及时。","直上排青云，傍看疾若飞。","前年斩楼兰，去岁平月支。","天子日殊宠，朝廷方见推。","何幸一书生，忽蒙国士知。","侧身佐戎幕，敛袵事边陲。","自逐定远侯，亦著短后衣。","近来能走马，不弱幷州儿。"]},{"id":"T01318","t":"杂曲歌辞 行路难二首 一","a":"高适","c":["君不见富家翁，昔时贫贱谁比数。","一朝金多结豪贵，万事胜人健如虎。","子孙成长满眼前，妻能管弦妾能舞。","自矜一朝忽如此，却笑傍人独悲苦。","东邻少年安所如，席门穷巷出无车。"]},{"id":"T01319","t":"相和歌辞 采菱行","a":"刘禹锡","c":["白马湖平秋日光，紫菱如锦彩鸾翔。","荡舟游女满中央，采菱不顾马上郎。","争多逐胜纷相向，时转兰桡破轻浪。","长鬟弱袂动参差，钗影钏文浮荡漾。","笑语哇咬顾晚晖，蓼花绿岸扣舷归。","归来共到市桥步，野蔓系船萍满衣。","家家竹楼临广陌，下有连樯多估客。","携觞荐芰夜经过，醉踏大堤相应歌。","屈平祠下沅江水，月照寒波白烟起。","一曲南音此地闻，长安北望三千里。"]},{"id":"T01320","t":"鼓吹曲辞 鼓吹铙歌 铁山碎","a":"柳宗元","c":["铁山碎，大漠舒。","二虏劲，连穹庐。","背北海，专坤隅。","岁来侵边，或傅于都。","天子命元帅，奋其雄图。","破定襄，降魁渠。","穷竟窟宅，斥余吾。","百蛮破胆，边氓苏。","威武辉耀，明鬼区。","利泽弥万祀，功不可逾。","官臣拜手，惟帝之谟。"]},{"id":"T01321","t":"杂曲歌辞 上皇三台","a":"韦应物","c":["不寐倦长更，披衣出户行。","月寒秋竹冷，风切夜窗声。"]},{"id":"T01322","t":"舞曲歌辞 冬白纻歌","a":"元稹","c":["吴宫夜长宫漏款，帘幕四垂灯焰暖。","西施自舞王自管，雪纻翻翻鹤翎散。","促节牵繁舞腰嬾，舞腰嬾，王罢饮。","盖覆西施凤花锦，身作匡床臂为枕。","朝佩𪭢𪭢王晏寝，酒醒阍报门无事。","子胥死后言为讳，近王之臣谕王意。","共笑越王穷惴惴，夜夜抱冰寒不睡。"]},{"id":"T01323","t":"琴曲歌辞 将归操","a":"韩愈","c":["秋之水兮其色幽幽，我将济兮不得其由。","涉其浅兮石啮我足，乘其深兮龙入我舟，我济而悔兮将安归尤？","归乎归乎，无与石鬬兮无应龙求。"]},{"id":"T01324","t":"相和歌辞 蜀国弦","a":"李贺","c":["枫香晚华静，锦水南山影。","惊石坠猨哀，竹云愁半岭。","凉月生秋浦，玉沙鳞鳞光。","谁家红泪客，不忍过瞿塘。"]},{"id":"T01325","t":"相和歌辞 常林欢","a":"温庭筠","c":["宜城酒熟花覆桥，沙晴绿鸭鸣咬咬。","秾桑绕舍麦如尾，幽轧鸣机双燕巢。","马声特特荆门道，蛮水扬光色如草。","锦荐金炉梦正长，东家呃喔鸡鸣早。"]},{"id":"T01326","t":"相和歌辞 从军行六首 六","a":"刘长卿","c":["黄沙一万里，白首无人怜。","报国劒已折，归乡身幸全。","单于古台下，边色寒苍然。"]},{"id":"T01327","t":"奉和圣制送十道采访使及朝集使","a":"张九龄","c":["三年一上计，万国趋河洛。","课最力已陈，赏延恩复博。","垂衣深共理，改瑟其咸若。","首路回竹符，分镳扬木铎。","戒程有攸往，诏饯无淹泊。","昭晰动天文，殷勤在人瘼。","持久望兹念，克终期所托。","行矣当自强，春耕庶秋获。"]},{"id":"T01328","t":"感遇诗三十八首 六","a":"陈子昂","c":["吾观龙变化，乃知至阳精。","石林何冥密，幽洞无留行。","古之得仙道，信与元化幷。","玄感非象识，谁能测沈冥。","世人拘目见，酣酒笑丹经。","昆仑有瑶树，安得采其英。"]},{"id":"T01329","t":"相和歌辞 杂怨三首 一","a":"孟郊","c":["夭桃花清晨，游女红粉新。","夭桃花薄暮，游女红粉故。","树有百年花，人无一定颜。","花送人老尽，人悲花自闲。"]},{"id":"T01330","t":"太和 太和","a":"贺知章","c":["昭昭有唐，天俾万国。","列祖应命，四宗顺则。","申锡无疆，宗我同德。","曾孙继绪，享神配极。"]},{"id":"T01331","t":"相和歌辞 楚妃怨","a":"张籍","c":["梧桐叶下黄金井，横架辘轳牵素绠。","美人初起天未明，手拂银缾秋水冷。"]},{"id":"T01332","t":"相和歌辞 饮马长城窟行","a":"王建","c":["长城窟，长城窟边多马骨。","古来此地无井泉，赖得秦家筑城卒。","征人饮马愁不回，长城变作望乡堆。","蹄迹未干人去近，续后马来泥污尽。","枕弓睡著待水生，不见阴山在前阵。","马蹄足脱装马头，健儿战死谁封侯。"]},{"id":"T01333","t":"杂曲歌辞 天长地久词 五","a":"卢纶","c":["台殿云凉风日微，君王初赐六宫衣。","楼船罢泛归犹早，行道才人鬬射飞。"]},{"id":"T01334","t":"杂曲歌辞 古别离","a":"李益","c":["双劒欲别风凄然，雌沈水底雄上天。","江回汉转两不见，云交雨合知何年。","古来万事皆由命，何用临岐苦涕涟。"]},{"id":"T01335","t":"横吹曲辞 幽州胡马客歌","a":"李白","c":["幽州胡马客，绿眼虎皮冠。","笑拂两只箭，万人不可干。","弯弓若转月，白雁落云端。","双双掉鞭行，游猎向楼兰。","出门不顾后，报国死何难。","天骄五单于，狼戾好凶残。","牛马散北海，割鲜若虎餐。","虽居燕支山，不道朔雪寒。","妇女马上笑，颜如赪玉盘。","飜入射鸟兽，花月醉雕鞍。","旄头四光芒，争战若蜂攒。","白刃洒赤血，流沙为之丹。","名将古谁是，疲兵良可叹。","何时天狼灭？父子得闲安。"]},{"id":"T01336","t":"横吹曲辞 前出塞九首 九","a":"杜甫","c":["从军十年余，能无分寸功。","众人贵苟得，欲语羞雷同。","中原有鬬争，况在狄与戎。","丈夫四方志，安可辞固穷。"]},{"id":"T01337","t":"相和歌辞 祠渔山神女歌 送神","a":"王维","c":["纷进舞兮堂前，目眷眷兮琼筵。","来不言兮意不传，作暮雨兮愁空山。","悲急管兮思繁弦，神之驾兮俨欲旋。","倏云收兮雨歇，山青青兮水潺湲。"]},{"id":"T01338","t":"相和歌辞 乌夜啼","a":"白居易","c":["城上归时晚，庭前宿处危。","月明无叶树，霜滑有风枝。","啼涩饥喉咽，飞低冻翅垂。","画堂鹦鹉鸟，冷暖不相知。"]},{"id":"T01339","t":"相和歌辞 采莲曲三首 一","a":"王昌龄","c":["吴姬越艳楚王妃，争弄莲舟水湿衣。","来时浦口花迎入，采罢江头月送归。"]},{"id":"T01340","t":"题云门山寄越府包户曹徐起居","a":"孟浩然","c":["我行适诸越，梦寐怀所欢。","久负独往愿，今来恣游盘。","台岭践磴石，耶溪溯林湍。","舍舟入香界，登阁憩旃檀。","晴山秦望近，春水镜湖宽。","远怀伫应接，卑位徒劳安。","白云日夕滞，沧海去来观。","故国眇天末，良朋在朝端。"]},{"id":"T01341","t":"初至西虢官舍南池呈左右省及南宫诸故人","a":"岑参","c":["黜官自西掖，待罪临下阳。","空积犬马恋，岂思鹓鹭行。","素多江湖意，偶佐山水乡。","满院池月静，卷帘溪雨凉。","轩窓竹翠湿，案牍荷花香。","白鸟上衣桁，青苔生笔床。","数公不可见，一别尽相忘。","敢恨青琐客，无情华省郎。","早年迷进退，晚节悟行藏。","他日能相访，嵩南旧草堂。"]},{"id":"T01342","t":"杂曲歌辞 行路难二首 二","a":"高适","c":["长安少年不少钱，能骑骏马鸣金鞭。","五侯相逢大道边，美人弦管争留连。","黄金如斗不敢惜，片言如山莫弃捐。","安知顦顇读书者，暮宿虚台私自怜。"]},{"id":"T01343","t":"琴曲歌辞 秋风引","a":"刘禹锡","c":["何处秋风至？萧萧送鴈群。","朝来入庭树，孤客最先闻。"]},{"id":"T01344","t":"鼓吹曲辞 鼓吹铙歌 靖本邦","a":"柳宗元","c":["本邦伊晋，惟时不靖。","根柢之摇，枝叶攸病。","守臣不任，勚于神圣。","惟钺之兴，翦焉则定。","洪惟我理，式和以敬。","群顽既夷，庶绩咸正。","皇谟载大，惟人之庆。"]},{"id":"T01345","t":"杂曲歌辞 突厥三台","a":"韦应物","c":["鴈门山上鴈初飞，马邑阑中马正肥。","日旰山西逢驿使，殷勤南北送征衣。"]},{"id":"T01346","t":"杂曲歌辞 出门行","a":"元稹","c":["兄弟同出门，同行不同志。","凄凄分岐路，各各营所为。","兄上荆山巅，翻石辨虹气。","弟沈沧海底，偷珠待龙睡。","出门不数年，同归亦同遂。","俱用私所珍，升沈自兹异。","献珠龙王宫，值龙觅珠次。","但喜复得珠，不求珠所自。","酬客双龙女，授客六龙辔。","遣充行雨神，雨泽随客意。","雩夏钟鼓繁，禜秋玉帛积。","彩色画廊庙，奴僮被珠翠。","骥𫘧千万双，鸳鸯七十二。","言者禾稼枯，无人敢轻议。","其兄因献璞，再刖不履地。","门户亲戚疎，匡床妻妾弃。","铭心有所待，视足无所愧。","持璞自枕头，泪痕双血渍。","一朝龙醒寤，本问偷珠事。","因知行雨偏，妻子五刑备。","仁兄捧尸哭，势友掉头讳。","丧车黔首葬，吊客青蝇至。","楚有望气人，王前忽长跪。","贺王得贵宝，不远王所莅。","求之果如言，剖则浮云腻。","白珩无颜色，垂棘有瑕累。","在楚列地封，入赵连城贵。","秦遣李斯书，书为传国瑞。","秦亡汉魏传，传者得神器。","卞和名永永，与宝不相坠。","劝尔出门行，行难莫行易。","易得还易失，难同亦难离。","善贾识贪廉，良田无稙穉。","磨劒莫磨锥，磨锥成小利。"]},{"id":"T01347","t":"琴曲歌辞 龟山操","a":"韩愈","c":["龟之气兮不能云雨，龟之枿兮不中梁柱，龟之大兮祗以奄鲁。","知将隳兮哀莫余伍，周公有鬼兮嗟余归辅。"]},{"id":"T01348","t":"相和歌辞 铜雀妓","a":"李贺","c":["佳人一壶酒，秋容满千里。","石马卧新烟，忧来何所似？","歌声且潜弄，陵树风自起。","长裾压高台，泪眼看花机。"]},{"id":"T01349","t":"相和歌辞 张静婉采莲曲","a":"温庭筠","c":["兰膏坠发红玉春，燕钗拖颈抛盘云。","城西杨柳向娇晚，门前沟水波潾潾。","麒麟公子朝天客，珮马珰珰铛度春陌。","掌中无力舞衣轻，翦断鲛绡破春碧。","抱月飘烟一尺腰，麝脐龙髓怜娇饶。","秋罗拂衣碎光动，露重花多香不销。","㶉𫛶胶胶塘水满，绿萍如粟莲茎短。","一夜西风送雨来，粉痕零落愁红浅。","船头折藕丝暗牵，藕根莲子相留连。","郎心似月月易缺，十五十六清光圆。"]},{"id":"T01350","t":"相和歌辞 长门怨","a":"刘长卿","c":["何事长门闭，珠帘只自垂。","月移深殿早，春向后宫迟。","蕙草生闲地，梨花发旧枝。","芳菲自恩幸，看却被风吹。"]},{"id":"T01351","t":"奉和圣制谒玄元皇帝庙斋","a":"张九龄","c":["兴运昔有感，建祠北山巅。","云雷初缔构，日月今悠然。","紫气尚蓊郁，玄元如在焉。","迨兹事追远，轮奂复增鲜。","洞府香林处，斋坛清汉边。","吾君乃尊祖，夙驾此留连。","乐动人神会，钟成律度圆。","笙歌下鸾鹤，芝术萃灵仙。","曾是福黎庶，岂唯味虚玄。","赓歌徒有作，微薄谢昭宣。"]},{"id":"T01352","t":"感遇诗三十八首 七","a":"陈子昂","c":["白日每不归，青阳时暮矣。","茫茫吾何思，林卧观无始。","众芳委时晦，𫛸鴂鸣悲耳。","鸿荒古已颓，谁识巢居子。"]},{"id":"T01353","t":"相和歌辞 杂怨三首 二","a":"孟郊","c":["贫女镜不明，寒花日少容。","暗蛩有虚织，短线无长缝。","浪水不可照，狂夫不可从。","浪水多散影，狂夫多异踪。","持此一生薄，空成百恨浓。"]},{"id":"T01354","t":"太和 晚发","a":"贺知章","c":["江臯闻曙钟，轻栧理还舼。","海潮夜约约，川露晨溶溶。","始见沙上鸟，犹埋云外峰。","故乡杳无际，明发怀朋从。"]},{"id":"T01355","t":"相和歌辞 短歌行","a":"张籍","c":["青天荡荡高且虚，上有白日无根株。","流光暂出还入地，催我少年不须臾。","与君相逢不寂寞，衰老不复如今乐。","玉卮盛酒置君前，再拜愿君千万年。"]},{"id":"T01356","t":"相和歌辞 乌夜啼","a":"王建","c":["庭树乌，尔何不向别处栖？","夜夜夜半当户啼。","家人把烛出洞户，惊栖失群飞落树。","一飞直欲飞上天，回回不离旧栖处。","未明重绕主人屋，欲下空中黑相触。","风飘雨湿亦不移，君家树头多好枝。"]},{"id":"T01357","t":"杂曲歌辞 皇帝感词 一","a":"卢纶","c":["提劒云雷动，垂衣日月明。","禁花呈瑞色，国老见星精。","发棹鱼先跃，窥巢鸟不惊。","山呼一万岁，直入九重城。"]},{"id":"T01358","t":"杂曲歌辞 鹧鸪词","a":"李益","c":["湘江斑竹枝，锦翼鹧鸪飞。","处处湘云合，郎从何处归。"]},{"id":"T01359","t":"横吹曲辞 白鼻䯄","a":"李白","c":["银鞍白鼻䯄，绿地障泥锦。","细雨春风花落时，挥鞭且就胡姬饮。"]},{"id":"T01360","t":"横吹曲辞 后出塞五首 一","a":"杜甫","c":["男儿生世间，及壮当封侯。","战伐有功业，焉能守旧丘。","召募赴蓟门，军动不可留。","千金买马鞭，百金装刀头。","闾里送我行，亲戚拥道周。","斑白居上列，酒酣进庶羞。","少年别有赠，含笑看吴钩。"]},{"id":"T01361","t":"杂曲歌辞 苦热行","a":"王维","c":["赤日满天地，火云成山岳。","草木尽焦卷，川泽皆竭涸。","轻纨觉衣重，密树苦阴薄。","莞簟不可近，𫄨绤再三濯。","思出宇宙外，旷然在寥廓。","长风万里来，江海荡烦浊。","却顾身为患，始知心未觉。","忽入甘露门，宛然清凉乐。"]},{"id":"T01362","t":"相和歌辞 采莲曲","a":"白居易","c":["菱叶萦波荷飐风，荷花深处小船通。","逢郎欲语低头笑，碧玉搔头落水中。"]},{"id":"T01363","t":"相和歌辞 采莲曲三首 二","a":"王昌龄","c":["荷叶罗裙一色裁，芙蓉向脸两边开。","乱入池中看不见，闻歌始觉有人来。"]},{"id":"T01364","t":"宿扬子津寄润州长山刘隐士","a":"孟浩然","c":["所思在建业，欲往大江深。","日夕望京口，烟波愁我心。","心驰茅山洞，目极枫树林。","不见少微星，星霜劳夜吟。"]},{"id":"T01365","t":"过梁州奉赠张尚书大夫公","a":"岑参","c":["汉中二良将，今昔各一时。","韩信此登坛，尚书复来斯。","手把铜虎符，身总丈人师。","错落北斗星，照耀黑水湄。","英雄若神授，大材济时危。","顷岁遇雷云，精神感灵祇。","勋业振青史，恩德继鸿私。","羌虏昔未平，华阳积僵尸。","人烟绝墟落，鬼火依城池。","巴汉空水流，襃斜惟鸟飞。","自公布德政，此地生光辉。","百堵创里闾，千家恤惸嫠。","层城重鼓角，甲士如熊罴。","坐啸风自调，行春雨仍随。","芃芃麦苗长，蔼蔼桑叶肥。","浮客相与来，群盗不敢窥。","何幸承嘉惠，小年即相知。","富贵情易疎，相逢心不移。","置酒宴高馆，娇歌杂青丝。","锦席绣拂庐，玉盘金屈巵。","春景透高戟，江云篲长麾。","枥马嘶柳阴，美人映花枝。","门传大夫印，世拥上将旗。","承家令名扬，许国苦节施。","戎幕宁久驻，台阶不应迟。","别有弹冠士，希君无见遗。"]},{"id":"T01366","t":"铜雀妓","a":"高适","c":["日暮铜雀迥，秋深玉座清。","萧森松柏望，委郁绮罗情。","君恩不再得，妾舞为谁轻。"]},{"id":"T01367","t":"琴曲歌辞 飞鸢操","a":"刘禹锡","c":["鸢飞杳杳青云里，鸢鸣萧萧风四起。","旗尾飘扬势渐高，箭头砉划声相似。","长空悠悠霁日悬，六翮不动凝飞烟。","游鶤翔鴈出其下，庆云清景相回旋。","忽闻饥乌一噪聚，瞥下云中争腐鼠。","腾音砺吻相喧呼，仰天大吓疑鸳雏。","畏人避犬投高处，俛啄无声犹屡顾。","青鸟自爱玉山禾，仙禽徒贵华亭露。","朴𣙙危巢向暮时，毰毸饱腹蹲枯枝。","游童挟弹一麾肘，臆碎羽分人不悲。","天生众禽各有类，威凤文章在仁义。","鹰隼仪形蝼蚁心，虽能戾天何足贵。"]},{"id":"T01368","t":"鼓吹曲辞 鼓吹铙歌 吐谷浑","a":"柳宗元","c":["吐谷浑盛彊，背西海以夸。","岁侵扰我疆，退匿险且遐。","帝谓神武师，往征靖皇家。","烈烈斾其旗，熊虎杂龙蛇。","王旅千万人，衔枚默无哗。","束刃逾山徼，张翼纵漠沙。","一举刈膻腥，尸骸积如麻。","除恶务本根，况敢遗萌芽。","洋洋西海水，威命穷天涯。","系虏来王都，犒乐穷休嘉。","登高望还师，竟野如春华。","行者靡不归，亲戚讙要遮。","凯旋献清庙，万国思无邪。"]},{"id":"T01369","t":"杂曲歌辞 宫中调笑 一","a":"韦应物","c":["胡马，胡马，远放燕支山下。","咆沙咆雪独嘶，东望西望路迷。","迷路，迷路，边草无穷日暮。"]},{"id":"T01370","t":"杂曲歌辞 侠客行","a":"元稹","c":["侠客不怕死，怕在事不成。","事成不肯藏姓名，我非窃贼谁夜行。","白日堂堂杀袁盎，九衢草草人面青。","此客此心师海鲸，海鲸露背横沧溟。","海滨分作两处生，海鲸分海减海力。","侠客有谋人不测，三尺铁蛇延二国。"]},{"id":"T01371","t":"琴曲歌辞 残形操","a":"韩愈","c":["有兽维狸兮我梦得之，其身孔明兮而头不知。","吉凶何为兮觉坐而思，巫咸上天兮识者其谁。"]},{"id":"T01372","t":"相和歌辞 长歌续短歌","a":"李贺","c":["长歌破衣襟，短歌断白发。","秦王不可见，旦夕成内热。","渴饮壶中酒，饥拔陇头粟。","凄凄四月兰，千里一时绿。","夜峰何离离，月明落石底。","裴回沿石寻，照出高峰外。","不得与之游，歌成鬓先改。"]},{"id":"T01373","t":"相和歌辞 阳春曲","a":"温庭筠","c":["云母空窗晓烟薄，香昏龙气凝辉阁。","霏霏雾雨杏花天，帘外春威著罗幕。","曲栏伏槛金麒麟，沙苑芳郊连翠茵。","廐马何能啮芳草，路人不敢随流尘。"]},{"id":"T01374","t":"琴曲歌辞 湘妃","a":"刘长卿","c":["帝子不可见，秋风来暮思。","婵娟湘江月，千载空蛾眉。"]},{"id":"T01375","t":"巫山高","a":"张九龄","c":["巫山与天近，烟景长青荧。","此中楚王梦，梦得神女灵。","神女去已久，云雨空冥冥。","唯有巴猿啸，哀音不可听。"]},{"id":"T01376","t":"感遇诗三十八首 八","a":"陈子昂","c":["吾观昆仑化，日月沦洞冥。","精魄相交会，天壤以罗生。","仲尼推太极，老聃贵窈冥。","西方金仙子，崇义乃无明。","空色皆寂灭，缘业定何成。","名教信纷藉，死生俱未停。"]},{"id":"T01377","t":"相和歌辞 杂怨三首 三","a":"孟郊","c":["忆人莫至悲，至悲空自衰。","寄人莫翦衣，翦衣未必归。","朝为双蒂花，暮为四散飞。","花落却绕树，游子不顾期。"]},{"id":"T01378","t":"奉和御制春台望","a":"贺知章","c":["青阳布王道，玄览陶真性。","欣若天下春，高逾域中圣。","神臯类观赏，帝里如悬镜。","缭绕八川浮，岧峣双阙映。","晓色徧昭阳，晴云卷建章。","华滋的皪丹青树，颢气氤氲金玉堂。","尚有灵蛇下鄜畤，还征瑞宝入陈仓。","自昔秦奢汉穷武，后庭万余宫百数。","旗回五丈殿千门，连绵南隥出西垣。","广画螓蛾夸窈窕，罗生玳瑁象昆仑。","廼睠天晴兴隐恤，古来土木良非一。","荆临章观赵丛台，何如尧阶将禹室。","层栏䆗窱下龙舆，清管逶迤半绮疏。","一听南风引鸾舞，长谣北极仰鹑居。"]},{"id":"T01379","t":"相和歌辞 猛虎行","a":"张籍","c":["南山北山树冥冥，猛虎白日绕林行。","向晚一身当道食，山中麋鹿尽无声。","年年养子在深谷，雌雄上山不相逐。","谷中近窟有山村，长向村家取黄犊。","五陵年少不敢射，空来林下看行迹。"]},{"id":"T01380","t":"相和歌辞 乌栖曲","a":"王建","c":["章华宫人夜上楼，君王望月西山头。","夜深宫殿门不锁，白露满山山叶堕。"]},{"id":"T01381","t":"杂曲歌辞 皇帝感词 二","a":"卢纶","c":["天衣五凤彩，御马六龙文。","雨露清驰道，风雷翊上军。","高旍花外转，行漏乐前闻。","时见金鞭举，空中指瑞云。"]},{"id":"T01382","t":"相和歌辞 公无渡河","a":"李白","c":["黄河西来决崐崘，咆吼万里触龙门。","波滔天，尧咨嗟。","大禹理百川，儿啼不窥家。","杀湍湮洪水，九州始蚕麻。","其害乃去，茫然风沙。","被发之叟狂而痴，清晨径流欲奚为。","旁人不惜妻止之，公无渡河苦渡之。","虎可搏，河难凭。","公果溺死流海湄，有长鲸白齿若雪山。","公乎公乎，挂骨于其间，箜篌所悲竟不还。"]},{"id":"T01383","t":"横吹曲辞 后出塞五首 二","a":"杜甫","c":["朝进东门营，暮上河阳桥。","落日照大旗，马鸣风萧萧。","平沙列万幕，部伍各见招。","中天悬明月，令严夜寂寥。","悲笳数声动，壮士惨不骄。","借问大将谁，恐是霍嫖姚。"]},{"id":"T01384","t":"杂曲歌辞 少年行四首 一","a":"王维","c":["新丰美酒斗十千，咸阳游侠多少年。","相逢意气为君饮，系马高楼垂柳边。"]},{"id":"T01385","t":"琴曲歌辞 昭君怨","a":"白居易","c":["明妃风貌最娉婷，合在椒房应四星。","只得当年备宫掖，何曾专夜奉帏屏。","见疎从道迷图画，知屈那教配虏廷。","自是君恩薄如纸，不须一向恨丹青。"]},{"id":"T01386","t":"相和歌辞 采莲曲三首 三","a":"王昌龄","c":["越女作桂舟，还将桂为檝。","湖上水渺漫，清江初可涉。","摘取芙蓉花，莫摘芙蓉叶。"]},{"id":"T01387","t":"书怀贻京邑同好","a":"孟浩然","c":["维先自邹鲁，家世重儒风。","诗体袭遗训，趋庭沾末躬。","昼夜常自强，词翰颇亦工。","三十既成立，嗟吁命不通。","慈亲向羸老，喜惧在深衷。","甘脆朝不足，箪瓢夕屡空。","执鞭慕夫子，捧檄怀毛公。","感激遂弹冠，安能守固穷。","当途诉知己，投剌匪求蒙。","秦楚邈离异，飜飞何日同。"]},{"id":"T01388","t":"登北庭北楼呈幕中诸公","a":"岑参","c":["尝读西域传，汉家得轮台。","古塞千年空，阴山独崔嵬。","二庭近西海，六月秋风来。","日暮上北楼，杀气凝不开。","大荒无鸟飞，但见白龙塠。","旧国眇天末，归心日悠哉。","上将新破胡，西郊绝烟埃。","边城寂无事，抚劒空徘徊。","幸得趋幕中，托身厕群才。","早知安边计，未尽平生怀。"]},{"id":"T01389","t":"塞下曲","a":"高适","c":["结束浮云骏，翩翩出从戎。","且凭天子怒，复倚将军雄。","万鼓雷殷地，千旗火生风。","日轮驻霜戈，月魄悬雕弓。","青海阵云匝，黑山兵气衡。","战酣太白高，战罢旄头空。","万里不惜死，一朝得成功。","画图骐麟阁，入朝明光宫。","大笑向文士，一经何足穷。","古人昧此道，往往成老翁。"]},{"id":"T01390","t":"杂曲歌辞 壮士行","a":"刘禹锡","c":["阴风振寒郊，猛虎正咆哮。","徐行出烧地，连吼入黄茆。","壮士走马去，镫前弯玉弰。","叱之使人立，一发如铍交。","悍睛忽星坠，飞血溅林梢。","彪炳为我席，膻腥充我庖。","里中欣害除，贺酒纷号呶。","明日长桥上，倾城看斩蛟。"]},{"id":"T01391","t":"鼓吹曲辞 鼓吹铙歌 高昌","a":"柳宗元","c":["曲氏雄西北，别绝臣外区。","既恃远且险，纵傲不我虞。","烈烈王者师，熊螭以为徒。","龙旗飜海浪，驲骑驰坤隅。","贲育搏婴儿，一扫不复余。","平沙际天极，但见黄云驱。","臣靖执长缨，智勇伏囚拘。","文皇南面坐，夷狄千群趋。","咸称天子神，往古不得俱。","献号天可汗，以覆我国都。","兵戎不交害，各保性与躯。"]},{"id":"T01392","t":"杂曲歌辞 宫中调笑 二","a":"韦应物","c":["河汉，河汉，晓挂秋城漫漫。","愁人起望相思，江南塞北别离。","离别，离别，河汉虽同路绝。"]},{"id":"T01393","t":"杂曲歌辞 筑城曲五解","a":"元稹","c":["年年塞下丁，长作出塞兵。","自从冒顿彊，官筑遮虏城。","筑城须努力，城高遮得贼。","但恐贼路多，有城遮不得。","丁口传父口，莫问城坚不。","平城被虏围，汉𣃁城墙走。","因兹虏请和，虏往骑来多。","半疑兼半信，筑城犹嵯峨。","筑城安敢烦，愿听丁一言。","请筑鸿胪寺，兼愁虏出关。"]},{"id":"T01394","t":"琴曲歌辞 别鹄操","a":"韩愈","c":["雄鹄衔枝来，雌鹄啄泥归。","巢成不生子，大义当乖离。","江汉水之大，鹄身鸟之微。","更无相逢日，安可相随飞。"]},{"id":"T01395","t":"相和歌辞 猛虎行","a":"李贺","c":["长戈莫舂，彊弩莫烹。","乳孙哺子，教得生狞。","举头为城，掉尾为旌。","东海黄公，愁见夜行。","道逢驺虞，牛哀不平。","生何用尺刀，壁上雷鸣。","泰山之下，妇人哭声。","官家有程，吏不敢听。"]},{"id":"T01396","t":"舞曲歌辞 屈柘词","a":"温庭筠","c":["杨柳萦桥绿，玫瑰拂地红。","绣衫金騕褭，花髻玉珑璁。","宿雨香潜润，春流水暗通。","画楼初梦断，晴日照湘风。"]},{"id":"T01397","t":"杂曲歌辞 太行苦热行","a":"刘长卿","c":["迢迢太行路，自古称险恶。","千骑俨欲前，群峰望如削。","火云从中起，仰视飞鸟落。","汗马卧高原，危旌倚长薄。","清风何不至？赤日方煎烁。","石露山木焦，鳞穷水泉涸。","九重今旰食，万里传明略。","诸将候轩车，元凶愁鼎镬。","何劳短兵接，自有长缨缚。","通越事岂难，渡泸功未博。","朝辞羊肠坂，夕望贝丘郭。","漳水斜遶营，常山遥入幕。","永怀姑苏下，因寄建安作。","白雪和诚难，沧波意空托。","陈琳书记好，王粲从军乐。","早晚归汉庭，随君上麟阁。"]},{"id":"T01398","t":"和黄门卢监望秦始皇陵","a":"张九龄","c":["秦帝始求仙，骊山何遽卜。","中年既无效，兹地所宜复。","徒役如雷奔，珍怪亦云蓄。","黔首无寄命，赭衣相追逐。","人怨神亦怒，身死宗遂覆。","土崩失天下，龙鬬入函谷。","国为项籍屠，君同华元戮。","始掘既由楚，终焚乃因牧。","上宰议扬贤，中阿感桓速。","一闻过秦论，载怀空杼轴。"]},{"id":"T01399","t":"感遇诗三十八首 九","a":"陈子昂","c":["圣人秘元命，惧世乱其真。","如何嵩公辈，诙谲误时人。","先天诚为美，阶乱祸谁因。","长城备胡寇，嬴祸发其亲。","赤精既迷汉，子年何救秦。","去去桃李花，多言死如麻。"]},{"id":"T01400","t":"琴曲歌辞 湘妃怨","a":"孟郊","c":["南巡竟不返，帝子怨逾积。","万里丧蛾眉，潇湘水空碧。","冥冥荒山下，古庙收贞魄。","乔木深青春，清光满瑶席。","搴芳徒有荐，灵意殊脉脉。","玉佩不可亲，裴回烟波夕。"]},{"id":"T01401","t":"望人家桃李花","a":"贺知章","c":["山源夜雨度仙家，朝发东园桃李花。","桃花红兮李花白，照灼城隅复南陌。","南陌青楼十二重，春风桃李为谁容。","弃置千金轻不顾，踟蹰五马谢相逢。","徒言南国容华晚，遂叹西家飘落远。","的皪长奉明光殿，氛氲半入披香苑。","苑中珍木元自奇，黄金作叶白银枝。","千年万岁不凋落，还将桃李更相宜。","桃李从来露井傍，成蹊结影矜艳阳。","莫道春花不可树，会持仙实荐君王。"]},{"id":"T01402","t":"相和歌辞  董逃行","a":"张籍","c":["洛阳城头火曈曈，乱兵烧我天子宫。","宫城南面有深山，尽将老幼藏其间。","重岩为屋橡为食，丁男夜行候消息。","闻道官军犹掠人，旧里如今归未得。","董逃行，汉家几时重太平。"]},{"id":"T01403","t":"舞曲歌辞 独漉歌","a":"王建","c":["独独漉漉，鼠食猫肉。","乌日中，鹤露宿，黄河水直人心曲。"]},{"id":"T01404","t":"杂曲歌辞 皇帝感词 三","a":"卢纶","c":["妙算干戈止，神谋宇宙清。","两阶文物盛，七德武功成。","校猎长杨苑，屯军细柳营。","归来献明主，歌舞隘春城。"]},{"id":"T01405","t":"相和歌辞 登高丘而望远","a":"李白","c":["登高丘而望远海，六鼇骨已霜，三山流安在。","扶桑半摧折，白日沈光彩。","银台金阙如梦中，秦皇汉武空相待。","精卫费木石，鼋鼍无所凭。","君不见骊山茂陵尽灰灭，牧羊之子来攀登。","盗贼劫宝玉，精灵竟何能。"]},{"id":"T01406","t":"横吹曲辞 后出塞五首 三","a":"杜甫","c":["古人重守边，今人重高勋。","岂知英雄主，出师亘长云。","六合已一家，四夷且孤军。","遂使貔虎士，奋身勇所闻。","拔劒击大荒，日牧胡马群。","誓开玄冥北，持以奉吾君。"]},{"id":"T01407","t":"杂曲歌辞 少年行四首 二","a":"王维","c":["汉家君臣欢宴终，高议云台论战功。","天子临轩赐侯印，将军佩出明光宫。"]},{"id":"T01408","t":"杂曲歌辞 悲哉行","a":"白居易","c":["悲哉为儒者，力学不能疲。","读书眼欲暗，秉笔手生胝。","十上方一第，成名常苦迟。","纵有宦达者，两鬓已成丝。","可怜少壮日，适在穷贱时。","丈夫老且病，焉用富贵为。","沈沈朱门宅，中有乳臭儿。","状貌如妇人，光明膏粱肌。","手不把书卷，身不擐戎衣。","二十袭封爵，门承勋戚资。","春来日日出，服御何轻肥。","朝从博徒饮，暮有倡楼期。","评封还酒债，堆金选蛾眉。","声色狗马外，其余一无知。","山苗与涧松，地势随高卑。","古来无奈何，非君独伤悲。"]},{"id":"T01409","t":"杂曲歌辞 少年行二首 一","a":"王昌龄","c":["西陵侠年少，送客过长亭。","青槐夹两路，白马如流星。","闻道羽书急，单于寇井陉。","气高轻赴难，谁顾燕山铭。"]},{"id":"T01410","t":"还山贻湛法师","a":"孟浩然","c":["幼闻无生理，常欲观此身。","心迹罕兼遂，[崎岖]多在尘。","晚途归旧壑，偶与支公邻。","导以微妙法，结为清净因。","烦恼业顿舍，山林情转殷。","朝来问疑义，夕话得清真。","墨妙称古绝，词华惊世人。","禅房闭虚静，花药连冬春。","平石籍琴砚，落泉洒衣巾。","欲知冥灭意，朝夕海鸥驯。"]},{"id":"T01411","t":"初过陇山途中呈宇文判官","a":"岑参","c":["一驿过一驿，驿骑如星流。","平明发咸阳，暮及陇山头。","陇水不可听，呜咽令人愁。","沙尘扑马汗，雾露凝貂裘。","西来谁家子，自道新封侯。","前月发安西，路上无停留。","都护犹未到，来时在西州。","十日过沙碛，终朝风不休。","马走碎石中，四蹄皆血流。","万里奉王事，一身无所求。","也知塞垣苦，岂为妻子谋。","山口月欲出，先照关城楼。","谿流与松风，静夜相飕飗。","别家赖归梦，山塞多离忧。","与子且携手，不愁前路修。"]},{"id":"T01412","t":"塞上","a":"高适","c":["东出卢龙塞，浩然客思孤。","亭堠列万里，汉兵犹备胡。","边尘涨北溟，虏骑正南驱。","转鬬岂长策，和亲非远图。","惟昔李将军，按节出皇都。","总戎扫大漠，一战擒单于。","常怀感激心，愿效纵横谟。","倚劒欲谁语，关河空郁纡。"]},{"id":"T01413","t":"杂曲歌辞 荆州乐二首 一","a":"刘禹锡","c":["渚宫杨柳暗，麦城朝雉飞。","可怜踏青伴，乘暖著轻衣。"]},{"id":"T01414","t":"鼓吹曲辞 鼓吹铙歌 东蛮","a":"柳宗元","c":["东蛮有谢氏，冠带理海中。","自言我异世，虽圣莫能通。","王卒如飞翰，鹏𬸣骇群龙。","轰然自天坠，乃信神武功。","系虏君臣人，累累来自东。","无思不服从，唐业如山崇。","百辟拜稽首，咸愿图形容。","如周王会书，永永传无穷。","睢盱万状乖，咿嗢九译重。","广轮抚四海，浩浩知皇风。","歌诗铙鼓间，以壮我元戎。"]},{"id":"T01415","t":"拟古诗十二首 一","a":"韦应物","c":["辞君远行迈，饮此长恨端。","已谓道里远，如何中险艰。","流水赴大壑，孤云还暮山。","无情尚有归，行子何独难。","驱车背乡园，朔风卷行迹。","严冬霜断肌，日入不遑息。","忧欢容发变，寒暑人事易。","中心君讵知，冰玉徒贞白。"]},{"id":"T01416","t":"杂曲歌辞 鸣雁行","a":"韩愈","c":["嗷嗷鸣雁鸣且飞，穷秋南去春北归。","去寒就暖识所处，天长地阔栖息稀。","风霜酸苦稻粱微，羽毛摧落身不肥。","徘徊反顾群侣违，哀鸣欲下洲渚非。","江南水阔朝云多，草长沙輭无网罗。"]},{"id":"T01417","t":"相和歌辞 难忘曲","a":"李贺","c":["夹道开洞门，弱杨低画戟。","帘影竹叶起，箫声吹日色。","蠭语绕妆镜，拂蛾学春碧。","乱系丁香梢，满阑花向夕。"]},{"id":"T01418","t":"杂曲歌辞 侠客行","a":"温庭筠","c":["欲出鸿都门，阴云蔽城阙。","宝劒黯如水，微红湿余血。","白马夜频嘶，三更霸陵雪。"]},{"id":"T01419","t":"杂曲歌辞 少年行","a":"刘长卿","c":["射飞夸侍猎，行乐爱联镳。","荐枕青娥艳，鸣鞭白马骄。","曲房珠翠合，深巷管弦调。","日晚春风里，衣香满路飘。"]},{"id":"T01420","t":"酬周判官巡至始兴会改秘书少监见贻之作兼呈耿广州","a":"张九龄","c":["惟昔迁乐土，迨今已重世。","阴庆荷先德，素风慙后裔。","唯益梓桑恭，岂禀山川丽。","于时初自勉，揆己无兼济。","瘠土资劳力，良书启蒙蔽。","一探石室文，再擢金门第。","既起南宫草，复掌西掖制。","过举及小人，便蕃在中岁。","亚司河海秩，转牧江湖澨。","勿谓符竹轻，但觉涓尘细。","一麾尚云忝，十驾宜求税。","心息已如灰，迹牵且为赘。","忽捧天书委，将革海隅弊。","朝闻循诚节，夕饮蒙瘴疠。","义疾耻无勇，盗憎攻亦锐。","葵藿是倾心，豺狼何反噬。","履险甘所受，劳贤恧相曳。","揽辔但荒服，循陔便私第。","嘉庆始获申，恩华复相继。","无庸我先举，同事君犹滞。","当推奉使绩，且结拜亲契。","更延怀安旨，曾是虑危际。","善谋虽若兹，至理焉可替。","所杖有神道，况承明主惠。"]},{"id":"T01421","t":"感遇诗三十八首 十","a":"陈子昂","c":["深居观元化，悱然争朵颐。","谗说相啖食，利害纷㘈㘈。","便便夸毘子，荣耀更相持。","务光让天下，商贾竞刀锥。","已矣行采芝，万世同一时。"]},{"id":"T01422","t":"杂曲歌辞 出门行二首 一","a":"孟郊","c":["长河悠悠去无极，百龄同此可叹息。","秋风白露沾人衣，壮心凋落夺颜色。","少年出门将诉谁，川无梁兮路无岐。","一闻陌上苦寒奏，使我伫立惊且悲。","君今得意厌粱肉，岂复念我贫贱时。"]},{"id":"T01423","t":"送人之军","a":"贺知章","c":["常经绝脉塞，复见断肠流。","送子成今别，令人起昔愁。","陇云晴半雨，边草夏先秋。","万里长城寄，无贻汉国忧。"]},{"id":"T01424","t":"相和歌辞 白头吟","a":"张籍","c":["请君膝上琴，弹我白头吟。","忆昔君前娇笑语，两情宛转如萦素。","宫中为我起高楼，更开华池种芳树。","春天百草秋始衰，弃我不待白头时。","罗襦玉珥色未暗，今朝已道不相宜。","扬州青铜作明镜，暗中持照不见影。","人心回互自无穷，眼前好恶那能定。","君恩已去若再返，菖蒲花生月长满。"]},{"id":"T01425","t":"舞曲歌辞 白纻歌二首 一","a":"王建","c":["天河漫漫北斗粲，宫中乌啼知夜半。","新缝白纻舞衣成，来迟邀得吴王迎。","低鬟转面掩双袖，玉钗浮动秋风生。","酒多夜长夜未晓，月明灯光两相照，后庭歌声更窈窕。"]},{"id":"T01426","t":"杂曲歌辞 皇帝感词 四","a":"卢纶","c":["天乐下天中，云𫐌俨在空。","铅黄艳河汉，语笑合笙镛。","已见长随凤，仍闻不避熊。","君王亲试舞，阊阖静无风。"]},{"id":"T01427","t":"相和歌辞 对酒二首 一","a":"李白","c":["松子栖金华，安期入蓬海。","此人古之仙，羽化竟何在？","浮生速流电，倏忽变光彩。","天地无凋换，容颜有迁改。","对酒不肯饮，含情欲谁待。"]},{"id":"T01428","t":"横吹曲辞 后出塞五首 四","a":"杜甫","c":["献凯日继踵，两蕃静无虞。","渔阳豪侠地，击鼓吹笙竽。","云帆转辽海，粳稻来东吴。","越罗与楚练，照耀舆台躯。","主将位益崇，气骄陵上都。","边人不敢议，议者死路衢。"]},{"id":"T01429","t":"杂曲歌辞 少年行四首 三","a":"王维","c":["出身仕汉羽林郎，初随骠骑战渔阳。","孰知不向边庭苦，纵死犹闻侠骨香。"]},{"id":"T01430","t":"杂曲歌辞 浩歌行","a":"白居易","c":["天长地久无终毕，昨夜今朝又明日。","鬓发苍浪牙齿疎，不觉身年四十七。","前去五十有几年，把镜照面心茫然。","既无长绳系白日，又无大药驻朱颜。","朱颜日渐不如故，青史功名在何处？","欲留年少待富贵，富贵不来年少去。","去复去兮如长河，东流赴海无回波。","贤愚贵贱同归尽，北邙冢墓高嵯峨。","古来如此非独我，未死有酒且酣歌。","颜回短命伯夷饿，我今所得亦已多。"]},{"id":"T01431","t":"杂曲歌辞 少年行二首 二","a":"王昌龄","c":["走马还相寻，西楼下夕阴。","结交期一劒，留意赠千金。","高阁歌声远，重关柳色深。","夜闲须尽醉，莫负百年心。"]},{"id":"T01432","t":"秋宵月下有怀","a":"孟浩然","c":["秋空明月悬，光彩露沾湿。","惊鹊栖未定，飞萤卷帘入。","庭槐寒影疎，邻杵夜声急。","佳期旷何许，望望空伫立。"]},{"id":"T01433","t":"陪狄员外早秋登府西楼因呈院中诸公","a":"岑参","c":["常爱张仪楼，西山正相当。","千峰带积雪，百里临城墙。","烟氛扫晴空，草树映朝光。","车马隘百井，里闬盘二江。","亚相自登坛，时危安此方。","威声振蛮貊，惠化钟华阳。","旌节罗广庭，戈铤凛秋霜。","阶下貔虎士，幕中鹓鹭行。","今我忽登临，顾恩不望乡。","知己犹未报，鬓毛飒已苍。","时命难自知，功业岂暂忘。","蝉鸣秋城夕，鸟去江天长。","兵马休战争，风尘尚苍茫。","谁当共携手，赖有冬官郎。"]},{"id":"T01434","t":"蓟门行五首 一","a":"高适","c":["蓟门逢古老，独立思氛氲。","一身既零丁，头鬓白纷纷。","勋庸今已矣，不识霍将军。"]},{"id":"T01435","t":"杂曲歌辞 荆州乐二首 二","a":"刘禹锡","c":["今日好南风，商旅相催发。","沙头樯竿上，始见春江阔。"]},{"id":"T01436","t":"相和歌辞 东门行","a":"柳宗元","c":["汉家三十六将军，东方雷动横阵云。","鸡鸣函谷客如雾，貌同心异不可数。","赤丸夜语飞电光，徼巡司隶眠如羊。","当街一叱百吏走，冯敬胷中函匕首。","凶徒侧耳潜惬心，悍臣破胆皆杜口。","魏王卧内藏兵符，子西掩袂真无辜。","羌胡毂下一朝起，敌国舟中非所拟。","安陵谁辨削砺功，韩国讵明深井里。","绝咽断骨那下补，万金宠赠不如土。"]},{"id":"T01437","t":"拟古诗十二首 二","a":"韦应物","c":["黄鸟何关关，幽兰亦靡靡。","此时深闺妇，日照纱窗里。","娟娟双青娥，微微启玉齿。","自惜桃李年，误身游侠子。","无事久离别，不知今生死。"]},{"id":"T01438","t":"相和歌辞 塘上行","a":"李贺","c":["藕花凉露湿，花缺藕根涩。","飞下雌鸳鸯，塘水声溢溢。"]},{"id":"T01439","t":"杂曲歌辞 西洲曲","a":"温庭筠","c":["悠悠复悠悠，昨日下西洲。","西洲风色好，遥见武昌楼。","武昌何郁郁，侬家定无匹。","小妇被流黄，登楼抚瑶瑟。","朱弦繁复轻，素手直凄清。","一弹三四解，掩抑似含情。","南楼登且望，西江广复平。","艇子摇两桨，催过石头城。","门前乌臼树，惨澹天将曙。","鹍𫛥飞复还，郎随早帆去。","回头语同伴，定复负情侬。","去帆不安幅，作抵使西风。","他日相寻索，莫作西洲客。","西洲人不归，春草年年碧。"]},{"id":"T01440","t":"逢雪宿芙蓉山主人","a":"刘长卿","c":["日暮苍山远，天寒白屋贫。","柴门闻犬吠，风雪夜归人。"]},{"id":"T01441","t":"和吏部李侍郎见示秋夜望月忆诸侍郎之什其卒章有前后行之戏因命仆继作","a":"张九龄","c":["清秋发高兴，凉月复闲宵。","光逐露华满，情因水镜摇。","同时亦所见，异路无相招。","美景向空尽，欢言随事销。","忽听金华作，诚如玉律调。","南宫尚为后，东观何其辽。","名数虽云隔，风期幸未遥。","今来重余论，怀此更终朝。"]},{"id":"T01442","t":"感遇诗三十八首 十一","a":"陈子昂","c":["吾爱鬼谷子，青谿无垢氛。","囊括经世道，遗身在白云。","七雄方龙鬬，天下久无君。","浮荣不足贵，遵养晦时文。","舒可弥宇宙，卷之不盈分。","岂徒山木寿，空与麋鹿群。"]},{"id":"T01443","t":"杂曲歌辞 出门行二首 二","a":"孟郊","c":["海风萧萧天雨霜，穷愁独坐夜何长？","驱车旧忆太行险，始知游子悲故乡。","美人相思隔天阙，长望云端不可越。","手持琅玕欲有赠，爱而不见心断绝。","南山峨峨白石烂，碧海之波浩漫漫。","参辰出没不相待，我欲横天无羽翰。"]},{"id":"T01444","t":"奉和圣制送张说上集贤学士赐宴赋得谟字","a":"贺知章","c":["西学垂玄览，东堂发圣谟。","天光烛武殿，时宰集鸿都。","枯朽沾皇泽，翾飞舞帝梧。","迹同游汗漫，荣是出泥涂。","三叹承汤鼎，千欢接舜壶。","微躯不可荅，空欲咏依蒲。"]},{"id":"T01445","t":"相和歌辞 乌栖曲","a":"张籍","c":["西山作宫潮满池，宫乌晓鸣茱萸枝。","吴姬自唱采莲曲，君王昨夜舟中宿。"]},{"id":"T01446","t":"舞曲歌辞 白纻歌二首 二","a":"王建","c":["馆娃宫中春日暮，荔枝木瓜花满树。","城头乌栖休击鼓，青娥弹瑟白纻舞。","夜天燑燑不见星，宫中火照西江明。","美人醉起无次第，堕钗遗佩满中庭。","此时但愿可君意，回昼为宵亦不寐，年年奉君君莫弃。"]},{"id":"T01447","t":"相和歌辞 对酒二首 二","a":"李白","c":["劝君莫拒杯，春风笑人来。","桃李如旧识，倾花向我开。","流莺啼碧树，明月窥金罍。","昨来朱颜子，今日白发催。","棘生石虎殿，鹿走姑苏台。","自古帝王宅，城阙闭黄埃。","君若不饮酒，昔人安在哉。"]},{"id":"T01448","t":"横吹曲辞 后出塞五首 五","a":"杜甫","c":["我本良家子，出师亦多门。","将骄益愁思，身贵不足论。","跃马二十年，恐辜明主恩。","坐见幽州骑，长驱河洛昏。","中夜间道归，故里但空村。","恶名幸脱免，穷老无儿孙。"]},{"id":"T01449","t":"杂曲歌辞 少年行四首 四","a":"王维","c":["一身能臂两雕弧，虏骑千群只似无。","偏坐金鞍调白羽，纷纷射杀五单于。"]},{"id":"T01450","t":"杂曲歌辞 长相思","a":"白居易","c":["九月西风兴，月冷霜华凝。","思君秋夜长，一夜魂九升。","二月东风来，草坼花心开。","思君春日迟，一日肠九回。","妾住洛桥北，君住洛桥南。","十五即相识，今年二十三。","有如女萝草，生在松之侧。","蔓短枝苦高，萦回上不得。","人言人有愿，愿至天必成。","愿作远方兽，步步比肩行。","愿作深山木，枝枝连理生。"]},{"id":"T01451","t":"杂曲歌辞 变行路难","a":"王昌龄","c":["向晚横吹悲，风动马嘶合。","前驱引旗节，千重阵云帀。","单于下阴山，砂砾空飒飒。","封侯取一战，岂复念闺合。"]},{"id":"T01452","t":"将适天台留别临安李主簿","a":"孟浩然","c":["枳棘君尚栖，匏瓜吾岂系。","念离当夏首，漂泊指炎裔。","江海非堕游，田园失归计。","定山既早发，渔浦亦宵济。","泛泛随波澜，行行任舻枻。","故林日已远，群木坐成翳。","羽人在丹丘，吾亦从此逝。"]},{"id":"T01453","t":"冬夜宿仙游寺南凉堂呈谦道人","a":"岑参","c":["太乙连太白，两山知几重。","路盘石门窄，匹马行才通。","日西倒山寺，林下逢支公。","昨夜山北时，星星闻此钟。","秦女去已久，仙台在中峰。","箫声不可闻，此地留遗踪。","石潭积黛色，每岁投金龙。","乱流争迅湍，喷薄如雷风。","夜来闻清磬，月出苍山空。","空山满清光，水树相玲珑。","回廊映密竹，秋殿隐深松。","灯影落前谿，夜宿水声中。","爱兹林峦好，结宇向谿东。","相识唯山僧，邻家一钓翁。","林晚栗初拆，枝寒梨已红。","物幽兴易惬，事胜趣弥浓。","愿谢区中缘，永依金人宫。","寄报乘辇客，簪裾尔何容。"]},{"id":"T01454","t":"蓟门行五首 二","a":"高适","c":["汉家能用武，开拓穷异域。","戍卒厌糠核，降胡饱衣食。","关亭试一望，吾欲泪沾臆。"]},{"id":"T01455","t":"杂曲歌辞 纪南歌","a":"刘禹锡","c":["风烟纪南城，尘土荆门路。","天寒猎兽者，走上樊姬墓。"]},{"id":"T01456","t":"舞曲歌辞 白纻歌","a":"柳宗元","c":["翠帷双卷出倾城，龙劒破匣霜月明。","朱唇掩抑悄无声，金簧玉磬宫中生。"]},{"id":"T01457","t":"拟古诗十二首 三","a":"韦应物","c":["峨峨高山巅，浼浼青川流。","世人不自悟，驰谢如惊飍。","百金非所重，厚意良难得。","旨酒亲与朋，芳年乐京国。","京城繁华地，轩盖凌晨出。","垂杨十二衢，隐暎金张室。","汉宫南北对，飞观齐白日。","游泳属芳时，平生自云毕。"]},{"id":"T01458","t":"相和歌辞 安乐宫","a":"李贺","c":["深井桐乌起，尚复牵清水。","未盥邵陵王，瓶中弄长翠。","新城安乐宫，宫如凤皇翅。","歌回蜡版鸣，大绾提壶使。","绿繁悲水曲，茱萸别秋子。"]},{"id":"T01459","t":"杂曲歌辞 湖阴曲","a":"温庭筠","c":["祖龙黄须珊瑚鞭，铁骢金面青连钱。","虎髯拔劒欲成梦，日压贼营如血鲜。","海旗风急惊眠起，甲重光摇照湖水。","苍黄追骑尘外归，森索妖星阵前死。","五陵愁碧春萋萋，灞川玉马空中嘶。","羽书如电入青琐，雪腕如搥催画鞞。","白虬天子金煌铓，高临帝座回龙章。","吴波不动楚山晚，花压阑干春昼长。"]},{"id":"T01460","t":"送张起崔载华之闽中","a":"刘长卿","c":["朝无寒士达，家在旧山贫。","相送天涯里，怜君更远人。"]},{"id":"T01461","t":"登南岳事毕谒司马道士","a":"张九龄","c":["将命祈灵岳，回策诣真士。","绝迹寻一径，异香闻数里。","分庭八桂树，肃容两童子。","入室希把袖，登床愿启齿。","诱我弃智诀，迨兹长生理。","吸精反自然，炼药求不死。","斯言眇霄汉，顾余婴纷滓。","相去九牛毛，慙叹知何已。"]},{"id":"T01462","t":"感遇诗三十八首 十二","a":"陈子昂","c":["呦呦南山鹿，罹罟以媒和。","招摇青桂树，幽蠹亦成科。","世情甘近习，荣耀纷如何。","怨憎未相复，亲爱生祸罗。","瑶台倾巧笑，玉杯殒双蛾。","谁见枯城蘖，青青成斧柯。"]},{"id":"T01463","t":"杂曲歌辞 伤歌行","a":"孟郊","c":["众毒蔓贞松，一枝难久荣。","岂知黄庭客，仙骨生不成。","春色舍芳蕙，秋风遶枯茎。","弹琴不成曲，始觉知音倾。","馆月改旧照，吊宾写余情。","还舟空江上，波浪送铭旌。"]},{"id":"T01464","t":"奉和圣制送张说巡边","a":"贺知章","c":["荒憬尽怀忠，梯航已自通。","九攻虽不战，五月尚持戎。","遣戍征周牒，恢边重汉功。","选车命元宰，授律取文雄。","胄出天弧上，谋成帝幄中。","诏旗分夏物，专土锡唐弓。","帐宿伊川右，钲传晋苑东。","饔人藉蕡实，乐正理丝桐。","岐陌涵余雨，离川照晚虹。","恭闻咏方叔，千载舞皇风。"]},{"id":"T01465","t":"相和歌辞 贾客乐","a":"张籍","c":["金陵向西贾客多，船中生长乐风波。","欲发移船近江口，船头祭神各浇酒。","停杯共说远行期，入蜀经蛮远别离。","金多众中为上客，夜夜算缗眠独迟。","秋江初月猩猩语，孤帆夜发满湘渚。","水工持檝防暗滩，直过山边及前侣。","年年逐利西复东，姓名不在县籍中。","农夫税多长辛苦，弃业长为贩卖翁。"]},{"id":"T01466","t":"舞曲歌辞 霓裳辞十首 一","a":"王建","c":["弟子部中留一色，听风听水作霓裳。","散声未足重来授，直到床前见上皇。"]},{"id":"T01467","t":"相和歌辞 陌上桑","a":"李白","c":["美女渭桥东，春还事蚕作。","五马如飞龙，青丝结金络。","不知谁家子，调笑来相谑。","妾本秦罗敷，玉颜艳名都。","绿条映素手，采桑向城隅。","使君且不顾，况复论秋胡。","寒螀爱碧草，鸣凤栖青梧。","托心自有处，但怪傍人愚。","徒令白日暮，高驾空踟蹰。"]},{"id":"T01468","t":"相和歌辞 前苦寒行二首 一","a":"杜甫","c":["汉时长安雪一丈，牛马毛寒缩如猬。","楚江巫峡冰入怀，虎豹哀号又堪记。","秦城老翁荆扬客，惯习炎蒸岁𫄨绤。","玄冥祝融气或交，手持白羽未敢释。"]},{"id":"T01469","t":"酬诸公见过","a":"王维","c":["嗟予未丧，哀此孤生。","屏居蓝田，薄地躬耕。","岁[晏]输税，以奉粢盛。","晨往东臯，草露未晞。","暮看烟火，负担来归。","我闻有客，足埽荆扉。","箪食伊何，疈瓜抓枣。","仰厕群贤，皤然一老。","媿无莞簟，班荆席藁。","泛泛登陂，折彼荷花。","静观素鲔，俯映白沙。","山鸟群飞，日隐轻霞。","登车上马，倏忽云散。","雀噪荒村，鸡鸣空馆。","还复幽独，重欷累叹。"]},{"id":"T01470","t":"杂曲歌辞 生别离","a":"白居易","c":["食蘗不易食梅难，蘗能苦兮梅能酸。","未如生别之为难，苦在心兮酸在肝。","晨鸡载鸣残月没，征马重嘶行人出。","回看骨肉哭一声，梅酸蘗苦甘如蜜。","黄河水白黄云秋，行人河边相对愁。","天寒野旷何处宿？棠梨叶战风飕飕。","生离别，生离别，忧从中来无断绝。","忧积心劳血气衰，未年三十生白发。"]},{"id":"T01471","t":"变行路难","a":"王昌龄","c":["向晚横吹悲，风动马嘶合。","前趋引旗节，千里阵云帀。","单于下阴山，砂砾空飒飒。","封侯取一战，岂复念闺合。"]},{"id":"T01472","t":"送丁大凤进士赴举呈张九龄","a":"孟浩然","c":["吾观鹪鹩赋，君负王佐才。","惜无金张援，十上空归来。","弃置乡园老，翻飞羽翼摧。","故人今在位，歧路莫迟回。"]},{"id":"T01473","t":"潼关镇国军句覆使院早春寄王同州","a":"岑参","c":["胡寇尚未尽，大军镇关门。","旌旗遍草木，兵马如云屯。","圣朝正用武，诸将皆承恩。","不见征战功，但闻歌吹喧。","儒生有长策，闭口不敢言。","昨从关东来，思与故人论。","何为廊庙器，至今居外藩。","黄霸宁淹留，苍生望腾𬸣。","卷帘见西岳，仙掌明朝暾。","昨夜闻春风，戴胜过后园。","各自限官守，何由叙凉温。","离忧不可忘，襟背思树萱。"]},{"id":"T01474","t":"蓟门行五首 三","a":"高适","c":["边城十一月，雨雪乱霏霏。","元戎号令严，人马亦轻肥。","羌胡无尽日，征战几时归。"]},{"id":"T01475","t":"杂曲歌辞 宜城歌","a":"刘禹锡","c":["野水遶空城，行尘起孤驿。","花台侧生树，石碣阳镌头。","靡靡度行人，温风吹宿麦。"]},{"id":"T01476","t":"杂曲歌辞 行路难三首 一","a":"柳宗元","c":["君不见夸父逐日窥虞渊，跳踉北海超昆仑。","披霄决汉出沆漭，瞥裂左右遗星辰。","须臾力尽道渴死，狐鼠蜂蚁争噬吞。","北方竫人长九寸，开口抵掌更笑喧。","啾啾饮食滴与粒，生死亦足终天年。","睢盱大志少成遂，坐使儿女相悲怜。"]},{"id":"T01477","t":"拟古诗十二首 四","a":"韦应物","c":["绮楼何氛氲，朝日正杲杲。","四壁含清风，丹霞射其牖。","玉颜上哀啭，绝耳非世有。","但感离恨情，不知谁家妇。","孤云忽无色，边马为回首。","曲绝碧天高，余声散秋草。","徘徊帷中意，独夜不堪守。","思逐朔风翔，一去千里道。"]},{"id":"T01478","t":"相和歌辞 雁门太守行","a":"李贺","c":["黑云压城城欲摧，甲光向月金鳞开。","角声满天秋色里，塞上燕支凝夜紫。","半卷红旗临易水，霜重鼓寒声不起。","报君黄金台上意，提携玉龙为君死。"]},{"id":"T01479","t":"杂曲歌辞 达摩支","a":"温庭筠","c":["捣麝成尘香不灭，拗莲作寸丝难绝。","红泪文姬洛水春，白头苏武天山雪。","君不见无愁高纬花漫漫，漳浦宴余清露寒。","一旦臣僚共囚虏，欲吹羌管先汍澜。","旧臣头鬓霜华早，可惜雄心醉中老。","万古春归梦不归，邺城风雨连天草。"]},{"id":"T01480","t":"赠秦系征君","a":"刘长卿","c":["群公谁让位，五柳独知贫。","惆怅青山路，烟霞老此人。"]},{"id":"T01481","t":"九月九日登龙山","a":"张九龄","c":["郡庭常窘束，凉野求昭旷。","楚客凛秋时，桓公旧台上。","清明风日好，历落江山望。","极远何萧条，中留坐惆怅。","东弥夏首阔，西拒荆门壮。","夷险虽异时，古今岂殊状。","先贤杳不接，故老犹可访。","投吊伤昔人，挥斤感前匠。","自为本疎散，未始忘幽尚。","际会非有欲，往来是无妄。","为邦复多幸，去国殊迁放。","且泛篱下菊，还聆郢中唱。","灌园亦何为，于陵乃逃相。"]},{"id":"T01482","t":"感遇诗三十八首 十三","a":"陈子昂","c":["林居病时久，水木澹孤清。","闲卧观物化，悠悠念无生。","青春始萌达，朱火已满盈。","徂落方自此，感叹何时平。"]},{"id":"T01483","t":"杂曲歌辞 妾薄命","a":"孟郊","c":["不惜十指弦，为君千万弹。","常恐新声至，坐使故声残。","弃置今日悲，即是昨日欢。","将新变故易，持故为新难。","青山有蘼芜，泪叶长不干。","空令后代人，采掇幽思攒。"]},{"id":"T01484","t":"题袁氏别业","a":"贺知章","c":["主人不相识，偶坐为林泉。","莫谩愁沽酒，囊中自有钱。"]},{"id":"T01485","t":"相和歌辞 采莲曲","a":"张籍","c":["秋江岸边莲子多，采莲女儿凭船歌。","青房圆实齐戢戢，争前竞折荡漾波。","试牵绿茎下寻藕，断处丝多刺伤手。","白练束腰袖半卷，不插玉钗妆梳浅。","船中未满度前洲，借问谁家家住远。","归时共待暮潮上，自弄芙蓉还荡桨。"]},{"id":"T01486","t":"舞曲歌辞 霓裳辞十首 二","a":"王建","c":["中管五弦初半曲，遥教合上隔帘听。","一声声向天头落，效得仙人夜唱经。"]},{"id":"T01487","t":"相和歌辞 日出行","a":"李白","c":["日出东方隈，似从地底来。","历天又入海，六龙所舍安在哉？","其始与终古不息，人非元气安能与之久裴回。","草不谢荣于春风，木不怨落于秋天。","谁挥鞭策驱四运，万物兴歇皆自然。","羲和羲和，汝奚汩没于荒淫之波。","鲁阳何德？驻景挥戈。","逆道违天，矫诬实多。","吾将囊括大块，浩然与溟涬同科。"]},{"id":"T01488","t":"相和歌辞 前苦寒行二首 二","a":"杜甫","c":["去年白帝雪在山，今年白帝雪在地。","冻埋蛟龙南浦缩，寒刮肌肤北风利。","楚人四时皆麻衣，楚天万里无晶辉。","三足之乌足恐断，羲和送将安所归。"]},{"id":"T01489","t":"奉和圣制登降圣观与宰臣等同望应制","a":"王维","c":["凤扆朝碧落，龙图耀金镜。","维岳降二臣，戴天临万姓。","山川八校满，井邑三农竟。","比屋皆可封，谁家不相庆。","林疎远村出，野旷寒山静。","帝城云里深，渭水天边映。","佳气含风景，颂声溢歌咏。","端拱能任贤，弥彰圣君圣。"]},{"id":"T01490","t":"杂曲歌辞 潜别离","a":"白居易","c":["不得哭，潜别离，不得语，暗相思，两心之外无人知。","深笼夜[锁]独栖鸟，利劒[春]断连理枝。","河水虽浊有清日，乌头虽黑有白时。","惟有潜离与暗别，彼此甘心无后期。"]},{"id":"T01491","t":"塞下曲四首 三","a":"王昌龄","c":["奉诏甘泉宫，总征天下兵。","朝廷备礼出，郡国豫郊迎。","纷纷几万人，去者无全生。","臣愿节宫廐，分以赐边城。"]},{"id":"T01492","t":"送吴悦游韶阳","a":"孟浩然","c":["五色怜凤雏，南飞适鹧鸪。","楚人不相识，何处求椅梧。","去去日千里，茫茫天一隅。","安能与斥鷃，决起但枪榆。"]},{"id":"T01493","t":"青山峡口泊舟怀狄侍御","a":"岑参","c":["峡口秋水壮，沙边且停桡。","奔涛振石壁，峰势如动摇。","九月芦花新，弥令客心焦。","谁念在江岛，故人满天朝。","无处豁心胸，忧来醉能销。","往来巴山道，三见秋草雕。","狄生新相知，才调凌云霄。","赋诗析造化，入幕生风飙。","把笔判甲兵，战士不敢骄。","皆云梁公后，遇鼎还能调。","离别倏经时，音尘殊寂寥。","何当见夫子，不叹乡关遥。"]},{"id":"T01494","t":"蓟门行五首 四","a":"高适","c":["幽州多骑射，结发重横行。","一朝事将军，出入有声名。","纷纷猎秋草，相向角弓鸣。"]},{"id":"T01495","t":"杂曲歌辞 竹枝 一","a":"刘禹锡","c":["白帝城头春草生，白盐山下蜀江清。","南人上来歌一曲，北人莫上动乡情。"]},{"id":"T01496","t":"杂曲歌辞 行路难三首 二","a":"柳宗元","c":["虞衡斤斧罗千山，工命采斫杙与椽。","深林土翦十取一，百牛连鞅摧双辕。","万围千寻妨道路，东西蹶倒山火焚。","遗余毫末不见保，𨅬砾磵壑何当存。","群材未成质已夭，突兀𡷸豁空岩峦。","柏梁天灾武库火，匠石狼顾相愁冤。","君不见南山栋梁益稀少，爱材养育谁复论。"]},{"id":"T01497","t":"拟古诗十二首 五","a":"韦应物","c":["嘉树蔼初绿，靡芜吐幽芳。","君子不在赏，寄之云路长。","路长信难越，惜此芳时歇。","孤鸟去不还，缄情向天末。"]},{"id":"T01498","t":"相和歌辞 神弦曲","a":"李贺","c":["西山日没东山昏，旋风吹马马踏云。","画弦素管声浅繁，花裙綷䌨步秋尘。","桂叶刷风桂坠子，青狸哭血寒狐死。","古壁彩虬金帖尾，雨工骑入秋潭水。","百年老鸮成木魅，笑声碧火巢中起。"]},{"id":"T01499","t":"杂曲歌辞 杨柳枝 一","a":"温庭筠","c":["宜春苑外最长条，闲袅春风伴舞腰。","正是玉人肠断处，一渠春水赤栏桥。"]},{"id":"T01500","t":"秦系顷以家事获谤因出旧山每荷观察崔公见知欲归未遂感其流寓诗以赠之","a":"刘长卿","c":["初迷武陵路，复出孟尝门。","回首江南岸，青山与旧恩。"]}];
